CREATE TABLE IF NOT EXISTS "public"."loyalty_ledger" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "points" integer NOT NULL,
    "balance_after" integer NOT NULL,
    "source" "text" NOT NULL,
    "description" "text" NOT NULL,
    "sale_id" "uuid",
    "rule_id" "uuid",
    "raffle_id" "uuid",
    "idempotency_key" "text",
    "expires_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "payment_method" "text",
    "payment_reference" "text",
    CONSTRAINT "loyalty_ledger_balance_non_negative" CHECK (("balance_after" >= 0)),
    CONSTRAINT "loyalty_ledger_payment_method_valid" CHECK ((("payment_method" IS NULL) OR ("payment_method" = ANY (ARRAY['cash'::"text", 'transfer'::"text", 'card'::"text"])))),
    CONSTRAINT "loyalty_ledger_points_not_zero" CHECK (("points" <> 0)),
    CONSTRAINT "loyalty_ledger_source_valid" CHECK (("source" = ANY (ARRAY['purchase'::"text", 'promotion'::"text", 'raffle_entry'::"text", 'raffle_refund'::"text", 'adjustment'::"text", 'expiration'::"text"])))
);


ALTER TABLE "public"."loyalty_ledger" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_loyalty_points"("p_customer_id" "uuid", "p_points" integer, "p_reason" "text") RETURNS "public"."loyalty_ledger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  customer_org uuid;
  current_balance integer := 0;
  inserted public.loyalty_ledger;
begin
  if p_points = 0 then
    raise exception 'El ajuste no puede ser cero.' using errcode = 'invalid_parameter_value';
  end if;

  if coalesce(trim(p_reason), '') = '' then
    raise exception 'Todo ajuste manual necesita un motivo.' using errcode = 'invalid_parameter_value';
  end if;

  select organization_id into customer_org from public.customers where id = p_customer_id;

  if customer_org is null then
    raise exception 'El cliente no existe.' using errcode = 'no_data_found';
  end if;

  if not public.has_org_permission(customer_org, 'promotions.manage') then
    raise exception 'No tenés permiso para ajustar puntos.' using errcode = 'insufficient_privilege';
  end if;

  select coalesce(balance, 0) into current_balance
  from public.loyalty_accounts where customer_id = p_customer_id;

  current_balance := coalesce(current_balance, 0);

  if current_balance + p_points < 0 then
    raise exception 'El ajuste dejaría el saldo en negativo (saldo actual: %).', current_balance
      using errcode = 'check_violation';
  end if;

  insert into public.loyalty_ledger (
    organization_id, customer_id, points, balance_after, source, description, created_by
  )
  values (
    customer_org, p_customer_id, p_points, current_balance + p_points,
    'adjustment', trim(p_reason), auth.uid()
  )
  returning * into inserted;

  return inserted;
end;
$$;


ALTER FUNCTION "public"."adjust_loyalty_points"("p_customer_id" "uuid", "p_points" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_variant_stock_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_variant_id" "uuid", "p_quantity_delta" integer, "p_movement_type" "text", "p_idempotency_key" "text", "p_actor_id" "uuid", "p_reference_type" "text" DEFAULT NULL::"text", "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inventory_row public.branch_variant_inventory%rowtype;
  existing_movement public.variant_inventory_movements%rowtype;
  resulting_stock integer;
begin
  if p_organization_id is null
     or p_branch_id is null
     or p_variant_id is null
     or p_actor_id is null
     or nullif(trim(p_idempotency_key), '') is null
     or p_quantity_delta = 0 then
    raise exception 'VARIANT_STOCK_INVALID_INPUT';
  end if;

  if not exists (
    select 1
    from public.organization_members member
    where member.organization_id = p_organization_id
      and member.user_id = p_actor_id
      and member.status = 'active'
  ) then
    raise exception 'VARIANT_ACTOR_FORBIDDEN';
  end if;

  select movement.* into existing_movement
  from public.variant_inventory_movements movement
  where movement.organization_id = p_organization_id
    and movement.idempotency_key = trim(p_idempotency_key);

  if found then
    return jsonb_build_object(
      'idempotent', true,
      'movement_id', existing_movement.id,
      'stock_before', existing_movement.stock_before,
      'stock_after', existing_movement.stock_after
    );
  end if;

  select inventory.* into inventory_row
  from public.branch_variant_inventory inventory
  where inventory.organization_id = p_organization_id
    and inventory.branch_id = p_branch_id
    and inventory.variant_id = p_variant_id
  for update;

  if not found then
    raise exception 'VARIANT_BRANCH_FORBIDDEN';
  end if;

  resulting_stock := inventory_row.stock_quantity + p_quantity_delta;
  if resulting_stock < 0 then
    raise exception 'VARIANT_STOCK_INSUFFICIENT|%|%',
      p_variant_id,
      inventory_row.stock_quantity;
  end if;

  update public.branch_variant_inventory
  set stock_quantity = resulting_stock,
      updated_at = now()
  where organization_id = p_organization_id
    and branch_id = p_branch_id
    and variant_id = p_variant_id;

  insert into public.variant_inventory_movements (
    organization_id,
    branch_id,
    product_id,
    variant_id,
    movement_type,
    quantity_delta,
    stock_before,
    stock_after,
    idempotency_key,
    reference_type,
    reference_id,
    reason,
    actor_id,
    metadata
  ) values (
    p_organization_id,
    p_branch_id,
    inventory_row.product_id,
    p_variant_id,
    p_movement_type,
    p_quantity_delta,
    inventory_row.stock_quantity,
    resulting_stock,
    trim(p_idempotency_key),
    nullif(trim(p_reference_type), ''),
    p_reference_id,
    nullif(trim(p_reason), ''),
    p_actor_id,
    coalesce(p_metadata, '{}'::jsonb)
  ) returning id into existing_movement.id;

  return jsonb_build_object(
    'idempotent', false,
    'movement_id', existing_movement.id,
    'stock_before', inventory_row.stock_quantity,
    'stock_after', resulting_stock
  );
exception
  when unique_violation then
    select movement.* into existing_movement
    from public.variant_inventory_movements movement
    where movement.organization_id = p_organization_id
      and movement.idempotency_key = trim(p_idempotency_key);

    if found then
      return jsonb_build_object(
        'idempotent', true,
        'movement_id', existing_movement.id,
        'stock_before', existing_movement.stock_before,
        'stock_after', existing_movement.stock_after
      );
    end if;
    raise;
end;
$$;


ALTER FUNCTION "public"."adjust_variant_stock_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_variant_id" "uuid", "p_quantity_delta" integer, "p_movement_type" "text", "p_idempotency_key" "text", "p_actor_id" "uuid", "p_reference_type" "text", "p_reference_id" "uuid", "p_reason" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_customer_order_status_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_to_status" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  order_row public.customer_orders%rowtype;
  target text := upper(coalesce(p_to_status, ''));
  expected text;
begin
  if p_actor_id is null or not exists (
    select 1 from public.organization_members membership
    where membership.organization_id = p_organization_id
      and membership.user_id = p_actor_id and membership.status = 'active'
      and membership.role in ('owner', 'admin', 'manager', 'seller', 'cashier')
  ) then raise exception 'ORDER_PERMISSION_DENIED'; end if;

  select * into order_row from public.customer_orders
  where id = p_order_id and organization_id = p_organization_id for update;
  if not found then raise exception 'ORDER_NOT_FOUND'; end if;
  if order_row.status = target then
    return jsonb_build_object('order_id', order_row.id, 'unchanged', true);
  end if;
  if order_row.status in ('DELIVERED', 'CANCELLED') then raise exception 'ORDER_TERMINAL'; end if;

  expected := case order_row.status
    when 'PENDING' then 'CONFIRMED'
    when 'CONFIRMED' then 'PREPARING'
    when 'PREPARING' then 'READY'
    when 'READY' then case when order_row.fulfillment_type = 'PICKUP' then 'DELIVERED' else 'SHIPPED' end
    when 'SHIPPED' then 'DELIVERED'
    else null end;
  if target is distinct from expected then raise exception 'ORDER_TRANSITION_INVALID'; end if;

  update public.customer_orders set status = target,
    delivered_at = case when target = 'DELIVERED' then now() else delivered_at end,
    updated_at = now()
  where id = order_row.id and organization_id = p_organization_id;
  insert into public.customer_order_status_history
    (organization_id, order_id, from_status, to_status, note, changed_by)
  values (p_organization_id, order_row.id, order_row.status, target, nullif(trim(p_note), ''), p_actor_id);
  return jsonb_build_object('order_id', order_row.id, 'unchanged', false);
end;
$$;


ALTER FUNCTION "public"."advance_customer_order_status_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_to_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_can_view_cost"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    -- admin / super_admin siempre ven el costo
    EXISTS (
      SELECT 1 FROM public.user_roles ur
      WHERE ur.user_id = auth.uid()
        AND ur.is_active IS NOT FALSE
        AND lower(ur.role) IN ('admin', 'super_admin')
    )
    OR EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND lower(p.role) IN ('admin', 'super_admin')
    )
    -- o cualquier usuario con el permiso específico products.read_cost
    OR EXISTS (
      SELECT 1 FROM public.user_permissions up
      WHERE up.user_id = auth.uid()
        AND up.permission = 'products.read_cost'
        AND up.is_active IS NOT FALSE
    );
$$;


ALTER FUNCTION "public"."app_can_view_cost"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_free_subscription_plan"("p_organization_id" "uuid", "p_plan" "text" DEFAULT 'FREE'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_plan <> 'FREE' then
    raise exception 'Solo el plan gratuito puede aplicarse sin confirmacion de pago.';
  end if;

  if not exists (select 1 from public.organizations where id = p_organization_id) then
    return false;
  end if;

  insert into public.subscriptions (
    organization_id,
    plan,
    status,
    payment_status,
    cancel_at_period_end,
    current_period_starts_at,
    current_period_ends_at,
    updated_at
  )
  values (
    p_organization_id,
    p_plan,
    'active',
    'manual',
    false,
    null,
    null,
    now()
  )
  on conflict (organization_id)
  do update set
    plan = excluded.plan,
    status = 'active',
    payment_status = 'manual',
    cancel_at_period_end = false,
    current_period_starts_at = null,
    current_period_ends_at = null,
    updated_at = now();

  update public.organizations
     set plan = p_plan,
         updated_at = now()
   where id = p_organization_id;

  return true;
end;
$$;


ALTER FUNCTION "public"."apply_free_subscription_plan"("p_organization_id" "uuid", "p_plan" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_installment_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  inst_id UUID;
  credit UUID;
  total NUMERIC;
  total_capped NUMERIC;
  inst_amount NUMERIC;
  inst_due TIMESTAMPTZ;
  new_status TEXT;
  payment_method_value TEXT;
BEGIN
  inst_id := COALESCE(NEW.installment_id, OLD.installment_id);
  IF inst_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT credit_id, amount, due_date
  INTO credit, inst_amount, inst_due
  FROM public.credit_installments
  WHERE id = inst_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(SUM(amount), 0)
  INTO total
  FROM public.credit_payments
  WHERE installment_id = inst_id;

  total_capped := LEAST(total, inst_amount);

  payment_method_value := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE NEW.payment_method END;

  IF total_capped >= inst_amount THEN
    UPDATE public.credit_installments
    SET amount_paid = total_capped,
        status = 'paid',
        paid_at = COALESCE(paid_at, NOW()),
        payment_method = COALESCE(payment_method_value, payment_method),
        updated_at = NOW()
    WHERE id = inst_id;
  ELSE
    new_status := CASE WHEN inst_due < NOW() THEN 'late' ELSE 'pending' END;
    UPDATE public.credit_installments
    SET amount_paid = total_capped,
        status = new_status,
        paid_at = NULL,
        payment_method = COALESCE(payment_method_value, payment_method),
        updated_at = NOW()
    WHERE id = inst_id;
  END IF;

  IF credit IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.credit_installments
      WHERE credit_id = credit
        AND status <> 'paid'
    ) THEN
      UPDATE public.customer_credits
      SET status = 'completed', updated_at = NOW()
      WHERE id = credit;
    ELSE
      UPDATE public.customer_credits
      SET status = 'active', updated_at = NOW()
      WHERE id = credit
        AND status = 'completed';
    END IF;
  END IF;

  RETURN NULL;
END
$$;


ALTER FUNCTION "public"."apply_installment_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_paid_subscription_payment"("p_external_reference" "text", "p_provider_payment_id" "text", "p_payment_method" "text", "p_paid_at" timestamp with time zone, "p_amount" numeric DEFAULT NULL::numeric) RETURNS TABLE("applied" boolean, "organization_id" "uuid", "plan_id" "text", "payment_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_payment public.subscription_payments%rowtype;
  v_existing_plan text;
  v_existing_period_end timestamptz;
  v_paid_at timestamptz := coalesce(p_paid_at, now());
  v_period_start timestamptz;
  v_period_end timestamptz;
begin
  if nullif(trim(p_external_reference), '') is null then
    raise exception 'La referencia externa es obligatoria.';
  end if;

  select *
    into v_payment
    from public.subscription_payments
   where provider = 'pagopar'
     and external_reference = p_external_reference
   for update;

  if not found then
    raise exception 'Pago de suscripcion no encontrado.';
  end if;

  if v_payment.plan_id is null then
    raise exception 'El pago no tiene un plan destino.';
  end if;

  if p_amount is not null and abs(v_payment.amount - p_amount) > 0.5 then
    raise exception 'El monto notificado no coincide con el pago pendiente.';
  end if;

  if v_payment.status = 'paid' then
    return query
      select false, v_payment.organization_id, v_payment.plan_id, v_payment.id;
    return;
  end if;

  select s.plan, s.current_period_ends_at
    into v_existing_plan, v_existing_period_end
    from public.subscriptions s
   where s.organization_id = v_payment.organization_id;

  v_period_start := case
    when v_existing_plan = v_payment.plan_id
      and v_existing_period_end is not null
      and v_existing_period_end > v_paid_at
    then v_existing_period_end
    else v_paid_at
  end;
  v_period_end := v_period_start + interval '1 month';

  update public.subscription_payments
     set status = 'paid',
         payment_method = coalesce(nullif(trim(p_payment_method), ''), 'Pagopar'),
         provider_payment_id = nullif(trim(p_provider_payment_id), ''),
         paid_at = v_paid_at
   where id = v_payment.id;

  insert into public.subscriptions (
    organization_id,
    plan,
    status,
    provider,
    provider_subscription_id,
    external_reference,
    payment_status,
    last_payment_method,
    started_at,
    current_period_starts_at,
    current_period_ends_at,
    cancel_at_period_end,
    updated_at
  )
  values (
    v_payment.organization_id,
    v_payment.plan_id,
    'active',
    'pagopar',
    p_external_reference,
    p_external_reference,
    'paid',
    coalesce(nullif(trim(p_payment_method), ''), 'Pagopar'),
    v_paid_at,
    v_period_start,
    v_period_end,
    false,
    now()
  )
  on conflict (organization_id)
  do update set
    plan = excluded.plan,
    status = 'active',
    provider = 'pagopar',
    provider_subscription_id = excluded.provider_subscription_id,
    external_reference = excluded.external_reference,
    payment_status = 'paid',
    last_payment_method = excluded.last_payment_method,
    started_at = coalesce(public.subscriptions.started_at, excluded.started_at),
    current_period_starts_at = excluded.current_period_starts_at,
    current_period_ends_at = excluded.current_period_ends_at,
    cancel_at_period_end = false,
    updated_at = now();

  update public.organizations
     set plan = v_payment.plan_id,
         updated_at = now()
   where id = v_payment.organization_id;

  insert into public.tenant_audit_log (
    organization_id,
    action,
    resource,
    resource_id,
    metadata
  )
  values (
    v_payment.organization_id,
    'subscription.payment_confirmed',
    'subscription_payments',
    v_payment.id::text,
    jsonb_build_object(
      'plan', v_payment.plan_id,
      'amount', v_payment.amount,
      'provider', 'pagopar',
      'external_reference', p_external_reference
    )
  );

  return query
    select true, v_payment.organization_id, v_payment.plan_id, v_payment.id;
end;
$$;


ALTER FUNCTION "public"."apply_paid_subscription_payment"("p_external_reference" "text", "p_provider_payment_id" "text", "p_payment_method" "text", "p_paid_at" timestamp with time zone, "p_amount" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_paid_subscription_payment"("p_external_reference" "text", "p_provider_payment_id" "text", "p_payment_method" "text", "p_paid_at" timestamp with time zone, "p_amount" numeric) IS 'Idempotently confirms one Pagopar payment and activates its target plan in a single transaction.';



CREATE OR REPLACE FUNCTION "public"."apply_pos_payment_metadata_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_sale_id" "uuid", "p_actor_id" "uuid", "p_payments" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  payment record;
begin
  if not exists (
    select 1
    from public.organization_members membership
    where membership.organization_id = p_organization_id
      and membership.user_id = p_actor_id
      and membership.status = 'active'
      and membership.role in ('owner', 'admin', 'manager', 'cashier', 'technician', 'seller')
  ) then
    raise exception 'POS_PERMISSION_DENIED';
  end if;

  if not exists (
    select 1 from public.sales sale
    where sale.id = p_sale_id
      and sale.organization_id = p_organization_id
      and sale.branch_id = p_branch_id
  ) then
    raise exception 'SALE_NOT_IN_POS_SCOPE';
  end if;

  for payment in
    select
      entry.ordinality - 1 as payment_index,
      lower(trim(entry.value->>'payment_method')) as payment_method,
      nullif(left(trim(entry.value->>'provider'), 120), '') as provider,
      nullif(left(trim(entry.value->>'institution'), 120), '') as institution,
      nullif(left(trim(entry.value->>'terminal_id'), 80), '') as terminal_id,
      case lower(trim(entry.value->>'channel'))
        when 'qr' then 'qr'
        when 'bank_transfer' then 'bank_transfer'
        when 'card_terminal' then 'card_terminal'
        else null
      end as requested_channel
    from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) with ordinality entry(value, ordinality)
  loop
    update public.sale_payments stored
    set
      branch_id = p_branch_id,
      channel = coalesce(payment.requested_channel, case payment.payment_method
        when 'cash' then 'cash'
        when 'card' then 'card_terminal'
        when 'transfer' then 'bank_transfer'
        when 'credit' then 'credit'
        else 'other'
      end),
      provider = coalesce(payment.provider, case payment.payment_method when 'card' then 'Terminal POS' else null end),
      institution = payment.institution,
      terminal_id = payment.terminal_id,
      reconciliation_status = case
        when payment.payment_method in ('card', 'transfer') then 'pending'
        else 'not_applicable'
      end,
      updated_at = now()
    where stored.organization_id = p_organization_id
      and stored.sale_id = p_sale_id
      and stored.payment_index = payment.payment_index;
  end loop;
end;
$$;


ALTER FUNCTION "public"."apply_pos_payment_metadata_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_sale_id" "uuid", "p_actor_id" "uuid", "p_payments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_payroll_run_atomic"("p_organization_id" "uuid", "p_payroll_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_id uuid := auth.uid();
  target_run public.payroll_runs%rowtype;
  entries_base_amount numeric(14, 2);
  entries_commission_amount numeric(14, 2);
  entries_adjustment_amount numeric(14, 2);
  entries_gross_amount numeric(14, 2);
  entries_net_amount numeric(14, 2);
begin
  if actor_id is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;
  if not (
    public.has_org_permission(p_organization_id, 'finances.manage')
    or public.get_user_role(actor_id) = 'super_admin'
  ) then
    raise exception 'PAYROLL_APPROVAL_PERMISSION_DENIED';
  end if;

  select run.*
  into target_run
  from public.payroll_runs run
  where run.organization_id = p_organization_id
    and run.id = p_payroll_run_id
  for update;

  if not found then
    raise exception 'PAYROLL_RUN_NOT_FOUND';
  end if;
  if target_run.branch_id is not null
     and not public.user_has_branch_access(target_run.branch_id, actor_id) then
    raise exception 'PAYROLL_BRANCH_PERMISSION_DENIED';
  end if;
  if target_run.status = 'approved' then
    return to_jsonb(target_run);
  end if;
  if target_run.status <> 'draft' then
    raise exception 'PAYROLL_RUN_NOT_APPROVABLE';
  end if;
  if not exists (
    select 1
    from public.payroll_entries entry
    where entry.organization_id = p_organization_id
      and entry.payroll_run_id = p_payroll_run_id
  ) then
    raise exception 'PAYROLL_RUN_HAS_NO_ENTRIES';
  end if;

  perform 1
  from public.payroll_entries entry
  where entry.organization_id = p_organization_id
    and entry.payroll_run_id = p_payroll_run_id
  order by entry.id
  for update;

  if target_run.run_type = 'standard' and exists (
    select 1
    from public.payroll_entries entry
    left join public.payroll_entry_commissions link
      on link.organization_id = entry.organization_id
     and link.payroll_entry_id = entry.id
    left join public.earned_commissions commission
      on commission.organization_id = link.organization_id
     and commission.id = link.earned_commission_id
    where entry.organization_id = p_organization_id
      and entry.payroll_run_id = p_payroll_run_id
    group by entry.id, entry.commission_amount
    having entry.commission_amount is distinct from
      coalesce(sum(commission.amount), 0)::numeric(14, 2)
  ) then
    raise exception 'PAYROLL_COMMISSION_SNAPSHOT_MISMATCH';
  end if;

  select
    coalesce(sum(entry.base_amount), 0)::numeric(14, 2),
    coalesce(sum(entry.commission_amount), 0)::numeric(14, 2),
    coalesce(sum(entry.adjustment_amount), 0)::numeric(14, 2),
    coalesce(sum(entry.gross_amount), 0)::numeric(14, 2),
    coalesce(sum(entry.net_amount), 0)::numeric(14, 2)
  into
    entries_base_amount,
    entries_commission_amount,
    entries_adjustment_amount,
    entries_gross_amount,
    entries_net_amount
  from public.payroll_entries entry
  where entry.organization_id = p_organization_id
    and entry.payroll_run_id = p_payroll_run_id;

  if target_run.base_amount is distinct from entries_base_amount
     or target_run.commission_amount is distinct from entries_commission_amount
     or target_run.adjustment_amount is distinct from entries_adjustment_amount
     or target_run.gross_amount is distinct from entries_gross_amount
     or target_run.net_amount is distinct from entries_net_amount then
    raise exception 'PAYROLL_RUN_TOTALS_MISMATCH';
  end if;

  update public.payroll_runs run
  set
    status = 'approved',
    approved_by = actor_id,
    approved_at = now(),
    updated_at = now()
  where run.organization_id = p_organization_id
    and run.id = p_payroll_run_id
  returning run.* into target_run;

  return to_jsonb(target_run);
end;
$$;


ALTER FUNCTION "public"."approve_payroll_run_atomic"("p_organization_id" "uuid", "p_payroll_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_old_product_alerts"("months_to_keep" integer DEFAULT 6) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    moved_count INT;
BEGIN
    IF to_regclass('public.product_alerts_archive') IS NULL THEN
      RETURN;
    END IF;

    WITH moved AS (
        DELETE FROM public.product_alerts
        WHERE created_at < NOW() - (months_to_keep || ' months')::interval
        RETURNING id, product_id, alert_type, message, details, read, is_resolved, resolved_at, created_at
    )
    INSERT INTO public.product_alerts_archive (id, product_id, type, message, details, read, is_resolved, resolved_at, created_at)
    SELECT id, product_id, alert_type, message, details, read, is_resolved, resolved_at, created_at FROM moved;

    GET DIAGNOSTICS moved_count = ROW_COUNT;

    RAISE NOTICE 'Archived % product alerts older than % months.', moved_count, months_to_keep;
END;
$$;


ALTER FUNCTION "public"."archive_old_product_alerts"("months_to_keep" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_superadmin_organization_owner"("p_organization_id" "uuid", "p_user_id" "uuid", "p_email" "text", "p_full_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_profile_status text;
begin
  if not exists (select 1 from public.organizations where id = p_organization_id for update) then
    raise exception 'ORGANIZATION_NOT_FOUND';
  end if;

  select status into v_profile_status
    from public.profiles
   where id = p_user_id;

  if v_profile_status in ('inactive', 'suspended') then
    raise exception 'OWNER_SUSPENDED';
  end if;

  insert into public.profiles (id, email, full_name, role, status)
  values (p_user_id, lower(trim(p_email)), nullif(trim(p_full_name), ''), 'admin', 'active')
  on conflict (id) do update
    set email = coalesce(public.profiles.email, excluded.email),
        full_name = coalesce(public.profiles.full_name, excluded.full_name);

  insert into public.user_roles (user_id, role, is_active, updated_at)
  values (p_user_id, 'admin', true, now())
  on conflict (user_id) do nothing;

  insert into public.organization_members (organization_id, user_id, role, status)
  values (p_organization_id, p_user_id, 'owner', 'active')
  on conflict (organization_id, user_id) do update
    set role = 'owner',
        status = 'active',
        updated_at = now();

  update public.organizations
     set owner_id = p_user_id,
         updated_at = now()
   where id = p_organization_id;
end;
$$;


ALTER FUNCTION "public"."assign_superadmin_organization_owner"("p_organization_id" "uuid", "p_user_id" "uuid", "p_email" "text", "p_full_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_trigger_function"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO audit_log (user_id, action, resource_type, resource_id, new_values)
    VALUES (auth.uid(), 'create', TG_TABLE_NAME, NEW.id::TEXT, to_jsonb(NEW));
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO audit_log (user_id, action, resource_type, resource_id, old_values, new_values)
    VALUES (auth.uid(), 'update', TG_TABLE_NAME, NEW.id::TEXT, to_jsonb(OLD), to_jsonb(NEW));
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO audit_log (user_id, action, resource_type, resource_id, old_values)
    VALUES (auth.uid(), 'delete', TG_TABLE_NAME, OLD.id::TEXT, to_jsonb(OLD));
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."audit_trigger_function"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_map_tenant_categories"("p_organization_id" "uuid", "p_threshold" double precision DEFAULT 0.4) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count int := 0;
  v_cat   record;
  v_match uuid;
BEGIN
  FOR v_cat IN
    SELECT id, name
    FROM public.categories
    WHERE organization_id = p_organization_id
      AND global_category_id IS NULL
      AND is_active = true
  LOOP
    SELECT id INTO v_match
    FROM public.suggest_global_category(v_cat.name, 1, p_threshold)
    LIMIT 1;

    IF v_match IS NOT NULL THEN
      UPDATE public.categories
      SET global_category_id = v_match,
          updated_at = now()
      WHERE id = v_cat.id;
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."auto_map_tenant_categories"("p_organization_id" "uuid", "p_threshold" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_loyalty_points_for_sale"("p_organization_id" "uuid", "p_customer_id" "uuid", "p_amount" numeric, "p_sale_id" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "public"."loyalty_ledger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  settings public.loyalty_settings;
  rule public.loyalty_point_rules;
  existing public.loyalty_ledger;
  base_points integer := 0;
  bonus_points integer := 0;
  total_points integer := 0;
  customer_bonus_used integer := 0;
  earned_today integer := 0;
  daily_room integer;
  current_balance integer := 0;
  inserted public.loyalty_ledger;
  key text := p_idempotency_key;
begin
  if p_organization_id is null or p_customer_id is null then
    raise exception 'Falta la organización o el cliente.' using errcode = 'invalid_parameter_value';
  end if;

  -- 'pos.sales.create' es el permiso que tiene quien cierra una venta:
  -- cajero, vendedor, encargado, admin y dueño. Con un nombre que
  -- has_org_permission no conozca, solo pasarían dueño y admin y el POS
  -- dejaría de acreditar.
  if not (
    public.has_org_permission(p_organization_id, 'pos.sales.create')
    or public.has_org_permission(p_organization_id, 'repairs.orders.update')
  ) then
    raise exception 'No tenés permiso para acreditar puntos en esta organización.'
      using errcode = 'insufficient_privilege';
  end if;

  if key is null and p_sale_id is not null then
    key := 'sale:' || p_sale_id::text;
  end if;

  -- Idempotencia: si ya se acredito este hecho, se devuelve el asiento previo.
  if key is not null then
    select * into existing
    from public.loyalty_ledger
    where organization_id = p_organization_id
      and idempotency_key = key;

    if found then
      return existing;
    end if;
  end if;

  select * into settings
  from public.loyalty_settings
  where organization_id = p_organization_id;

  if not found or not settings.enabled then
    return null;
  end if;

  -- El cliente tiene que pertenecer a la organizacion.
  if not exists (
    select 1 from public.customers c
    where c.id = p_customer_id and c.organization_id = p_organization_id
  ) then
    raise exception 'El cliente no pertenece a la organización indicada.' using errcode = 'invalid_parameter_value';
  end if;

  base_points := public.calculate_base_loyalty_points(
    p_amount,
    settings.currency_per_point,
    settings.points_per_unit,
    settings.rounding
  );

  if base_points <= 0 then
    return null;
  end if;

  -- Promocion vigente: se toma la de mayor beneficio y se bloquea la fila para
  -- que dos ventas simultaneas no se pasen del cupo total.
  select * into rule
  from public.loyalty_point_rules r
  where r.organization_id = p_organization_id
    and r.is_active
    and now() >= r.starts_at
    and now() < r.ends_at
    and (r.min_purchase_amount is null or p_amount >= r.min_purchase_amount)
  order by
    case when r.kind = 'multiplier' then base_points * (r.multiplier - 1) else r.bonus_points end desc
  limit 1
  for update;

  if found then
    if rule.kind = 'multiplier' then
      bonus_points := greatest(0, floor(base_points * (rule.multiplier - 1))::integer);
    else
      bonus_points := rule.bonus_points;
    end if;

    -- Tope por cliente dentro de la promocion.
    if rule.max_bonus_points_per_customer is not null then
      select coalesce(sum(points), 0) into customer_bonus_used
      from public.loyalty_ledger
      where rule_id = rule.id and customer_id = p_customer_id and source = 'promotion';

      bonus_points := least(
        bonus_points,
        greatest(0, rule.max_bonus_points_per_customer - customer_bonus_used)
      );
    end if;

    -- Tope total de la promocion.
    if rule.max_bonus_points_total is not null then
      bonus_points := least(
        bonus_points,
        greatest(0, rule.max_bonus_points_total - rule.awarded_bonus_points)
      );
    end if;

    if bonus_points > 0 then
      update public.loyalty_point_rules
      set awarded_bonus_points = awarded_bonus_points + bonus_points
      where id = rule.id;
    end if;
  end if;

  total_points := base_points + bonus_points;

  -- Tope diario de la organizacion: acota el dano de un error de carga.
  if settings.max_points_per_customer_per_day is not null then
    select coalesce(sum(points), 0) into earned_today
    from public.loyalty_ledger
    where customer_id = p_customer_id
      and points > 0
      and created_at >= date_trunc('day', now());

    daily_room := greatest(0, settings.max_points_per_customer_per_day - earned_today);
    total_points := least(total_points, daily_room);
  end if;

  if total_points <= 0 then
    return null;
  end if;

  select coalesce(balance, 0) into current_balance
  from public.loyalty_accounts
  where customer_id = p_customer_id;

  current_balance := coalesce(current_balance, 0);

  insert into public.loyalty_ledger (
    organization_id, customer_id, points, balance_after, source, description,
    sale_id, rule_id, idempotency_key, expires_at, created_by
  )
  values (
    p_organization_id,
    p_customer_id,
    total_points,
    current_balance + total_points,
    case when bonus_points > 0 then 'promotion' else 'purchase' end,
    case
      when bonus_points > 0 then
        format('Compra: %s puntos base + %s de bonificación (%s)', base_points, bonus_points, coalesce(rule.name, 'promoción'))
      else format('Compra: %s puntos', base_points)
    end,
    p_sale_id,
    case when bonus_points > 0 then rule.id else null end,
    key,
    case
      when settings.points_expiration_months is not null
        then now() + make_interval(months => settings.points_expiration_months)
      else null
    end,
    auth.uid()
  )
  returning * into inserted;

  return inserted;
end;
$$;


ALTER FUNCTION "public"."award_loyalty_points_for_sale"("p_organization_id" "uuid", "p_customer_id" "uuid", "p_amount" numeric, "p_sale_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bootstrap_first_admin"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  current_user_id UUID := auth.uid();
  current_email TEXT;
BEGIN
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('bootstrap_first_admin'));

  IF EXISTS (
    SELECT 1
    FROM public.user_roles
    WHERE role IN ('admin', 'super_admin')
      AND is_active = TRUE
  ) OR EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE role IN ('admin', 'super_admin')
  ) THEN
    RETURN FALSE;
  END IF;

  SELECT email INTO current_email
  FROM auth.users
  WHERE id = current_user_id;

  INSERT INTO public.profiles (id, email, role, status, updated_at)
  VALUES (current_user_id, current_email, 'admin', 'active', NOW())
  ON CONFLICT (id) DO UPDATE
  SET role = 'admin',
      status = 'active',
      updated_at = NOW();

  INSERT INTO public.user_roles (user_id, role, is_active, updated_at)
  VALUES (current_user_id, 'admin', TRUE, NOW())
  ON CONFLICT (user_id) DO UPDATE
  SET role = 'admin',
      is_active = TRUE,
      updated_at = NOW();

  INSERT INTO public.audit_log (
    user_id,
    action,
    resource,
    resource_id,
    new_values,
    created_at
  )
  VALUES (
    current_user_id,
    'grant_admin_self_rpc',
    'auth',
    current_user_id::TEXT,
    jsonb_build_object('role', 'admin', 'is_first_admin', TRUE),
    NOW()
  );

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."bootstrap_first_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_base_loyalty_points"("p_amount" numeric, "p_currency_per_point" numeric, "p_points_per_unit" integer, "p_rounding" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  raw_points numeric;
begin
  if p_amount is null or p_amount <= 0 or p_currency_per_point is null or p_currency_per_point <= 0 then
    return 0;
  end if;

  raw_points := (p_amount / p_currency_per_point) * coalesce(p_points_per_unit, 1);

  if p_rounding = 'round' then
    return greatest(0, round(raw_points)::integer);
  end if;

  return greatest(0, floor(raw_points)::integer);
end;
$$;


ALTER FUNCTION "public"."calculate_base_loyalty_points"("p_amount" numeric, "p_currency_per_point" numeric, "p_points_per_unit" integer, "p_rounding" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_cash_session_expected"("p_session_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(sum(
    case
      when m.type = 'opening' then m.amount
      when m.type = 'cash_in' and coalesce(m.payment_method, 'cash') in ('cash', 'efectivo') then m.amount
      when m.type = 'sale' and coalesce(m.payment_method, 'cash') = 'cash' then m.amount
      when m.type = 'sale' and m.payment_method = 'efectivo' then m.amount
      when m.type = 'cash_out' and coalesce(m.payment_method, 'cash') in ('cash', 'efectivo') then -m.amount
      else 0
    end
  ), 0)
  from public.cash_movements m
  where m.session_id = p_session_id
    and m.organization_id = p_organization_id
    and m.branch_id = p_branch_id;
$$;


ALTER FUNCTION "public"."calculate_cash_session_expected"("p_session_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_earned_commissions"("p_organization_id" "uuid", "p_period_from" "date", "p_period_to" "date", "p_branch_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_id uuid := auth.uid();
  organization_timezone text := 'America/Asuncion';
  accrual_count integer := 0;
  terminal_reversal_count integer := 0;
  refund_reversal_count integer := 0;
begin
  if p_organization_id is null then
    raise exception 'PAYROLL_ORGANIZATION_REQUIRED';
  end if;
  if p_period_from is null or p_period_to is null or p_period_to < p_period_from then
    raise exception 'PAYROLL_INVALID_PERIOD';
  end if;
  if actor_id is not null and not (
    public.has_org_permission(p_organization_id, 'finances.manage')
    or public.get_user_role(actor_id) = 'super_admin'
  ) then
    raise exception 'PAYROLL_COMMISSION_PERMISSION_DENIED';
  end if;
  if p_branch_id is not null then
    if not exists (
      select 1
      from public.branches branch
      where branch.organization_id = p_organization_id
        and branch.id = p_branch_id
        and branch.is_active = true
    ) then
      raise exception 'PAYROLL_BRANCH_NOT_IN_ORGANIZATION';
    end if;
    if actor_id is not null and not public.user_has_branch_access(p_branch_id, actor_id) then
      raise exception 'PAYROLL_BRANCH_PERMISSION_DENIED';
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':earned-commissions',
    0
  ));

  select timezone_record.name
  into organization_timezone
  from public.organization_settings settings
  join pg_timezone_names timezone_record
    on timezone_record.name = settings.timezone
  where settings.organization_id = p_organization_id
  limit 1;
  organization_timezone := coalesce(organization_timezone, 'America/Asuncion');

  with operation_candidates as (
    select
      'sale:' || attribution.source_id::text as candidate_key,
      attribution.employee_id,
      attribution.employee_role,
      attribution.branch_id,
      'sale'::text as source_type,
      null::uuid as source_reference_id,
      null::text as accrual_status,
      'sale'::text as origin_type,
      attribution.source_id as origin_id,
      attribution.source_id as parent_origin_id,
      null::numeric(14, 4) as source_quantity,
      attribution.occurred_at,
      (attribution.occurred_at at time zone organization_timezone)::date as occurred_on,
      attribution.basis_amount
    from public.commission_operation_attributions attribution
    where attribution.organization_id = p_organization_id
      and attribution.source_type = 'sale'
      and (p_branch_id is null or attribution.branch_id = p_branch_id)
      and (attribution.occurred_at at time zone organization_timezone)::date
        between p_period_from and p_period_to
      and attribution.basis_amount > 0

    union all

    select
      'product:' || item_attribution.sale_item_id::text,
      attribution.employee_id,
      attribution.employee_role,
      attribution.branch_id,
      'product'::text,
      item_attribution.product_id,
      null::text,
      'sale_item'::text,
      item_attribution.sale_item_id,
      item_attribution.sale_id,
      item_attribution.quantity,
      attribution.occurred_at,
      (attribution.occurred_at at time zone organization_timezone)::date,
      item_attribution.subtotal::numeric(14, 2)
    from public.commission_operation_attributions attribution
    join public.commission_sale_item_attributions item_attribution
      on item_attribution.organization_id = attribution.organization_id
     and item_attribution.sale_id = attribution.source_id
    where attribution.organization_id = p_organization_id
      and attribution.source_type = 'sale'
      and (p_branch_id is null or attribution.branch_id = p_branch_id)
      and (attribution.occurred_at at time zone organization_timezone)::date
        between p_period_from and p_period_to
      and item_attribution.product_id is not null
      and item_attribution.subtotal > 0

    union all

    select
      'category:' || item_attribution.sale_item_id::text,
      attribution.employee_id,
      attribution.employee_role,
      attribution.branch_id,
      'category'::text,
      item_attribution.category_id,
      null::text,
      'sale_item'::text,
      item_attribution.sale_item_id,
      item_attribution.sale_id,
      item_attribution.quantity,
      attribution.occurred_at,
      (attribution.occurred_at at time zone organization_timezone)::date,
      item_attribution.subtotal::numeric(14, 2)
    from public.commission_operation_attributions attribution
    join public.commission_sale_item_attributions item_attribution
      on item_attribution.organization_id = attribution.organization_id
     and item_attribution.sale_id = attribution.source_id
    where attribution.organization_id = p_organization_id
      and attribution.source_type = 'sale'
      and (p_branch_id is null or attribution.branch_id = p_branch_id)
      and (attribution.occurred_at at time zone organization_timezone)::date
        between p_period_from and p_period_to
      and item_attribution.category_id is not null
      and item_attribution.subtotal > 0

    union all

    select
      'repair:' || attribution.source_id::text,
      attribution.employee_id,
      attribution.employee_role,
      attribution.branch_id,
      'repair'::text,
      null::uuid,
      attribution.accrual_status,
      'repair'::text,
      attribution.source_id,
      attribution.source_id,
      null::numeric(14, 4),
      attribution.occurred_at,
      (attribution.occurred_at at time zone organization_timezone)::date,
      attribution.basis_amount
    from public.commission_operation_attributions attribution
    where attribution.organization_id = p_organization_id
      and attribution.source_type = 'repair'
      and (p_branch_id is null or attribution.branch_id = p_branch_id)
      and (attribution.occurred_at at time zone organization_timezone)::date
        between p_period_from and p_period_to
      and attribution.basis_amount > 0

    union all

    select
      'repair-labor:' || attribution.source_id::text,
      attribution.employee_id,
      attribution.employee_role,
      attribution.branch_id,
      'repair_labor'::text,
      null::uuid,
      attribution.accrual_status,
      'repair'::text,
      attribution.source_id,
      attribution.source_id,
      null::numeric(14, 4),
      attribution.occurred_at,
      (attribution.occurred_at at time zone organization_timezone)::date,
      attribution.labor_basis_amount
    from public.commission_operation_attributions attribution
    where attribution.organization_id = p_organization_id
      and attribution.source_type = 'repair'
      and (p_branch_id is null or attribution.branch_id = p_branch_id)
      and (attribution.occurred_at at time zone organization_timezone)::date
        between p_period_from and p_period_to
      and attribution.labor_basis_amount > 0
  ),
  ranked_rules as (
    select
      candidate.*,
      rule.id as commission_rule_id,
      rule.calculation_type,
      rule.value,
      row_number() over (
        partition by candidate.candidate_key, rule.calculation_type
        order by
          case when rule.scope_type = 'employee' then 1 else 0 end desc,
          case when rule.branch_id is not null then 1 else 0 end desc,
          candidate.occurred_at,
          rule.effective_from desc,
          rule.id
      ) as rule_rank
    from operation_candidates candidate
    join public.commission_rules rule
      on rule.organization_id = p_organization_id
     and rule.status = 'approved'
     and rule.source_type = candidate.source_type
     and (rule.branch_id is null or rule.branch_id = candidate.branch_id)
     and rule.effective_from <= candidate.occurred_on
     and (rule.effective_to is null or rule.effective_to >= candidate.occurred_on)
     and candidate.occurred_on >= coalesce(rule.legacy_cutover_on, rule.effective_from)
     and rule.source_reference_id is not distinct from candidate.source_reference_id
     and (
       candidate.source_type not in ('repair', 'repair_labor')
       or (
         rule.accrual_status = 'entregado'
         and candidate.accrual_status = 'entregado'
       )
       or (
         rule.accrual_status = 'listo'
         and candidate.accrual_status in ('listo', 'entregado')
       )
     )
     and (
       (
         rule.scope_type = 'employee'
         and rule.employee_id = candidate.employee_id
       )
       or (
         rule.scope_type = 'role'
         and rule.role = candidate.employee_role
       )
     )
  )
  insert into public.earned_commissions (
    organization_id,
    branch_id,
    employee_id,
    commission_rule_id,
    entry_kind,
    source_type,
    origin_type,
    origin_id,
    origin_key,
    occurred_on,
    basis_amount,
    amount,
    employee_role,
    rule_snapshot
  )
  select
    p_organization_id,
    ranked.branch_id,
    ranked.employee_id,
    ranked.commission_rule_id,
    'accrual',
    ranked.source_type,
    ranked.origin_type,
    ranked.origin_id,
    'accrual:' || ranked.source_type || ':' || ranked.origin_id::text
      || ':' || ranked.calculation_type,
    ranked.occurred_on,
    ranked.basis_amount,
    case ranked.calculation_type
      when 'percentage' then round(ranked.basis_amount * ranked.value / 100, 2)
      else ranked.value
    end,
    ranked.employee_role,
    jsonb_build_object(
      'calculation_type', ranked.calculation_type,
      'value', ranked.value,
      'source_type', ranked.source_type,
      'accrual_status', ranked.accrual_status,
      'parent_origin_id', ranked.parent_origin_id,
      'source_quantity', ranked.source_quantity
    )
  from ranked_rules ranked
  where ranked.rule_rank = 1
    and case ranked.calculation_type
      when 'percentage' then round(ranked.basis_amount * ranked.value / 100, 2)
      else ranked.value
    end > 0
  on conflict (organization_id, origin_key) do nothing;

  get diagnostics accrual_count = row_count;

  with terminal_events as (
    select
      commission.id as accrual_id,
      terminal_event.source_id as terminal_origin_id,
      (terminal_event.occurred_at at time zone organization_timezone)::date as reversed_on
    from public.earned_commissions commission
    join public.commission_terminal_events terminal_event
      on commission.origin_type = 'sale'
     and terminal_event.organization_id = commission.organization_id
     and terminal_event.branch_id = commission.branch_id
     and terminal_event.source_type = 'sale'
     and terminal_event.source_id = commission.origin_id
    where commission.organization_id = p_organization_id
      and commission.entry_kind = 'accrual'
      and (p_branch_id is null or commission.branch_id = p_branch_id)
      and (terminal_event.occurred_at at time zone organization_timezone)::date
        <= p_period_to

    union all

    select
      commission.id,
      terminal_event.source_id,
      (terminal_event.occurred_at at time zone organization_timezone)::date
    from public.earned_commissions commission
    join public.commission_terminal_events terminal_event
      on terminal_event.organization_id = commission.organization_id
     and terminal_event.branch_id = commission.branch_id
     and terminal_event.source_type = 'sale'
     and terminal_event.source_id = (
       commission.rule_snapshot ->> 'parent_origin_id'
     )::uuid
    where commission.organization_id = p_organization_id
      and commission.entry_kind = 'accrual'
      and commission.origin_type = 'sale_item'
      and (p_branch_id is null or commission.branch_id = p_branch_id)
      and (terminal_event.occurred_at at time zone organization_timezone)::date
        <= p_period_to

    union all

    select
      commission.id,
      terminal_event.source_id,
      (terminal_event.occurred_at at time zone organization_timezone)::date
    from public.earned_commissions commission
    join public.commission_terminal_events terminal_event
      on commission.origin_type = 'repair'
     and terminal_event.organization_id = commission.organization_id
     and terminal_event.branch_id = commission.branch_id
     and terminal_event.source_type = 'repair'
     and terminal_event.source_id = commission.origin_id
    where commission.organization_id = p_organization_id
      and commission.entry_kind = 'accrual'
      and (p_branch_id is null or commission.branch_id = p_branch_id)
      and (terminal_event.occurred_at at time zone organization_timezone)::date
        <= p_period_to
  ),
  terminal_accruals as (
    select distinct on (event.accrual_id)
      accrual.*,
      event.terminal_origin_id,
      event.reversed_on,
      greatest(
        accrual.amount + coalesce(sum(existing_reversal.amount), 0),
        0
      )::numeric(14, 2) as remaining_amount
    from terminal_events event
    join public.earned_commissions accrual
      on accrual.organization_id = p_organization_id
     and accrual.id = event.accrual_id
    left join public.earned_commissions existing_reversal
      on existing_reversal.organization_id = accrual.organization_id
     and existing_reversal.reverses_commission_id = accrual.id
     and existing_reversal.entry_kind = 'reversal'
    group by accrual.id, event.terminal_origin_id, event.reversed_on
    order by event.accrual_id, event.reversed_on, event.terminal_origin_id
  )
  insert into public.earned_commissions (
    organization_id,
    branch_id,
    employee_id,
    commission_rule_id,
    entry_kind,
    source_type,
    origin_type,
    origin_id,
    origin_key,
    reverses_commission_id,
    occurred_on,
    basis_amount,
    amount,
    employee_role,
    rule_snapshot
  )
  select
    terminal.organization_id,
    terminal.branch_id,
    terminal.employee_id,
    terminal.commission_rule_id,
    'reversal',
    terminal.source_type,
    'terminal_status',
    terminal.terminal_origin_id,
    'terminal-status:' || terminal.terminal_origin_id::text
      || ':' || terminal.id::text,
    terminal.id,
    terminal.reversed_on,
    terminal.basis_amount,
    -terminal.remaining_amount,
    terminal.employee_role,
    terminal.rule_snapshot || jsonb_build_object('reversal_reason', 'terminal_status')
  from terminal_accruals terminal
  where terminal.remaining_amount > 0
  on conflict (organization_id, origin_key) do nothing;

  get diagnostics terminal_reversal_count = row_count;

  with refund_matches as (
    select
      accrual.*,
      refund_event.id as refund_case_id,
      (refund_event.occurred_at at time zone organization_timezone)::date as refunded_on,
      least(
        1::numeric,
        greatest(
          0::numeric,
          case
            when accrual.origin_type = 'sale_item'
                 and refund_event.sale_item_id is not null then
              coalesce(
                refund_event.refund_quantity
                  / nullif(refund_event.source_quantity, 0),
                1
              )
            when refund_event.sale_id is not null then
              coalesce(
                refund_event.refund_amount / nullif(refund_event.source_amount, 0),
                1
              )
            when refund_event.repair_id is not null then
              coalesce(
                refund_event.refund_amount / nullif(refund_event.source_amount, 0),
                1
              )
            else 1
          end
        )
      ) as refund_ratio
    from public.commission_refund_events refund_event
    join public.earned_commissions accrual
      on accrual.organization_id = refund_event.organization_id
     and accrual.entry_kind = 'accrual'
     and (
       (accrual.origin_type = 'sale' and accrual.origin_id = refund_event.sale_id)
       or (
         accrual.origin_type = 'sale_item'
         and (accrual.rule_snapshot ->> 'parent_origin_id')::uuid = refund_event.sale_id
         and (
           refund_event.sale_item_id is null
           or refund_event.sale_item_id = accrual.origin_id
         )
       )
       or (accrual.origin_type = 'repair' and accrual.origin_id = refund_event.repair_id)
     )
    where refund_event.organization_id = p_organization_id
      and (p_branch_id is null or accrual.branch_id = p_branch_id)
      and (refund_event.occurred_at at time zone organization_timezone)::date
        <= p_period_to
      and not exists (
        select 1
        from public.earned_commissions materialized_reversal
        where materialized_reversal.organization_id = accrual.organization_id
          and materialized_reversal.origin_key = 'after-sales:'
            || refund_event.id::text || ':' || accrual.id::text
      )
  ),
  requested_refunds as (
    select
      refund.*,
      round(refund.amount * refund.refund_ratio, 2) as requested_amount,
      coalesce((
        select sum(existing_reversal.amount)
        from public.earned_commissions existing_reversal
        where existing_reversal.organization_id = refund.organization_id
          and existing_reversal.reverses_commission_id = refund.id
          and existing_reversal.entry_kind = 'reversal'
      ), 0) as existing_reversals
    from refund_matches refund
  ),
  bounded_refunds as (
    select
      requested.*,
      least(
        requested.requested_amount,
        greatest(
          requested.amount + requested.existing_reversals
            - coalesce(sum(requested.requested_amount) over (
                partition by requested.id
                order by requested.refunded_on, requested.refund_case_id
                rows between unbounded preceding and 1 preceding
              ), 0),
          0
        )
      )::numeric(14, 2) as reversal_amount
    from requested_refunds requested
  )
  insert into public.earned_commissions (
    organization_id,
    branch_id,
    employee_id,
    commission_rule_id,
    entry_kind,
    source_type,
    origin_type,
    origin_id,
    origin_key,
    reverses_commission_id,
    occurred_on,
    basis_amount,
    amount,
    employee_role,
    rule_snapshot
  )
  select
    refund.organization_id,
    refund.branch_id,
    refund.employee_id,
    refund.commission_rule_id,
    'reversal',
    refund.source_type,
    'after_sales',
    refund.refund_case_id,
    'after-sales:' || refund.refund_case_id::text || ':' || refund.id::text,
    refund.id,
    refund.refunded_on,
    refund.basis_amount,
    -refund.reversal_amount,
    refund.employee_role,
    refund.rule_snapshot || jsonb_build_object(
      'reversal_reason', 'refund',
      'refund_ratio', refund.refund_ratio
    )
  from bounded_refunds refund
  where refund.reversal_amount > 0
  on conflict (organization_id, origin_key) do nothing;

  get diagnostics refund_reversal_count = row_count;

  return accrual_count + terminal_reversal_count + refund_reversal_count;
end;
$$;


ALTER FUNCTION "public"."calculate_earned_commissions"("p_organization_id" "uuid", "p_period_from" "date", "p_period_to" "date", "p_branch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_repair_progress"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Calcular progreso basado en el estado
  NEW.progress = CASE NEW.status
    WHEN 'recibido' THEN 10
    WHEN 'diagnostico' THEN 30
    WHEN 'reparacion' THEN 60
    WHEN 'listo' THEN 100
    WHEN 'entregado' THEN 100
    ELSE NEW.progress
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_repair_progress"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_customer_order_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare order_row public.customer_orders%rowtype; released_amount numeric := 0;
begin
  select * into order_row from public.customer_orders customer_order
  where customer_order.id = p_order_id and customer_order.organization_id = p_organization_id for update;
  if not found then raise exception 'ORDER_NOT_FOUND'; end if;
  if order_row.status = 'CANCELLED' then
    return jsonb_build_object('order_id', order_row.id, 'from_status', order_row.status,
      'stock_released', false, 'store_credit_released', 0);
  end if;
  update public.customer_store_credit_reservations set status = 'released', released_at = now(), updated_at = now()
  where organization_id = p_organization_id and order_id = p_order_id and status = 'reserved'
  returning amount into released_amount;

  if order_row.stock_reserved then
    update public.product_variants variant
    set stock_quantity = variant.stock_quantity + quantities.quantity, updated_at = now()
    from (
      select order_item.variant_id, sum(order_item.quantity)::integer quantity
      from public.customer_order_items order_item
      where order_item.order_id = order_row.id and order_item.variant_id is not null
      group by order_item.variant_id
    ) quantities
    where variant.id = quantities.variant_id and variant.organization_id = p_organization_id;

    if order_row.branch_id is null then
      update public.products product set stock_quantity = product.stock_quantity + quantities.quantity, updated_at = now()
      from (
        select order_item.product_id, sum(order_item.quantity)::integer quantity
        from public.customer_order_items order_item
        where order_item.order_id = order_row.id and order_item.product_id is not null and order_item.variant_id is null
        group by order_item.product_id
      ) quantities
      where product.id = quantities.product_id and product.organization_id = p_organization_id;
    else
      update public.branch_inventory inventory set stock_quantity = inventory.stock_quantity + quantities.quantity, updated_at = now()
      from (
        select order_item.product_id, sum(order_item.quantity)::integer quantity
        from public.customer_order_items order_item
        where order_item.order_id = order_row.id and order_item.product_id is not null and order_item.variant_id is null
        group by order_item.product_id
      ) quantities
      where inventory.branch_id = order_row.branch_id and inventory.product_id = quantities.product_id;
    end if;
  end if;

  update public.customer_orders set status = 'CANCELLED', stock_reserved = false, store_credit_reserved = 0,
    cancelled_at = now(), updated_at = now()
  where id = order_row.id and organization_id = p_organization_id;
  insert into public.customer_order_status_history (organization_id, order_id, from_status, to_status, note, changed_by)
  values (p_organization_id, order_row.id, order_row.status, 'CANCELLED', p_note, p_actor_id);
  return jsonb_build_object('order_id', order_row.id, 'from_status', order_row.status,
    'stock_released', order_row.stock_reserved, 'store_credit_released', coalesce(released_amount, 0));
end;
$$;


ALTER FUNCTION "public"."cancel_customer_order_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_commission_operation_attribution"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  attributed_employee_id uuid;
  attributed_employee_role public.organization_role;
  attributed_employment_status text;
  attribution_occurred_at timestamptz;
begin
  if new.organization_id is null or new.branch_id is null then
    return new;
  end if;

  if tg_table_name = 'sales' then
    if lower(coalesce(new.status, 'completed')) not in (
      'completed', 'refunded', 'cancelled', 'canceled', 'voided'
    ) then
      return new;
    end if;
    attributed_employee_id := new.created_by;
  elsif tg_table_name = 'repairs' then
    if lower(coalesce(new.payment_status, '')) not in ('pagado', 'paid')
       or lower(coalesce(new.status::text, '')) not in (
         'listo', 'entregado', 'cancelado', 'cancelled', 'canceled'
       ) then
      return new;
    end if;
    attributed_employee_id := new.technician_id;
  else
    raise exception 'PAYROLL_UNSUPPORTED_ATTRIBUTION_SOURCE';
  end if;

  if attributed_employee_id is null then
    return new;
  end if;

  if tg_table_name = 'sales' then
    attribution_occurred_at := coalesce(new.created_at, now());

    select employment.employee_role, employment.employment_status
    into attributed_employee_role, attributed_employment_status
    from public.employee_employment_events employment
    where employment.organization_id = new.organization_id
      and employment.employee_id = attributed_employee_id
      and employment.occurred_at <= attribution_occurred_at
    order by employment.occurred_at desc, employment.id desc
    limit 1;

    if not found
       or attributed_employment_status <> 'active'
       or attributed_employee_role = 'customer' then
      return new;
    end if;

    insert into public.commission_operation_attributions (
      organization_id,
      branch_id,
      source_type,
      source_id,
      accrual_status,
      employee_id,
      employee_role,
      occurred_at,
      basis_amount,
      labor_basis_amount
    ) values (
      new.organization_id,
      new.branch_id,
      'sale',
      new.id,
      null,
      attributed_employee_id,
      attributed_employee_role,
      attribution_occurred_at,
      coalesce(new.total_amount, 0),
      0
    )
    on conflict (
      organization_id,
      source_type,
      source_id,
      (coalesce(accrual_status, 'sale'))
    ) do nothing;

    return new;
  end if;

  if new.completed_at is not null then
    attribution_occurred_at := new.completed_at;
    select employment.employee_role, employment.employment_status
    into attributed_employee_role, attributed_employment_status
    from public.employee_employment_events employment
    where employment.organization_id = new.organization_id
      and employment.employee_id = attributed_employee_id
      and employment.occurred_at <= attribution_occurred_at
    order by employment.occurred_at desc, employment.id desc
    limit 1;

    if found
       and attributed_employment_status = 'active'
       and attributed_employee_role <> 'customer' then
    insert into public.commission_operation_attributions (
      organization_id,
      branch_id,
      source_type,
      source_id,
      accrual_status,
      employee_id,
      employee_role,
      occurred_at,
      basis_amount,
      labor_basis_amount
    ) values (
      new.organization_id,
      new.branch_id,
      'repair',
      new.id,
      'listo',
      attributed_employee_id,
      attributed_employee_role,
      attribution_occurred_at,
      coalesce(new.final_cost, new.estimated_cost, 0),
      coalesce(new.labor_cost, 0)
    )
    on conflict (
      organization_id,
      source_type,
      source_id,
      (coalesce(accrual_status, 'sale'))
    ) do nothing;
    end if;
  end if;

  if new.delivered_at is not null then
    attribution_occurred_at := new.delivered_at;
    select employment.employee_role, employment.employment_status
    into attributed_employee_role, attributed_employment_status
    from public.employee_employment_events employment
    where employment.organization_id = new.organization_id
      and employment.employee_id = attributed_employee_id
      and employment.occurred_at <= attribution_occurred_at
    order by employment.occurred_at desc, employment.id desc
    limit 1;

    if found
       and attributed_employment_status = 'active'
       and attributed_employee_role <> 'customer' then
    insert into public.commission_operation_attributions (
      organization_id,
      branch_id,
      source_type,
      source_id,
      accrual_status,
      employee_id,
      employee_role,
      occurred_at,
      basis_amount,
      labor_basis_amount
    ) values (
      new.organization_id,
      new.branch_id,
      'repair',
      new.id,
      'entregado',
      attributed_employee_id,
      attributed_employee_role,
      attribution_occurred_at,
      coalesce(new.final_cost, new.estimated_cost, 0),
      coalesce(new.labor_cost, 0)
    )
    on conflict (
      organization_id,
      source_type,
      source_id,
      (coalesce(accrual_status, 'sale'))
    ) do nothing;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."capture_commission_operation_attribution"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_commission_refund_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  canonical_organization_id uuid;
  canonical_branch_id uuid;
  canonical_source_amount numeric(14, 2);
  canonical_source_quantity numeric(14, 4);
begin
  if lower(coalesce(new.status, '')) not in ('completed', 'completado')
     or lower(coalesce(new.request_type, '')) not in ('return', 'devolucion') then
    return new;
  end if;

  if new.source_type = 'repair' and new.repair_id is not null then
    select repair.organization_id, repair.branch_id,
           coalesce(repair.final_cost, repair.estimated_cost, 0)
    into canonical_organization_id, canonical_branch_id, canonical_source_amount
    from public.repairs repair
    where repair.id = new.repair_id;
  elsif new.source_type = 'sale' and new.sale_id is not null then
    select sale.organization_id, sale.branch_id, coalesce(sale.total_amount, 0)
    into canonical_organization_id, canonical_branch_id, canonical_source_amount
    from public.sales sale
    where sale.id = new.sale_id;

    if new.sale_item_id is not null then
      select item.quantity::numeric(14, 4)
      into canonical_source_quantity
      from public.sale_items item
      where item.organization_id = canonical_organization_id
        and item.sale_id = new.sale_id
        and item.id = new.sale_item_id;

      if not found then
        raise exception 'PAYROLL_REFUND_ITEM_SCOPE_MISMATCH';
      end if;
    end if;
  else
    raise exception 'PAYROLL_REFUND_SOURCE_REQUIRED';
  end if;

  if canonical_organization_id is null
     or canonical_branch_id is null
     or canonical_organization_id is distinct from new.organization_id then
    raise exception 'PAYROLL_REFUND_SOURCE_SCOPE_MISMATCH';
  end if;

  insert into public.commission_refund_events (
    organization_id,
    branch_id,
    after_sales_case_id,
    source_type,
    sale_id,
    sale_item_id,
    repair_id,
    refund_amount,
    refund_quantity,
    source_amount,
    source_quantity,
    occurred_at
  ) values (
    canonical_organization_id,
    canonical_branch_id,
    new.id,
    new.source_type,
    new.sale_id,
    new.sale_item_id,
    new.repair_id,
    new.refund_amount,
    new.quantity,
    canonical_source_amount,
    canonical_source_quantity,
    coalesce(new.resolved_at, now())
  )
  on conflict (organization_id, after_sales_case_id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."capture_commission_refund_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_commission_sale_item_attribution"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  source_sale public.sales%rowtype;
  source_category_id uuid;
begin
  select sale.*
  into source_sale
  from public.sales sale
  where sale.id = new.sale_id
    and sale.organization_id = new.organization_id;

  if not found or source_sale.branch_id is null then
    return new;
  end if;

  if new.product_id is not null then
    select product.category_id
    into source_category_id
    from public.products product
    where product.organization_id = source_sale.organization_id
      and product.id = new.product_id;
  end if;

  insert into public.commission_sale_item_attributions (
    organization_id,
    branch_id,
    sale_id,
    sale_item_id,
    product_id,
    category_id,
    quantity,
    subtotal,
    occurred_at
  ) values (
    source_sale.organization_id,
    source_sale.branch_id,
    source_sale.id,
    new.id,
    new.product_id,
    source_category_id,
    new.quantity,
    coalesce(new.subtotal, 0),
    coalesce(source_sale.created_at, now())
  )
  on conflict (organization_id, sale_item_id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."capture_commission_sale_item_attribution"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_commission_terminal_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  terminal_source_type text;
  terminal_status text := lower(coalesce(new.status::text, ''));
  was_terminal boolean := false;
begin
  if tg_table_name = 'sales' then
    terminal_source_type := 'sale';
    if tg_op = 'UPDATE' then
      was_terminal := lower(coalesce(old.status::text, '')) in (
        'refunded', 'cancelled', 'canceled', 'voided'
      );
    end if;
    if terminal_status not in ('refunded', 'cancelled', 'canceled', 'voided') then
      return new;
    end if;
  elsif tg_table_name = 'repairs' then
    terminal_source_type := 'repair';
    if tg_op = 'UPDATE' then
      was_terminal := lower(coalesce(old.status::text, '')) in (
        'cancelado', 'cancelled', 'canceled'
      );
    end if;
    if terminal_status not in ('cancelado', 'cancelled', 'canceled') then
      return new;
    end if;
  else
    raise exception 'PAYROLL_UNSUPPORTED_TERMINAL_EVENT_SOURCE';
  end if;

  if was_terminal or new.organization_id is null or new.branch_id is null then
    return new;
  end if;

  insert into public.commission_terminal_events (
    organization_id,
    branch_id,
    source_type,
    source_id,
    source_status,
    occurred_at
  ) values (
    new.organization_id,
    new.branch_id,
    terminal_source_type,
    new.id,
    terminal_status,
    now()
  )
  on conflict (organization_id, source_type, source_id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."capture_commission_terminal_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_customer_order_item_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  order_organization_id uuid;
  captured_product_id uuid;
  captured_unit_cost numeric(14, 2);
begin
  select o.organization_id, product.id, nullif(product.purchase_price, 0)
  into order_organization_id, captured_product_id, captured_unit_cost
  from public.customer_orders o
  left join public.products product
    on product.id = new.product_id
   and product.organization_id = o.organization_id
  where o.id = new.order_id;

  -- Sin pedido no hay a que asociar el costo, pero tampoco se corta la creacion
  -- del pedido por esto: el snapshot es un dato de reporte, no del negocio.
  if order_organization_id is null then
    return new;
  end if;

  insert into public.customer_order_item_cost_snapshots (
    organization_id,
    order_id,
    order_item_id,
    product_id,
    quantity,
    unit_cost,
    total_cost
  ) values (
    order_organization_id,
    new.order_id,
    new.id,
    captured_product_id,
    new.quantity,
    captured_unit_cost,
    case when captured_unit_cost is null then null else round(captured_unit_cost * new.quantity, 2) end
  )
  on conflict (organization_id, order_item_id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."capture_customer_order_item_cost"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_employee_employment_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.role is not distinct from old.role
       and new.status is not distinct from old.status then
      return new;
    end if;

    if new.role = 'customer' and old.role = 'customer' then
      return new;
    end if;
  end if;

  if tg_op = 'INSERT' and new.role = 'customer' then
    return new;
  end if;

  insert into public.employee_employment_events (
    organization_id,
    employee_id,
    employee_role,
    employment_status,
    occurred_at,
    capture_basis
  ) values (
    new.organization_id,
    new.user_id,
    new.role,
    new.status,
    case when tg_op = 'INSERT' then coalesce(new.created_at, now()) else now() end,
    'live_transition'
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."capture_employee_employment_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_pos_repair_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status = 'entregado' and old.status is distinct from 'entregado' then
    if old.status <> 'listo' then
      raise exception 'REPAIR_DELIVERY_INVALID_STATE';
    end if;
    if new.delivery_outcome not in ('repaired', 'withdrawn', 'unrepairable') then
      raise exception 'REPAIR_DELIVERY_OUTCOME_INVALID';
    end if;
    new.warranty_expires_at := case
      when coalesce(new.warranty_months, 0) > 0
        then coalesce(new.delivered_at, now()) + make_interval(months => new.warranty_months)
      else null
    end;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."capture_pos_repair_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_pos_repair_payments_statement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  allocation record;
  resolved_method text;
  resolved_immediate numeric(12, 2);
  resolved_financed numeric(12, 2);
  resolved_breakdown jsonb;
begin
  for allocation in
    with changed as (
      select
        new_rows.id as repair_id,
        new_rows.organization_id,
        new_rows.branch_id,
        greatest(0, coalesce(new_rows.paid_amount, 0) - coalesce(old_rows.paid_amount, 0))::numeric(12, 2) as payment_delta,
        substring(new_rows.problem_description from 'Venta relacionada #([0-9a-fA-F-]{36})')::uuid as resolved_sale_id
      from new_rows
      join old_rows using (id)
      where coalesce(new_rows.paid_amount, 0) > coalesce(old_rows.paid_amount, 0)
        and new_rows.problem_description ~ 'Venta relacionada #[0-9a-fA-F-]{36}'
    ),
    payment_totals as (
      select
        changed.*,
        sale.created_by as sale_created_by,
        sale.payment_method as sale_payment_method,
        coalesce(sum(payment.amount) filter (where payment.payment_method <> 'credit'), 0)::numeric(12, 2) as sale_immediate,
        coalesce(sum(payment.amount) filter (where payment.payment_method = 'credit'), 0)::numeric(12, 2) as sale_financed
      from changed
      join public.sales sale
        on sale.id = changed.resolved_sale_id
       and sale.organization_id = changed.organization_id
      left join public.sale_payments payment
        on payment.sale_id = changed.resolved_sale_id
       and payment.organization_id = changed.organization_id
      group by changed.repair_id, changed.organization_id, changed.branch_id,
        changed.payment_delta, changed.resolved_sale_id,
        sale.created_by, sale.payment_method
    ),
    ordered as (
      select
        payment_totals.*,
        coalesce(sum(payment_delta) over (
          partition by organization_id, resolved_sale_id
          order by repair_id
          rows between unbounded preceding and 1 preceding
        ), 0)::numeric(12, 2) as prior_repair_delta
      from payment_totals
    )
    select * from ordered order by organization_id, resolved_sale_id, repair_id
  loop
    resolved_immediate := least(
      allocation.payment_delta,
      greatest(0, allocation.sale_immediate - allocation.prior_repair_delta)
    );
    resolved_financed := allocation.payment_delta - resolved_immediate;

    if resolved_immediate + resolved_financed <> allocation.payment_delta then
      raise exception 'REPAIR_POS_PAYMENT_ALLOCATION_MISMATCH';
    end if;
    if resolved_financed > allocation.sale_financed then
      raise exception 'REPAIR_POS_FINANCING_ALLOCATION_EXCEEDS_SALE';
    end if;

    resolved_method := case
      when resolved_immediate > 0 and resolved_financed > 0 then 'mixed'
      when resolved_financed > 0 then 'credit'
      when lower(coalesce(allocation.sale_payment_method, '')) in ('cash', 'efectivo') then 'cash'
      when lower(coalesce(allocation.sale_payment_method, '')) in ('card', 'tarjeta') then 'card'
      when lower(coalesce(allocation.sale_payment_method, '')) in ('transfer', 'transferencia') then 'transfer'
      else 'mixed'
    end;

    resolved_breakdown := case
      when resolved_immediate > 0 and resolved_financed > 0 then jsonb_build_array(
        jsonb_build_object('method', 'immediate', 'amount', resolved_immediate),
        jsonb_build_object('method', 'credit', 'amount', resolved_financed)
      )
      when resolved_financed > 0 then jsonb_build_array(
        jsonb_build_object('method', 'credit', 'amount', resolved_financed)
      )
      else jsonb_build_array(
        jsonb_build_object('method', resolved_method, 'amount', resolved_immediate)
      )
    end;

    insert into public.repair_payments (
      repair_id, organization_id, branch_id, amount, payment_method,
      idempotency_key, source, sale_id, created_by, payment_breakdown,
      immediate_amount, financed_amount, created_at
    ) values (
      allocation.repair_id, allocation.organization_id, allocation.branch_id,
      allocation.payment_delta, resolved_method,
      'pos:' || allocation.resolved_sale_id::text || ':' || allocation.repair_id::text,
      'pos', allocation.resolved_sale_id, allocation.sale_created_by,
      resolved_breakdown, resolved_immediate, resolved_financed, now()
    ) on conflict (organization_id, idempotency_key) do nothing;
  end loop;

  return null;
end;
$$;


ALTER FUNCTION "public"."capture_pos_repair_payments_statement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_sale_item_cost_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  sale_organization_id uuid;
  sale_branch_id uuid;
  captured_product_id uuid;
  captured_unit_cost numeric(14, 2);
begin
  select sale.organization_id, sale.branch_id, product.id, nullif(product.purchase_price, 0)
  into sale_organization_id, sale_branch_id, captured_product_id, captured_unit_cost
  from public.sales sale
  left join public.products product
    on product.id = new.product_id
   and product.organization_id = sale.organization_id
  where sale.id = new.sale_id
    and sale.organization_id = new.organization_id;

  if sale_organization_id is null or sale_branch_id is null then
    raise exception 'SALE_ITEM_COST_SNAPSHOT_SCOPE_MISMATCH';
  end if;

  if new.product_id is not null and captured_product_id is null then
    raise exception 'SALE_ITEM_COST_SNAPSHOT_PRODUCT_SCOPE_MISMATCH';
  end if;

  insert into public.sale_item_cost_snapshots (
    organization_id,
    branch_id,
    sale_id,
    sale_item_id,
    product_id,
    quantity,
    unit_cost,
    total_cost
  ) values (
    sale_organization_id,
    sale_branch_id,
    new.sale_id,
    new.id,
    new.product_id,
    new.quantity,
    captured_unit_cost,
    case
      when captured_unit_cost is null then null
      else round(captured_unit_cost * new.quantity, 2)
    end
  )
  on conflict (organization_id, sale_item_id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."capture_sale_item_cost_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cash_movement_effect"("p_type" "text", "p_payment_method" "text", "p_amount" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select case
    when p_type = 'opening' then coalesce(p_amount, 0)
    when p_type = 'cash_in' and coalesce(p_payment_method, 'cash') in ('cash', 'efectivo') then coalesce(p_amount, 0)
    when p_type = 'sale' and coalesce(p_payment_method, 'cash') = 'cash' then coalesce(p_amount, 0)
    when p_type = 'sale' and p_payment_method = 'efectivo' then coalesce(p_amount, 0)
    when p_type = 'cash_out' and coalesce(p_payment_method, 'cash') in ('cash', 'efectivo') then -coalesce(p_amount, 0)
    else 0
  end;
$$;


