CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_action_type" "text", "p_max_attempts" integer DEFAULT 5, "p_window_minutes" integer DEFAULT 1) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
    v_window_start TIMESTAMPTZ;
BEGIN
    -- Obtener el inicio de la ventana actual
    SELECT window_start, attempt_count INTO v_window_start, v_count
    FROM rate_limit_settings
    WHERE user_id = p_user_id AND action_type = p_action_type;

    -- Si no existe registro o la ventana expiró, crear nuevo
    IF v_window_start IS NULL OR v_window_start < NOW() - (p_window_minutes || ' minutes')::INTERVAL THEN
        INSERT INTO rate_limit_settings (user_id, action_type, attempt_count, window_start)
        VALUES (p_user_id, p_action_type, 1, NOW())
        ON CONFLICT (user_id, action_type)
        DO UPDATE SET attempt_count = 1, window_start = NOW();
        RETURN TRUE;
    END IF;

    -- Si está dentro del límite, incrementar contador
    IF v_count < p_max_attempts THEN
        UPDATE rate_limit_settings
        SET attempt_count = attempt_count + 1
        WHERE user_id = p_user_id AND action_type = p_action_type;
        RETURN TRUE;
    END IF;

    -- Límite excedido
    RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_action_type" "text", "p_max_attempts" integer, "p_window_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_action_type" "text", "p_max_attempts" integer, "p_window_minutes" integer) IS 'Verifica si un usuario puede realizar una acción según rate limits';



CREATE OR REPLACE FUNCTION "public"."cleanup_old_audit_logs"("p_days_to_keep" integer DEFAULT 90) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    -- Solo admins pueden ejecutar esta función
    IF NOT (public.get_user_role() IN ('admin', 'super_admin')) THEN
        RAISE EXCEPTION 'Acceso denegado: se requieren permisos de administrador';
    END IF;

    -- Eliminar logs más antiguos que el número de días especificado
    DELETE FROM public.audit_log
    WHERE created_at < NOW() - INTERVAL '1 day' * p_days_to_keep;

    GET DIAGNOSTICS deleted_count = ROW_COUNT;

    -- Registrar la limpieza
    PERFORM public.log_system_event(
        'cleanup_audit_logs',
        'maintenance',
        jsonb_build_object(
            'deleted_records', deleted_count,
            'days_kept', p_days_to_keep
        ),
        'low'
    );

    RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_old_audit_logs"("p_days_to_keep" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_old_audit_logs"("p_days_to_keep" integer) IS 'Limpia logs de auditoría antiguos (solo admins)';



