CREATE OR REPLACE FUNCTION "public"."close_all_user_sessions_except_current"("p_user_id" "uuid", "p_current_session_id" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  affected INT;
BEGIN
  UPDATE public.user_sessions
  SET is_active = false, last_activity = now()
  WHERE user_id = p_user_id AND session_id != p_current_session_id AND is_active = true;

  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;
$$;


