CREATE OR REPLACE FUNCTION "public"."close_cash_register_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_session_id" "uuid", "p_closing_balance" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
  target_session public.cash_closures%rowtype;
  expected_total numeric;
  difference numeric;
begin
  if actor_id is null then
    raise exception 'Authentication required';
  end if;
  if not public.has_org_permission(p_organization_id, 'pos.cash.manage') then
    raise exception 'Insufficient cash permissions';
  end if;
  if coalesce(p_closing_balance, -1) < 0 then
    raise exception 'Closing balance cannot be negative';
  end if;

  select * into target_session
  from public.cash_closures c
  where c.id = p_session_id
    and c.organization_id = p_organization_id
    and c.branch_id = p_branch_id
  for update;

  if not found then
    raise exception 'Cash session not found in selected branch';
  end if;
  if target_session.date is not null then
    raise exception 'Cash session is already closed';
  end if;

  expected_total := public.calculate_cash_session_expected(
    target_session.id,
    p_organization_id,
    p_branch_id
  );
  difference := p_closing_balance - expected_total;

  update public.cash_closures
  set closed_by = actor_id::text,
      closing_balance = p_closing_balance,
      expected_balance = expected_total,
      discrepancy = difference,
      date = now(),
      updated_at = now()
  where id = target_session.id;

  update public.cash_registers r
  set is_open = false, balance = p_closing_balance
  where r.id::text = target_session.register_id
    and r.organization_id = p_organization_id
    and r.branch_id = p_branch_id;

  insert into public.cash_movements (
    session_id, type, amount, reason, created_by, created_at,
    organization_id, branch_id
  ) values (
    target_session.id, 'closing', p_closing_balance, 'Cierre de caja',
    actor_id, now(), p_organization_id, p_branch_id
  );

  return jsonb_build_object(
    'id', target_session.id,
    'expected_balance', expected_total,
    'closing_balance', p_closing_balance,
    'discrepancy', difference,
    'closed_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."close_cash_register_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_session_id" "uuid", "p_closing_balance" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_inactive_sessions"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE user_sessions
  SET is_active = FALSE,
      ended_at = NOW()
  WHERE is_active = TRUE
    AND last_activity < NOW() - INTERVAL '7 days';
END;
$$;


ALTER FUNCTION "public"."close_inactive_sessions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_repair_and_register_payment"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_deliver" boolean DEFAULT false, "p_delivery_outcome" "text" DEFAULT NULL::"text", "p_delivery_note" "text" DEFAULT NULL::"text", "p_allow_outstanding_balance" boolean DEFAULT false, "p_payment_method" "text" DEFAULT NULL::"text", "p_payment_amount" numeric DEFAULT NULL::numeric, "p_payment_reference" "text" DEFAULT NULL::"text", "p_payment_note" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_cash_session_id" "uuid" DEFAULT NULL::"uuid", "p_credit_id" "uuid" DEFAULT NULL::"uuid", "p_sale_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'repairs'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_repair public.repairs%rowtype;
  existing_payment public.repair_payments%rowtype;
  resolved_total numeric(12, 2);
  resolved_parts_price numeric(12, 2);
  resolved_paid numeric(12, 2);
  resolved_amount numeric(12, 2);
  resolved_balance numeric(12, 2);
  resolved_payment_status text;
  created_payment_id uuid;
  operation_time timestamptz := now();
begin
  if p_actor_id is null or not exists (
    select 1
    from public.organization_members membership
    where membership.organization_id = p_organization_id
      and membership.user_id = p_actor_id
      and membership.status = 'active'
      and membership.role in ('owner', 'admin', 'manager', 'cashier', 'technician', 'seller')
  ) then
    raise exception 'REPAIR_FINANCIAL_PERMISSION_DENIED';
  end if;

  if p_idempotency_key is null
     or char_length(trim(p_idempotency_key)) < 8
     or char_length(trim(p_idempotency_key)) > 120 then
    raise exception 'REPAIR_IDEMPOTENCY_KEY_REQUIRED';
  end if;

  if p_source not in ('repairs', 'delivery', 'pos') then
    raise exception 'REPAIR_PAYMENT_SOURCE_INVALID';
  end if;

  select payment.*
  into existing_payment
  from public.repair_payments payment
  where payment.organization_id = p_organization_id
    and payment.idempotency_key = trim(p_idempotency_key)
  limit 1;

  select repair.*
  into target_repair
  from public.repairs repair
  where repair.id = p_repair_id
    and repair.organization_id = p_organization_id
    and repair.branch_id = p_branch_id
  for update;

  if not found then
    raise exception 'REPAIR_NOT_FOUND';
  end if;

  if existing_payment.id is not null then
    if existing_payment.repair_id <> p_repair_id
       or existing_payment.amount is distinct from p_payment_amount
       or existing_payment.payment_method is distinct from p_payment_method
       or existing_payment.source is distinct from p_source
       or existing_payment.reference is distinct from nullif(trim(coalesce(p_payment_reference, '')), '')
       or (p_deliver and (
         target_repair.status <> 'entregado'
         or target_repair.delivery_idempotency_key is distinct from trim(p_idempotency_key)
       ))
       or (not p_deliver and existing_payment.source = 'delivery') then
      raise exception 'REPAIR_IDEMPOTENCY_CONFLICT';
    end if;
    resolved_total := greatest(0, coalesce(target_repair.final_cost, target_repair.estimated_cost, 0));
    resolved_paid := greatest(0, coalesce(target_repair.paid_amount, 0));
    return jsonb_build_object(
      'repair_id', target_repair.id,
      'payment_id', existing_payment.id,
      'idempotent', true,
      'total', resolved_total,
      'paid_amount', resolved_paid,
      'balance', greatest(0, resolved_total - resolved_paid),
      'payment_status', target_repair.payment_status,
      'delivered', target_repair.status = 'entregado'
    );
  end if;

  if p_deliver and target_repair.status = 'entregado' then
    if target_repair.delivery_idempotency_key = trim(p_idempotency_key) then
      resolved_total := greatest(0, coalesce(target_repair.final_cost, target_repair.estimated_cost, 0));
      resolved_paid := greatest(0, coalesce(target_repair.paid_amount, 0));
      return jsonb_build_object(
        'repair_id', target_repair.id,
        'payment_id', null,
        'idempotent', true,
        'total', resolved_total,
        'paid_amount', resolved_paid,
        'balance', greatest(0, resolved_total - resolved_paid),
        'payment_status', target_repair.payment_status,
        'delivered', true
      );
    end if;
    raise exception 'REPAIR_ALREADY_DELIVERED';
  end if;

  if p_deliver and target_repair.status <> 'listo' then
    raise exception 'REPAIR_DELIVERY_INVALID_STATE';
  end if;

  if not p_deliver and target_repair.status = 'cancelado' then
    raise exception 'REPAIR_PAYMENT_INVALID_STATE';
  end if;

  if p_deliver and p_delivery_outcome not in ('repaired', 'withdrawn', 'unrepairable') then
    raise exception 'REPAIR_DELIVERY_OUTCOME_INVALID';
  end if;

  select coalesce(sum(coalesce(part.unit_price, part.unit_cost, 0) * greatest(part.quantity, 0)), 0)
  into resolved_parts_price
  from public.repair_parts part
  where part.repair_id = target_repair.id;

  if coalesce(target_repair.pricing_mode, 'automatic') = 'automatic' then
    resolved_total := greatest(
      0,
      coalesce(target_repair.labor_cost, 0)
        + resolved_parts_price
        - coalesce(target_repair.discount_amount, 0)
    );
  else
    if target_repair.final_cost is null then
      raise exception 'REPAIR_FINAL_COST_REQUIRED';
    end if;
    resolved_total := greatest(0, target_repair.final_cost);
  end if;

  resolved_paid := greatest(0, coalesce(target_repair.paid_amount, 0));
  resolved_amount := greatest(0, coalesce(p_payment_amount, 0));

  if p_payment_method is null and resolved_amount > 0 then
    raise exception 'REPAIR_PAYMENT_METHOD_REQUIRED';
  end if;
  if p_payment_method is not null and p_payment_method not in ('cash', 'card', 'transfer', 'credit') then
    raise exception 'REPAIR_PAYMENT_METHOD_INVALID';
  end if;
  if p_payment_method is not null and resolved_amount <= 0 then
    raise exception 'REPAIR_PAYMENT_AMOUNT_INVALID';
  end if;
  if resolved_amount > greatest(0, resolved_total - resolved_paid) then
    raise exception 'REPAIR_PAYMENT_EXCEEDS_BALANCE';
  end if;
  if p_payment_method = 'credit' and resolved_amount <> greatest(0, resolved_total - resolved_paid) then
    raise exception 'REPAIR_CREDIT_MUST_COVER_BALANCE';
  end if;
  if not p_deliver and resolved_amount <= 0 then
    raise exception 'REPAIR_PAYMENT_AMOUNT_INVALID';
  end if;

  resolved_paid := resolved_paid + resolved_amount;
  resolved_balance := greatest(0, resolved_total - resolved_paid);
  resolved_payment_status := case
    when resolved_balance <= 0 then 'pagado'
    when resolved_paid > 0 then 'parcial'
    else 'pendiente'
  end;

  if p_deliver and resolved_balance > 0 and not p_allow_outstanding_balance then
    raise exception 'REPAIR_OUTSTANDING_CONFIRMATION_REQUIRED';
  end if;

  if resolved_amount > 0 and p_payment_method <> 'credit' then
    if p_cash_session_id is null or not exists (
      select 1
      from public.cash_closures closure
      where closure.id = p_cash_session_id
        and closure.organization_id = p_organization_id
        and closure.branch_id = p_branch_id
        and closure.date is null
    ) then
      raise exception 'REPAIR_CASH_REGISTER_NOT_OPEN';
    end if;
  end if;

  if resolved_amount > 0 then
    insert into public.repair_payments (
      repair_id, organization_id, branch_id, amount, payment_method,
      idempotency_key, source, reference, notes, cash_session_id,
      credit_id, sale_id, created_by, created_at
    ) values (
      target_repair.id, p_organization_id, p_branch_id, resolved_amount,
      p_payment_method, trim(p_idempotency_key), p_source,
      nullif(trim(coalesce(p_payment_reference, '')), ''),
      nullif(trim(coalesce(p_payment_note, '')), ''),
      p_cash_session_id, p_credit_id, p_sale_id, p_actor_id, operation_time
    ) returning id into created_payment_id;

    if p_payment_method <> 'credit' then
      insert into public.cash_movements (
        session_id, type, amount, reason, payment_method, created_by,
        created_at, organization_id, branch_id
      ) values (
        p_cash_session_id, 'cash_in', resolved_amount,
        'Cobro reparación ' || coalesce(target_repair.ticket_number, target_repair.id::text),
        p_payment_method, p_actor_id, operation_time, p_organization_id, p_branch_id
      );
    end if;
  end if;

  update public.repairs
  set final_cost = resolved_total,
      estimated_cost = resolved_total,
      paid_amount = resolved_paid,
      payment_status = resolved_payment_status,
      status = case when p_deliver then 'entregado' else status end,
      picked_up_at = case when p_deliver then operation_time else picked_up_at end,
      delivered_at = case when p_deliver then operation_time else delivered_at end,
      completed_at = case when p_deliver then coalesce(completed_at, operation_time) else completed_at end,
      delivery_outcome = case when p_deliver then p_delivery_outcome else delivery_outcome end,
      solution = case
        when p_deliver and nullif(trim(coalesce(p_delivery_note, '')), '') is not null
          then trim(p_delivery_note)
        else solution
      end,
      warranty_expires_at = case
        when p_deliver and coalesce(warranty_months, 0) > 0
          then operation_time + make_interval(months => warranty_months)
        when p_deliver then null
        else warranty_expires_at
      end,
      delivery_idempotency_key = case
        when p_deliver then trim(p_idempotency_key)
        else delivery_idempotency_key
      end,
      updated_at = operation_time
  where id = target_repair.id
    and organization_id = p_organization_id
    and branch_id = p_branch_id;

  if resolved_amount > 0 then
    insert into public.repair_notes (
      repair_id, author_id, author_name, note_text, is_internal, created_at
    ) values (
      target_repair.id, p_actor_id, 'Sistema',
      case when p_payment_method = 'credit' then 'Cobro a crédito: ' else 'Pago registrado: ' end
        || resolved_amount::text || ' | Método: ' || p_payment_method,
      true, operation_time
    );
  end if;

  return jsonb_build_object(
    'repair_id', target_repair.id,
    'payment_id', created_payment_id,
    'idempotent', false,
    'total', resolved_total,
    'paid_amount', resolved_paid,
    'balance', resolved_balance,
    'payment_status', resolved_payment_status,
    'delivered', p_deliver
  );
end;
$$;


ALTER FUNCTION "public"."close_repair_and_register_payment"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_deliver" boolean, "p_delivery_outcome" "text", "p_delivery_note" "text", "p_allow_outstanding_balance" boolean, "p_payment_method" "text", "p_payment_amount" numeric, "p_payment_reference" "text", "p_payment_note" "text", "p_idempotency_key" "text", "p_cash_session_id" "uuid", "p_credit_id" "uuid", "p_sale_id" "uuid", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_repair_and_register_payment_v2"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_deliver" boolean DEFAULT false, "p_delivery_outcome" "text" DEFAULT NULL::"text", "p_delivery_note" "text" DEFAULT NULL::"text", "p_allow_outstanding_balance" boolean DEFAULT false, "p_payment_method" "text" DEFAULT NULL::"text", "p_payment_amount" numeric DEFAULT NULL::numeric, "p_payment_reference" "text" DEFAULT NULL::"text", "p_payment_note" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_cash_session_id" "uuid" DEFAULT NULL::"uuid", "p_credit_id" "uuid" DEFAULT NULL::"uuid", "p_sale_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'repairs'::"text", "p_credit_interest_rate" numeric DEFAULT NULL::numeric, "p_credit_installment_count" integer DEFAULT NULL::integer, "p_credit_frequency" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  operation_result jsonb;
  target_customer_id uuid;
  target_ticket_number text;
  existing_payment public.repair_payments%rowtype;
  existing_credit_rate numeric(8, 2);
  existing_credit_count integer;
  existing_credit_frequency text;
  customer_credit_limit numeric(12, 2);
  current_credit_balance numeric(12, 2);
  available_credit numeric(12, 2);
  credit_rate numeric(8, 2);
  credit_count integer;
  credit_frequency text;
  financed_total numeric(12, 2);
  installment_base numeric(12, 2);
  principal_base numeric(12, 2);
  installment_due timestamptz;
  installment_index integer;
  resolved_credit_id uuid;
begin
  if p_payment_method in ('card', 'transfer')
     and nullif(trim(coalesce(p_payment_reference, '')), '') is null then
    raise exception 'REPAIR_PAYMENT_REFERENCE_REQUIRED';
  end if;

  if p_payment_method is distinct from 'credit' then
    operation_result := public.close_repair_and_register_payment(
      p_repair_id, p_organization_id, p_branch_id, p_actor_id, p_deliver,
      p_delivery_outcome, p_delivery_note, p_allow_outstanding_balance,
      p_payment_method, p_payment_amount, p_payment_reference, p_payment_note,
      p_idempotency_key, p_cash_session_id, p_credit_id, p_sale_id, p_source
    );
    return operation_result || jsonb_build_object('credit_id', null, 'credit_total', null);
  end if;

  if p_credit_id is not null
     or p_credit_interest_rate is null
     or p_credit_interest_rate < 0
     or p_credit_interest_rate > 1000
     or p_credit_installment_count is null
     or p_credit_installment_count < 1
     or p_credit_installment_count > 60
     or p_credit_frequency not in ('weekly', 'biweekly', 'monthly') then
    raise exception 'REPAIR_CREDIT_TERMS_INVALID';
  end if;

  credit_rate := round(p_credit_interest_rate, 2);
  credit_count := p_credit_installment_count;
  credit_frequency := p_credit_frequency;

  -- Serialize retries and concurrent payments for the same repair before any
  -- credit record can be created.
  select repair.customer_id, repair.ticket_number
  into target_customer_id, target_ticket_number
  from public.repairs repair
  where repair.id = p_repair_id
    and repair.organization_id = p_organization_id
    and repair.branch_id = p_branch_id
  for update;

  if not found then
    raise exception 'REPAIR_NOT_FOUND';
  end if;

  select payment.*
  into existing_payment
  from public.repair_payments payment
  where payment.organization_id = p_organization_id
    and payment.idempotency_key = trim(p_idempotency_key)
  limit 1;

  if existing_payment.id is not null then
    select
      credit.principal,
      credit.interest_rate,
      credit.term_months,
      credit.metadata->>'frequency'
    into financed_total, existing_credit_rate, existing_credit_count, existing_credit_frequency
    from public.customer_credits credit
    where credit.id = existing_payment.credit_id
      and credit.organization_id = p_organization_id;

    if not found
       or existing_credit_rate is distinct from credit_rate
       or existing_credit_count is distinct from credit_count
       or existing_credit_frequency is distinct from credit_frequency then
      raise exception 'REPAIR_IDEMPOTENCY_CONFLICT';
    end if;

    operation_result := public.close_repair_and_register_payment(
      p_repair_id, p_organization_id, p_branch_id, p_actor_id, p_deliver,
      p_delivery_outcome, p_delivery_note, p_allow_outstanding_balance,
      p_payment_method, p_payment_amount, p_payment_reference, p_payment_note,
      p_idempotency_key, p_cash_session_id, existing_payment.credit_id,
      p_sale_id, p_source
    );
    return operation_result || jsonb_build_object(
      'credit_id', existing_payment.credit_id,
      'credit_total', financed_total
    );
  end if;

  if target_customer_id is null then
    raise exception 'REPAIR_CREDIT_CUSTOMER_REQUIRED';
  end if;

  -- The customer lock also serializes other financing flows that follow the
  -- same locking contract, preventing concurrent credit-limit oversubscription.
  select greatest(0, coalesce(customer.credit_limit, 0))
  into customer_credit_limit
  from public.customers customer
  where customer.id = target_customer_id
    and customer.organization_id = p_organization_id
  for update;

  if not found or customer_credit_limit <= 0 then
    raise exception 'REPAIR_CREDIT_LIMIT_DISABLED';
  end if;

  select coalesce(sum(greatest(
    0,
    coalesce(installment.amount, 0) - coalesce(installment.amount_paid, 0)
  )), 0)
  into current_credit_balance
  from public.customer_credits credit
  join public.credit_installments installment on installment.credit_id = credit.id
  where credit.organization_id = p_organization_id
    and credit.customer_id = target_customer_id
    and installment.status in ('pending', 'late');

  financed_total := round(p_payment_amount * (1 + credit_rate / 100), 2);
  available_credit := customer_credit_limit - current_credit_balance;

  if available_credit < financed_total then
    raise exception 'REPAIR_CREDIT_LIMIT_EXCEEDED|%', greatest(0, available_credit);
  end if;

  insert into public.customer_credits (
    customer_id, organization_id, branch_id, sale_id, principal, interest_rate,
    term_months, start_date, status, credit_code, credit_type, origin_type,
    label, metadata
  ) values (
    target_customer_id, p_organization_id, p_branch_id, null, financed_total,
    credit_rate, credit_count, now(), 'active',
    'CR-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8)),
    'repair_financing', 'repair',
    'Reparación ' || coalesce(target_ticket_number, upper(substr(p_repair_id::text, 1, 8))),
    jsonb_build_object(
      'repair_id', p_repair_id,
      'idempotency_key', trim(p_idempotency_key),
      'frequency', credit_frequency
    )
  ) returning id into resolved_credit_id;

  installment_base := trunc((financed_total / credit_count) * 100) / 100;
  principal_base := trunc((p_payment_amount / credit_count) * 100) / 100;

  for installment_index in 1..credit_count loop
    installment_due := case credit_frequency
      when 'weekly' then now() + make_interval(days => 7 * installment_index)
      when 'biweekly' then now() + make_interval(days => 14 * installment_index)
      else now() + make_interval(months => installment_index)
    end;

    insert into public.credit_installments (
      credit_id, sale_id, installment_number, due_date, amount,
      principal_component, interest_component, status
    ) values (
      resolved_credit_id, null, installment_index, installment_due,
      case when installment_index = credit_count
        then financed_total - installment_base * (credit_count - 1)
        else installment_base end,
      case when installment_index = credit_count
        then p_payment_amount - principal_base * (credit_count - 1)
        else principal_base end,
      case when installment_index = credit_count
        then (financed_total - p_payment_amount)
          - (installment_base - principal_base) * (credit_count - 1)
        else installment_base - principal_base end,
      'pending'
    );
  end loop;

  -- Calling the established closure function inside this function keeps all
  -- writes in the current PostgreSQL transaction. Any error rolls back credit,
  -- installments, payment ledger, and repair summary together.
  operation_result := public.close_repair_and_register_payment(
    p_repair_id, p_organization_id, p_branch_id, p_actor_id, p_deliver,
    p_delivery_outcome, p_delivery_note, p_allow_outstanding_balance,
    p_payment_method, p_payment_amount, p_payment_reference, p_payment_note,
    p_idempotency_key, p_cash_session_id, resolved_credit_id, p_sale_id, p_source
  );

  return operation_result || jsonb_build_object(
    'credit_id', resolved_credit_id,
    'credit_total', financed_total
  );
end;
$$;


ALTER FUNCTION "public"."close_repair_and_register_payment_v2"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_deliver" boolean, "p_delivery_outcome" "text", "p_delivery_note" "text", "p_allow_outstanding_balance" boolean, "p_payment_method" "text", "p_payment_amount" numeric, "p_payment_reference" "text", "p_payment_note" "text", "p_idempotency_key" "text", "p_cash_session_id" "uuid", "p_credit_id" "uuid", "p_sale_id" "uuid", "p_source" "text", "p_credit_interest_rate" numeric, "p_credit_installment_count" integer, "p_credit_frequency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_unrepaired_repair"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_outcome" "text", "p_charge" "jsonb", "p_parts" "jsonb", "p_settlement" "jsonb", "p_reason" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_cash_session_id" "uuid" DEFAULT NULL::"uuid", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_repair public.repairs%rowtype;
  existing_closeout public.repair_closeouts%rowtype;
  part_record record;
  resolution jsonb;
  operation_time timestamptz := now();
  resolved_mode text;
  resolved_kind text;
  resolved_method text;
  labor_charge numeric(12,2) := 0;
  consumed_parts_charge numeric(12,2) := 0;
  consumed_parts_cost numeric(12,2) := 0;
  final_charge numeric(12,2) := 0;
  paid_before numeric(12,2) := 0;
  difference numeric(12,2) := 0;
  settlement_amount numeric(12,2) := 0;
  net_paid numeric(12,2) := 0;
  resolved_payment_status text;
  created_payment_id uuid;
  created_credit_id uuid;
  previous_stock integer;
  resolved_parts jsonb := '[]'::jsonb;
  expected_count integer;
  supplied_count integer;
begin
  if p_actor_id is null or not exists (
    select 1 from public.organization_members membership
    where membership.organization_id = p_organization_id
      and membership.user_id = p_actor_id
      and membership.status = 'active'
      and membership.role in ('owner', 'admin', 'manager', 'cashier', 'technician', 'seller')
  ) then raise exception 'REPAIR_FINANCIAL_PERMISSION_DENIED'; end if;

  if p_idempotency_key is null or char_length(trim(p_idempotency_key)) not between 8 and 120 then
    raise exception 'REPAIR_IDEMPOTENCY_KEY_REQUIRED';
  end if;
  if p_outcome not in ('withdrawn', 'unrepairable') then raise exception 'REPAIR_DELIVERY_OUTCOME_INVALID'; end if;
  if jsonb_typeof(coalesce(p_charge, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_parts, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_settlement, '{}'::jsonb)) <> 'object' then
    raise exception 'REPAIR_CLOSEOUT_INVALID';
  end if;

  select closeout.* into existing_closeout
  from public.repair_closeouts closeout
  where closeout.organization_id = p_organization_id
    and closeout.idempotency_key = trim(p_idempotency_key);
  if existing_closeout.id is not null then
    if existing_closeout.repair_id <> p_repair_id or existing_closeout.outcome <> p_outcome then
      raise exception 'REPAIR_CLOSEOUT_CONFLICT';
    end if;
    return jsonb_build_object('repair_id', p_repair_id, 'closeout_id', existing_closeout.id,
      'payment_id', existing_closeout.payment_id, 'store_credit_id', existing_closeout.store_credit_id,
      'idempotent', true, 'final_charge', existing_closeout.final_charge,
      'settlement_amount', existing_closeout.settlement_amount);
  end if;

  select repair.* into target_repair from public.repairs repair
  where repair.id = p_repair_id and repair.organization_id = p_organization_id and repair.branch_id = p_branch_id
  for update;
  if not found then raise exception 'REPAIR_NOT_FOUND'; end if;
  select closeout.* into existing_closeout
  from public.repair_closeouts closeout
  where closeout.organization_id = p_organization_id
    and closeout.idempotency_key = trim(p_idempotency_key);
  if existing_closeout.id is not null then
    if existing_closeout.repair_id <> p_repair_id or existing_closeout.outcome <> p_outcome then
      raise exception 'REPAIR_CLOSEOUT_CONFLICT';
    end if;
    return jsonb_build_object('repair_id', p_repair_id, 'closeout_id', existing_closeout.id,
      'payment_id', existing_closeout.payment_id, 'store_credit_id', existing_closeout.store_credit_id,
      'idempotent', true, 'final_charge', existing_closeout.final_charge,
      'settlement_amount', existing_closeout.settlement_amount);
  end if;
  if target_repair.status = 'entregado' then raise exception 'REPAIR_ALREADY_DELIVERED'; end if;
  if target_repair.status <> 'listo' then raise exception 'REPAIR_DELIVERY_INVALID_STATE'; end if;

  perform 1 from public.repair_payments payment
  where payment.repair_id = p_repair_id and payment.organization_id = p_organization_id and payment.branch_id = p_branch_id
  order by payment.id for update;
  select coalesce(sum(payment.amount), 0) into paid_before
  from public.repair_payments payment
  where payment.repair_id = p_repair_id and payment.organization_id = p_organization_id and payment.branch_id = p_branch_id;
  paid_before := greatest(paid_before, greatest(0, coalesce(target_repair.paid_amount, 0)));

  perform 1 from public.repair_parts part where part.repair_id = p_repair_id order by part.id for update;
  select count(*) into expected_count from public.repair_parts part where part.repair_id = p_repair_id;
  select count(*), count(distinct value->>'repairPartId') into supplied_count, previous_stock
  from jsonb_array_elements(p_parts);
  if supplied_count <> expected_count or previous_stock <> expected_count then
    raise exception 'REPAIR_PART_RESOLUTION_REQUIRED';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_parts) item
    left join public.repair_parts part on part.id = nullif(item.value->>'repairPartId', '')::uuid and part.repair_id = p_repair_id
    where part.id is null or item.value->>'disposition' not in ('consumed', 'restocked')
  ) then raise exception 'REPAIR_PART_RESOLUTION_REQUIRED'; end if;

  for part_record in
    select part.*, item.value->>'disposition' as disposition
    from public.repair_parts part
    join jsonb_array_elements(p_parts) item on (item.value->>'repairPartId')::uuid = part.id
    where part.repair_id = p_repair_id order by part.id
  loop
    consumed_parts_charge := consumed_parts_charge + case when part_record.disposition = 'consumed'
      then greatest(part_record.quantity, 0) * greatest(coalesce(part_record.unit_price, part_record.unit_cost, 0), 0) else 0 end;
    consumed_parts_cost := consumed_parts_cost + case when part_record.disposition = 'consumed'
      then greatest(part_record.quantity, 0) * greatest(coalesce(part_record.unit_cost, 0), 0) else 0 end;
    resolved_parts := resolved_parts || jsonb_build_array(jsonb_build_object(
      'repairPartId', part_record.id, 'productId', part_record.product_id,
      'name', part_record.part_name, 'quantity', part_record.quantity,
      'unitPrice', coalesce(part_record.unit_price, part_record.unit_cost, 0), 'disposition', part_record.disposition));
  end loop;

  resolved_mode := p_charge->>'mode';
  if resolved_mode = 'none' then final_charge := 0;
  elsif resolved_mode = 'labor' then
    labor_charge := greatest(0, coalesce(nullif(p_charge->>'laborAmount', '')::numeric, 0)); final_charge := labor_charge;
  elsif resolved_mode = 'labor_and_consumed_parts' then
    labor_charge := greatest(0, coalesce(nullif(p_charge->>'laborAmount', '')::numeric, 0)); final_charge := labor_charge + consumed_parts_charge;
  elsif resolved_mode = 'exceptional' then
    if nullif(trim(coalesce(p_reason, '')), '') is null then raise exception 'REPAIR_EXCEPTION_REASON_REQUIRED'; end if;
    final_charge := greatest(0, coalesce(nullif(p_charge->>'amount', '')::numeric, 0));
  else raise exception 'REPAIR_CHARGE_MODE_INVALID'; end if;

  difference := final_charge - paid_before;
  resolved_kind := p_settlement->>'kind';
  resolved_method := nullif(p_settlement->>'method', '');
  settlement_amount := abs(difference);
  if difference > 0 and resolved_kind not in ('payment', 'outstanding') then raise exception 'REPAIR_SETTLEMENT_MISMATCH'; end if;
  if difference = 0 and resolved_kind <> 'none' then raise exception 'REPAIR_SETTLEMENT_MISMATCH'; end if;
  if difference < 0 and resolved_kind not in ('refund', 'store_credit') then raise exception 'REPAIR_SETTLEMENT_MISMATCH'; end if;
  if resolved_kind = 'payment' then
    if resolved_method not in ('cash', 'card', 'transfer')
       or coalesce(nullif(p_settlement->>'amount', '')::numeric, -1) <> settlement_amount then
      raise exception 'REPAIR_SETTLEMENT_MISMATCH';
    end if;
  end if;
  if resolved_kind = 'refund' and resolved_method not in ('cash', 'transfer') then raise exception 'REPAIR_SETTLEMENT_MISMATCH'; end if;
  if resolved_method = 'transfer' and nullif(trim(coalesce(p_settlement->>'reference', '')), '') is null then
    raise exception 'REPAIR_TRANSFER_REFERENCE_REQUIRED';
  end if;
  if resolved_kind in ('payment', 'refund') and resolved_method in ('cash', 'card') then
    if p_cash_session_id is null or not exists (
      select 1 from public.cash_closures closure where closure.id = p_cash_session_id
        and closure.organization_id = p_organization_id and closure.branch_id = p_branch_id and closure.date is null
    ) then raise exception 'REPAIR_CASH_REGISTER_NOT_OPEN'; end if;
  end if;

  for part_record in
    select part.*, item.value->>'disposition' as disposition
    from public.repair_parts part
    join jsonb_array_elements(p_parts) item on (item.value->>'repairPartId')::uuid = part.id
    where part.repair_id = p_repair_id and item.value->>'disposition' = 'restocked' and part.product_id is not null
    order by part.product_id, part.id
  loop
    select inventory.stock_quantity into previous_stock from public.branch_inventory inventory
    where inventory.branch_id = p_branch_id and inventory.product_id = part_record.product_id for update;
    if not found then raise exception 'REPAIR_INVENTORY_ROW_MISSING|%', part_record.product_id; end if;
    update public.branch_inventory set stock_quantity = previous_stock + part_record.quantity, updated_at = operation_time
    where branch_id = p_branch_id and product_id = part_record.product_id;
    insert into public.product_movements (
      product_id, movement_type, quantity, previous_stock, new_stock, unit_cost, total_cost,
      reference_id, reference_type, notes, user_id, branch_id, organization_id, created_at
    ) values (
      part_record.product_id, 'return', part_record.quantity, previous_stock, previous_stock + part_record.quantity,
      part_record.unit_cost, part_record.unit_cost * part_record.quantity, p_repair_id, 'repair_closeout',
      'Repuesto reutilizable devuelto al cerrar reparación sin reparar', p_actor_id, p_branch_id, p_organization_id, operation_time
    );
  end loop;

  if resolved_kind = 'payment' then
    insert into public.repair_payments (
      repair_id, organization_id, branch_id, amount, payment_method, idempotency_key, source,
      reference, notes, cash_session_id, created_by, created_at
    ) values (
      p_repair_id, p_organization_id, p_branch_id, settlement_amount, resolved_method,
      trim(p_idempotency_key) || ':payment', 'delivery', nullif(trim(coalesce(p_settlement->>'reference', '')), ''),
      'Cierre de reparación sin reparar', p_cash_session_id, p_actor_id, operation_time
    ) returning id into created_payment_id;
    if resolved_method <> 'transfer' or p_cash_session_id is not null then
      insert into public.cash_movements (session_id, type, amount, reason, payment_method, created_by, created_at, organization_id, branch_id)
      values (p_cash_session_id, 'cash_in', settlement_amount, 'Cobro cierre reparación ' || coalesce(target_repair.ticket_number, p_repair_id::text),
        resolved_method, p_actor_id, operation_time, p_organization_id, p_branch_id);
    end if;
  elsif resolved_kind = 'refund' then
    if p_cash_session_id is not null then
      insert into public.cash_movements (session_id, type, amount, reason, payment_method, created_by, created_at, organization_id, branch_id)
      values (p_cash_session_id, 'cash_out', settlement_amount, 'Devolución cierre reparación ' || coalesce(target_repair.ticket_number, p_repair_id::text),
        resolved_method, p_actor_id, operation_time, p_organization_id, p_branch_id);
    end if;
  elsif resolved_kind = 'store_credit' then
    insert into public.customer_store_credits (organization_id, customer_id, amount, reason, source_type, source_id, created_by, created_at)
    values (p_organization_id, target_repair.customer_id, settlement_amount,
      'Saldo a favor por cierre de reparación ' || coalesce(target_repair.ticket_number, p_repair_id::text),
      'repair', p_repair_id, p_actor_id, operation_time)
    returning id into created_credit_id;
  end if;

  net_paid := case when difference > 0 and resolved_kind = 'outstanding' then paid_before else final_charge end;
  resolved_payment_status := case when final_charge <= net_paid then 'pagado' when net_paid > 0 then 'parcial' else 'pendiente' end;
  update public.repairs set final_cost = final_charge, estimated_cost = final_charge,
    labor_cost = labor_charge, parts_cost = consumed_parts_cost, paid_amount = net_paid,
    payment_status = resolved_payment_status, status = 'entregado', picked_up_at = operation_time,
    delivered_at = operation_time, completed_at = coalesce(completed_at, operation_time),
    delivery_outcome = p_outcome, solution = coalesce(nullif(trim(coalesce(p_note, '')), ''), solution),
    warranty_expires_at = null, delivery_idempotency_key = trim(p_idempotency_key), updated_at = operation_time
  where id = p_repair_id and organization_id = p_organization_id and branch_id = p_branch_id;

  insert into public.repair_closeouts (
    organization_id, branch_id, repair_id, outcome, charge_mode, labor_charge, consumed_parts_charge,
    final_charge, paid_before, settlement_kind, settlement_amount, settlement_method, settlement_reference,
    cash_session_id, payment_id, store_credit_id, reason, note, parts_resolution, created_by, idempotency_key, created_at
  ) values (
    p_organization_id, p_branch_id, p_repair_id, p_outcome, resolved_mode, labor_charge, consumed_parts_charge,
    final_charge, paid_before, resolved_kind, settlement_amount, resolved_method,
    nullif(trim(coalesce(p_settlement->>'reference', '')), ''), p_cash_session_id, created_payment_id,
    created_credit_id, nullif(trim(coalesce(p_reason, '')), ''), nullif(trim(coalesce(p_note, '')), ''),
    resolved_parts, p_actor_id, trim(p_idempotency_key), operation_time
  ) returning id into existing_closeout.id;

  return jsonb_build_object('repair_id', p_repair_id, 'closeout_id', existing_closeout.id,
    'payment_id', created_payment_id, 'store_credit_id', created_credit_id, 'idempotent', false,
    'final_charge', final_charge, 'paid_before', paid_before, 'settlement_amount', settlement_amount,
    'payment_status', resolved_payment_status);
end;
$$;


ALTER FUNCTION "public"."close_unrepaired_repair"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_outcome" "text", "p_charge" "jsonb", "p_parts" "jsonb", "p_settlement" "jsonb", "p_reason" "text", "p_note" "text", "p_cash_session_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_user_session"("p_session_id" "text", "p_user_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  affected INT;
BEGIN
  UPDATE public.user_sessions
  SET is_active = false, last_activity = now()
  WHERE session_id = p_session_id AND user_id = p_user_id AND is_active = true;

  GET DIAGNOSTICS affected = ROW_COUNT;

  IF affected > 0 THEN
    RETURN json_build_object('success', true, 'message', 'Sesión cerrada correctamente');
  ELSE
    RETURN json_build_object('success', false, 'message', 'Sesión no encontrada o ya cerrada');
  END IF;
END;
$$;


ALTER FUNCTION "public"."close_user_session"("p_session_id" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."collect_pos_first_installment"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_session_id" "uuid", "p_credit_id" "uuid", "p_payment" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  credit public.customer_credits%rowtype;
  installment public.credit_installments%rowtype;
  method text := p_payment->>'method';
  bank text := nullif(trim(p_payment->>'bank'), '');
  reference text := nullif(trim(p_payment->>'reference'), '');
  received numeric;
  payment_id uuid;
begin
  if p_payment is null or p_payment = 'null'::jsonb then return; end if;
  if jsonb_typeof(p_payment) <> 'object' or method is null or method not in ('cash', 'transfer') then
    raise exception 'INVALID_FIRST_INSTALLMENT_PAYMENT';
  end if;
  if not exists (select 1 from public.organization_members m where m.organization_id = p_organization_id
    and m.user_id = p_actor_id and m.status = 'active' and m.role in ('owner','admin','manager','cashier','technician','seller')) then
    raise exception 'POS_PERMISSION_DENIED';
  end if;
  select * into credit from public.customer_credits c where c.id = p_credit_id
    and c.organization_id = p_organization_id and c.branch_id = p_branch_id for update;
  if not found then raise exception 'INVALID_FIRST_INSTALLMENT_PAYMENT'; end if;
  if credit.metadata->'first_installment_payment' is not null then return; end if;
  if credit.metadata->>'first_installment_timing' is distinct from 'at_start' then
    raise exception 'FIRST_INSTALLMENT_REQUIRES_START';
  end if;
  perform 1 from public.cash_closures c where c.id = p_session_id and c.organization_id = p_organization_id
    and c.branch_id = p_branch_id and c.date is null for update;
  if not found then raise exception 'CASH_REGISTER_NOT_OPEN'; end if;
  select * into installment from public.credit_installments i where i.credit_id = p_credit_id
    and i.installment_number = 1 for update;
  if not found or installment.amount <= 0 or coalesce(installment.amount_paid,0) <> 0
    or installment.status = 'paid' then raise exception 'INVALID_FIRST_INSTALLMENT_PAYMENT'; end if;
  if method = 'transfer' then
    if bank is null or reference is null or length(bank) > 120 or length(reference) > 120 then
      raise exception 'FIRST_INSTALLMENT_TRANSFER_REQUIRED';
    end if;
  else
    received := (p_payment->>'cashReceived')::numeric;
    if received is null or received::text in ('NaN','Infinity','-Infinity') or received < installment.amount then
      raise exception 'FIRST_INSTALLMENT_CASH_INSUFFICIENT';
    end if;
  end if;
  insert into public.credit_payments (credit_id, installment_id, amount, payment_method, notes)
  values (credit.id, installment.id, installment.amount, method,
    'Primera cuota cobrada al generar crédito. Venta ' || credit.sale_id::text ||
    case when method = 'transfer' then '. Banco/cuenta: ' || bank || '. Referencia: ' || reference else '' end)
  returning id into payment_id;
  -- The existing payment trigger is the canonical updater of installment/credit status.
  if not exists (select 1 from public.credit_installments i where i.id = installment.id
    and i.status = 'paid' and i.amount_paid = i.amount) then
    raise exception 'CREDIT_PAYMENT_TRIGGER_REQUIRED';
  end if;
  if method = 'cash' then
    insert into public.cash_movements (session_id, type, amount, reason, payment_method, created_by, created_at, organization_id, branch_id)
    values (p_session_id, 'cash_in', installment.amount, 'Cobro primera cuota crédito ' || credit.id::text,
      'cash', p_actor_id, now(), p_organization_id, p_branch_id);
  end if;
  update public.customer_credits set metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
    'first_installment_payment', jsonb_build_object('amount', installment.amount, 'method', method,
      'bank', bank, 'reference', reference, 'cashReceived', received,
      'change', case when method = 'cash' then received - installment.amount else 0 end,
      'paymentId', payment_id, 'actorId', p_actor_id, 'sessionId', p_session_id)) where id = credit.id;
end $$;


ALTER FUNCTION "public"."collect_pos_first_installment"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_session_id" "uuid", "p_credit_id" "uuid", "p_payment" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_organization_onboarding"("p_organization_id" "uuid", "p_user_id" "uuid", "p_display_name" "text", "p_currency" "text", "p_timezone" "text", "p_logo_url" "text", "p_modules" "jsonb", "p_branch" "jsonb", "p_company_info" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  target_branch_id uuid;
  completed_at timestamptz := now();
  existing_company jsonb;
  merged_company jsonb;
  publication jsonb;
begin
  if not exists (
    select 1
    from public.organization_members membership
    where membership.organization_id = p_organization_id
      and membership.user_id = p_user_id
      and membership.status = 'active'
      and membership.role in ('owner', 'admin')
  ) and not exists (
    select 1
    from public.profiles profile
    where profile.id = p_user_id
      and profile.role = 'super_admin'
      and coalesce(profile.status, 'active') not in ('inactive', 'suspended')
  ) then
    raise exception 'ONBOARDING_FORBIDDEN';
  end if;

  update public.organizations
  set name = p_display_name,
      logo_url = nullif(p_logo_url, ''),
      updated_at = completed_at
  where id = p_organization_id;

  if not found then
    raise exception 'ORGANIZATION_NOT_FOUND';
  end if;

  insert into public.organization_settings (
    organization_id, display_name, currency, timezone, branding, modules, updated_at
  )
  values (
    p_organization_id, p_display_name, p_currency, p_timezone,
    '{}'::jsonb, coalesce(p_modules, '{}'::jsonb), completed_at
  )
  on conflict (organization_id) do update
  set display_name = excluded.display_name,
      currency = excluded.currency,
      timezone = excluded.timezone,
      modules = excluded.modules,
      updated_at = excluded.updated_at;

  select branch.id
  into target_branch_id
  from public.branches branch
  where branch.organization_id = p_organization_id
    and (branch.is_default = true or branch.slug = 'principal')
  order by branch.is_default desc, branch.created_at asc
  limit 1
  for update;

  if target_branch_id is null then
    insert into public.branches (
      organization_id, code, name, slug, address, city, phone, email,
      is_active, is_default, metadata, updated_at
    )
    values (
      p_organization_id, 'principal', 'Sucursal principal', 'principal',
      p_branch->>'address', p_branch->>'city',
      nullif(p_branch->>'phone', ''), nullif(p_branch->>'email', ''),
      true, true,
      jsonb_build_object('onboarding_completed_at', completed_at),
      completed_at
    )
    returning id into target_branch_id;
  else
    update public.branches
    set address = p_branch->>'address',
        city = p_branch->>'city',
        phone = nullif(p_branch->>'phone', ''),
        email = nullif(p_branch->>'email', ''),
        metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object('onboarding_completed_at', completed_at),
        updated_at = completed_at
    where id = target_branch_id;
  end if;

  -- ---------------------------------------------------------------------
  -- company_info: fusion, no reemplazo
  -- ---------------------------------------------------------------------
  select value into existing_company
  from public.website_settings
  where organization_id = p_organization_id and key = 'company_info';

  existing_company := coalesce(existing_company, '{}'::jsonb);

  -- `||` deja ganar al lado derecho y conserva las claves que solo estan en el
  -- izquierdo: lo que el onboarding no menciona sobrevive.
  merged_company := existing_company || coalesce(p_company_info, '{}'::jsonb);

  -- `hours` es un objeto anidado y `||` es superficial: sin este paso, mandar
  -- {weekdays, saturday} borraria el domingo que el admin habia cargado.
  if p_company_info ? 'hours' then
    merged_company := jsonb_set(
      merged_company,
      '{hours}',
      coalesce(existing_company->'hours', '{}'::jsonb) || coalesce(p_company_info->'hours', '{}'::jsonb)
    );
  end if;

  -- La publicacion es la unica que se reafirma desde la tabla canonica: nunca
  -- se habilita implicitamente al completar o revisitar el onboarding.
  select jsonb_build_object(
    'marketplacePublic', marketplace_public,
    'storefrontPublic', storefront_public
  )
  into publication
  from public.organizations
  where id = p_organization_id;

  merged_company := merged_company || coalesce(publication, '{}'::jsonb);

  insert into public.website_settings (
    organization_id, key, value, updated_by, updated_at
  )
  values (
    p_organization_id, 'company_info', merged_company, p_user_id, completed_at
  )
  on conflict (organization_id, key) do update
  set value = excluded.value,
      updated_by = excluded.updated_by,
      updated_at = excluded.updated_at;

  return jsonb_build_object(
    'organization_id', p_organization_id,
    'branch_id', target_branch_id,
    'completed_at', completed_at
  );
end;
$$;


ALTER FUNCTION "public"."complete_organization_onboarding"("p_organization_id" "uuid", "p_user_id" "uuid", "p_display_name" "text", "p_currency" "text", "p_timezone" "text", "p_logo_url" "text", "p_modules" "jsonb", "p_branch" "jsonb", "p_company_info" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."complete_organization_onboarding"("p_organization_id" "uuid", "p_user_id" "uuid", "p_display_name" "text", "p_currency" "text", "p_timezone" "text", "p_logo_url" "text", "p_modules" "jsonb", "p_branch" "jsonb", "p_company_info" "jsonb") IS 'Persiste el onboarding de forma atomica. company_info se FUSIONA con lo que ya hubiera (incluido el objeto hours) para no borrar la personalizacion hecha en /admin/website. La publicacion de la tienda nunca se habilita desde aca.';



CREATE OR REPLACE FUNCTION "public"."compute_loyalty_balance_after"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  locked_balance integer;
begin
  insert into public.loyalty_accounts (customer_id, organization_id, balance)
  values (new.customer_id, new.organization_id, 0)
  on conflict (customer_id) do nothing;

  select balance into locked_balance
  from public.loyalty_accounts
  where customer_id = new.customer_id
  for update;

  new.balance_after := coalesce(locked_balance, 0) + new.points;

  if new.balance_after < 0 then
    raise exception 'La operación dejaría el saldo en negativo (saldo actual: %, movimiento: %).',
      coalesce(locked_balance, 0), new.points
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."compute_loyalty_balance_after"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_customer_order_from_pending_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare current_status text;
begin
  select status into current_status from public.customer_orders
  where id = p_order_id and organization_id = p_organization_id for update;
  if not found then raise exception 'ORDER_NOT_FOUND'; end if;
  if current_status = 'CONFIRMED' then
    return jsonb_build_object('order_id', p_order_id, 'unchanged', true);
  end if;
  if current_status <> 'PENDING' then raise exception 'ORDER_TRANSITION_INVALID'; end if;
  return public.confirm_customer_order_store_credit_atomic(
    p_organization_id, p_order_id, p_actor_id, p_note
  );
end;
$$;


ALTER FUNCTION "public"."confirm_customer_order_from_pending_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_customer_order_store_credit_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  order_row public.customer_orders%rowtype;
  reservation_row public.customer_store_credit_reservations%rowtype;
  applied_amount numeric := 0;
begin
  if p_actor_id is null or not exists (
    select 1 from public.organization_members membership
    where membership.organization_id = p_organization_id
      and membership.user_id = p_actor_id
      and membership.status = 'active'
      and membership.role in ('owner', 'admin', 'manager', 'seller', 'cashier')
  ) then
    raise exception 'ORDER_PERMISSION_DENIED';
  end if;

  select * into order_row
  from public.customer_orders customer_order
  where customer_order.id = p_order_id
    and customer_order.organization_id = p_organization_id
  for update;

  if not found then raise exception 'ORDER_NOT_FOUND'; end if;
  if order_row.status = 'CANCELLED' then raise exception 'ORDER_ALREADY_CANCELLED'; end if;

  select * into reservation_row
  from public.customer_store_credit_reservations reservation
  where reservation.organization_id = p_organization_id
    and reservation.order_id = p_order_id
  for update;

  if found then
    applied_amount := reservation_row.amount;
    if reservation_row.status = 'reserved' then
      insert into public.customer_store_credits (
        organization_id, customer_id, amount, reason, source_type, source_id, created_by
      ) values (
        p_organization_id, reservation_row.customer_id, -reservation_row.amount,
        'Aplicado al pedido ' || order_row.order_number,
        'order', p_order_id, p_actor_id
      )
      on conflict (organization_id, source_id)
        where source_type = 'order' and source_id is not null
      do nothing;

      update public.customer_store_credit_reservations
      set status = 'consumed', consumed_at = now(), updated_at = now()
      where id = reservation_row.id and status = 'reserved';
    elsif reservation_row.status = 'released' then
      raise exception 'STORE_CREDIT_RESERVATION_RELEASED';
    end if;
  end if;

  update public.customer_orders
  set status = 'CONFIRMED',
      store_credit_reserved = 0,
      store_credit_applied = applied_amount,
      payment_status = case when applied_amount >= total then 'PAID'
                            when applied_amount > 0 then 'PARTIAL'
                            else payment_status end,
      updated_at = now()
  where id = p_order_id and organization_id = p_organization_id;

  if order_row.status is distinct from 'CONFIRMED' then
    insert into public.customer_order_status_history (
      organization_id, order_id, from_status, to_status, note, changed_by
    ) values (
      p_organization_id, p_order_id, order_row.status, 'CONFIRMED', p_note, p_actor_id
    );
  end if;

  return jsonb_build_object(
    'order_id', p_order_id,
    'store_credit_applied', applied_amount,
    'amount_due', greatest(0, order_row.total - applied_amount),
    'payment_status', case when applied_amount >= order_row.total then 'PAID'
                           when applied_amount > 0 then 'PARTIAL'
                           else order_row.payment_status end
  );
end;
$$;


ALTER FUNCTION "public"."confirm_customer_order_store_credit_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."correct_delivered_repair_final_price"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_new_final_total" numeric, "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  target_repair public.repairs%rowtype;
  existing_revision public.repair_cost_revisions%rowtype;
  membership_role text;
  normalized_reason text := nullif(trim(coalesce(p_reason, '')), '');
  normalized_final_total numeric := round(coalesce(p_new_final_total, -1), 2);
  previous_final_total numeric;
  paid_snapshot numeric;
  new_balance numeric;
  new_payment_status text;
  request_hash text;
  parts_subtotal numeric := 0;
  parts_internal_cost numeric := 0;
  current_labor_tax_rate numeric := 10;
  current_tax_breakdown jsonb := '[]'::jsonb;
  current_tax_gross numeric := 0;
  new_tax_breakdown jsonb := '[]'::jsonb;
  new_revision_id uuid;
  new_revision_number integer;
  previous_snapshot jsonb;
  policy_snapshot jsonb;
  result_payload jsonb;
begin
  if normalized_final_total <= 0 then raise exception 'INVALID_REPAIR_FINAL_PRICE'; end if;
  if normalized_reason is null or length(normalized_reason) < 10 then
    raise exception 'REPAIR_FINAL_PRICE_CORRECTION_REASON_REQUIRED';
  end if;
  if length(trim(coalesce(p_idempotency_key, ''))) < 8 then
    raise exception 'INVALID_REPAIR_COST_IDEMPOTENCY_KEY';
  end if;

  request_hash := md5(jsonb_build_object(
    'repair_id', p_repair_id, 'new_final_total', normalized_final_total, 'reason', normalized_reason
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':' || p_idempotency_key, 0));
  select * into existing_revision
  from public.repair_cost_revisions revision
  where revision.organization_id = p_organization_id and revision.idempotency_key = p_idempotency_key;
  if found then
    if existing_revision.intent_hash is distinct from request_hash then
      raise exception 'REPAIR_COST_IDEMPOTENCY_CONFLICT';
    end if;
    return existing_revision.result_snapshot;
  end if;

  select * into target_repair
  from public.repairs repair
  where repair.id = p_repair_id
    and repair.organization_id = p_organization_id
    and repair.branch_id = p_branch_id
  for update;
  if not found then raise exception 'REPAIR_NOT_FOUND'; end if;
  if target_repair.status <> 'entregado' then raise exception 'REPAIR_FINAL_PRICE_CORRECTION_REQUIRES_DELIVERED'; end if;

  select membership.role::text into membership_role
  from public.organization_members membership
  where membership.organization_id = p_organization_id
    and membership.user_id = p_actor_id and membership.status = 'active';
  if membership_role is null or membership_role not in ('owner', 'admin', 'super_admin') then
    raise exception 'REPAIR_FINAL_PRICE_CORRECTION_FORBIDDEN';
  end if;

  previous_final_total := round(coalesce(target_repair.final_cost, target_repair.estimated_cost, 0), 2);
  paid_snapshot := round(greatest(coalesce(target_repair.paid_amount, 0), 0), 2);
  if normalized_final_total = previous_final_total then raise exception 'REPAIR_FINAL_PRICE_UNCHANGED'; end if;
  if normalized_final_total < paid_snapshot then
    raise exception 'REPAIR_FINAL_PRICE_BELOW_PAID|%' , round(paid_snapshot - normalized_final_total, 2);
  end if;
  new_balance := round(greatest(normalized_final_total - paid_snapshot, 0), 2);
  new_payment_status := case
    when normalized_final_total > 0 and paid_snapshot >= normalized_final_total then 'pagado'
    when paid_snapshot > 0 then 'parcial'
    else 'pendiente'
  end;

  select
    round(coalesce(sum(greatest(0, part.unit_price * part.quantity - coalesce(part.discount_amount, 0))), 0), 2),
    round(coalesce(sum(part.unit_cost * part.quantity), 0), 2)
  into parts_subtotal, parts_internal_cost
  from public.repair_parts part where part.repair_id = p_repair_id;

  select coalesce(revision.labor_tax_rate, 10), coalesce(revision.tax_breakdown, '[]'::jsonb)
  into current_labor_tax_rate, current_tax_breakdown
  from public.repair_cost_revisions revision where revision.id = target_repair.current_cost_revision_id;
  current_labor_tax_rate := coalesce(current_labor_tax_rate, 10);
  current_tax_breakdown := coalesce(current_tax_breakdown, '[]'::jsonb);
  select coalesce(sum((bucket->>'grossAmount')::numeric), 0)
  into current_tax_gross from jsonb_array_elements(current_tax_breakdown) bucket;

  if current_tax_gross > 0 then
    with raw_buckets as (
      select (bucket->>'rate')::numeric rate,
        round((bucket->>'grossAmount')::numeric * normalized_final_total / current_tax_gross, 2) gross_amount
      from jsonb_array_elements(current_tax_breakdown) bucket
    ), adjusted as (
      select rate, case when rate = (select max(rate) from raw_buckets)
        then gross_amount + normalized_final_total - (select sum(gross_amount) from raw_buckets)
        else gross_amount end gross_amount
      from raw_buckets
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'rate', rate, 'grossAmount', gross_amount,
      'taxableBase', round(gross_amount / (1 + rate / 100), 2),
      'taxAmount', round(gross_amount - gross_amount / (1 + rate / 100), 2)
    ) order by rate), '[]'::jsonb) into new_tax_breakdown from adjusted;
  elsif normalized_final_total > 0 then
    new_tax_breakdown := jsonb_build_array(jsonb_build_object(
      'rate', current_labor_tax_rate, 'grossAmount', normalized_final_total,
      'taxableBase', round(normalized_final_total / (1 + current_labor_tax_rate / 100), 2),
      'taxAmount', round(normalized_final_total - normalized_final_total / (1 + current_labor_tax_rate / 100), 2)
    ));
  end if;

  select coalesce(max(revision.revision_number), 0) + 1 into new_revision_number
  from public.repair_cost_revisions revision where revision.repair_id = p_repair_id;
  previous_snapshot := jsonb_build_object(
    'laborAmount', coalesce(target_repair.labor_cost, 0), 'partsSubtotal', parts_subtotal,
    'partsInternalCost', parts_internal_cost, 'additionalCharges', coalesce(target_repair.additional_charges, 0),
    'deductions', coalesce(target_repair.deductions, 0), 'discountAmount', coalesce(target_repair.discount_amount, 0),
    'finalTotal', previous_final_total, 'paidAmount', paid_snapshot
  );
  policy_snapshot := jsonb_build_object(
    'commercialPriceCorrection', true, 'internalCostChanged', false,
    'inventoryChanged', false, 'paymentEntriesChanged', false
  );
  new_revision_id := gen_random_uuid();
  result_payload := jsonb_build_object(
    'revisionId', new_revision_id, 'revisionNumber', new_revision_number,
    'previousFinalTotal', previous_final_total, 'newFinalTotal', normalized_final_total,
    'difference', normalized_final_total - previous_final_total,
    'paidAmount', paid_snapshot, 'balance', new_balance, 'paymentStatus', new_payment_status
  );

  insert into public.repair_cost_revisions (
    id, organization_id, branch_id, repair_id, revision_number, actor_id, actor_role,
    reason, labor_amount, labor_tax_rate, parts_subtotal, parts_internal_cost,
    additional_charges, deductions, discount_amount, subtotal_before_discount,
    final_total, paid_amount_snapshot, balance_snapshot, tax_breakdown,
    policy_snapshot, previous_snapshot, intent_hash, idempotency_key, result_snapshot
  ) values (
    new_revision_id, p_organization_id, p_branch_id, p_repair_id, new_revision_number,
    p_actor_id, membership_role, normalized_reason, coalesce(target_repair.labor_cost, 0),
    current_labor_tax_rate, parts_subtotal, parts_internal_cost,
    coalesce(target_repair.additional_charges, 0), coalesce(target_repair.deductions, 0),
    coalesce(target_repair.discount_amount, 0),
    coalesce(target_repair.labor_cost, 0) + parts_subtotal + coalesce(target_repair.additional_charges, 0),
    normalized_final_total, paid_snapshot, new_balance, new_tax_breakdown,
    policy_snapshot, previous_snapshot, request_hash, p_idempotency_key, result_payload
  );

  insert into public.repair_cost_revision_parts (
    revision_id, organization_id, branch_id, repair_id, product_id, part_name,
    part_number, supplier, quantity, unit_cost_snapshot, unit_price_snapshot,
    discount_amount, tax_rate, subtotal
  ) select new_revision_id, p_organization_id, p_branch_id, p_repair_id,
    part.product_id, part.part_name, part.part_number, part.supplier, part.quantity,
    part.unit_cost, part.unit_price, coalesce(part.discount_amount, 0), coalesce(part.tax_rate, 10),
    greatest(0, part.unit_price * part.quantity - coalesce(part.discount_amount, 0))
  from public.repair_parts part where part.repair_id = p_repair_id;

  update public.repairs
  set final_cost = normalized_final_total,
      estimated_cost = normalized_final_total,
      payment_status = new_payment_status,
      pricing_mode = 'manual',
      price_override_reason = normalized_reason,
      current_cost_revision_id = new_revision_id,
      pricing_updated_by = p_actor_id,
      pricing_updated_at = now(),
      updated_at = now()
  where id = p_repair_id and organization_id = p_organization_id and branch_id = p_branch_id;

  return result_payload;
end;
$$;


ALTER FUNCTION "public"."correct_delivered_repair_final_price"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_new_final_total" numeric, "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."correct_delivered_repair_internal_cost"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_corrections" "jsonb", "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  target_repair public.repairs%rowtype;
  existing_revision public.repair_cost_revisions%rowtype;
  membership_role text;
  normalized_reason text := nullif(trim(coalesce(p_reason, '')), '');
  normalized_corrections jsonb := coalesce(p_corrections, '[]'::jsonb);
  request_hash text;
  correction jsonb;
  corrected_part_id uuid;
  corrected_unit_cost numeric;
  affected_rows integer;
  previous_internal_cost numeric := 0;
  new_internal_cost numeric := 0;
  parts_subtotal numeric := 0;
  new_revision_id uuid;
  new_revision_number integer;
  previous_snapshot jsonb;
  policy_snapshot jsonb;
  result_payload jsonb;
  current_tax_breakdown jsonb := '[]'::jsonb;
  current_labor_tax_rate numeric := 10;
begin
  if jsonb_typeof(normalized_corrections) <> 'array'
     or jsonb_array_length(normalized_corrections) = 0
     or jsonb_array_length(normalized_corrections) > 100 then
    raise exception 'INVALID_REPAIR_INTERNAL_COST_CORRECTIONS';
  end if;
  if normalized_reason is null or length(normalized_reason) < 10 then
    raise exception 'REPAIR_COST_CORRECTION_REASON_REQUIRED';
  end if;
  if length(trim(coalesce(p_idempotency_key, ''))) < 8 then
    raise exception 'INVALID_REPAIR_COST_IDEMPOTENCY_KEY';
  end if;

  request_hash := md5(jsonb_build_object(
    'repair_id', p_repair_id,
    'corrections', normalized_corrections,
    'reason', normalized_reason
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':' || p_idempotency_key, 0));

  select * into existing_revision
  from public.repair_cost_revisions revision
  where revision.organization_id = p_organization_id
    and revision.idempotency_key = p_idempotency_key;
  if found then
    if existing_revision.intent_hash is distinct from request_hash then
      raise exception 'REPAIR_COST_IDEMPOTENCY_CONFLICT';
    end if;
    return existing_revision.result_snapshot;
  end if;

  select * into target_repair
  from public.repairs repair
  where repair.id = p_repair_id
    and repair.organization_id = p_organization_id
    and repair.branch_id = p_branch_id
  for update;
  if not found then raise exception 'REPAIR_NOT_FOUND'; end if;
  if target_repair.status <> 'entregado' then
    raise exception 'REPAIR_COST_CORRECTION_REQUIRES_DELIVERED';
  end if;

  select membership.role::text into membership_role
  from public.organization_members membership
  where membership.organization_id = p_organization_id
    and membership.user_id = p_actor_id
    and membership.status = 'active';
  if membership_role is null or membership_role not in ('owner', 'admin', 'super_admin') then
    raise exception 'REPAIR_COST_CORRECTION_FORBIDDEN';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(normalized_corrections) item
    group by item->>'part_id'
    having count(*) > 1
  ) then
    raise exception 'DUPLICATE_REPAIR_PART_CORRECTION';
  end if;

  select round(coalesce(sum(part.unit_cost * part.quantity), 0), 2)
  into previous_internal_cost
  from public.repair_parts part
  where part.repair_id = p_repair_id;

  for correction in select value from jsonb_array_elements(normalized_corrections)
  loop
    begin
      corrected_part_id := (correction->>'part_id')::uuid;
      corrected_unit_cost := round((correction->>'unit_cost')::numeric, 2);
    exception when others then
      raise exception 'INVALID_REPAIR_INTERNAL_COST_CORRECTION';
    end;
    if corrected_part_id is null or corrected_unit_cost is null or corrected_unit_cost < 0 then
      raise exception 'INVALID_REPAIR_INTERNAL_COST_CORRECTION';
    end if;

    update public.repair_parts
    set unit_cost = corrected_unit_cost
    where id = corrected_part_id
      and repair_id = p_repair_id;
    get diagnostics affected_rows = row_count;
    if affected_rows <> 1 then raise exception 'REPAIR_PART_NOT_FOUND'; end if;
  end loop;

  select
    round(coalesce(sum(part.unit_cost * part.quantity), 0), 2),
    round(coalesce(sum(greatest(0, part.unit_price * part.quantity - coalesce(part.discount_amount, 0))), 0), 2)
  into new_internal_cost, parts_subtotal
  from public.repair_parts part
  where part.repair_id = p_repair_id;

  select coalesce(revision.tax_breakdown, '[]'::jsonb), coalesce(revision.labor_tax_rate, 10)
  into current_tax_breakdown, current_labor_tax_rate
  from public.repair_cost_revisions revision
  where revision.id = target_repair.current_cost_revision_id;
  current_tax_breakdown := coalesce(current_tax_breakdown, '[]'::jsonb);
  current_labor_tax_rate := coalesce(current_labor_tax_rate, 10);

  select coalesce(max(revision.revision_number), 0) + 1
  into new_revision_number
  from public.repair_cost_revisions revision
  where revision.repair_id = p_repair_id;

  previous_snapshot := jsonb_build_object(
    'laborAmount', coalesce(target_repair.labor_cost, 0),
    'partsSubtotal', parts_subtotal,
    'partsInternalCost', previous_internal_cost,
    'additionalCharges', coalesce(target_repair.additional_charges, 0),
    'deductions', coalesce(target_repair.deductions, 0),
    'discountAmount', coalesce(target_repair.discount_amount, 0),
    'finalTotal', coalesce(target_repair.final_cost, target_repair.estimated_cost, 0)
  );
  policy_snapshot := jsonb_build_object(
    'internalCostCorrection', true,
    'commercialTotalChanged', false,
    'inventoryChanged', false,
    'paymentChanged', false
  );
  new_revision_id := gen_random_uuid();
  result_payload := jsonb_build_object(
    'revisionId', new_revision_id,
    'revisionNumber', new_revision_number,
    'previousInternalCost', previous_internal_cost,
    'newInternalCost', new_internal_cost,
    'difference', new_internal_cost - previous_internal_cost,
    'finalTotal', coalesce(target_repair.final_cost, target_repair.estimated_cost, 0)
  );

  insert into public.repair_cost_revisions (
    id, organization_id, branch_id, repair_id, revision_number, actor_id, actor_role,
    reason, labor_amount, labor_tax_rate, parts_subtotal, parts_internal_cost,
    additional_charges, deductions, discount_amount, subtotal_before_discount,
    final_total, paid_amount_snapshot, balance_snapshot, tax_breakdown,
    policy_snapshot, previous_snapshot, intent_hash, idempotency_key, result_snapshot
  ) values (
    new_revision_id, p_organization_id, p_branch_id, p_repair_id, new_revision_number,
    p_actor_id, membership_role, normalized_reason, coalesce(target_repair.labor_cost, 0),
    current_labor_tax_rate, parts_subtotal, new_internal_cost, coalesce(target_repair.additional_charges, 0),
    coalesce(target_repair.deductions, 0), coalesce(target_repair.discount_amount, 0),
    coalesce(target_repair.labor_cost, 0) + parts_subtotal + coalesce(target_repair.additional_charges, 0),
    coalesce(target_repair.final_cost, target_repair.estimated_cost, 0),
    greatest(coalesce(target_repair.paid_amount, 0), 0),
    greatest(coalesce(target_repair.final_cost, target_repair.estimated_cost, 0) - coalesce(target_repair.paid_amount, 0), 0),
    current_tax_breakdown, policy_snapshot, previous_snapshot, request_hash,
    p_idempotency_key, result_payload
  );

  insert into public.repair_cost_revision_parts (
    revision_id, organization_id, branch_id, repair_id, product_id, part_name,
    part_number, supplier, quantity, unit_cost_snapshot, unit_price_snapshot,
    discount_amount, tax_rate, subtotal
  )
  select new_revision_id, p_organization_id, p_branch_id, p_repair_id,
    part.product_id, part.part_name, part.part_number, part.supplier, part.quantity,
    part.unit_cost, part.unit_price, coalesce(part.discount_amount, 0),
    coalesce(part.tax_rate, 10),
    greatest(0, part.unit_price * part.quantity - coalesce(part.discount_amount, 0))
  from public.repair_parts part
  where part.repair_id = p_repair_id;

  update public.repairs
  set parts_cost = new_internal_cost,
      current_cost_revision_id = new_revision_id,
      pricing_updated_by = p_actor_id,
      pricing_updated_at = now(),
      updated_at = now()
  where id = p_repair_id
    and organization_id = p_organization_id
    and branch_id = p_branch_id;

  return result_payload;
end;
$$;


ALTER FUNCTION "public"."correct_delivered_repair_internal_cost"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_corrections" "jsonb", "p_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_dashboard_order_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_customer_id" "uuid", "p_customer" "jsonb", "p_order" "jsonb", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_customer_id uuid := p_customer_id;
  created_order_id uuid;
  item record;
begin
  if not exists (
    select 1 from public.branches b
    where b.id = p_branch_id
      and b.organization_id = p_organization_id
      and b.is_active = true
  ) then
    raise exception 'Invalid branch for order';
  end if;

  if resolved_customer_id is not null and not exists (
    select 1 from public.customers c
    where c.id = resolved_customer_id
      and c.organization_id = p_organization_id
  ) then
    raise exception 'Customer does not belong to organization';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_organization_id::text || ':' || p_branch_id::text || ':order-stock', 0)
  );

  for item in
    select
      (value->>'product_id')::uuid as product_id,
      sum((value->>'quantity')::integer) as quantity
    from jsonb_array_elements(p_items)
    group by (value->>'product_id')::uuid
    order by (value->>'product_id')::uuid
  loop
    update public.branch_inventory bi
    set stock_quantity = bi.stock_quantity - item.quantity,
        updated_at = now()
    from public.products p
    where bi.branch_id = p_branch_id
      and bi.product_id = item.product_id
      and bi.stock_quantity >= item.quantity
      and p.id = bi.product_id
      and p.organization_id = p_organization_id;

    if not found then
      raise exception 'Insufficient stock for product %', item.product_id;
    end if;
  end loop;

  if resolved_customer_id is null then
    insert into public.customers (
      organization_id,
      name,
      email,
      phone,
      address,
      status,
      customer_type,
      created_at,
      updated_at
    )
    values (
      p_organization_id,
      p_customer->>'name',
      nullif(p_customer->>'email', ''),
      coalesce(p_customer->>'phone', ''),
      nullif(p_customer->>'address', ''),
      'active',
      'regular',
      now(),
      now()
    )
    returning id into resolved_customer_id;
  end if;

  insert into public.customer_orders (
    organization_id,
    branch_id,
    customer_id,
    order_number,
    status,
    payment_status,
    payment_method,
    fulfillment_type,
    customer_name,
    customer_email,
    customer_phone,
    customer_address,
    subtotal,
    tax_amount,
    shipping_cost,
    discount_amount,
    total,
    notes,
    stock_reserved,
    created_by,
    created_at,
    updated_at
  )
  values (
    p_organization_id,
    p_branch_id,
    resolved_customer_id,
    p_order->>'order_number',
    'PENDING',
    'PENDING',
    p_order->>'payment_method',
    p_order->>'fulfillment_type',
    p_customer->>'name',
    nullif(p_customer->>'email', ''),
    nullif(p_customer->>'phone', ''),
    nullif(p_customer->>'address', ''),
    (p_order->>'subtotal')::numeric,
    0,
    (p_order->>'shipping_cost')::numeric,
    (p_order->>'discount_amount')::numeric,
    (p_order->>'total')::numeric,
    nullif(p_order->>'notes', ''),
    true,
    p_actor_id,
    now(),
    now()
  )
  returning id into created_order_id;

  insert into public.customer_order_items (
    organization_id,
    order_id,
    product_id,
    product_name,
    product_sku,
    quantity,
    unit_price,
    subtotal
  )
  select
    p_organization_id,
    created_order_id,
    (value->>'product_id')::uuid,
    value->>'product_name',
    nullif(value->>'product_sku', ''),
    (value->>'quantity')::integer,
    (value->>'unit_price')::numeric,
    (value->>'subtotal')::numeric
  from jsonb_array_elements(p_items);

  insert into public.customer_order_status_history (
    organization_id,
    order_id,
    to_status,
    note,
    changed_by
  )
  values (
    p_organization_id,
    created_order_id,
    'PENDING',
    'Pedido creado desde el dashboard.',
    p_actor_id
  );

  return jsonb_build_object(
    'order_id', created_order_id,
    'customer_id', resolved_customer_id
  );
end;
$$;


ALTER FUNCTION "public"."create_dashboard_order_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_customer_id" "uuid", "p_customer" "jsonb", "p_order" "jsonb", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_public_order_atomic"("p_organization_id" "uuid", "p_customer_id" "uuid", "p_customer" "jsonb", "p_order" "jsonb", "p_items" "jsonb", "p_promotion_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  resolved_customer_id uuid := p_customer_id;
  created_order_id uuid;
  item record;
  available_stock integer;
begin
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'ORDER_ITEMS_REQUIRED';
  end if;
  if resolved_customer_id is not null and not exists (
    select 1 from public.customers c where c.id = resolved_customer_id and c.organization_id = p_organization_id
  ) then raise exception 'CUSTOMER_NOT_IN_ORGANIZATION'; end if;

  for item in
    select (value->>'product_id')::uuid product_id,
      nullif(value->>'variant_id', '')::uuid variant_id,
      sum((value->>'quantity')::integer)::integer quantity
    from jsonb_array_elements(p_items)
    group by (value->>'product_id')::uuid, nullif(value->>'variant_id', '')::uuid
    order by (value->>'product_id')::uuid, nullif(value->>'variant_id', '')::uuid nulls first
  loop
    if item.quantity <= 0 then raise exception 'INVALID_ORDER_QUANTITY'; end if;
    if item.variant_id is not null then
      update public.product_variants variant
      set stock_quantity = variant.stock_quantity - item.quantity, updated_at = now()
      where variant.id = item.variant_id and variant.product_id = item.product_id
        and variant.organization_id = p_organization_id and variant.is_active = true
        and variant.stock_quantity >= item.quantity;
      if not found then
        select coalesce(variant.stock_quantity, 0) into available_stock
        from public.product_variants variant
        where variant.id = item.variant_id and variant.product_id = item.product_id
          and variant.organization_id = p_organization_id;
        raise exception 'STOCK_CHANGED_VARIANT|%|%|%', item.product_id, item.variant_id, coalesce(available_stock, 0);
      end if;
    else
      if exists (
        select 1 from public.products product where product.id = item.product_id
          and product.organization_id = p_organization_id and product.has_variants = true
      ) then raise exception 'VARIANT_NOT_AVAILABLE'; end if;
      update public.products product
      set stock_quantity = product.stock_quantity - item.quantity, updated_at = now()
      where product.id = item.product_id and product.organization_id = p_organization_id
        and product.is_active = true and product.stock_quantity >= item.quantity;
      if not found then
        select coalesce(product.stock_quantity, 0) into available_stock from public.products product
        where product.id = item.product_id and product.organization_id = p_organization_id;
        raise exception 'STOCK_CHANGED|%|%', item.product_id, coalesce(available_stock, 0);
      end if;
    end if;
  end loop;

  if p_promotion_id is not null then
    update public.promotions set usage_count = usage_count + 1, updated_at = now()
    where id = p_promotion_id and organization_id = p_organization_id and is_active = true
      and (usage_limit is null or usage_count < usage_limit);
    if not found then raise exception 'PROMOTION_LIMIT_REACHED'; end if;
  end if;

  if resolved_customer_id is null then
    insert into public.customers (organization_id, name, email, phone, address, status, customer_type, created_at, updated_at)
    values (p_organization_id, p_customer->>'name', nullif(p_customer->>'email', ''),
      coalesce(p_customer->>'phone', ''), nullif(p_customer->>'address', ''), 'active', 'regular', now(), now())
    returning id into resolved_customer_id;
  end if;

  insert into public.customer_orders (
    organization_id, customer_id, order_number, status, payment_status, payment_method,
    fulfillment_type, customer_name, customer_email, customer_phone, customer_address,
    subtotal, shipping_cost, discount_amount, tax_amount, total, notes, stock_reserved, created_at, updated_at
  ) values (
    p_organization_id, resolved_customer_id, p_order->>'order_number', 'PENDING', 'PENDING',
    p_order->>'payment_method', p_order->>'fulfillment_type', p_customer->>'name',
    nullif(p_customer->>'email', ''), nullif(p_customer->>'phone', ''), nullif(p_customer->>'address', ''),
    (p_order->>'subtotal')::numeric, (p_order->>'shipping_cost')::numeric,
    (p_order->>'discount_amount')::numeric, 0, (p_order->>'total')::numeric,
    nullif(p_order->>'notes', ''), true, now(), now()
  ) returning id into created_order_id;

  insert into public.customer_order_items (
    organization_id, order_id, product_id, variant_id, variant_name, product_name,
    product_sku, quantity, unit_price, subtotal
  )
  select p_organization_id, created_order_id, (value->>'product_id')::uuid,
    nullif(value->>'variant_id', '')::uuid, nullif(value->>'variant_name', ''),
    value->>'product_name', nullif(value->>'product_sku', ''),
    (value->>'quantity')::integer, (value->>'unit_price')::numeric, (value->>'subtotal')::numeric
  from jsonb_array_elements(p_items);

  insert into public.customer_order_status_history (organization_id, order_id, to_status, note)
  values (p_organization_id, created_order_id, 'PENDING', 'Pedido creado desde la tienda publica.');
  return jsonb_build_object('order_id', created_order_id, 'customer_id', resolved_customer_id);
end;
$$;


ALTER FUNCTION "public"."create_public_order_atomic"("p_organization_id" "uuid", "p_customer_id" "uuid", "p_customer" "jsonb", "p_order" "jsonb", "p_items" "jsonb", "p_promotion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_public_order_idempotent_atomic"("p_organization_id" "uuid", "p_customer_id" "uuid", "p_customer" "jsonb", "p_order" "jsonb", "p_items" "jsonb", "p_promotion_id" "uuid", "p_profile_id" "uuid", "p_profile_name" "text", "p_profile_email" "text", "p_profile_phone" "text", "p_store_credit_amount" numeric, "p_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  inserted_count integer;
  result jsonb;
  existing_order_id uuid;
  existing_customer_id uuid;
begin
  insert into public.customer_order_checkout_attempts (organization_id, attempt_id)
  values (p_organization_id, p_attempt_id)
  on conflict do nothing;
  get diagnostics inserted_count = row_count;

  if inserted_count = 0 then
    select attempt.order_id, customer_order.customer_id
      into existing_order_id, existing_customer_id
    from public.customer_order_checkout_attempts attempt
    left join public.customer_orders customer_order on customer_order.id = attempt.order_id
    where attempt.organization_id = p_organization_id and attempt.attempt_id = p_attempt_id;
    if existing_order_id is null then raise exception 'ORDER_ATTEMPT_IN_PROGRESS'; end if;
    return jsonb_build_object('order_id', existing_order_id, 'customer_id', existing_customer_id, 'replayed', true);
  end if;

  result := public.create_public_order_with_store_credit_atomic(
    p_organization_id, p_customer_id, p_customer, p_order, p_items,
    p_promotion_id, p_profile_id, p_profile_name, p_profile_email,
    p_profile_phone, p_store_credit_amount
  );
  update public.customer_order_checkout_attempts
    set order_id = nullif(result->>'order_id', '')::uuid
    where organization_id = p_organization_id and attempt_id = p_attempt_id;
  return result || jsonb_build_object('replayed', false);
end;
$$;


ALTER FUNCTION "public"."create_public_order_idempotent_atomic"("p_organization_id" "uuid", "p_customer_id" "uuid", "p_customer" "jsonb", "p_order" "jsonb", "p_items" "jsonb", "p_promotion_id" "uuid", "p_profile_id" "uuid", "p_profile_name" "text", "p_profile_email" "text", "p_profile_phone" "text", "p_store_credit_amount" numeric, "p_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_public_order_with_customer_account_atomic"("p_organization_id" "uuid", "p_customer_id" "uuid", "p_customer" "jsonb", "p_order" "jsonb", "p_items" "jsonb", "p_promotion_id" "uuid", "p_profile_id" "uuid", "p_profile_name" "text", "p_profile_email" "text", "p_profile_phone" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  created_order jsonb;
  created_customer_id uuid;
begin
  created_order := public.create_public_order_atomic(
    p_organization_id,
    p_customer_id,
    p_customer,
    p_order,
    p_items,
    p_promotion_id
  );

  if p_profile_id is not null then
    created_customer_id := nullif(created_order->>'customer_id', '')::uuid;

    perform public.link_public_customer_account(
      p_organization_id,
      p_profile_id,
      coalesce(nullif(trim(p_profile_name), ''), p_customer->>'name', 'Cliente'),
      coalesce(nullif(trim(p_profile_email), ''), p_customer->>'email'),
      coalesce(nullif(trim(p_profile_phone), ''), p_customer->>'phone'),
      created_customer_id
    );
  end if;

  return created_order;
end;
$$;


ALTER FUNCTION "public"."create_public_order_with_customer_account_atomic"("p_organization_id" "uuid", "p_customer_id" "uuid", "p_customer" "jsonb", "p_order" "jsonb", "p_items" "jsonb", "p_promotion_id" "uuid", "p_profile_id" "uuid", "p_profile_name" "text", "p_profile_email" "text", "p_profile_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_public_order_with_store_credit_atomic"("p_organization_id" "uuid", "p_customer_id" "uuid", "p_customer" "jsonb", "p_order" "jsonb", "p_items" "jsonb", "p_promotion_id" "uuid", "p_profile_id" "uuid", "p_profile_name" "text", "p_profile_email" "text", "p_profile_phone" "text", "p_store_credit_amount" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  created_order jsonb;
  created_order_id uuid;
  created_customer_id uuid;
  requested_amount numeric := round(greatest(0, coalesce(p_store_credit_amount, 0)), 2);
  order_total numeric := 0;
  ledger_balance numeric := 0;
  reserved_balance numeric := 0;
  available_balance numeric := 0;
begin
  if requested_amount > 0 and p_profile_id is null then
    raise exception 'STORE_CREDIT_PROFILE_REQUIRED';
  end if;

  created_order := public.create_public_order_with_customer_account_atomic(
    p_organization_id,
    p_customer_id,
    p_customer,
    p_order,
    p_items,
    p_promotion_id,
    p_profile_id,
    p_profile_name,
    p_profile_email,
    p_profile_phone
  );

  created_order_id := nullif(created_order->>'order_id', '')::uuid;
  created_customer_id := nullif(created_order->>'customer_id', '')::uuid;

  if requested_amount <= 0 then
    return created_order || jsonb_build_object(
      'store_credit_reserved', 0,
      'store_credit_applied', 0
    );
  end if;

  perform 1
  from public.customers customer
  where customer.id = created_customer_id
    and customer.organization_id = p_organization_id
    and customer.profile_id = p_profile_id
  for update;

  if not found then
    raise exception 'STORE_CREDIT_PROFILE_REQUIRED';
  end if;

  select customer_order.total
  into order_total
  from public.customer_orders customer_order
  where customer_order.id = created_order_id
    and customer_order.organization_id = p_organization_id
  for update;

  if requested_amount > order_total then
    raise exception 'STORE_CREDIT_EXCEEDS_ORDER_TOTAL';
  end if;

  select coalesce(sum(movement.amount), 0)
  into ledger_balance
  from public.customer_store_credits movement
  where movement.organization_id = p_organization_id
    and movement.customer_id = created_customer_id;

  select coalesce(sum(reservation.amount), 0)
  into reserved_balance
  from public.customer_store_credit_reservations reservation
  where reservation.organization_id = p_organization_id
    and reservation.customer_id = created_customer_id
    and reservation.status = 'reserved';

  available_balance := ledger_balance - reserved_balance;
  if requested_amount > available_balance then
    raise exception 'STORE_CREDIT_EXCEEDS_AVAILABLE|%', greatest(0, available_balance);
  end if;

  insert into public.customer_store_credit_reservations (
    organization_id, customer_id, order_id, amount, status, created_by
  ) values (
    p_organization_id, created_customer_id, created_order_id,
    requested_amount, 'reserved', p_profile_id
  );

  update public.customer_orders
  set store_credit_reserved = requested_amount,
      store_credit_applied = 0,
      payment_status = 'PARTIAL',
      updated_at = now()
  where id = created_order_id
    and organization_id = p_organization_id;

  return created_order || jsonb_build_object(
    'store_credit_reserved', requested_amount,
    'store_credit_applied', 0,
    'amount_due', greatest(0, order_total - requested_amount)
  );
end;
$$;


ALTER FUNCTION "public"."create_public_order_with_store_credit_atomic"("p_organization_id" "uuid", "p_customer_id" "uuid", "p_customer" "jsonb", "p_order" "jsonb", "p_items" "jsonb", "p_promotion_id" "uuid", "p_profile_id" "uuid", "p_profile_name" "text", "p_profile_email" "text", "p_profile_phone" "text", "p_store_credit_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_recurring_finance_obligation_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_category_id" "uuid", "p_concept" "text", "p_amount" numeric, "p_vendor" "text", "p_notes" "text", "p_frequency" "text", "p_starts_on" "date", "p_ends_on" "date", "p_due_days_after_accounting" integer, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_id uuid := auth.uid();
  existing_template public.finance_expense_templates%rowtype;
  created_template public.finance_expense_templates%rowtype;
  created_obligation public.finance_obligations%rowtype;
begin
  if actor_id is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;
  if not (
    public.has_org_permission(p_organization_id, 'finances.manage')
    or public.get_user_role(actor_id) = 'super_admin'
  ) then
    raise exception 'FINANCE_RECURRING_PERMISSION_DENIED';
  end if;
  if not public.user_has_branch_access(p_branch_id, actor_id) then
    raise exception 'FINANCE_BRANCH_PERMISSION_DENIED';
  end if;
  if not exists (
    select 1 from public.branches branch
    where branch.id = p_branch_id
      and branch.organization_id = p_organization_id
      and branch.is_active = true
  ) then
    raise exception 'FINANCE_BRANCH_NOT_IN_ORGANIZATION';
  end if;
  if not exists (
    select 1 from public.finance_categories category
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.is_active = true
  ) then
    raise exception 'FINANCE_CATEGORY_INVALID';
  end if;
  if nullif(trim(p_idempotency_key), '') is null
     or char_length(trim(p_idempotency_key)) > 128
     or lower(trim(p_idempotency_key)) like 'finance-system:%' then
    raise exception 'FINANCE_INVALID_IDEMPOTENCY_KEY';
  end if;
  if nullif(trim(p_concept), '') is null or char_length(trim(p_concept)) > 200
     or p_amount is null or p_amount <= 0 or p_amount > 999999999999.99
     or p_amount <> trunc(p_amount, 2)
     or p_frequency not in ('weekly', 'monthly', 'quarterly', 'yearly')
     or p_starts_on is null
     or (p_ends_on is not null and p_ends_on < p_starts_on)
     or p_due_days_after_accounting not between 0 and 366 then
    raise exception 'FINANCE_INVALID_RECURRING_OBLIGATION';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':' || p_branch_id::text || ':' || trim(p_idempotency_key),
    0
  ));

  select template.* into existing_template
  from public.finance_expense_templates template
  where template.organization_id = p_organization_id
    and template.branch_id = p_branch_id
    and template.creation_idempotency_key = trim(p_idempotency_key);

  if found then
    if existing_template.category_id is distinct from p_category_id
       or existing_template.concept is distinct from trim(p_concept)
       or existing_template.amount is distinct from p_amount
       or existing_template.vendor is distinct from nullif(trim(p_vendor), '')
       or existing_template.notes is distinct from nullif(left(trim(p_notes), 2000), '')
       or existing_template.frequency is distinct from p_frequency
       or existing_template.starts_on is distinct from p_starts_on
       or existing_template.ends_on is distinct from p_ends_on
       or existing_template.due_days_after_accounting is distinct from p_due_days_after_accounting then
      raise exception 'FINANCE_RECURRING_IDEMPOTENCY_KEY_REUSED';
    end if;

    select obligation.* into created_obligation
    from public.finance_obligations obligation
    where obligation.organization_id = p_organization_id
      and obligation.branch_id = p_branch_id
      and obligation.template_id = existing_template.id
      and obligation.recurrence_period = p_starts_on;

    return jsonb_build_object(
      'template', to_jsonb(existing_template),
      'obligation', to_jsonb(created_obligation)
    );
  end if;

  insert into public.finance_expense_templates (
    organization_id, branch_id, creation_idempotency_key, category_id,
    concept, amount, vendor, notes, frequency, starts_on, ends_on,
    due_days_after_accounting, status, created_by, updated_by
  ) values (
    p_organization_id, p_branch_id, trim(p_idempotency_key), p_category_id,
    trim(p_concept), p_amount, nullif(trim(p_vendor), ''),
    nullif(left(trim(p_notes), 2000), ''), p_frequency, p_starts_on, p_ends_on,
    p_due_days_after_accounting, 'active', actor_id, actor_id
  ) returning * into created_template;

  insert into public.finance_obligations (
    organization_id, branch_id, category_id, template_id, recurrence_period,
    concept, amount, vendor, accounting_date, due_date, status, notes,
    created_by, updated_by
  ) values (
    p_organization_id, p_branch_id, p_category_id, created_template.id, p_starts_on,
    trim(p_concept), p_amount, nullif(trim(p_vendor), ''), p_starts_on,
    p_starts_on + p_due_days_after_accounting,
    case when p_starts_on + p_due_days_after_accounting < current_date
      then 'overdue' else 'pending' end,
    nullif(left(trim(p_notes), 2000), ''), actor_id, actor_id
  ) returning * into created_obligation;

  return jsonb_build_object(
    'template', to_jsonb(created_template),
    'obligation', to_jsonb(created_obligation)
  );
end;
$$;


ALTER FUNCTION "public"."create_recurring_finance_obligation_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_category_id" "uuid", "p_concept" "text", "p_amount" numeric, "p_vendor" "text", "p_notes" "text", "p_frequency" "text", "p_starts_on" "date", "p_ends_on" "date", "p_due_days_after_accounting" integer, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_stock_movement"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.stock_quantity IS DISTINCT FROM NEW.stock_quantity THEN
    INSERT INTO product_movements (
      product_id,
      movement_type,
      quantity,
      previous_stock,
      new_stock,
      notes
    ) VALUES (
      NEW.id,
      CASE
        WHEN NEW.stock_quantity > OLD.stock_quantity THEN 'entrada'
        WHEN NEW.stock_quantity < OLD.stock_quantity THEN 'salida'
        ELSE 'ajuste'
      END,
      ABS(NEW.stock_quantity - OLD.stock_quantity),
      OLD.stock_quantity,
      NEW.stock_quantity,
      'Ajuste automático de inventario'
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_stock_movement"() OWNER TO "postgres";


