CREATE OR REPLACE FUNCTION "public"."create_test_credit"("p_customer_id" "uuid", "p_principal" numeric, "p_term_months" integer, "p_paid_installments" integer DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_credit_id UUID;
  v_installment_amount NUMERIC;
  i INTEGER;
BEGIN
  INSERT INTO customer_credits (
    customer_id, principal, interest_rate, term_months,
    start_date, status, created_at, updated_at
  ) VALUES (
    p_customer_id, p_principal, 0, p_term_months,
    CURRENT_DATE - INTERVAL '1 month', 'active', NOW(), NOW()
  ) RETURNING id INTO v_credit_id;

  v_installment_amount := ROUND(p_principal / p_term_months, 0);

  FOR i IN 1..p_term_months LOOP
    INSERT INTO credit_installments (
      credit_id, installment_number, due_date, amount, status,
      paid_at, payment_method, amount_paid, created_at
    ) VALUES (
      v_credit_id, i,
      CURRENT_DATE + ((i - 1) || ' months')::INTERVAL,
      v_installment_amount,
      CASE
        WHEN i <= p_paid_installments THEN 'paid'
        WHEN i = p_paid_installments + 1 AND p_paid_installments > 0 THEN 'late'
        ELSE 'pending'
      END,
      CASE WHEN i <= p_paid_installments THEN NOW() ELSE NULL END,
      CASE WHEN i <= p_paid_installments THEN 'cash' ELSE NULL END,
      CASE WHEN i <= p_paid_installments THEN v_installment_amount ELSE 0 END,
      NOW()
    );

    IF i <= p_paid_installments THEN
      INSERT INTO credit_payments (
        credit_id,
        installment_id,
        amount,
        payment_method,
        created_at,
        notes
      )
      SELECT
        v_credit_id,
        id,
        amount,
        'cash',
        NOW() - ((p_paid_installments - i) || ' days')::INTERVAL,
        'Pago cuota ' || installment_number
      FROM credit_installments
      WHERE credit_id = v_credit_id AND installment_number = i;
    END IF;
  END LOOP;

  RETURN v_credit_id;
END;
$$;


ALTER FUNCTION "public"."create_test_credit"("p_customer_id" "uuid", "p_principal" numeric, "p_term_months" integer, "p_paid_installments" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."credit_schedule_due_date"("p_start_date" "date", "p_index" integer, "p_frequency" "text", "p_timing" "text") RETURNS "date"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare
  cycle_index integer;
begin
  if p_start_date is null or p_index is null or p_index < 0
    or p_frequency is null or p_frequency not in ('weekly', 'biweekly', 'monthly')
    or p_timing is null or p_timing not in ('at_start', 'next_cycle') then
    raise exception 'INVALID_CREDIT_SCHEDULE';
  end if;
  cycle_index := p_index + case when p_timing = 'next_cycle' then 1 else 0 end;
  return case p_frequency
    when 'weekly' then p_start_date + 7 * cycle_index
    when 'biweekly' then p_start_date + 15 * cycle_index
    else (p_start_date + make_interval(months => cycle_index))::date
  end;
end $$;


ALTER FUNCTION "public"."credit_schedule_due_date"("p_start_date" "date", "p_index" integer, "p_frequency" "text", "p_timing" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_organization_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_id uuid := auth.uid();
  request_headers jsonb := '{}'::jsonb;
  requested_organization_id uuid;
  membership_count integer;
  sole_organization_id uuid;
begin
  if actor_id is null then
    return null;
  end if;

  begin
    request_headers := coalesce(
      nullif(current_setting('request.headers', true), '')::jsonb,
      '{}'::jsonb
    );
    requested_organization_id := nullif(
      request_headers ->> 'x-organization-id',
      ''
    )::uuid;
  exception
    when invalid_text_representation or invalid_parameter_value then
      requested_organization_id := null;
  end;

  if requested_organization_id is not null and exists (
    select 1
    from public.organization_members membership
    where membership.organization_id = requested_organization_id
      and membership.user_id = actor_id
      and membership.status = 'active'
  ) then
    return requested_organization_id;
  end if;

  select
    count(distinct membership.organization_id),
    (array_agg(membership.organization_id order by membership.created_at))[1]
  into membership_count, sole_organization_id
  from public.organization_members membership
  where membership.user_id = actor_id
    and membership.status = 'active';

  if membership_count = 1 then
    return sole_organization_id;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."current_organization_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrement_branch_order_stock"("p_product_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_quantity" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_updated integer;
begin
  if p_quantity <= 0 then
    return false;
  end if;

  if not exists (
    select 1
      from public.branches
     where id = p_branch_id
       and organization_id = p_organization_id
       and is_active = true
  ) then
    return false;
  end if;

  update public.branch_inventory bi
     set stock_quantity = bi.stock_quantity - p_quantity,
         updated_at = now()
    from public.products p
   where bi.branch_id = p_branch_id
     and bi.product_id = p_product_id
     and bi.stock_quantity >= p_quantity
     and p.id = bi.product_id
     and p.organization_id = p_organization_id;

  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$$;


ALTER FUNCTION "public"."decrement_branch_order_stock"("p_product_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrement_pos_stock_batch_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_items" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  item record;
  product_stock numeric;
  branch_stock numeric;
begin
  if p_branch_id is null or not exists (
    select 1 from public.branches b
    where b.id = p_branch_id
      and b.organization_id = p_organization_id
      and b.is_active = true
  ) then
    raise exception 'Invalid branch for stock operation';
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'At least one stock item is required';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_organization_id::text || ':' || p_branch_id::text || ':pos-stock', 0)
  );

  for item in
    select
      (value->>'product_id')::uuid as product_id,
      sum((value->>'quantity')::numeric) as quantity
    from jsonb_array_elements(p_items)
    group by (value->>'product_id')::uuid
    order by (value->>'product_id')::uuid
  loop
    if item.quantity <= 0 then
      raise exception 'Stock quantity must be positive';
    end if;

    select p.stock_quantity
    into product_stock
    from public.products p
    where p.id = item.product_id
      and p.organization_id = p_organization_id
    for update;

    if not found then
      raise exception 'Product % does not belong to organization', item.product_id;
    end if;

    insert into public.branch_inventory (branch_id, product_id, stock_quantity)
    values (p_branch_id, item.product_id, product_stock)
    on conflict (branch_id, product_id) do nothing;

    select bi.stock_quantity
    into branch_stock
    from public.branch_inventory bi
    where bi.branch_id = p_branch_id
      and bi.product_id = item.product_id
    for update;

    if product_stock < item.quantity or branch_stock < item.quantity then
      raise exception 'Insufficient stock for product %', item.product_id;
    end if;

    update public.products
    set stock_quantity = stock_quantity - item.quantity,
        updated_at = now()
    where id = item.product_id
      and organization_id = p_organization_id;

    update public.branch_inventory
    set stock_quantity = stock_quantity - item.quantity,
        updated_at = now()
    where branch_id = p_branch_id
      and product_id = item.product_id;
  end loop;

  return true;
end;
$$;


ALTER FUNCTION "public"."decrement_pos_stock_batch_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrement_product_stock"("p_product_id" "uuid", "p_organization_id" "uuid", "p_quantity" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_current_stock integer;
begin
  -- Lock the product row for the duration of this transaction.
  -- Any concurrent call for the same product will wait here.
  select stock_quantity
    into v_current_stock
    from public.products
   where id              = p_product_id
     and organization_id = p_organization_id
  for update;

  -- Product not found or stock insufficient → report failure
  if not found or v_current_stock < p_quantity then
    return false;
  end if;

  -- Safe to subtract — do it atomically inside the same transaction
  update public.products
     set stock_quantity = stock_quantity - p_quantity,
         updated_at     = now()
   where id              = p_product_id
     and organization_id = p_organization_id;

  return true;
end;
$$;


ALTER FUNCTION "public"."decrement_product_stock"("p_product_id" "uuid", "p_organization_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."decrement_product_stock"("p_product_id" "uuid", "p_organization_id" "uuid", "p_quantity" integer) IS 'Atomically checks and decrements stock_quantity for a product. Returns FALSE when stock is 0 or insufficient.';



CREATE OR REPLACE FUNCTION "public"."delete_repair_with_inventory"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  deleted_id uuid;
begin
  perform public.replace_repair_parts_with_inventory(
    p_repair_id,
    p_organization_id,
    p_branch_id,
    '[]'::jsonb,
    p_actor_id
  );

  delete from public.repairs
  where id = p_repair_id
    and organization_id = p_organization_id
    and branch_id = p_branch_id
  returning id into deleted_id;

  return deleted_id is not null;
end;
$$;


ALTER FUNCTION "public"."delete_repair_with_inventory"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_due_global_notifications"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer;
begin
  update public.global_notifications
     set status = 'sent',
         sent_at = coalesce(sent_at, now()),
         updated_at = now()
   where status = 'scheduled'
     and scheduled_at is not null
     and scheduled_at <= now();

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."dispatch_due_global_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."downgrade_overdue_accounts"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  affected integer;
begin
  update public.subscriptions
  set
    previous_plan = case when coalesce(plan, 'FREE') <> 'FREE' then plan else previous_plan end,
    plan = 'FREE',
    status = 'active',           -- FREE es un estado usable, no bloqueado
    payment_status = 'unpaid',   -- marca que fue una baja por impago (para banner/reactivación)
    updated_at = now()
  where
    status = 'past_due'
    and updated_at < now() - interval '7 days';

  get diagnostics affected = row_count;

  -- Sincronizar organizations.plan con la suscripción.
  update public.organizations o
  set plan = 'FREE'
  from public.subscriptions s
  where s.organization_id = o.id
    and s.plan = 'FREE'
    and o.plan is distinct from 'FREE';

  return affected;
end;
$$;


ALTER FUNCTION "public"."downgrade_overdue_accounts"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."raffle_winners" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "raffle_id" "uuid" NOT NULL,
    "ticket_id" "uuid" NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "prize_position" integer NOT NULL,
    "prize_title" "text" NOT NULL,
    "claim_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "validated_at" timestamp with time zone,
    "validated_by" "uuid",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "raffle_winners_claim_valid" CHECK (("claim_status" = ANY (ARRAY['pending'::"text", 'validated'::"text", 'delivered'::"text", 'forfeited'::"text"]))),
    CONSTRAINT "raffle_winners_position_positive" CHECK (("prize_position" > 0))
);


ALTER TABLE "public"."raffle_winners" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."draw_raffle_winners"("p_raffle_id" "uuid", "p_seed" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."raffle_winners"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth', 'extensions'
    AS $$
declare
  raffle public.raffles;
  seed text;
  prize jsonb;
  position_index integer := 0;
  winner_ticket public.raffle_tickets;
  taken_customers uuid[] := array[]::uuid[];
  total_tickets integer;
begin
  select * into raffle from public.raffles where id = p_raffle_id for update;

  if not found then
    raise exception 'El sorteo no existe.' using errcode = 'no_data_found';
  end if;

  if current_setting('role', true) <> 'service_role' and not public.has_org_permission(raffle.organization_id, 'promotions.manage') then
    raise exception 'No tenés permiso para sortear.' using errcode = 'insufficient_privilege';
  end if;

  if raffle.status = 'completed' then
    raise exception 'Este sorteo ya fue realizado el %.', raffle.drawn_at
      using errcode = 'restrict_violation';
  end if;

  if raffle.status <> 'closed' and now() < raffle.ends_at then
    raise exception 'El sorteo sigue abierto: cerralo antes de sortear.' using errcode = 'invalid_parameter_value';
  end if;

  if jsonb_array_length(raffle.prizes) = 0 then
    raise exception 'El sorteo no tiene premios cargados.' using errcode = 'invalid_parameter_value';
  end if;

  select count(*) into total_tickets from public.raffle_tickets where raffle_id = p_raffle_id;

  if total_tickets = 0 then
    raise exception 'El sorteo no tiene participantes.' using errcode = 'invalid_parameter_value';
  end if;

  -- Generación de semilla nativa y segura (32 caracteres hex sin depender de pgcrypto)
  seed := coalesce(nullif(p_seed, ''), md5(gen_random_uuid()::text || clock_timestamp()::text));

  perform setseed(
    ((('x' || substr(md5(seed), 1, 8))::bit(32)::bigint % 1000000)::numeric / 1000000)::double precision
  );

  for prize in select * from jsonb_array_elements(raffle.prizes) loop
    position_index := position_index + 1;

    -- Una persona no se lleva dos premios del mismo sorteo
    select t.* into winner_ticket
    from public.raffle_tickets t
    where t.raffle_id = p_raffle_id
      and not (t.customer_id = any(taken_customers))
    order by random()
    limit 1;

    exit when not found;

    taken_customers := taken_customers || winner_ticket.customer_id;

    insert into public.raffle_winners (
      organization_id, raffle_id, ticket_id, customer_id, prize_position, prize_title
    )
    values (
      raffle.organization_id,
      p_raffle_id,
      winner_ticket.id,
      winner_ticket.customer_id,
      coalesce((prize ->> 'position')::integer, position_index),
      coalesce(prize ->> 'title', format('Premio %s', position_index))
    );
  end loop;

  update public.raffles
  set status = 'completed',
      drawn_at = now(),
      drawn_by = coalesce(auth.uid(), raffle.created_by),
      draw_seed = seed,
      updated_at = now()
  where id = p_raffle_id;

  return query
  select * from public.raffle_winners where raffle_id = p_raffle_id order by prize_position;
end;
$$;


ALTER FUNCTION "public"."draw_raffle_winners"("p_raffle_id" "uuid", "p_seed" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_plan_downgrade_archive"("p_organization_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  affected integer := 0;
begin
  update public.products
  set archived_by_plan_at = now(),
      updated_at = now()
  where organization_id = p_organization_id
    and deactivated_by_plan = true
    and archived_by_plan_at is null;

  get diagnostics affected = row_count;

  update public.plan_downgrade_grace
  set stage = 'archived',
      archived_at = now(),
      updated_at = now()
  where organization_id = p_organization_id;

  return affected;
end;
$$;


ALTER FUNCTION "public"."enforce_plan_downgrade_archive"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_plan_downgrade_deactivation"("p_organization_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  grace_row public.plan_downgrade_grace;
  affected integer := 0;
begin
  select * into grace_row
  from public.plan_downgrade_grace
  where organization_id = p_organization_id
    and stage = 'grace'
  for update;

  if grace_row.organization_id is null then
    return 0;
  end if;

  with ranked as (
    select
      r.product_id,
      row_number() over (order by r.units_sold desc, p.created_at asc) as position
    from public.rank_products_by_sales(p_organization_id) r
    join public.products p on p.id = r.product_id
    where p.is_active = true
      and p.archived_by_plan_at is null
  )
  update public.products p
  set is_active = false,
      deactivated_by_plan = true,
      updated_at = now()
  from ranked
  where ranked.product_id = p.id
    and ranked.position > grace_row.product_limit;

  get diagnostics affected = row_count;

  update public.plan_downgrade_grace
  set stage = 'deactivated',
      deactivated_at = now(),
      archive_deadline_at = now() + interval '30 days',
      updated_at = now()
  where organization_id = p_organization_id;

  return affected;
end;
$$;


ALTER FUNCTION "public"."enforce_plan_downgrade_deactivation"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_branch_inventory_tenant_match"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_branch_organization_id UUID;
  v_product_organization_id UUID;
BEGIN
  SELECT organization_id
  INTO v_branch_organization_id
  FROM public.branches
  WHERE id = NEW.branch_id;

  SELECT organization_id
  INTO v_product_organization_id
  FROM public.products
  WHERE id = NEW.product_id;

  IF v_branch_organization_id IS NOT NULL
     AND v_product_organization_id IS NOT NULL
     AND v_branch_organization_id IS DISTINCT FROM v_product_organization_id THEN
    RAISE EXCEPTION 'La sucursal y el producto pertenecen a organizaciones diferentes.';
  END IF;

  RETURN NEW;
END;
$$;


