CREATE OR REPLACE FUNCTION "public"."expire_stale_orders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  stale_order record;
  expired_count integer := 0;
begin
  for stale_order in
    select id, organization_id
    from public.customer_orders
    where status = 'PENDING'
      and payment_status in ('PENDING', 'PARTIAL')
      and stock_reserved = true
      and created_at < now() - interval '72 hours'
    order by created_at
    for update skip locked
  loop
    perform public.cancel_customer_order_atomic(
      stale_order.organization_id, stale_order.id, null,
      'Expirada automaticamente por falta de pago (72h).'
    );
    expired_count := expired_count + 1;
  end loop;
  return expired_count;
end;
$$;


ALTER FUNCTION "public"."expire_stale_orders"() OWNER TO "postgres";


