CREATE OR REPLACE FUNCTION "public"."fill_product_movement_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product_org UUID;
  v_branch_org  UUID;
BEGIN
  SELECT organization_id INTO v_product_org
  FROM public.products
  WHERE id = NEW.product_id;

  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := v_product_org;
  END IF;

  -- La sucursal por defecto de la columna puede ser de otra empresa
  -- (get_default_branch_id no filtra por organization_id). Si la sucursal no
  -- pertenece a la misma empresa que el producto, se reemplaza por la sucursal
  -- por defecto de esa empresa antes de que la fila quede escrita.
  IF NEW.branch_id IS NOT NULL AND v_product_org IS NOT NULL THEN
    SELECT organization_id INTO v_branch_org
    FROM public.branches
    WHERE id = NEW.branch_id;

    IF v_branch_org IS DISTINCT FROM v_product_org THEN
      NEW.branch_id := NULL;
    END IF;
  END IF;

  IF NEW.branch_id IS NULL AND v_product_org IS NOT NULL THEN
    SELECT id INTO NEW.branch_id
    FROM public.branches
    WHERE organization_id = v_product_org
    ORDER BY is_default DESC NULLS LAST, created_at ASC
    LIMIT 1;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fill_product_movement_scope"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fill_product_movement_scope"() IS 'Completa organization_id y corrige branch_id en product_movements. Sin organization_id la política de lectura oculta la fila para siempre.';



CREATE OR REPLACE FUNCTION "public"."fix_mojibake_latin1_utf8"("input_text" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  converted text;
BEGIN
  IF input_text IS NULL THEN
    RETURN NULL;
  END IF;

  IF position('Ã' in input_text) = 0
     AND position('Â' in input_text) = 0
     AND position('�' in input_text) = 0
     AND position('Ãƒ' in input_text) = 0
     AND position('Ã‚' in input_text) = 0
     AND position('ï¿½' in input_text) = 0 THEN
    RETURN input_text;
  END IF;

  BEGIN
    converted := convert_from(convert_to(input_text, 'LATIN1'), 'UTF8');
    RETURN COALESCE(converted, input_text);
  EXCEPTION WHEN OTHERS THEN
    RETURN input_text;
  END;
END;
$$;


ALTER FUNCTION "public"."fix_mojibake_latin1_utf8"("input_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_all_recurring_finance_obligations"("p_generation_date" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  organization_record record;
  inserted_count integer := 0;
begin
  if auth.uid() is not null then
    raise exception 'FINANCE_GLOBAL_GENERATION_SERVICE_ONLY';
  end if;
  if p_generation_date is null then
    raise exception 'FINANCE_GENERATION_DATE_REQUIRED';
  end if;

  for organization_record in
    select distinct template.organization_id
    from public.finance_expense_templates template
    where template.status = 'active'
      and template.starts_on <= p_generation_date
      and (template.ends_on is null or template.ends_on >= p_generation_date)
    order by template.organization_id
  loop
    inserted_count := inserted_count
      + public.generate_recurring_finance_obligations(
        p_generation_date,
        organization_record.organization_id
      );
  end loop;

  return inserted_count;
end;
$$;


ALTER FUNCTION "public"."generate_all_recurring_finance_obligations"("p_generation_date" "date") OWNER TO "postgres";


