CREATE OR REPLACE FUNCTION "public"."get_database_growth_history"("days_back" integer DEFAULT 30) RETURNS TABLE("snapshot_date" "date", "total_size_bytes" bigint, "total_size_mb" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    dgs.snapshot_date,
    dgs.total_size_bytes,
    round(dgs.total_size_bytes / (1024.0 * 1024.0), 2) AS total_size_mb
  FROM public.database_growth_snapshots dgs
  WHERE dgs.snapshot_date >= (CURRENT_DATE - days_back)
  ORDER BY dgs.snapshot_date ASC;
END;
$$;


