CREATE OR REPLACE FUNCTION "public"."get_default_dashboard_organization"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS TABLE("organization_id" "uuid", "organization_slug" "text", "membership_role" "text")
    LANGUAGE "sql" STABLE
    AS $$
  with memberships as (
    select
      om.organization_id,
      o.slug as organization_slug,
      om.role::text as membership_role,
      case
        when om.role::text in ('owner', 'admin') then 1
        when om.role::text in ('manager', 'staff') then 2
        when om.role::text = 'customer' then 3
        else 99
      end as role_priority,
      om.created_at
    from public.organization_members om
    join public.organizations o on o.id = om.organization_id
    where om.user_id = p_user_id
      and om.status = 'active'
  )
  select
    m.organization_id,
    m.organization_slug,
    m.membership_role
  from memberships m
  order by m.role_priority asc, m.created_at asc
  limit 1;
$$;


ALTER FUNCTION "public"."get_default_dashboard_organization"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_index_stats"() RETURNS TABLE("table_name" "text", "index_name" "text", "size_bytes" bigint, "idx_scan" bigint, "idx_tup_read" bigint, "is_primary" boolean, "is_unique" boolean, "is_constraint_backed" boolean, "stats_reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH current_db AS (
    SELECT stats_reset
    FROM pg_stat_database
    WHERE datname = current_database()
    LIMIT 1
  )
  SELECT
    format('%I.%I', idx.schemaname, idx.relname)::text AS table_name,
    idx.indexrelname::text AS index_name,
    pg_relation_size(idx.indexrelid) AS size_bytes,
    idx.idx_scan::bigint,
    idx.idx_tup_read::bigint,
    ind.indisprimary AS is_primary,
    ind.indisunique AS is_unique,
    EXISTS (
      SELECT 1
      FROM pg_constraint con
      WHERE con.conindid = idx.indexrelid
    ) AS is_constraint_backed,
    current_db.stats_reset AS stats_reset_at
  FROM pg_stat_user_indexes idx
  JOIN pg_index ind ON ind.indexrelid = idx.indexrelid
  CROSS JOIN current_db
  ORDER BY idx.idx_scan ASC, pg_relation_size(idx.indexrelid) DESC;
END;
$$;


ALTER FUNCTION "public"."get_index_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_jwt_role"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return coalesce(
    (
      select ur.role
      from public.user_roles ur
      where ur.user_id = auth.uid()
        and ur.is_active = true
      order by (ur.expires_at is null) desc, ur.expires_at desc
      limit 1
    ),
    (
      select p.role
      from public.profiles p
      where p.id = auth.uid()
      limit 1
    ),
    'cliente'
  )::text;
end;
$$;


