CREATE OR REPLACE FUNCTION "public"."get_products_with_alerts"("p_limit" integer DEFAULT 10, "p_offset" integer DEFAULT 0) RETURNS TABLE("product_id" "uuid", "name" "text", "sku" "text", "stock_quantity" integer, "min_stock" integer, "alert_type" "text", "alert_message" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.id as product_id,
    p.name,
    p.sku,
    p.stock_quantity,
    p.min_stock,
    pa.alert_type,
    pa.message as alert_message,
    pa.created_at
  FROM product_alerts pa
  JOIN products p ON pa.product_id = p.id
  WHERE pa.is_resolved = false
  ORDER BY pa.created_at DESC
  LIMIT p_limit OFFSET p_offset;
END;
$$;


