CREATE OR REPLACE FUNCTION "public"."get_profile_summary"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_profile jsonb;
  v_role text;
  v_stats jsonb;
  v_sales_count int;
  v_tasks_count int;
  v_login_streak int;
  v_last_activity timestamptz;
  v_thirty_days_ago timestamptz := now() - interval '30 days';
begin
  if p_user_id is null or p_user_id <> auth.uid() then
    raise exception 'No autorizado: acceso al resumen de perfil';
  end if;

  select to_jsonb(p.*) into v_profile
  from profiles p
  where p.id = p_user_id;

  if v_profile is null then
     return jsonb_build_object('error', 'Perfil no encontrado');
  end if;

  begin
    select role into v_role
    from user_roles
    where user_id = p_user_id
    limit 1;
  exception when undefined_table then
    v_role := null;
  end;

  if v_role is null then
    v_role := v_profile->>'role';
  end if;

  select count(*) into v_sales_count
  from sales
  where created_by = p_user_id
    and created_at >= v_thirty_days_ago;

  select count(*) into v_tasks_count
  from audit_log
  where user_id = p_user_id
    and created_at >= v_thirty_days_ago
    and action not in ('login', 'sign_in', 'login_failed');

  with distinct_dates as (
    select distinct date_trunc('day', created_at)::date as day
    from audit_log
    where user_id = p_user_id
      and action in ('login', 'sign_in')
      and created_at >= (now() - interval '60 days')
  ),
  groups as (
    select
      day,
      day - (row_number() over (order by day) * interval '1 day')::interval as grp
    from distinct_dates
  ),
  latest_streak as (
      select count(*) as streak
      from groups
      where grp = (
        select grp
        from groups
        order by day desc
        limit 1
      )
      and day >= (current_date - interval '1 day')
  )
  select coalesce((select streak from latest_streak), 0) into v_login_streak;

  select max(ts) into v_last_activity
  from (
    select created_at as ts from sales where created_by = p_user_id
    union all
    select created_at as ts from audit_log where user_id = p_user_id
  ) t;

  v_stats := jsonb_build_object(
    'totalSales', coalesce(v_sales_count, 0),
    'completedTasks', coalesce(v_tasks_count, 0),
    'loginStreak', coalesce(v_login_streak, 0),
    'lastActivity', v_last_activity
  );

  return jsonb_build_object(
    'profile', v_profile,
    'role', v_role,
    'stats', v_stats
  );
end;
$$;


ALTER FUNCTION "public"."get_profile_summary"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_query_performance"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result json;
  cache_hit_ratio numeric;
  total_blks_hit numeric;
  total_blks_read numeric;
BEGIN
  SELECT sum(blks_hit), sum(blks_read)
  INTO total_blks_hit, total_blks_read
  FROM pg_stat_database
  WHERE datname = current_database();

  IF total_blks_hit + total_blks_read > 0 THEN
    cache_hit_ratio := round((total_blks_hit * 100.0 / (total_blks_hit + total_blks_read)), 2);
  ELSE
    cache_hit_ratio := 100.0;
  END IF;

  result := json_build_object(
    'avgQueryTime', 0,
    'queriesPerSecond', 0,
    'cacheHitRatio', cache_hit_ratio,
    'slowQueries', '[]'::json
  );

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_query_performance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recent_activity_feed"("p_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "type" "text", "amount" numeric, "status" "text", "created_at" timestamp with time zone, "info_1" "text", "info_2" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH all_activity AS (
    (
      SELECT
        s.id,
        'sale'::TEXT as type,
        s.total_amount as amount,
        s.status,
        s.created_at,
        NULL::TEXT as info_1,
        NULL::TEXT as info_2
      FROM sales s
      ORDER BY s.created_at DESC
      LIMIT p_limit
    )
    UNION ALL
    (
      SELECT
        r.id,
        'repair'::TEXT as type,
        r.final_cost as amount,
        r.status,
        r.created_at,
        r.device_brand as info_1,
        r.device_model as info_2
      FROM repairs r
      ORDER BY r.created_at DESC
      LIMIT p_limit
    )
    UNION ALL
    (
      SELECT
        c.id,
        'customer'::TEXT as type,
        NULL::NUMERIC as amount,
        'new'::TEXT as status,
        c.created_at,
        c.name as info_1,
        NULL::TEXT as info_2
      FROM customers c
      ORDER BY c.created_at DESC
      LIMIT p_limit
    )
  )
  SELECT *
  FROM all_activity
  ORDER BY created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_recent_activity_feed"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recent_movements"("days" integer DEFAULT 30, "limit_count" integer DEFAULT 50) RETURNS TABLE("movement_id" "uuid", "product_name" character varying, "product_sku" character varying, "movement_type" character varying, "quantity" integer, "previous_stock" integer, "new_stock" integer, "total_cost" numeric, "created_at" timestamp with time zone, "notes" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        pm.id,
        p.name,
        p.sku,
        pm.movement_type,
        pm.quantity,
        pm.previous_stock,
        pm.new_stock,
        pm.total_cost,
        pm.created_at,
        pm.notes
    FROM product_movements pm
    JOIN products p ON pm.product_id = p.id
    WHERE pm.created_at >= NOW() - INTERVAL '%s days' % days
    ORDER BY pm.created_at DESC
    LIMIT limit_count;
END;
$$;


ALTER FUNCTION "public"."get_recent_movements"("days" integer, "limit_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_security_stats"("p_hours" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    stats JSONB;
    total_events INTEGER;
    critical_events INTEGER;
    high_risk_events INTEGER;
    failed_attempts INTEGER;
    unique_users INTEGER;
    unique_ips INTEGER;
BEGIN
    -- Solo usuarios con permisos pueden ver estadísticas
    IF NOT public.has_permission('settings.read') THEN
        RAISE EXCEPTION 'Acceso denegado: se requiere permiso settings.read';
    END IF;

    -- Calcular estadísticas para el período especificado
    SELECT
        COUNT(*),
        COUNT(*) FILTER (WHERE new_values->>'severity' = 'critical'),
        COUNT(*) FILTER (WHERE new_values->>'severity' = 'high'),
        COUNT(*) FILTER (WHERE action LIKE '%failed%' OR action = 'permission_denied'),
        COUNT(DISTINCT user_id) FILTER (WHERE user_id IS NOT NULL),
        COUNT(DISTINCT ip_address) FILTER (WHERE ip_address IS NOT NULL)
    INTO
        total_events,
        critical_events,
        high_risk_events,
        failed_attempts,
        unique_users,
        unique_ips
    FROM public.audit_log
    WHERE created_at >= NOW() - INTERVAL '1 hour' * p_hours;

    -- Construir objeto JSON con las estadísticas
    stats := jsonb_build_object(
        'totalEvents', total_events,
        'criticalEvents', critical_events,
        'highRiskEvents', high_risk_events,
        'failedAttempts', failed_attempts,
        'uniqueUsers', unique_users,
        'uniqueIPs', unique_ips,
        'period_hours', p_hours,
        'generated_at', NOW()
    );

    RETURN stats;
END;
$$;


ALTER FUNCTION "public"."get_security_stats"("p_hours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_security_stats"("p_hours" integer) IS 'Obtiene estadísticas de seguridad para el período especificado';



CREATE OR REPLACE FUNCTION "public"."get_site_analytics_summary"("p_days" integer DEFAULT 30, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_site" "text" DEFAULT NULL::"text", "p_tz" "text" DEFAULT 'America/Asuncion'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_days integer := least(greatest(coalesce(p_days, 30), 1), 366);
  v_today date := (now() at time zone p_tz)::date;
  v_first_day date := v_today - (v_days - 1);
  v_from timestamptz := v_first_day::timestamp at time zone p_tz;
  v_prev_from timestamptz := (v_first_day - v_days)::timestamp at time zone p_tz;
  v_result jsonb;
begin
  with scoped as (
    select *
    from public.site_analytics_events e
    where e.created_at >= v_prev_from
      and (p_organization_id is null or e.organization_id = p_organization_id)
      and (p_site is null or e.site = p_site)
  ),
  ev as (
    select * from scoped where created_at >= v_from
  ),
  pv as (
    select * from ev where event_type = 'page_view'
  ),
  prev_pv as (
    select * from scoped where created_at < v_from and event_type = 'page_view'
  ),
  orders as (
    select session_id, organization_id, coalesce(value, 0) as value
    from ev
    where event_type = 'order_placed'
  ),
  searches as (
    select session_id, search_term, results_count
    from ev
    where event_type = 'search' and search_term is not null
  ),
  sessions as (
    select session_id, count(*) as views
    from pv
    group by session_id
  ),
  session_sources as (
    select distinct on (session_id)
      session_id,
      coalesce(nullif(utm_source, ''), nullif(referrer_host, ''), 'directo') as source,
      coalesce(device, 'desktop') as device
    from pv
    order by session_id, created_at
  ),
  session_orders as (
    select session_id, count(*) as orders, sum(value) as revenue
    from orders
    group by session_id
  ),
  session_flags as (
    select
      session_id,
      bool_or(event_type = 'page_view') as viewed,
      bool_or(event_type = 'page_view' and page_type = 'producto') as viewed_product,
      bool_or(event_type = 'add_to_cart') as added_to_cart,
      bool_or(event_type in ('order_placed', 'whatsapp_click', 'phone_click')) as contacted_or_ordered
    from ev
    group by session_id
  )
  select jsonb_build_object(
    'range', jsonb_build_object('days', v_days, 'from', v_first_day, 'to', v_today, 'timezone', p_tz),
    'totals', jsonb_build_object(
      'page_views', (select count(*) from pv),
      'visitors', (select count(distinct visitor_id) from pv),
      'sessions', (select count(*) from sessions),
      'bounce_rate', coalesce((
        select round(100.0 * count(*) filter (where views = 1) / nullif(count(*), 0), 1)
        from sessions
      ), 0),
      'pages_per_session', coalesce((select round(avg(views)::numeric, 2) from sessions), 0)
    ),
    'previous', jsonb_build_object(
      'page_views', (select count(*) from prev_pv),
      'visitors', (select count(distinct visitor_id) from prev_pv),
      'orders', (select count(*) from scoped where created_at < v_from and event_type = 'order_placed'),
      'revenue', (
        select coalesce(sum(value), 0)
        from scoped
        where created_at < v_from and event_type = 'order_placed'
      )
    ),
    'active_now', (
      select count(distinct visitor_id)
      from ev
      where created_at >= now() - interval '5 minutes'
    ),
    'sales', jsonb_build_object(
      'orders', (select count(*) from orders),
      'revenue', (select coalesce(sum(value), 0) from orders),
      'average_order_value', coalesce((select round(avg(value), 2) from orders), 0),
      'conversion_rate', coalesce((
        select round(100.0 * (select count(distinct session_id) from orders) / nullif(count(*), 0), 2)
        from sessions
      ), 0)
    ),
    'daily', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'date', d.day,
        'page_views', coalesce(x.page_views, 0),
        'visitors', coalesce(x.visitors, 0)
      ) order by d.day), '[]'::jsonb)
      from generate_series(v_first_day, v_today, interval '1 day') as g(ts)
      cross join lateral (select g.ts::date as day) d
      left join (
        select (created_at at time zone p_tz)::date as day,
               count(*) as page_views,
               count(distinct visitor_id) as visitors
        from pv
        group by 1
      ) x on x.day = d.day
    ),
    'top_pages', (
      select coalesce(jsonb_agg(t order by t.page_views desc), '[]'::jsonb)
      from (
        select x.path, x.page_type, p.name as product_name, x.page_views, x.visitors
        from (
          select path,
                 max(page_type) as page_type,
                 max(entity_id) as entity_id,
                 count(*) as page_views,
                 count(distinct visitor_id) as visitors
          from pv
          group by path
          order by count(*) desc
          limit 10
        ) x
        left join public.products p on p.id::text = x.entity_id
      ) t
    ),
    'top_products', (
      select coalesce(jsonb_agg(t order by t.views desc), '[]'::jsonb)
      from (
        select x.entity_id as product_id, p.name, x.views, x.add_to_cart
        from (
          select entity_id,
                 count(*) filter (where event_type = 'page_view') as views,
                 count(*) filter (where event_type = 'add_to_cart') as add_to_cart
          from ev
          where entity_id is not null
            and (page_type = 'producto' or event_type = 'add_to_cart')
          group by entity_id
        ) x
        left join public.products p on p.id::text = x.entity_id
        order by x.views desc, x.add_to_cart desc
        limit 10
      ) t
    ),
    'sources', (
      select coalesce(jsonb_agg(t order by t.sessions desc), '[]'::jsonb)
      from (
        select s.source,
               count(*) as sessions,
               coalesce(sum(o.orders), 0) as orders,
               coalesce(sum(o.revenue), 0) as revenue
        from session_sources s
        left join session_orders o on o.session_id = s.session_id
        group by s.source
        order by count(*) desc
        limit 10
      ) t
    ),
    'devices', (
      select coalesce(jsonb_agg(t order by t.sessions desc), '[]'::jsonb)
      from (
        select device, count(*) as sessions
        from session_sources
        group by device
      ) t
    ),
    'countries', (
      select coalesce(jsonb_agg(t order by t.visitors desc), '[]'::jsonb)
      from (
        select coalesce(country, '??') as country, count(distinct visitor_id) as visitors
        from pv
        group by 1
        order by count(distinct visitor_id) desc
        limit 10
      ) t
    ),
    'searches', jsonb_build_object(
      'total', (select count(*) from searches),
      'without_results', (select count(*) from searches where results_count = 0),
      'top_terms', (
        select coalesce(jsonb_agg(t order by t.searches desc), '[]'::jsonb)
        from (
          select search_term as term,
                 count(*) as searches,
                 count(distinct session_id) as sessions,
                 round(avg(results_count)::numeric, 1) as avg_results
          from searches
          group by search_term
          order by count(*) desc
          limit 15
        ) t
      ),
      'without_results_terms', (
        select coalesce(jsonb_agg(t order by t.searches desc), '[]'::jsonb)
        from (
          select search_term as term, count(*) as searches
          from searches
          where results_count = 0
          group by search_term
          order by count(*) desc
          limit 15
        ) t
      )
    ),
    'interactions', jsonb_build_object(
      'whatsapp_click', (select count(*) from ev where event_type = 'whatsapp_click'),
      'phone_click', (select count(*) from ev where event_type = 'phone_click'),
      'add_to_cart', (select count(*) from ev where event_type = 'add_to_cart'),
      'order_placed', (select count(*) from orders)
    ),
    'funnel', jsonb_build_object(
      'sessions', (select count(*) from session_flags where viewed),
      'viewed_product', (select count(*) from session_flags where viewed and viewed_product),
      'added_to_cart', (select count(*) from session_flags where viewed and added_to_cart),
      'contacted_or_ordered', (select count(*) from session_flags where viewed and contacted_or_ordered)
    ),
    'by_site', (
      select coalesce(jsonb_agg(t order by t.page_views desc), '[]'::jsonb)
      from (
        select site, count(*) as page_views, count(distinct visitor_id) as visitors
        from pv
        group by site
      ) t
    ),
    'top_organizations', (
      select coalesce(jsonb_agg(t order by t.page_views desc), '[]'::jsonb)
      from (
        select o.id as organization_id, o.name, o.slug,
               v.page_views, v.visitors, v.marketplace_views,
               coalesce(r.orders, 0) as orders,
               coalesce(r.revenue, 0) as revenue
        from (
          select organization_id,
                 count(*) as page_views,
                 count(distinct visitor_id) as visitors,
                 count(*) filter (where site = 'marketplace') as marketplace_views
          from pv
          where organization_id is not null
          group by organization_id
          order by count(*) desc
          limit 25
        ) v
        join public.organizations o on o.id = v.organization_id
        left join (
          select organization_id, count(*) as orders, sum(value) as revenue
          from orders
          group by organization_id
        ) r on r.organization_id = v.organization_id
      ) t
    )
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_site_analytics_summary"("p_days" integer, "p_organization_id" "uuid", "p_site" "text", "p_tz" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_storage_usage"() RETURNS TABLE("category" "text", "size_bytes" bigint, "size_mb" numeric, "percentage" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  total_db_size bigint;
BEGIN
  -- Get total database size
  SELECT pg_database_size(current_database()) INTO total_db_size;

  RETURN QUERY
  WITH storage_data AS (
    SELECT
      'Tablas' as category,
      SUM(pg_total_relation_size(format('%I.%I', schemaname, tablename))) as size_bytes
    FROM pg_tables
    WHERE schemaname NOT IN ('information_schema', 'pg_catalog', 'pg_toast')

    UNION ALL

    SELECT
      'Índices' as category,
      SUM(pg_indexes_size(format('%I.%I', schemaname, tablename))) as size_bytes
    FROM pg_tables
    WHERE schemaname NOT IN ('information_schema', 'pg_catalog', 'pg_toast')
  )
  SELECT
    sd.category,
    sd.size_bytes,
    ROUND(sd.size_bytes / 1024.0 / 1024.0, 2) as size_mb,
    ROUND((sd.size_bytes::numeric / NULLIF(total_db_size, 0)::numeric) * 100, 2) as percentage
  FROM storage_data sd
  ORDER BY sd.size_bytes DESC;
END;
$$;


ALTER FUNCTION "public"."get_storage_usage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_storefront_daily_visits"("p_from" "date", "p_to" "date", "p_tz" "text" DEFAULT 'America/Asuncion'::"text") RETURNS TABLE("organization_id" "uuid", "day" "date", "page" "text", "views" bigint, "visitors" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
begin
  return query
  with pv as (
    select
      e.organization_id,
      (e.created_at at time zone p_tz)::date as day,
      case
        when e.page_type in ('inicio', 'productos', 'producto', 'ofertas', 'servicios') then e.page_type
        else 'otra'
      end as page,
      e.visitor_id,
      e.created_at
    from public.site_analytics_events e
    where e.site = 'storefront'
      and e.event_type = 'page_view'
      and e.organization_id is not null
      and coalesce(e.page_type, '') not in ('carrito', 'track')
      and e.created_at >= (p_from::timestamp at time zone p_tz)
      and e.created_at < ((p_to + 1)::timestamp at time zone p_tz)
  ),
  entries as (
    select distinct on (organization_id, day, visitor_id) organization_id, day, page
    from pv
    order by organization_id, day, visitor_id, created_at
  ),
  view_counts as (
    select organization_id, day, page, count(*)::bigint as views
    from pv
    group by organization_id, day, page
  ),
  visitor_counts as (
    select organization_id, day, page, count(*)::bigint as visitors
    from entries
    group by organization_id, day, page
  )
  select v.organization_id, v.day, v.page, v.views, coalesce(x.visitors, 0)::bigint
  from view_counts v
  left join visitor_counts x using (organization_id, day, page);

  if to_regclass('public.storefront_daily_visits') is not null then
    return query execute $legacy$
      select l.organization_id, l.day, l.page, l.views::bigint, l.visitors::bigint
      from public.storefront_daily_visits l
      where l.day between $1 and $2
        and not exists (
          select 1
          from public.site_analytics_events e
          where e.site = 'storefront'
            and e.event_type = 'page_view'
            and e.organization_id = l.organization_id
            and (e.created_at at time zone $3)::date = l.day
        )
    $legacy$ using p_from, p_to, p_tz;
  end if;
end;
$_$;


ALTER FUNCTION "public"."get_storefront_daily_visits"("p_from" "date", "p_to" "date", "p_tz" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_superadmin_org_usage_counts"("p_organization_ids" "uuid"[]) RETURNS TABLE("organization_id" "uuid", "members_count" bigint, "products_count" bigint, "sales_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select requested.organization_id,
         (
           select count(*)
             from public.organization_members members
            where members.organization_id = requested.organization_id
              and members.status = 'active'
         ) as members_count,
         (
           select count(*)
             from public.products products
            where products.organization_id = requested.organization_id
              and products.is_active = true
         ) as products_count,
         (
           select count(*)
             from public.sales sales
            where sales.organization_id = requested.organization_id
         ) as sales_count
    from unnest(coalesce(p_organization_ids, array[]::uuid[])) as requested(organization_id);
$$;


ALTER FUNCTION "public"."get_superadmin_org_usage_counts"("p_organization_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supplier_stats"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    result JSON;
BEGIN
    SELECT json_build_object(
        'total_suppliers', COUNT(*)::bigint,
        'active_suppliers', COUNT(*) FILTER (WHERE status = 'active')::bigint,
        'inactive_suppliers', COUNT(*) FILTER (WHERE status = 'inactive')::bigint,
        'pending_suppliers', COUNT(*) FILTER (WHERE status = 'pending')::bigint,
        'avg_rating', COALESCE(AVG(rating), 0)::numeric,
        'total_orders', COALESCE(SUM(total_orders), 0)::bigint,
        'total_amount', COALESCE(SUM(total_amount), 0)::numeric
    ) INTO result
    FROM suppliers;

    RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_supplier_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_table_sizes"() RETURNS TABLE("schema_name" "text", "table_name" "text", "size_bytes" bigint, "size_pretty" "text", "row_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    stat.schemaname::text AS schema_name,
    stat.relname::text AS table_name,
    pg_total_relation_size(format('%I.%I', stat.schemaname, stat.relname)) AS size_bytes,
    pg_size_pretty(pg_total_relation_size(format('%I.%I', stat.schemaname, stat.relname))) AS size_pretty,
    stat.n_live_tup::bigint AS row_count
  FROM pg_stat_user_tables stat
  ORDER BY pg_total_relation_size(format('%I.%I', stat.schemaname, stat.relname)) DESC;
END;
$$;


ALTER FUNCTION "public"."get_table_sizes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_top_selling_products"("limit_count" integer DEFAULT 10) RETURNS TABLE("product_id" "uuid", "product_name" character varying, "product_sku" character varying, "category_name" character varying, "total_sold" integer, "total_revenue" numeric, "current_stock" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        p.id,
        p.name,
        p.sku,
        c.name,
        COALESCE(SUM(pm.quantity) FILTER (WHERE pm.movement_type IN ('sale', 'exit')), 0)::INTEGER as total_sold,
        COALESCE(SUM(pm.quantity * p.sale_price) FILTER (WHERE pm.movement_type IN ('sale', 'exit')), 0) as total_revenue,
        p.stock_quantity
    FROM products p
    LEFT JOIN categories c ON p.category_id = c.id
    LEFT JOIN product_movements pm ON p.id = pm.product_id
    WHERE p.is_active = true
    GROUP BY p.id, p.name, p.sku, c.name, p.stock_quantity
    ORDER BY total_sold DESC, total_revenue DESC
    LIMIT limit_count;
END;
$$;


