CREATE OR REPLACE FUNCTION "public"."get_user_stats"() RETURNS json
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result json;
BEGIN
  SELECT json_build_object(
    'totalUsers', COUNT(*),
    'activeUsers', COUNT(*) FILTER (WHERE status = 'active'),
    'inactiveUsers', COUNT(*) FILTER (WHERE status = 'inactive'),
    'suspendedUsers', COUNT(*) FILTER (WHERE status = 'suspended'),
    'adminsCount', COUNT(*) FILTER (WHERE role = 'admin'),
    'supervisorsCount', COUNT(*) FILTER (WHERE role = 'supervisor'),
    'techsCount', COUNT(*) FILTER (WHERE role = 'tecnico'),
    'sellersCount', COUNT(*) FILTER (WHERE role = 'vendedor'),
    'clientsCount', COUNT(*) FILTER (WHERE role = 'cliente'),
    'newUsersThisMonth', COUNT(*) FILTER (
      WHERE created_at >= date_trunc('month', CURRENT_DATE)
    ),
    'newUsersThisWeek', COUNT(*) FILTER (
      WHERE created_at >= date_trunc('week', CURRENT_DATE)
    ),
    'activeToday', COUNT(*) FILTER (
      WHERE updated_at >= CURRENT_DATE
    )
  ) INTO result
  FROM profiles;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_user_stats"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_stats"() IS 'Retorna estadísticas globales de usuarios de forma eficiente usando agregaciones SQL';



CREATE OR REPLACE FUNCTION "public"."get_user_stats"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result json;
  v_org_id uuid;
BEGIN
  IF public.get_jwt_role() <> 'super_admin' THEN
    v_org_id := COALESCE(p_organization_id, public.get_current_user_org_id());
  ELSE
    v_org_id := p_organization_id;
  END IF;

  IF v_org_id IS NOT NULL THEN
    SELECT json_build_object(
      'totalUsers',        COUNT(*),
      'activeUsers',       COUNT(*) FILTER (WHERE status = 'active'),
      'inactiveUsers',     COUNT(*) FILTER (WHERE status = 'inactive'),
      'suspendedUsers',    COUNT(*) FILTER (WHERE status = 'suspended'),
      'adminsCount',       COUNT(*) FILTER (WHERE role = 'admin'),
      'techsCount',        COUNT(*) FILTER (WHERE role = 'tecnico'),
      'sellersCount',      COUNT(*) FILTER (WHERE role = 'vendedor'),
      'clientsCount',      COUNT(*) FILTER (WHERE role = 'cliente'),
      'newUsersThisMonth', COUNT(*) FILTER (
        WHERE created_at >= date_trunc('month', CURRENT_DATE)
      ),
      'newUsersThisWeek',  COUNT(*) FILTER (
        WHERE created_at >= date_trunc('week', CURRENT_DATE)
      ),
      'activeToday',       COUNT(*) FILTER (
        WHERE updated_at >= CURRENT_DATE
      )
    ) INTO result
    FROM profiles
    WHERE id IN (
      SELECT user_id FROM organization_members WHERE organization_id = v_org_id
    );
  ELSE
    -- super_admin global view
    SELECT json_build_object(
      'totalUsers',        COUNT(*),
      'activeUsers',       COUNT(*) FILTER (WHERE status = 'active'),
      'inactiveUsers',     COUNT(*) FILTER (WHERE status = 'inactive'),
      'suspendedUsers',    COUNT(*) FILTER (WHERE status = 'suspended'),
      'adminsCount',       COUNT(*) FILTER (WHERE role IN ('admin', 'super_admin')),
      'techsCount',        COUNT(*) FILTER (WHERE role = 'tecnico'),
      'sellersCount',      COUNT(*) FILTER (WHERE role = 'vendedor'),
      'clientsCount',      COUNT(*) FILTER (WHERE role = 'cliente'),
      'newUsersThisMonth', COUNT(*) FILTER (
        WHERE created_at >= date_trunc('month', CURRENT_DATE)
      ),
      'newUsersThisWeek',  COUNT(*) FILTER (
        WHERE created_at >= date_trunc('week', CURRENT_DATE)
      ),
      'activeToday',       COUNT(*) FILTER (
        WHERE updated_at >= CURRENT_DATE
      )
    ) INTO result
    FROM profiles;
  END IF;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_user_stats"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  full_name_val text;
begin
  full_name_val := coalesce(
    nullif(trim(new.raw_user_meta_data->>'full_name'), ''),
    nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
    'Usuario'
  );

  insert into public.profiles (id, email, full_name, role, status)
  values (new.id, new.email, full_name_val, 'cliente', 'active')
  on conflict (id) do update
  set email = excluded.email,
      full_name = coalesce(nullif(excluded.full_name, ''), profiles.full_name),
      updated_at = now();

  return new;
exception when others then
  raise warning '[handle_new_user] Profile synchronization failed for user %: %', new.id, sqlerrm;
  return new;
end;
$$;


