CREATE OR REPLACE FUNCTION "public"."has_org_permission"("target_organization_id" "uuid", "permission_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  member_role public.organization_role;
begin
  member_role := public.get_org_role(target_organization_id);

  if member_role is null then return false; end if;
  if member_role = 'owner' then return true; end if;
  if member_role = 'admin' then return permission_name <> 'billing.manage'; end if;

  if member_role = 'manager' then
    return permission_name = any(array[
      'inventory.products.read', 'inventory.products.create', 'inventory.products.update',
      'inventory.stock.manage', 'pos.sales.read', 'pos.sales.create', 'pos.cash.manage',
      'repairs.orders.read', 'repairs.orders.create', 'repairs.orders.update',
      'repairs.orders.assign', 'repairs.orders.deliver', 'crm.customers.read',
      'crm.customers.manage', 'promotions.read', 'promotions.create',
      'promotions.update', 'analytics.read'
    ]);
  end if;

  if member_role = 'cashier' then
    return permission_name = any(array[
      'inventory.products.read', 'pos.sales.read', 'pos.sales.create',
      'pos.cash.manage', 'crm.customers.read', 'repairs.orders.read',
      'repairs.orders.deliver'
    ]);
  end if;

  if member_role = 'technician' then
    return permission_name = any(array[
      'inventory.products.read', 'inventory.stock.manage', 'repairs.orders.read',
      'repairs.orders.update', 'repairs.orders.deliver'
    ]);
  end if;

  if member_role = 'seller' then
    return permission_name = any(array[
      'inventory.products.read', 'pos.sales.read', 'pos.sales.create',
      'crm.customers.read', 'crm.customers.manage', 'promotions.read',
      'promotions.create', 'promotions.update'
    ]);
  end if;

  return member_role = 'customer' and permission_name = 'repairs.orders.read';
end;
$$;


ALTER FUNCTION "public"."has_org_permission"("target_organization_id" "uuid", "permission_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_permission"("permission_name" "text", "user_uuid" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_role TEXT;
    v_permissions TEXT[];
BEGIN
    -- Obtener el rol actual
    v_role := public.get_user_role(user_uuid);

    -- Super admin tiene todo
    IF v_role = 'super_admin' THEN
        RETURN true;
    END IF;

    -- Admin tiene todo
    IF v_role = 'admin' THEN
        RETURN true;
    END IF;

    -- Manager
    IF v_role = 'manager' THEN
        v_permissions := ARRAY[
            'inventory.products.read', 'inventory.products.create', 'inventory.products.update',
            'products.read', 'products.create', 'products.update', 'products.manage',
            'pos.read', 'customers.read'
        ];
        RETURN permission_name = ANY(v_permissions);
    END IF;

    -- Vendedor
    IF v_role = 'vendedor' THEN
        v_permissions := ARRAY[
            'products.create', 'products.read', 'products.update',
            'inventory.products.read', 'inventory.products.create', 'inventory.products.update',
            'pos.read', 'customers.read', 'orders.read', 'promotions.read'
        ];
        RETURN permission_name = ANY(v_permissions);
    END IF;

    -- Técnico
    IF v_role = 'tecnico' THEN
        v_permissions := ARRAY[
            'products.read', 'products.update',
            'inventory.products.read', 'inventory.products.update',
            'repairs.read'
        ];
        RETURN permission_name = ANY(v_permissions);
    END IF;

    -- Cliente
    IF v_role = 'cliente' THEN
        v_permissions := ARRAY['products.read', 'inventory.products.read'];
        RETURN permission_name = ANY(v_permissions);
    END IF;

    RETURN false;
END;
$$;


ALTER FUNCTION "public"."has_permission"("permission_name" "text", "user_uuid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_branch_order_stock"("p_product_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_quantity" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_updated integer;
begin
  if p_quantity <= 0 then
    return false;
  end if;

  update public.branch_inventory bi
     set stock_quantity = bi.stock_quantity + p_quantity,
         updated_at = now()
    from public.products p, public.branches b
   where bi.branch_id = p_branch_id
     and bi.product_id = p_product_id
     and p.id = bi.product_id
     and p.organization_id = p_organization_id
     and b.id = bi.branch_id
     and b.organization_id = p_organization_id;

  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$$;


ALTER FUNCTION "public"."increment_branch_order_stock"("p_product_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_product_stock"("p_product_id" "uuid", "p_organization_id" "uuid", "p_quantity" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_quantity <= 0 then
    return false;
  end if;

  update public.products
     set stock_quantity = coalesce(stock_quantity, 0) + p_quantity,
         updated_at = now()
   where id = p_product_id
     and organization_id = p_organization_id;

  return found;
end;
$$;


