ALTER FUNCTION "public"."is_technician"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_public_customer_account"("p_organization_id" "uuid", "p_profile_id" "uuid", "p_full_name" "text", "p_email" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_customer_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("customer_id" "uuid", "membership_role" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_customer_id uuid;
  resolved_membership_role text;
  normalized_name text := coalesce(nullif(trim(p_full_name), ''), 'Cliente');
  normalized_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
  normalized_phone text := nullif(trim(coalesce(p_phone, '')), '');
  first_name_val text;
  last_name_val text;
begin
  if not exists (select 1 from public.organizations where id = p_organization_id) then
    raise exception 'ORGANIZATION_NOT_FOUND';
  end if;

  if not exists (select 1 from auth.users where id = p_profile_id) then
    raise exception 'PROFILE_AUTH_USER_NOT_FOUND';
  end if;

  first_name_val := split_part(normalized_name, ' ', 1);
  last_name_val := coalesce(nullif(trim(substring(normalized_name from position(' ' in normalized_name) + 1)), ''), '');

  insert into public.profiles (id, email, full_name, role, status)
  values (p_profile_id, normalized_email, normalized_name, 'cliente', 'active')
  on conflict (id) do update
  set email = coalesce(excluded.email, profiles.email),
      full_name = excluded.full_name,
      status = 'active',
      updated_at = now();

  if p_customer_id is not null then
    select c.id into resolved_customer_id
    from public.customers c
    where c.id = p_customer_id
      and c.organization_id = p_organization_id
      and (c.profile_id is null or c.profile_id = p_profile_id);
  end if;

  if resolved_customer_id is null then
    select c.id into resolved_customer_id
    from public.customers c
    where c.organization_id = p_organization_id
      and c.profile_id = p_profile_id
    order by c.updated_at desc nulls last, c.created_at desc
    limit 1;
  end if;

  if resolved_customer_id is null and normalized_email is not null then
    select c.id into resolved_customer_id
    from public.customers c
    where c.organization_id = p_organization_id
      and lower(c.email) = normalized_email
      and c.profile_id is null
    order by c.updated_at desc nulls last, c.created_at desc
    limit 1;
  end if;

  if resolved_customer_id is null and normalized_phone is not null then
    select c.id into resolved_customer_id
    from public.customers c
    where c.organization_id = p_organization_id
      and c.phone = normalized_phone
      and c.profile_id is null
    order by c.updated_at desc nulls last, c.created_at desc
    limit 1;
  end if;

  if resolved_customer_id is null then
    insert into public.customers (
      organization_id, profile_id, name, first_name, last_name, email, phone,
      customer_type, segment, status, created_at, updated_at
    ) values (
      p_organization_id, p_profile_id, normalized_name, first_name_val,
      last_name_val, normalized_email, coalesce(normalized_phone, ''),
      'regular', 'new', 'active', now(), now()
    )
    returning id into resolved_customer_id;
  else
    update public.customers
    set profile_id = p_profile_id,
        name = normalized_name,
        first_name = first_name_val,
        last_name = last_name_val,
        email = coalesce(normalized_email, email),
        phone = coalesce(normalized_phone, phone, ''),
        status = 'active',
        updated_at = now()
    where id = resolved_customer_id
      and organization_id = p_organization_id;
  end if;

  insert into public.organization_members (organization_id, user_id, role, status)
  values (p_organization_id, p_profile_id, 'customer', 'active')
  on conflict (organization_id, user_id) do update
  set status = case
        when organization_members.role = 'customer' then 'active'
        else organization_members.status
      end,
      updated_at = now();

  select om.role::text into resolved_membership_role
  from public.organization_members om
  where om.organization_id = p_organization_id
    and om.user_id = p_profile_id;

  return query select resolved_customer_id, resolved_membership_role;
end;
$$;


ALTER FUNCTION "public"."link_public_customer_account"("p_organization_id" "uuid", "p_profile_id" "uuid", "p_full_name" "text", "p_email" "text", "p_phone" "text", "p_customer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_auth_event"("event_type" "text" DEFAULT 'login'::"text", "metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Silently log or do nothing if audit_log doesn't exist
  INSERT INTO public.audit_log (user_id, action, resource_type, new_values, created_at)
  VALUES (auth.uid(), event_type, 'auth', metadata, NOW())
  ON CONFLICT DO NOTHING;
EXCEPTION WHEN OTHERS THEN
  -- Silently fail if table doesn't exist
  NULL;
END;
$$;


ALTER FUNCTION "public"."log_auth_event"("event_type" "text", "metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_auth_event"("p_user_id" "uuid" DEFAULT NULL::"uuid", "p_action" "text" DEFAULT 'login'::"text", "p_success" boolean DEFAULT true, "p_ip_address" "inet" DEFAULT NULL::"inet", "p_user_agent" "text" DEFAULT NULL::"text", "p_details" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    log_id UUID;
    event_severity TEXT;
BEGIN
    -- Determinar severidad basada en el tipo de evento
    CASE
        WHEN p_action = 'login' AND p_success THEN
            event_severity := 'low';
        WHEN p_action = 'login_failed' THEN
            event_severity := 'medium';
        WHEN p_action = 'password_change' THEN
            event_severity := 'low';
        WHEN p_action = 'role_change' THEN
            event_severity := 'high';
        WHEN p_action = 'permission_denied' THEN
            event_severity := 'medium';
        WHEN p_action = 'suspicious_activity' THEN
            event_severity := 'high';
        WHEN p_action = 'account_locked' THEN
            event_severity := 'critical';
        ELSE
            event_severity := 'low';
    END CASE;

    -- Insertar el log
    INSERT INTO public.audit_log (
        user_id,
        action,
        resource,
        resource_id,
        new_values,
        ip_address,
        user_agent,
        created_at
    ) VALUES (
        p_user_id,
        p_action,
        'auth',
        COALESCE(p_user_id::text, 'unknown'),
        p_details || jsonb_build_object('severity', event_severity, 'success', p_success),
        p_ip_address,
        p_user_agent,
        NOW()
    ) RETURNING id INTO log_id;

    RETURN log_id;
END;
$$;


ALTER FUNCTION "public"."log_auth_event"("p_user_id" "uuid", "p_action" "text", "p_success" boolean, "p_ip_address" "inet", "p_user_agent" "text", "p_details" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_auth_event"("p_user_id" "uuid", "p_action" "text", "p_success" boolean, "p_ip_address" "inet", "p_user_agent" "text", "p_details" "jsonb") IS 'Registra eventos de autenticación y autorización';



CREATE OR REPLACE FUNCTION "public"."log_data_event"("p_user_id" "uuid" DEFAULT "auth"."uid"(), "p_action" "text" DEFAULT 'read'::"text", "p_resource" "text" DEFAULT 'unknown'::"text", "p_resource_id" "text" DEFAULT NULL::"text", "p_old_values" "jsonb" DEFAULT NULL::"jsonb", "p_new_values" "jsonb" DEFAULT NULL::"jsonb", "p_ip_address" "inet" DEFAULT NULL::"inet", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    log_id UUID;
    event_severity TEXT;
BEGIN
    -- Determinar severidad basada en el tipo de acción
    CASE
        WHEN p_action = 'create' THEN
            event_severity := 'low';
        WHEN p_action = 'read' THEN
            event_severity := 'low';
        WHEN p_action = 'update' THEN
            event_severity := 'low';
        WHEN p_action = 'delete' THEN
            event_severity := 'medium';
        WHEN p_action = 'bulk_operation' THEN
            event_severity := 'medium';
        WHEN p_action = 'data_export' THEN
            event_severity := 'medium';
        ELSE
            event_severity := 'low';
    END CASE;

    -- Insertar el log
    INSERT INTO public.audit_log (
        user_id,
        action,
        resource,
        resource_id,
        old_values,
        new_values,
        ip_address,
        user_agent,
        created_at
    ) VALUES (
        p_user_id,
        p_action,
        p_resource,
        p_resource_id,
        p_old_values,
        p_new_values || jsonb_build_object('severity', event_severity),
        p_ip_address,
        p_user_agent,
        NOW()
    ) RETURNING id INTO log_id;

    RETURN log_id;
END;
$$;


ALTER FUNCTION "public"."log_data_event"("p_user_id" "uuid", "p_action" "text", "p_resource" "text", "p_resource_id" "text", "p_old_values" "jsonb", "p_new_values" "jsonb", "p_ip_address" "inet", "p_user_agent" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_data_event"("p_user_id" "uuid", "p_action" "text", "p_resource" "text", "p_resource_id" "text", "p_old_values" "jsonb", "p_new_values" "jsonb", "p_ip_address" "inet", "p_user_agent" "text") IS 'Registra eventos de manipulación de datos (CRUD)';



CREATE OR REPLACE FUNCTION "public"."log_repair_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only log if status actually changed
  IF (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status) THEN
    INSERT INTO repair_status_history (repair_id, old_status, new_status, changed_by, notes)
    VALUES (
      NEW.id,
      OLD.status,
      NEW.status,
      auth.uid(),
      'Estado actualizado'
    );
  ELSIF (TG_OP = 'INSERT') THEN
    INSERT INTO repair_status_history (repair_id, new_status, changed_by, notes)
    VALUES (
      NEW.id,
      NEW.status,
      auth.uid(),
      'Reparación creada'
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_repair_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_sale_item_stock_movement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sale_id        UUID;
  v_product_id     UUID;
  v_sale           RECORD;
  v_total          INTEGER;
  v_previous_stock INTEGER;
  v_movement_id    UUID;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_sale_id := OLD.sale_id;
    v_product_id := OLD.product_id;
  ELSE
    v_sale_id := NEW.sale_id;
    v_product_id := NEW.product_id;
  END IF;

  IF v_product_id IS NULL OR v_sale_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT s.id, s.organization_id, s.branch_id, s.code, s.created_by
  INTO v_sale
  FROM public.sales s
  WHERE s.id = v_sale_id;

  IF NOT FOUND THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- El total vigente de la venta para ese producto, sea cual sea el camino que
  -- lo dejo asi.
  SELECT COALESCE(SUM(item.quantity), 0)
  INTO v_total
  FROM public.sale_items item
  WHERE item.sale_id = v_sale_id
    AND item.product_id = v_product_id;

  SELECT movement.id, movement.previous_stock
  INTO v_movement_id, v_previous_stock
  FROM public.product_movements movement
  WHERE movement.reference_id = v_sale_id
    AND movement.reference_type = 'sale'
    AND movement.product_id = v_product_id
  ORDER BY movement.created_at ASC
  LIMIT 1;

  -- El producto salio de la venta: el movimiento tampoco tiene razon de existir.
  IF v_total <= 0 THEN
    IF v_movement_id IS NOT NULL THEN
      DELETE FROM public.product_movements WHERE id = v_movement_id;
    END IF;
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF v_movement_id IS NOT NULL THEN
    -- `previous_stock` es el que se capturo la primera vez: es el stock real de
    -- antes de la venta. Recalcularlo ahora leeria el stock YA descontado.
    UPDATE public.product_movements
    SET quantity = v_total,
        new_stock = v_previous_stock - v_total
    WHERE id = v_movement_id;

    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Primera vez para este producto en esta venta: se captura el stock previo.
  SELECT bi.stock_quantity
  INTO v_previous_stock
  FROM public.branch_inventory bi
  WHERE bi.branch_id = v_sale.branch_id
    AND bi.product_id = v_product_id;

  IF v_previous_stock IS NULL THEN
    SELECT p.stock_quantity INTO v_previous_stock
    FROM public.products p
    WHERE p.id = v_product_id;
  END IF;

  v_previous_stock := COALESCE(v_previous_stock, 0);

  INSERT INTO public.product_movements (
    organization_id,
    branch_id,
    product_id,
    movement_type,
    quantity,
    previous_stock,
    new_stock,
    notes,
    reference_id,
    reference_type,
    user_id,
    created_at
  )
  VALUES (
    v_sale.organization_id,
    v_sale.branch_id,
    v_product_id,
    'sale',
    v_total,
    v_previous_stock,
    v_previous_stock - v_total,
    'Venta ' || COALESCE(v_sale.code, v_sale.id::TEXT),
    v_sale.id,
    'sale',
    v_sale.created_by,
    NOW()
  );

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."log_sale_item_stock_movement"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_sale_item_stock_movement"() IS 'Mantiene en product_movements un movimiento por venta y producto, con la cantidad total vigente en sale_items. Idempotente ante el borrado y reinsercion de lineas que hace process_pos_sale_atomic_v5.';



CREATE OR REPLACE FUNCTION "public"."log_segment_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO segment_history (segment_id, action, changes, performed_by)
        VALUES (NEW.id, 'created', to_jsonb(NEW), NEW.created_by);
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO segment_history (segment_id, action, changes, previous_values, performed_by)
        VALUES (NEW.id, 'updated', to_jsonb(NEW), to_jsonb(OLD), NEW.created_by);
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO segment_history (segment_id, action, previous_values)
        VALUES (OLD.id, 'deleted', to_jsonb(OLD));
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."log_segment_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_settings_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    field_name TEXT;
    old_val JSONB;
    new_val JSONB;
BEGIN
    -- Comparar cada campo y registrar cambios
    FOR field_name IN
        SELECT column_name
        FROM information_schema.columns
        WHERE table_name = 'system_settings'
        AND column_name NOT IN ('id', 'updated_at', 'updated_by')
    LOOP
        old_val := to_jsonb(OLD) -> field_name;
        new_val := to_jsonb(NEW) -> field_name;

        IF old_val IS DISTINCT FROM new_val THEN
            INSERT INTO system_settings_audit (
                user_id,
                action,
                field_name,
                old_value,
                new_value,
                severity,
                details
            ) VALUES (
                auth.uid(),
                'update',
                field_name,
                old_val,
                new_val,
                CASE
                    WHEN field_name IN ('maintenance_mode', 'allow_registration', 'require_two_factor') THEN 'critical'
                    WHEN field_name IN ('max_login_attempts', 'password_min_length', 'require_email_verification') THEN 'high'
                    WHEN field_name IN ('tax_rate', 'currency', 'session_timeout') THEN 'medium'
                    ELSE 'low'
                END,
                jsonb_build_object('trigger', 'log_settings_change')
            );
        END IF;
    END LOOP;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_settings_change"() OWNER TO "postgres";


