ALTER FUNCTION "public"."log_system_event"("p_action" "text", "p_resource" "text", "p_details" "jsonb", "p_severity" "text", "p_ip_address" "inet") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_system_event"("p_action" "text", "p_resource" "text", "p_details" "jsonb", "p_severity" "text", "p_ip_address" "inet") IS 'Registra eventos del sistema';



CREATE OR REPLACE FUNCTION "public"."normalize_after_sales_cases_es"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.source_type IS NOT NULL THEN
    NEW.source_type := CASE NEW.source_type
      WHEN 'repair' THEN 'reparacion'
      WHEN 'sale' THEN 'venta'
      ELSE NEW.source_type
    END;
  END IF;

  IF NEW.request_type IS NOT NULL THEN
    NEW.request_type := CASE NEW.request_type
      WHEN 'repair_warranty' THEN 'garantia_reparacion'
      WHEN 'product_warranty' THEN 'garantia_producto'
      WHEN 'exchange' THEN 'cambio'
      WHEN 'return' THEN 'devolucion'
      ELSE NEW.request_type
    END;
  END IF;

  IF NEW.status IS NOT NULL THEN
    NEW.status := CASE NEW.status
      WHEN 'open' THEN 'abierto'
      WHEN 'approved' THEN 'aprobado'
      WHEN 'rejected' THEN 'rechazado'
      WHEN 'completed' THEN 'completado'
      WHEN 'cancelled' THEN 'cancelado'
      ELSE NEW.status
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_after_sales_cases_es"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_branch_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.is_default THEN
    UPDATE public.branches
    SET is_default = FALSE,
        updated_at = NOW()
    WHERE id <> NEW.id
      AND organization_id = NEW.organization_id
      AND is_default = TRUE;
  END IF;

  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


