CREATE OR REPLACE FUNCTION "public"."normalize_credit_payment_amount"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  installment_amount numeric;
  installment_credit_id uuid;
  already_paid numeric;
  outstanding numeric;
begin
  if new.installment_id is null then
    return new;
  end if;

  select i.amount, i.credit_id
  into installment_amount, installment_credit_id
  from public.credit_installments i
  where i.id = new.installment_id
  for update;

  if not found then
    raise exception 'Datos inválidos: la cuota % no fue encontrada', new.installment_id;
  end if;

  if new.credit_id is null then
    new.credit_id := installment_credit_id;
  elsif new.credit_id <> installment_credit_id then
    raise exception 'Datos inválidos: el credit_id % no coincide con la cuota % (credit_id %)', new.credit_id, new.installment_id, installment_credit_id;
  end if;

  if coalesce(new.amount, 0) <= 0 then
    raise exception 'Datos inválidos: el monto del pago debe ser mayor a 0';
  end if;

  select coalesce(sum(p.amount), 0)
  into already_paid
  from public.credit_payments p
  where p.installment_id = new.installment_id;

  outstanding := greatest(installment_amount - already_paid, 0);

  if outstanding <= 0 then
    raise exception 'Datos inválidos: la cuota % no tiene saldo pendiente', new.installment_id;
  end if;

  new.amount := least(new.amount, outstanding);
  return new;
end
$$;


ALTER FUNCTION "public"."normalize_credit_payment_amount"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_customer_orders_es"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status IS NOT NULL THEN
    NEW.status := CASE NEW.status
      WHEN 'PENDING' THEN 'PENDIENTE'
      WHEN 'CONFIRMED' THEN 'CONFIRMADO'
      WHEN 'PREPARING' THEN 'PREPARANDO'
      WHEN 'READY' THEN 'LISTO'
      WHEN 'SHIPPED' THEN 'ENVIADO'
      WHEN 'DELIVERED' THEN 'ENTREGADO'
      WHEN 'CANCELLED' THEN 'CANCELADO'
      ELSE NEW.status
    END;
  END IF;

  IF NEW.payment_status IS NOT NULL THEN
    NEW.payment_status := CASE NEW.payment_status
      WHEN 'PENDING' THEN 'PENDIENTE'
      WHEN 'PAID' THEN 'PAGADO'
      WHEN 'PARTIAL' THEN 'PARCIAL'
      WHEN 'REFUNDED' THEN 'REEMBOLSADO'
      WHEN 'FAILED' THEN 'FALLIDO'
      ELSE NEW.payment_status
    END;
  END IF;

  IF NEW.payment_method IS NOT NULL THEN
    NEW.payment_method := CASE NEW.payment_method
      WHEN 'CASH' THEN 'EFECTIVO'
      WHEN 'CARD' THEN 'TARJETA'
      WHEN 'TRANSFER' THEN 'TRANSFERENCIA'
      WHEN 'DIGITAL_WALLET' THEN 'BILLETERA_DIGITAL'
      ELSE NEW.payment_method
    END;
  END IF;

  IF NEW.fulfillment_type IS NOT NULL THEN
    NEW.fulfillment_type := CASE NEW.fulfillment_type
      WHEN 'PICKUP' THEN 'RETIRO'
      WHEN 'DELIVERY' THEN 'ENTREGA'
      ELSE NEW.fulfillment_type
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_customer_orders_es"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_customers_status_es"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status IS NOT NULL THEN
    NEW.status := CASE NEW.status
      WHEN 'active' THEN 'activo'
      WHEN 'inactive' THEN 'inactivo'
      WHEN 'suspended' THEN 'suspendido'
      WHEN 'pending' THEN 'pendiente'
      ELSE NEW.status
    END;
  END IF;

  IF NEW.customer_type IS NOT NULL THEN
    NEW.customer_type := CASE NEW.customer_type
      WHEN 'regular' THEN 'regular'
      WHEN 'premium' THEN 'premium'
      WHEN 'vip' THEN 'vip'
      WHEN 'empresa' THEN 'empresa'
      ELSE NEW.customer_type
    END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_customers_status_es"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_popular_subscription_plan"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.is_popular then
    update public.subscription_plans
       set is_popular = false,
           updated_at = now()
     where id <> new.id
       and is_popular = true;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_popular_subscription_plan"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_primary_branch_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target_organization_id UUID;
BEGIN
  SELECT organization_id
  INTO target_organization_id
  FROM public.branches
  WHERE id = NEW.branch_id;

  IF target_organization_id IS NULL THEN
    RAISE EXCEPTION 'Branch % has no organization', NEW.branch_id;
  END IF;

  NEW.organization_id = target_organization_id;

  IF NEW.is_primary AND NEW.is_active THEN
    UPDATE public.user_branch_assignments
    SET is_primary = FALSE,
        updated_at = NOW()
    WHERE user_id = NEW.user_id
      AND organization_id = target_organization_id
      AND id <> NEW.id
      AND is_primary = TRUE;
  END IF;

  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_primary_branch_assignment"() OWNER TO "postgres";


