CREATE OR REPLACE FUNCTION "public"."normalize_public_access_audit_event_type_es"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.event_type IS NOT NULL THEN
    NEW.event_type := CASE NEW.event_type
      WHEN 'auth_attempt' THEN 'intento_autenticacion'
      WHEN 'auth_success' THEN 'autenticacion_exitosa'
      WHEN 'auth_failure' THEN 'autenticacion_fallida'
      WHEN 'token_expired' THEN 'token_expirado'
      WHEN 'unauthorized_access' THEN 'acceso_no_autorizado'
      WHEN 'rate_limit_exceeded' THEN 'limite_tasa_excedido'
      WHEN 'invalid_token' THEN 'token_invalido'
      ELSE NEW.event_type
    END;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_public_access_audit_event_type_es"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_role_es"("input_role" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case lower(input_role)
    when 'technician' then 'tecnico'
    when 'client_normal' then 'cliente'
    when 'client_mayorista' then 'mayorista'
    when 'sales' then 'vendedor'
    when 'support' then 'soporte'
    when 'developer' then 'desarrollador'
    when 'employee' then 'empleado'
    when 'viewer' then 'visor'
    when 'cashier' then 'cajero'
    when 'manager' then 'gerente'
    else lower(input_role)
  end;
$$;


ALTER FUNCTION "public"."normalize_role_es"("input_role" "text") OWNER TO "postgres";


