CREATE OR REPLACE FUNCTION "public"."open_cash_register_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_register_id" "text", "p_opening_balance" numeric, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
  created_session public.cash_closures%rowtype;
begin
  if actor_id is null then
    raise exception 'Authentication required';
  end if;
  if not public.has_org_permission(p_organization_id, 'pos.cash.manage') then
    raise exception 'Insufficient cash permissions';
  end if;
  if coalesce(trim(p_register_id), '') = '' then
    raise exception 'Register is required';
  end if;
  if coalesce(p_opening_balance, -1) < 0 then
    raise exception 'Opening balance cannot be negative';
  end if;
  if not exists (
    select 1
    from public.cash_registers r
    join public.branches b on b.id = r.branch_id
    where r.id::text = trim(p_register_id)
      and r.organization_id = p_organization_id
      and r.branch_id = p_branch_id
      and r.is_active = true
      and b.organization_id = p_organization_id
      and b.is_active = true
  ) then
    raise exception 'REGISTER_NOT_IN_BRANCH';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_organization_id::text || ':' || p_branch_id::text || ':' || trim(p_register_id), 0)
  );

  if exists (
    select 1
    from public.cash_closures c
    where c.organization_id = p_organization_id
      and c.branch_id = p_branch_id
      and c.register_id = trim(p_register_id)
      and c.date is null
  ) then
    raise exception 'Register is already open';
  end if;

  update public.cash_registers r
  set is_open = true, balance = 0
  where r.id::text = trim(p_register_id)
    and r.organization_id = p_organization_id
    and r.branch_id = p_branch_id;

  insert into public.cash_closures (
    type, register_id, date, opening_balance, opened_by,
    organization_id, branch_id, notes
  ) values (
    'z', trim(p_register_id), null, p_opening_balance, actor_id::text,
    p_organization_id, p_branch_id, nullif(trim(p_note), '')
  ) returning * into created_session;

  insert into public.cash_movements (
    session_id, type, amount, reason, created_by, created_at,
    organization_id, branch_id
  ) values (
    created_session.id,
    'opening',
    p_opening_balance,
    case when nullif(trim(p_note), '') is null
      then 'Apertura de caja'
      else 'Apertura de caja - ' || trim(p_note)
    end,
    actor_id,
    now(),
    p_organization_id,
    p_branch_id
  );

  return jsonb_build_object(
    'id', created_session.id,
    'register_id', created_session.register_id,
    'opening_balance', created_session.opening_balance,
    'opened_by', created_session.opened_by,
    'opened_at', created_session.created_at,
    'organization_id', created_session.organization_id,
    'branch_id', created_session.branch_id
  );
end;
$$;


ALTER FUNCTION "public"."open_cash_register_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_register_id" "text", "p_opening_balance" numeric, "p_note" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."plan_downgrade_grace" (
    "organization_id" "uuid" NOT NULL,
    "plan_code" "text" NOT NULL,
    "product_limit" integer NOT NULL,
    "active_products_at_start" integer NOT NULL,
    "stage" "text" DEFAULT 'grace'::"text" NOT NULL,
    "grace_started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "grace_ends_at" timestamp with time zone NOT NULL,
    "deactivated_at" timestamp with time zone,
    "archive_deadline_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "last_notified_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "plan_downgrade_grace_active_products_at_start_check" CHECK (("active_products_at_start" >= 0)),
    CONSTRAINT "plan_downgrade_grace_product_limit_check" CHECK (("product_limit" >= 0)),
    CONSTRAINT "plan_downgrade_grace_stage_check" CHECK (("stage" = ANY (ARRAY['grace'::"text", 'deactivated'::"text", 'archived'::"text", 'resolved'::"text"])))
);


ALTER TABLE "public"."plan_downgrade_grace" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_plan_downgrade_grace"("p_organization_id" "uuid", "p_plan_code" "text", "p_product_limit" integer) RETURNS "public"."plan_downgrade_grace"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  active_count integer;
  existing public.plan_downgrade_grace;
  result public.plan_downgrade_grace;
begin
  if p_product_limit is null then
    return null; -- plan sin limite: nada que regularizar
  end if;

  select count(*) into active_count
  from public.products
  where organization_id = p_organization_id
    and is_active = true
    and archived_by_plan_at is null;

  if active_count <= p_product_limit then
    -- Entra en el cupo: si habia un ciclo abierto, se cierra.
    delete from public.plan_downgrade_grace where organization_id = p_organization_id;
    return null;
  end if;

  select * into existing
  from public.plan_downgrade_grace
  where organization_id = p_organization_id;

  -- Un ciclo en curso no se reinicia: reabrir la ventana en cada visita dejaria
  -- el plazo corriendo para siempre.
  if existing.organization_id is not null and existing.stage <> 'resolved' then
    return existing;
  end if;

  insert into public.plan_downgrade_grace as g (
    organization_id, plan_code, product_limit, active_products_at_start,
    stage, grace_started_at, grace_ends_at
  )
  values (
    p_organization_id, p_plan_code, p_product_limit, active_count,
    'grace', now(), now() + interval '7 days'
  )
  on conflict (organization_id) do update set
    plan_code = excluded.plan_code,
    product_limit = excluded.product_limit,
    active_products_at_start = excluded.active_products_at_start,
    stage = 'grace',
    grace_started_at = now(),
    grace_ends_at = now() + interval '7 days',
    deactivated_at = null,
    archive_deadline_at = null,
    archived_at = null,
    resolved_at = null,
    updated_at = now()
  returning * into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."open_plan_downgrade_grace"("p_organization_id" "uuid", "p_plan_code" "text", "p_product_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pay_finance_obligation_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_obligation_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_payment_date" "date", "p_idempotency_key" "text", "p_cash_session_id" "uuid" DEFAULT NULL::"uuid", "p_reference" "text" DEFAULT NULL::"text", "p_receipt_storage_path" "text" DEFAULT NULL::"text", "p_receipt_original_name" "text" DEFAULT NULL::"text", "p_receipt_mime_type" "text" DEFAULT NULL::"text", "p_receipt_size_bytes" bigint DEFAULT NULL::bigint, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_id uuid := auth.uid();
  target_obligation public.finance_obligations%rowtype;
  created_payment public.finance_payments%rowtype;
begin
  if actor_id is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;
  if not (
    public.has_org_permission(p_organization_id, 'finances.pay')
    or public.get_user_role(actor_id) = 'super_admin'
  ) then
    raise exception 'FINANCE_PAYMENT_PERMISSION_DENIED';
  end if;
  if not public.user_has_branch_access(p_branch_id) then
    raise exception 'FINANCE_BRANCH_PERMISSION_DENIED';
  end if;
  if not exists (
    select 1
    from public.branches branch
    where branch.id = p_branch_id
      and branch.organization_id = p_organization_id
      and branch.is_active = true
  ) then
    raise exception 'FINANCE_BRANCH_NOT_IN_ORGANIZATION';
  end if;
  if p_amount is null
     or p_amount <= 0
     or p_amount > 999999999999.99
     or p_amount <> trunc(p_amount, 2) then
    raise exception 'FINANCE_INVALID_PAYMENT_AMOUNT';
  end if;
  if p_payment_method not in ('cash', 'bank_transfer', 'other') then
    raise exception 'FINANCE_INVALID_PAYMENT_METHOD';
  end if;
  if p_payment_date is null then
    raise exception 'FINANCE_PAYMENT_DATE_REQUIRED';
  end if;
  if nullif(trim(p_idempotency_key), '') is null
     or char_length(trim(p_idempotency_key)) > 128
     or lower(trim(p_idempotency_key)) like 'finance-system:%' then
    raise exception 'FINANCE_INVALID_IDEMPOTENCY_KEY';
  end if;

  select obligation.*
  into target_obligation
  from public.finance_obligations obligation
  where obligation.id = p_obligation_id
    and obligation.organization_id = p_organization_id
    and obligation.branch_id = p_branch_id
  for update;

  if not found then
    raise exception 'FINANCE_OBLIGATION_NOT_FOUND';
  end if;

  select payment.*
  into created_payment
  from public.finance_payments payment
  where payment.organization_id = p_organization_id
    and payment.obligation_id = p_obligation_id
    and payment.idempotency_key = trim(p_idempotency_key)
    and payment.branch_id = p_branch_id
    and payment.direction = 'payment'
    and payment.amount = p_amount
    and payment.payment_method = p_payment_method
    and payment.payment_date = p_payment_date
    and payment.cash_session_id is not distinct from p_cash_session_id
    and payment.reference is not distinct from nullif(left(trim(p_reference), 200), '')
    and payment.receipt_storage_path is not distinct from nullif(trim(p_receipt_storage_path), '')
    and payment.receipt_original_name is not distinct from nullif(left(trim(p_receipt_original_name), 255), '')
    and payment.receipt_mime_type is not distinct from nullif(lower(trim(p_receipt_mime_type)), '')
    and payment.receipt_size_bytes is not distinct from p_receipt_size_bytes
    and payment.notes is not distinct from nullif(left(trim(p_notes), 2000), '');

  if found then
    return jsonb_build_object(
      'payment', to_jsonb(created_payment),
      'obligation', to_jsonb(target_obligation)
    );
  end if;

  if exists (
    select 1
    from public.finance_payments payment
    where payment.organization_id = p_organization_id
      and payment.obligation_id = p_obligation_id
      and payment.idempotency_key = trim(p_idempotency_key)
  ) then
    raise exception 'FINANCE_IDEMPOTENCY_KEY_REUSED';
  end if;

  if target_obligation.status in ('draft', 'paid', 'voided') then
    raise exception 'FINANCE_OBLIGATION_NOT_PAYABLE';
  end if;
  if p_amount > target_obligation.amount - target_obligation.paid_amount then
    raise exception 'FINANCE_OVERPAYMENT';
  end if;

  if p_payment_method = 'cash' then
    perform 1
    from public.cash_closures session
    join public.cash_registers register
      on register.id::text = session.register_id
     and register.organization_id = session.organization_id
     and register.branch_id = session.branch_id
    where session.id = p_cash_session_id
      and session.organization_id = p_organization_id
      and session.branch_id = p_branch_id
      and session.date is null
      and register.is_active = true
    for update of session, register;

    if not found then
      raise exception 'OPEN_CASH_SESSION_NOT_FOUND';
    end if;
  elsif p_cash_session_id is not null then
    raise exception 'NON_CASH_PAYMENT_CANNOT_USE_CASH_SESSION';
  end if;

  insert into public.finance_payments (
    organization_id,
    branch_id,
    obligation_id,
    idempotency_key,
    direction,
    amount,
    payment_method,
    payment_date,
    cash_session_id,
    reference,
    receipt_storage_path,
    receipt_original_name,
    receipt_mime_type,
    receipt_size_bytes,
    notes,
    created_by
  ) values (
    p_organization_id,
    p_branch_id,
    p_obligation_id,
    trim(p_idempotency_key),
    'payment',
    p_amount,
    p_payment_method,
    p_payment_date,
    p_cash_session_id,
    nullif(left(trim(p_reference), 200), ''),
    nullif(trim(p_receipt_storage_path), ''),
    nullif(left(trim(p_receipt_original_name), 255), ''),
    nullif(lower(trim(p_receipt_mime_type)), ''),
    p_receipt_size_bytes,
    nullif(left(trim(p_notes), 2000), ''),
    actor_id
  )
  returning * into created_payment;

  return jsonb_build_object(
    'payment', to_jsonb(created_payment),
    'obligation', (
      select to_jsonb(updated_obligation)
      from public.finance_obligations updated_obligation
      where updated_obligation.id = p_obligation_id
        and updated_obligation.organization_id = p_organization_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."pay_finance_obligation_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_obligation_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_payment_date" "date", "p_idempotency_key" "text", "p_cash_session_id" "uuid", "p_reference" "text", "p_receipt_storage_path" "text", "p_receipt_original_name" "text", "p_receipt_mime_type" "text", "p_receipt_size_bytes" bigint, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pay_payroll_entry_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_payroll_entry_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_payment_date" "date", "p_idempotency_key" "text", "p_cash_session_id" "uuid" DEFAULT NULL::"uuid", "p_reference" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_id uuid := auth.uid();
  target_run_id uuid;
  target_entry public.payroll_entries%rowtype;
  target_run public.payroll_runs%rowtype;
  created_payment public.payroll_payments%rowtype;
  adjusted_payable numeric(14, 2);
begin
  if actor_id is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;
  if not (
    public.has_org_permission(p_organization_id, 'finances.pay')
    or public.get_user_role(actor_id) = 'super_admin'
  ) then
    raise exception 'PAYROLL_PAYMENT_PERMISSION_DENIED';
  end if;
  if not public.user_has_branch_access(p_branch_id, actor_id) then
    raise exception 'PAYROLL_BRANCH_PERMISSION_DENIED';
  end if;
  if not exists (
    select 1
    from public.branches branch
    where branch.organization_id = p_organization_id
      and branch.id = p_branch_id
      and branch.is_active = true
  ) then
    raise exception 'PAYROLL_BRANCH_NOT_IN_ORGANIZATION';
  end if;
  if p_amount is null
     or p_amount <= 0
     or p_amount > 999999999999.99
     or p_amount <> trunc(p_amount, 2) then
    raise exception 'PAYROLL_INVALID_PAYMENT_AMOUNT';
  end if;
  if p_payment_method not in ('cash', 'bank_transfer', 'other') then
    raise exception 'PAYROLL_INVALID_PAYMENT_METHOD';
  end if;
  if p_payment_date is null then
    raise exception 'PAYROLL_PAYMENT_DATE_REQUIRED';
  end if;
  if nullif(trim(p_idempotency_key), '') is null
     or char_length(trim(p_idempotency_key)) > 128
     or lower(trim(p_idempotency_key)) like 'payroll-system:%'
     or lower(trim(p_idempotency_key)) like 'legacy-technician:%' then
    raise exception 'PAYROLL_INVALID_IDEMPOTENCY_KEY';
  end if;

  select entry.payroll_run_id
  into target_run_id
  from public.payroll_entries entry
  where entry.organization_id = p_organization_id
    and entry.id = p_payroll_entry_id;

  if not found then
    raise exception 'PAYROLL_ENTRY_NOT_FOUND';
  end if;

  select run.*
  into target_run
  from public.payroll_runs run
  where run.organization_id = p_organization_id
    and run.id = target_run_id
  for update;

  select entry.*
  into target_entry
  from public.payroll_entries entry
  where entry.organization_id = p_organization_id
    and entry.id = p_payroll_entry_id
    and entry.payroll_run_id = target_run.id
  for update;

  if not found then
    raise exception 'PAYROLL_ENTRY_NOT_FOUND';
  end if;

  if target_run.status <> 'approved' then
    raise exception 'PAYROLL_ENTRY_NOT_PAYABLE';
  end if;
  if target_entry.branch_id is not null and target_entry.branch_id <> p_branch_id then
    raise exception 'PAYROLL_PAYMENT_BRANCH_MISMATCH';
  end if;

  select payment.*
  into created_payment
  from public.payroll_payments payment
  where payment.organization_id = p_organization_id
    and payment.payroll_entry_id = p_payroll_entry_id
    and payment.idempotency_key = trim(p_idempotency_key)
    and payment.direction = 'payment'
    and payment.branch_id = p_branch_id
    and payment.amount = p_amount
    and payment.payment_method = p_payment_method
    and payment.payment_date = p_payment_date
    and payment.cash_session_id is not distinct from p_cash_session_id
    and payment.reference is not distinct from nullif(left(trim(p_reference), 200), '')
    and payment.notes is not distinct from nullif(left(trim(p_notes), 2000), '');

  if found then
    return jsonb_build_object(
      'payment', to_jsonb(created_payment),
      'entry', to_jsonb(target_entry)
    );
  end if;

  if exists (
    select 1
    from public.payroll_payments payment
    where payment.organization_id = p_organization_id
      and payment.payroll_entry_id = p_payroll_entry_id
      and payment.idempotency_key = trim(p_idempotency_key)
  ) then
    raise exception 'PAYROLL_PAYMENT_IDEMPOTENCY_KEY_REUSED';
  end if;

  select target_entry.net_amount + coalesce(sum(adjustment.amount) filter (
    where adjustment.included_in_net = false
  ), 0)
  into adjusted_payable
  from public.payroll_adjustments adjustment
  where adjustment.organization_id = p_organization_id
    and adjustment.payroll_entry_id = p_payroll_entry_id;

  if adjusted_payable <= 0 then
    raise exception 'PAYROLL_ENTRY_NOT_PAYABLE';
  end if;
  if p_amount > adjusted_payable - target_entry.paid_amount then
    raise exception 'PAYROLL_OVERPAYMENT';
  end if;

  if p_payment_method = 'cash' then
    perform 1
    from public.cash_closures session
    join public.cash_registers register
      on register.id::text = session.register_id
     and register.organization_id = session.organization_id
     and register.branch_id = session.branch_id
    where session.id = p_cash_session_id
      and session.organization_id = p_organization_id
      and session.branch_id = p_branch_id
      and session.date is null
      and register.is_active = true
    for update of session, register;

    if not found then
      raise exception 'OPEN_CASH_SESSION_NOT_FOUND';
    end if;
  elsif p_cash_session_id is not null then
    raise exception 'NON_CASH_PAYMENT_CANNOT_USE_CASH_SESSION';
  end if;

  insert into public.payroll_payments (
    organization_id,
    branch_id,
    allocation_scope,
    payroll_entry_id,
    idempotency_key,
    direction,
    amount,
    payment_method,
    payment_date,
    cash_session_id,
    reference,
    notes,
    created_by
  ) values (
    p_organization_id,
    p_branch_id,
    'branch',
    p_payroll_entry_id,
    trim(p_idempotency_key),
    'payment',
    p_amount,
    p_payment_method,
    p_payment_date,
    p_cash_session_id,
    nullif(left(trim(p_reference), 200), ''),
    nullif(left(trim(p_notes), 2000), ''),
    actor_id
  )
  returning * into created_payment;

  return jsonb_build_object(
    'payment', to_jsonb(created_payment),
    'entry', (
      select to_jsonb(updated_entry)
      from public.payroll_entries updated_entry
      where updated_entry.organization_id = p_organization_id
        and updated_entry.id = p_payroll_entry_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."pay_payroll_entry_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_payroll_entry_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_payment_date" "date", "p_idempotency_key" "text", "p_cash_session_id" "uuid", "p_reference" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_organization_date"("p_organization_id" "uuid", "p_instant" timestamp with time zone DEFAULT "now"()) RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  organization_timezone text := 'America/Asuncion';
begin
  select timezone_record.name
  into organization_timezone
  from public.organization_settings settings
  join pg_timezone_names timezone_record
    on timezone_record.name = settings.timezone
  where settings.organization_id = p_organization_id
  limit 1;

  return (p_instant at time zone coalesce(
    organization_timezone,
    'America/Asuncion'
  ))::date;
end;
$$;


ALTER FUNCTION "public"."payroll_organization_date"("p_organization_id" "uuid", "p_instant" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."perform_cash_admin_action"("p_session_id" "uuid", "p_action" "text", "p_reason" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  actor_id UUID := auth.uid();
  previous_session public.cash_closures%ROWTYPE;
  updated_session public.cash_closures%ROWTYPE;
  session_organization_id UUID;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_action NOT IN ('remote_close', 'suspend', 'unsuspend', 'block', 'unblock', 'reopen') THEN
    RAISE EXCEPTION 'Unsupported cash admin action';
  END IF;

  SELECT *
  INTO previous_session
  FROM public.cash_closures
  WHERE id = p_session_id
  FOR UPDATE;

  IF previous_session.id IS NULL THEN
    RAISE EXCEPTION 'Cash session not found';
  END IF;

  SELECT organization_id
  INTO session_organization_id
  FROM public.cash_closures
  WHERE id = p_session_id;

  IF NOT (
    EXISTS (
      SELECT 1 FROM public.user_roles
      WHERE user_id = actor_id AND role = 'super_admin' AND is_active = TRUE
    )
    OR EXISTS (
      SELECT 1 FROM public.organization_members
      WHERE user_id = actor_id
        AND organization_id = session_organization_id
        AND role IN ('owner', 'admin')
        AND status = 'active'
    )
  ) THEN
    RAISE EXCEPTION 'Insufficient organization permissions';
  END IF;

  UPDATE public.cash_closures
  SET
    status = CASE p_action
      WHEN 'remote_close' THEN 'closed'
      WHEN 'suspend' THEN 'suspended'
      WHEN 'unsuspend' THEN 'open'
      WHEN 'block' THEN 'blocked'
      WHEN 'unblock' THEN 'open'
      WHEN 'reopen' THEN 'open'
    END,
    date = CASE
      WHEN p_action = 'remote_close' THEN NOW()
      WHEN p_action = 'reopen' THEN NULL
      ELSE date
    END,
    closed_by = CASE
      WHEN p_action = 'remote_close' THEN actor_id
      WHEN p_action = 'reopen' THEN NULL
      ELSE closed_by
    END,
    suspended_by = CASE
      WHEN p_action = 'suspend' THEN actor_id
      WHEN p_action = 'unsuspend' THEN NULL
      ELSE suspended_by
    END,
    suspended_at = CASE
      WHEN p_action = 'suspend' THEN NOW()
      WHEN p_action = 'unsuspend' THEN NULL
      ELSE suspended_at
    END,
    blocked_by = CASE
      WHEN p_action = 'block' THEN actor_id
      WHEN p_action = 'unblock' THEN NULL
      ELSE blocked_by
    END,
    blocked_at = CASE
      WHEN p_action = 'block' THEN NOW()
      WHEN p_action = 'unblock' THEN NULL
      ELSE blocked_at
    END,
    updated_at = NOW()
  WHERE id = p_session_id
  RETURNING * INTO updated_session;

  INSERT INTO public.cash_admin_audit (
    session_id, register_id, action, performed_by, reason,
    previous_state, new_state, ip_address, user_agent
  )
  VALUES (
    p_session_id,
    previous_session.register_id,
    p_action,
    actor_id,
    NULLIF(BTRIM(p_reason), ''),
    to_jsonb(previous_session),
    to_jsonb(updated_session),
    inet_client_addr(),
    NULLIF(BTRIM(p_user_agent), '')
  );

  RETURN to_jsonb(updated_session);
END;
$$;


ALTER FUNCTION "public"."perform_cash_admin_action"("p_session_id" "uuid", "p_action" "text", "p_reason" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."perform_maintenance_task"("task_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF task_name = 'reset_stats' THEN
    -- Try to reset stats
    PERFORM pg_stat_reset();
    RETURN true;
  END IF;

  RETURN false;
EXCEPTION WHEN OTHERS THEN
  -- Log error or just return false
  RAISE WARNING 'Error performing maintenance task %: %', task_name, SQLERRM;
  RETURN false;
END;
$$;


ALTER FUNCTION "public"."perform_maintenance_task"("task_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."plan_limit_int"("plan_limits" "jsonb", "limit_key" "text", "fallback" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when plan_limits ? limit_key then
      case
        when jsonb_typeof(plan_limits -> limit_key) = 'number' then (plan_limits ->> limit_key)::integer
        when jsonb_typeof(plan_limits -> limit_key) = 'string'
          and lower(plan_limits ->> limit_key) not like 'ilimit%'
          and regexp_replace(plan_limits ->> limit_key, '[^0-9]', '', 'g') <> ''
        then regexp_replace(plan_limits ->> limit_key, '[^0-9]', '', 'g')::integer
        else null
      end
    else fallback
  end;
$$;


ALTER FUNCTION "public"."plan_limit_int"("plan_limits" "jsonb", "limit_key" "text", "fallback" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_credit_checkout_summary"("p_organization_id" "uuid", "p_sale_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'firstInstallmentTiming', c.metadata->>'first_installment_timing',
    'startDate', to_char(c.start_date at time zone 'America/Asuncion','YYYY-MM-DD'),
    'frequency', c.metadata->>'frequency',
    'firstPayment', c.metadata->'first_installment_payment',
    'firstPaymentAmount', coalesce((c.metadata->'first_installment_payment'->>'amount')::numeric,0),
    'remainingBalance', c.principal - coalesce((c.metadata->'first_installment_payment'->>'amount')::numeric,0),
    'installments', (select jsonb_agg(jsonb_build_object('number',i.installment_number,
      'dueDate',to_char(i.due_date at time zone 'America/Asuncion','YYYY-MM-DD'),
      'amount',i.amount,'amountPaid',coalesce(i.amount_paid,0),'status',i.status) order by i.installment_number)
      from public.credit_installments i where i.credit_id = c.id)
  ) from public.customer_credits c where c.sale_id = p_sale_id and c.organization_id = p_organization_id limit 1;
$$;


ALTER FUNCTION "public"."pos_credit_checkout_summary"("p_organization_id" "uuid", "p_sale_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_decrement_stock"("p_product_id" "uuid", "p_quantity" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org uuid;
  v_stock integer;
begin
  if p_quantity is null or p_quantity <= 0 then
    return false;
  end if;

  -- Bloquea la fila del producto y obtiene su organización + stock actual.
  select organization_id, stock_quantity
    into v_org, v_stock
  from public.products
  where id = p_product_id
  for update;

  if not found then
    return false;
  end if;

  -- El llamador debe ser staff activo (no cliente) de la org del producto.
  if not exists (
    select 1
    from public.organization_members m
    where m.organization_id = v_org
      and m.user_id = auth.uid()
      and m.status = 'active'
      and m.role <> 'customer'
  ) then
    return false;
  end if;

  if coalesce(v_stock, 0) < p_quantity then
    return false;
  end if;

  update public.products
  set stock_quantity = stock_quantity - p_quantity,
      updated_at = now()
  where id = p_product_id;

  return true;
end;
$$;


ALTER FUNCTION "public"."pos_decrement_stock"("p_product_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


