CREATE OR REPLACE FUNCTION "public"."post_finance_cash_movement_from_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  obligation_concept text;
begin
  if new.payment_method <> 'cash' then
    return new;
  end if;

  select obligation.concept
  into obligation_concept
  from public.finance_obligations obligation
  where obligation.id = new.obligation_id
    and obligation.organization_id = new.organization_id
    and obligation.branch_id = new.branch_id;

  insert into public.cash_movements (
    session_id,
    type,
    amount,
    reason,
    payment_method,
    created_by,
    created_at,
    organization_id,
    branch_id,
    finance_payment_id
  ) values (
    new.cash_session_id,
    case when new.direction = 'payment' then 'cash_out' else 'cash_in' end,
    new.amount,
    left(
      case when new.direction = 'payment'
        then 'Pago de gasto: '
        else 'Compensacion por anulacion: '
      end || obligation_concept,
      500
    ),
    'cash',
    new.created_by,
    now(),
    new.organization_id,
    new.branch_id,
    new.id
  );

  update public.cash_closures
  set last_activity_at = now(), updated_at = now()
  where id = new.cash_session_id
    and organization_id = new.organization_id
    and branch_id = new.branch_id;

  return new;
end;
$$;


ALTER FUNCTION "public"."post_finance_cash_movement_from_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_payroll_cash_movement_from_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  employee_label text;
begin
  if new.payment_method <> 'cash' or new.legacy_source_id is not null then
    return new;
  end if;

  select coalesce(profile.full_name, profile.email, new.payroll_entry_id::text)
  into employee_label
  from public.payroll_entries entry
  left join public.profiles profile on profile.id = entry.employee_id
  where entry.organization_id = new.organization_id
    and entry.id = new.payroll_entry_id;

  insert into public.cash_movements (
    session_id,
    type,
    amount,
    reason,
    payment_method,
    created_by,
    created_at,
    organization_id,
    branch_id,
    payroll_payment_id
  ) values (
    new.cash_session_id,
    case when new.direction = 'payment' then 'cash_out' else 'cash_in' end,
    new.amount,
    left(
      case when new.direction = 'payment'
        then 'Pago de nomina: '
        else 'Compensacion de pago de nomina: '
      end || employee_label,
      500
    ),
    'cash',
    new.created_by,
    now(),
    new.organization_id,
    new.branch_id,
    new.id
  );

  update public.cash_closures
  set last_activity_at = now(), updated_at = now()
  where id = new.cash_session_id
    and organization_id = new.organization_id
    and branch_id = new.branch_id;

  return new;
end;
$$;


ALTER FUNCTION "public"."post_payroll_cash_movement_from_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_finance_audit_event_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'UPDATE'
     and tg_table_name = 'finance_payments'
     and old.created_by is not null
     and new.created_by is null
     and to_jsonb(new) - 'created_by' = to_jsonb(old) - 'created_by'
     and not exists (
       select 1 from auth.users actor where actor.id = old.created_by
     ) then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and tg_table_name = 'finance_audit_events'
     and old.actor_id is not null
     and new.actor_id is null
     and to_jsonb(new) - 'actor_id' = to_jsonb(old) - 'actor_id'
     and not exists (
       select 1 from auth.users actor where actor.id = old.actor_id
     ) then
    return new;
  end if;

  if tg_op = 'DELETE'
     and tg_table_name = 'finance_audit_events'
     and (
       not exists (
         select 1
         from public.organizations organization
         where organization.id = old.organization_id
       )
       or (
         old.branch_id is not null
         and not exists (
           select 1
           from public.branches branch
           where branch.organization_id = old.organization_id
             and branch.id = old.branch_id
         )
       )
     ) then
    return old;
  end if;

  raise exception 'FINANCE_AUDIT_EVENTS_ARE_APPEND_ONLY';
end;
$$;


ALTER FUNCTION "public"."prevent_finance_audit_event_mutation"() OWNER TO "postgres";


