CREATE OR REPLACE FUNCTION "public"."process_plan_downgrade_grace"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target record;
  processed integer := 0;
begin
  for target in
    select organization_id, stage
    from public.plan_downgrade_grace
    where (stage = 'grace' and grace_ends_at <= now())
       or (stage = 'deactivated' and archive_deadline_at <= now())
    order by grace_ends_at asc
    for update skip locked
  loop
    if target.stage = 'grace' then
      perform public.enforce_plan_downgrade_deactivation(target.organization_id);
    else
      perform public.enforce_plan_downgrade_archive(target.organization_id);
    end if;
    processed := processed + 1;
  end loop;

  return processed;
end;
$$;


ALTER FUNCTION "public"."process_plan_downgrade_grace"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_pos_sale"("p_sale_data" "jsonb", "p_items" "jsonb", "p_payments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid;
  v_sale_id uuid;
  v_item jsonb;
  v_product_id uuid;
  v_quantity integer;
  v_customer_id uuid;
  v_total_amount decimal;
  v_payment_method text;
  v_status text;
  v_notes text;
  v_created_at timestamptz;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'No autorizado: autenticación requerida';
  end if;

  if not public.has_permission('sales.create', v_uid) then
    raise exception 'No autorizado: permisos insuficientes para procesar ventas POS';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Datos inválidos: se requiere al menos un ítem de venta';
  end if;

  v_customer_id := (p_sale_data->>'customer_id')::uuid;
  v_total_amount := (p_sale_data->>'total_amount')::decimal;
  v_payment_method := p_sale_data->>'payment_method';
  v_status := coalesce(p_sale_data->>'status', 'completed');
  v_notes := p_sale_data->>'notes';
  v_created_at := coalesce((p_sale_data->>'created_at')::timestamptz, now());

  insert into public.sales (
    customer_id,
    total_amount,
    payment_method,
    status,
    notes,
    created_at
  ) values (
    v_customer_id,
    v_total_amount,
    v_payment_method,
    v_status,
    v_notes,
    v_created_at
  )
  returning id into v_sale_id;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_product_id := (v_item->>'product_id')::uuid;
    v_quantity := (v_item->>'quantity')::integer;

    insert into public.sale_items (
      sale_id,
      product_id,
      quantity,
      unit_price,
      subtotal
    ) values (
      v_sale_id,
      v_product_id,
      v_quantity,
      (v_item->>'unit_price')::decimal,
      (v_item->>'subtotal')::decimal
    );

    update public.products
    set stock_quantity = stock_quantity - v_quantity
    where id = v_product_id;
  end loop;

  return jsonb_build_object(
    'id', v_sale_id,
    'success', true
  );
exception when others then
  raise exception 'Error de procesamiento: %', sqlerrm;
end;
$$;


ALTER FUNCTION "public"."process_pos_sale"("p_sale_data" "jsonb", "p_items" "jsonb", "p_payments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_pos_sale_atomic_v2"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_session_id" "uuid", "p_idempotency_key" "text", "p_code" "text", "p_customer_id" "uuid", "p_items" "jsonb", "p_payments" "jsonb", "p_price_mode" "text" DEFAULT 'retail'::"text", "p_order_discount_rate" numeric DEFAULT 0, "p_notes" "text" DEFAULT NULL::"text", "p_tax_rate" numeric DEFAULT 0, "p_prices_include_tax" boolean DEFAULT true, "p_credit" "jsonb" DEFAULT NULL::"jsonb", "p_repair_ids" "jsonb" DEFAULT '[]'::"jsonb", "p_mark_repairs_delivered" boolean DEFAULT false, "p_delivery_outcome" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  existing_sale_id uuid;
  created_sale_id uuid := gen_random_uuid();
  item record;
  payment record;
  selected_product public.products%rowtype;
  branch_stock numeric;
  unit_price numeric;
  line_base numeric;
  line_discount numeric;
  products_subtotal numeric := 0;
  total_discount numeric := 0;
  order_discount numeric := 0;
  repairs_subtotal numeric := 0;
  products_net numeric := 0;
  net_subtotal numeric := 0;
  tax_amount numeric := 0;
  sale_total numeric := 0;
  payments_total numeric := 0;
  payment_count integer := 0;
  payment_method_summary text;
  credit_base numeric := 0;
  credit_limit numeric := 0;
  current_credit_balance numeric := 0;
  available_credit numeric := 0;
  credit_rate numeric := 0;
  credit_count integer := 1;
  credit_frequency text := 'monthly';
  financed_total numeric := 0;
  created_credit_id uuid;
  installment_base numeric;
  principal_base numeric;
  installment_index integer;
  installment_due timestamptz;
begin
  if p_actor_id is null or not exists (
    select 1
    from public.organization_members membership
    where membership.organization_id = p_organization_id
      and membership.user_id = p_actor_id
      and membership.status = 'active'
      and membership.role in ('owner', 'admin', 'manager', 'cashier', 'technician', 'seller')
  ) then
    raise exception 'POS_PERMISSION_DENIED';
  end if;

  if p_branch_id is null or not exists (
    select 1 from public.branches branch
    where branch.id = p_branch_id
      and branch.organization_id = p_organization_id
      and branch.is_active = true
  ) then
    raise exception 'INVALID_POS_BRANCH';
  end if;

  if p_session_id is null or not exists (
    select 1 from public.cash_closures closure
    where closure.id = p_session_id
      and closure.organization_id = p_organization_id
      and closure.branch_id = p_branch_id
      and closure.date is null
  ) then
    raise exception 'CASH_REGISTER_NOT_OPEN';
  end if;

  if coalesce(trim(p_idempotency_key), '') = '' then
    raise exception 'IDEMPOTENCY_KEY_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_organization_id::text || ':pos:' || trim(p_idempotency_key), 0)
  );

  select sale.id into existing_sale_id
  from public.sales sale
  where sale.organization_id = p_organization_id
    and sale.idempotency_key = trim(p_idempotency_key);

  if existing_sale_id is not null then
    return jsonb_build_object('sale_id', existing_sale_id, 'idempotent', true, 'credit_schedule', public.pos_credit_checkout_summary(p_organization_id,existing_sale_id));
  end if;

  if p_customer_id is not null and not exists (
    select 1 from public.customers customer
    where customer.id = p_customer_id
      and customer.organization_id = p_organization_id
  ) then
    raise exception 'CUSTOMER_NOT_IN_ORGANIZATION';
  end if;

  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then
    raise exception 'INVALID_POS_ITEMS';
  end if;
  if jsonb_typeof(coalesce(p_payments, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_payments, '[]'::jsonb)) = 0 then
    raise exception 'PAYMENTS_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_repair_ids, '[]'::jsonb)) <> 'array' then
    raise exception 'INVALID_REPAIR_LIST';
  end if;

  for item in
    select
      (value->>'product_id')::uuid as product_id,
      sum((value->>'quantity')::integer)::integer as quantity,
      sum(greatest(0, coalesce((value->>'discount_amount')::numeric, 0))) as discount_amount
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
    group by (value->>'product_id')::uuid
    order by (value->>'product_id')::uuid
  loop
    if item.product_id is null or item.quantity <= 0 then
      raise exception 'INVALID_ORDER_QUANTITY';
    end if;

    select product.* into selected_product
    from public.products product
    where product.id = item.product_id
      and product.organization_id = p_organization_id
    for update;

    if not found then
      raise exception 'PRODUCT_NOT_IN_ORGANIZATION';
    end if;

    select inventory.stock_quantity into branch_stock
    from public.branch_inventory inventory
    where inventory.branch_id = p_branch_id
      and inventory.product_id = item.product_id
    for update;

    if not found then
      raise exception 'BRANCH_INVENTORY_NOT_CONFIGURED|%', item.product_id;
    end if;
    if coalesce(selected_product.stock_quantity, 0) < item.quantity or coalesce(branch_stock, 0) < item.quantity then
      raise exception 'INSUFFICIENT_STOCK|%|%', item.product_id, least(coalesce(selected_product.stock_quantity, 0), coalesce(branch_stock, 0));
    end if;

    unit_price := case
      when p_price_mode = 'wholesale' and coalesce(selected_product.wholesale_price, 0) > 0
        then selected_product.wholesale_price
      when p_price_mode = 'wholesale'
        then round(selected_product.sale_price * 0.90, 2)
      else selected_product.sale_price
    end;
    line_base := round(unit_price * item.quantity, 2);
    line_discount := least(line_base, item.discount_amount);
    products_subtotal := products_subtotal + line_base;
    total_discount := total_discount + line_discount;
  end loop;

  if exists (
    select 1
    from jsonb_array_elements_text(coalesce(p_repair_ids, '[]'::jsonb)) as requested(value)
    where requested.value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ) then
    raise exception 'INVALID_REPAIR_LIST';
  end if;

  if jsonb_array_length(coalesce(p_repair_ids, '[]'::jsonb)) > 0 then
    if exists (
      select 1
      from jsonb_array_elements_text(p_repair_ids) as requested(value)
      left join public.repairs repair on repair.id = requested.value::uuid
      where repair.id is null
        or repair.organization_id <> p_organization_id
        or repair.branch_id <> p_branch_id
    ) then
      raise exception 'REPAIR_NOT_IN_POS_SCOPE';
    end if;

    -- Saldo pendiente = costo total menos lo ya cobrado (p.ej. un anticipo
    -- registrado desde Reparaciones). Nunca negativo.
    select coalesce(sum(
      greatest(0, coalesce(repair.final_cost, repair.estimated_cost, 0) - coalesce(repair.paid_amount, 0))
    ), 0)
    into repairs_subtotal
    from public.repairs repair
    where repair.id in (select value::uuid from jsonb_array_elements_text(p_repair_ids));
  end if;

  products_net := round(products_subtotal - total_discount, 2);
  p_order_discount_rate := least(100, greatest(0, coalesce(p_order_discount_rate, 0)));
  order_discount := round(products_net * p_order_discount_rate / 100, 2);
  products_net := products_net - order_discount;
  total_discount := total_discount + order_discount;
  net_subtotal := round(products_net + repairs_subtotal, 2);
  if net_subtotal <= 0 then
    raise exception 'POS_TOTAL_MUST_BE_POSITIVE';
  end if;

  p_tax_rate := least(100, greatest(0, coalesce(p_tax_rate, 0)));
  tax_amount := case when p_tax_rate = 0 then 0 else
    (case when p_prices_include_tax
      then round(products_net * p_tax_rate / (100 + p_tax_rate), 2)
      else round(products_net * p_tax_rate / 100, 2)
    end) + round(repairs_subtotal * p_tax_rate / (100 + p_tax_rate), 2)
  end;
  sale_total := round(
    (case when p_prices_include_tax
      then products_net
      else products_net + round(products_net * p_tax_rate / 100, 2)
    end) + repairs_subtotal,
    2
  );

  for payment in
    select
      payment_entry.ordinality - 1 as payment_index,
      lower(trim(payment_entry.value->>'payment_method')) as payment_method,
      round((payment_entry.value->>'amount')::numeric, 2) as amount,
      nullif(trim(payment_entry.value->>'reference'), '') as reference,
      nullif(trim(payment_entry.value->>'card_last4'), '') as card_last4
    from jsonb_array_elements(p_payments) with ordinality as payment_entry(value, ordinality)
  loop
    if payment.payment_method not in ('cash', 'card', 'transfer', 'credit') or payment.amount <= 0 then
      raise exception 'INVALID_POS_PAYMENT';
    end if;
    if payment.payment_method = 'card' and payment.card_last4 is not null
       and payment.card_last4 !~ '^[0-9]{4}$' then
      raise exception 'INVALID_CARD_REFERENCE';
    end if;
    if payment.payment_method = 'transfer' and payment.reference is null then
      raise exception 'TRANSFER_REFERENCE_REQUIRED';
    end if;
    payments_total := payments_total + payment.amount;
    payment_count := payment_count + 1;
    if payment.payment_method = 'credit' then
      credit_base := credit_base + payment.amount;
    end if;
  end loop;

  if abs(payments_total - sale_total) > 0.01 then
    raise exception 'PAYMENT_TOTAL_MISMATCH|%|%', sale_total, payments_total;
  end if;
  if credit_base > 0 and p_customer_id is null then
    raise exception 'CREDIT_CUSTOMER_REQUIRED';
  end if;

  payment_method_summary := case
    when payment_count > 1 then 'mixed'
    else (select case lower(trim(value->>'payment_method'))
      when 'cash' then 'efectivo'
      when 'card' then 'tarjeta'
      when 'transfer' then 'transferencia'
      else 'credit'
    end from jsonb_array_elements(p_payments) limit 1)
  end;

  insert into public.sales (
    id, organization_id, branch_id, idempotency_key, code, customer_id, created_by,
    subtotal_amount, total_amount, tax_amount, discount_amount, payment_method,
    payment_status, status, notes, created_at, updated_at
  ) values (
    created_sale_id, p_organization_id, p_branch_id, trim(p_idempotency_key), trim(p_code),
    p_customer_id, p_actor_id, products_subtotal + repairs_subtotal, sale_total,
    tax_amount, total_discount, payment_method_summary, 'completed', 'completed',
    nullif(trim(p_notes), ''), now(), now()
  );

  insert into public.sale_items (
    sale_id, product_id, quantity, unit_price, discount_amount, subtotal, organization_id
  )
  select
    created_sale_id,
    product.id,
    grouped.quantity,
    case
      when p_price_mode = 'wholesale' and coalesce(product.wholesale_price, 0) > 0 then product.wholesale_price
      when p_price_mode = 'wholesale' then round(product.sale_price * 0.90, 2)
      else product.sale_price
    end,
    least(
      round((case
        when p_price_mode = 'wholesale' and coalesce(product.wholesale_price, 0) > 0 then product.wholesale_price
        when p_price_mode = 'wholesale' then product.sale_price * 0.90
        else product.sale_price
      end) * grouped.quantity, 2),
      grouped.discount_amount
    ),
    round((case
      when p_price_mode = 'wholesale' and coalesce(product.wholesale_price, 0) > 0 then product.wholesale_price
      when p_price_mode = 'wholesale' then product.sale_price * 0.90
      else product.sale_price
    end) * grouped.quantity, 2) - least(
      round((case
        when p_price_mode = 'wholesale' and coalesce(product.wholesale_price, 0) > 0 then product.wholesale_price
        when p_price_mode = 'wholesale' then product.sale_price * 0.90
        else product.sale_price
      end) * grouped.quantity, 2),
      grouped.discount_amount
    ),
    p_organization_id
  from (
    select
      (value->>'product_id')::uuid as product_id,
      sum((value->>'quantity')::integer)::integer as quantity,
      sum(greatest(0, coalesce((value->>'discount_amount')::numeric, 0))) as discount_amount
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
    group by (value->>'product_id')::uuid
  ) grouped
  join public.products product on product.id = grouped.product_id;

  for item in
    select
      (value->>'product_id')::uuid as product_id,
      sum((value->>'quantity')::integer)::integer as quantity
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
    group by (value->>'product_id')::uuid
  loop
    update public.products
    set stock_quantity = stock_quantity - item.quantity, updated_at = now()
    where id = item.product_id and organization_id = p_organization_id;

    update public.branch_inventory
    set stock_quantity = stock_quantity - item.quantity, updated_at = now()
    where branch_id = p_branch_id and product_id = item.product_id;
  end loop;

  for payment in
    select
      payment_entry.ordinality - 1 as payment_index,
      lower(trim(payment_entry.value->>'payment_method')) as payment_method,
      round((payment_entry.value->>'amount')::numeric, 2) as amount,
      nullif(trim(payment_entry.value->>'reference'), '') as reference,
      nullif(trim(payment_entry.value->>'card_last4'), '') as card_last4
    from jsonb_array_elements(p_payments) with ordinality as payment_entry(value, ordinality)
  loop
    insert into public.sale_payments (
      organization_id, sale_id, payment_index, payment_method, amount,
      reference, card_last4, status, created_by
    ) values (
      p_organization_id, created_sale_id, payment.payment_index, payment.payment_method,
      payment.amount, payment.reference, payment.card_last4, 'completed', p_actor_id
    );

    if payment.payment_method <> 'credit' then
      insert into public.cash_movements (
        session_id, type, amount, reason, payment_method, created_by, created_at,
        organization_id, branch_id, sale_id, payment_index
      ) values (
        p_session_id, 'sale', payment.amount, 'Venta ' || created_sale_id::text,
        payment.payment_method, p_actor_id, now(), p_organization_id, p_branch_id,
        created_sale_id, payment.payment_index
      );
    end if;
  end loop;

  if credit_base > 0 then
    select coalesce(customer.credit_limit, 0) into credit_limit
    from public.customers customer
    where customer.id = p_customer_id and customer.organization_id = p_organization_id
    for update;

    select coalesce(sum(greatest(0, installment.amount - coalesce(installment.amount_paid, 0))), 0)
    into current_credit_balance
    from public.customer_credits credit
    join public.credit_installments installment on installment.credit_id = credit.id
    where credit.organization_id = p_organization_id
      and credit.customer_id = p_customer_id
      and installment.status in ('pending', 'late');

    if p_credit->>'start_date' is not null
      and (p_credit->>'start_date')::date <> (now() at time zone 'America/Asuncion')::date then
      raise exception 'CREDIT_START_DATE_CHANGED';
    end if;
    credit_rate := least(100, greatest(0, coalesce((p_credit->>'interest_rate')::numeric, 0)));
    credit_count := least(60, greatest(1, coalesce((p_credit->>'installment_count')::integer, 1)));
    credit_frequency := case p_credit->>'frequency'
      when 'weekly' then 'weekly'
      when 'biweekly' then 'biweekly'
      else 'monthly'
    end;
    credit_base := round(credit_base, coalesce((p_credit->>'fraction_digits')::integer, 0)); financed_total := credit_base + round(credit_base * credit_rate / 100, coalesce((p_credit->>'fraction_digits')::integer, 0));
    available_credit := credit_limit - current_credit_balance;

    if credit_limit <= 0 or available_credit < financed_total then
      raise exception 'CREDIT_LIMIT_EXCEEDED|%', greatest(0, available_credit);
    end if;

    insert into public.customer_credits (
      customer_id, organization_id, branch_id, sale_id, principal, interest_rate,
      term_months, start_date, status, credit_code, credit_type, origin_type, label, metadata
    ) values (
      p_customer_id, p_organization_id, p_branch_id, created_sale_id, financed_total,
      credit_rate, credit_count, now(), 'active',
      'CR-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8)),
      'product_financing', 'sale', 'Venta ' || trim(p_code), jsonb_build_object('first_installment_timing', coalesce(p_credit->>'first_installment_timing', 'at_start'), 'frequency', credit_frequency)
    ) returning id into created_credit_id;

    installment_base := trunc(credit_base / credit_count, coalesce((p_credit->>'fraction_digits')::integer, 0)) + trunc((financed_total - credit_base) / credit_count, coalesce((p_credit->>'fraction_digits')::integer, 0));
    principal_base := trunc(credit_base / credit_count, coalesce((p_credit->>'fraction_digits')::integer, 0));

    for installment_index in 1..credit_count loop
      installment_due := public.credit_schedule_due_date(
        (now() at time zone 'America/Asuncion')::date,
        installment_index - 1, credit_frequency,
        coalesce(p_credit->>'first_installment_timing', 'at_start')
      )::timestamp at time zone 'America/Asuncion';

      insert into public.credit_installments (
        credit_id, sale_id, installment_number, due_date, amount,
        principal_component, interest_component, status
      ) values (
        created_credit_id,
        created_sale_id,
        installment_index,
        installment_due,
        case when installment_index = credit_count
          then financed_total - installment_base * (credit_count - 1)
          else installment_base end,
        case when installment_index = credit_count
          then credit_base - principal_base * (credit_count - 1)
          else principal_base end,
        case when installment_index = credit_count
          then (financed_total - credit_base) - (installment_base - principal_base) * (credit_count - 1)
          else installment_base - principal_base end,
        'pending'
      );
    end loop;
  end if;

  if jsonb_array_length(coalesce(p_repair_ids, '[]'::jsonb)) > 0 then
    -- El saldo vinculado se acaba de cobrar en esta venta: la reparación
    -- queda saldada por completo (paid_amount = costo total).
    update public.repairs repair
    set
      problem_description = trim(coalesce(repair.problem_description, ''))
        || E'\n\nVenta relacionada #' || created_sale_id::text
        || ' (' || payment_method_summary || ') por ' || sale_total::text || '.',
      payment_status = 'pagado',
      paid_amount = coalesce(repair.final_cost, repair.estimated_cost, 0),
      status = case when p_mark_repairs_delivered then 'entregado' else repair.status end,
      picked_up_at = case when p_mark_repairs_delivered then now() else repair.picked_up_at end,
      delivered_at = case when p_mark_repairs_delivered then now() else repair.delivered_at end,
      completed_at = case when p_mark_repairs_delivered then now() else repair.completed_at end,
      delivery_outcome = case when p_mark_repairs_delivered then p_delivery_outcome else repair.delivery_outcome end,
      updated_at = now()
    where repair.id in (select value::uuid from jsonb_array_elements_text(p_repair_ids))
      and repair.organization_id = p_organization_id
      and repair.branch_id = p_branch_id;
  end if;

  update public.cash_closures
  set last_activity_at = now(), updated_at = now()
  where id = p_session_id and organization_id = p_organization_id;

  if p_credit->'first_payment' is not null and p_credit->'first_payment' <> 'null'::jsonb then
    if created_credit_id is null then raise exception 'INVALID_FIRST_INSTALLMENT_PAYMENT'; end if;
    perform public.collect_pos_first_installment(p_organization_id,p_branch_id,p_actor_id,p_session_id,created_credit_id,p_credit->'first_payment');
  end if;
  return jsonb_build_object(
    'sale_id', created_sale_id,
    'idempotent', false,
    'total', sale_total,
    'subtotal', products_subtotal + repairs_subtotal,
    'discount', total_discount,
    'tax', tax_amount,
    'payment_method', payment_method_summary,
    'credit_id', created_credit_id,
    'credit_schedule', public.pos_credit_checkout_summary(p_organization_id,created_sale_id)
  );
end;
$_$;


ALTER FUNCTION "public"."process_pos_sale_atomic_v2"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_session_id" "uuid", "p_idempotency_key" "text", "p_code" "text", "p_customer_id" "uuid", "p_items" "jsonb", "p_payments" "jsonb", "p_price_mode" "text", "p_order_discount_rate" numeric, "p_notes" "text", "p_tax_rate" numeric, "p_prices_include_tax" boolean, "p_credit" "jsonb", "p_repair_ids" "jsonb", "p_mark_repairs_delivered" boolean, "p_delivery_outcome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_pos_sale_atomic_v3"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_session_id" "uuid", "p_idempotency_key" "text", "p_code" "text", "p_customer_id" "uuid", "p_items" "jsonb", "p_payments" "jsonb", "p_price_mode" "text" DEFAULT 'retail'::"text", "p_order_discount_rate" numeric DEFAULT 0, "p_notes" "text" DEFAULT NULL::"text", "p_tax_rate" numeric DEFAULT 0, "p_prices_include_tax" boolean DEFAULT true, "p_credit" "jsonb" DEFAULT NULL::"jsonb", "p_repair_ids" "jsonb" DEFAULT '[]'::"jsonb", "p_mark_repairs_delivered" boolean DEFAULT false, "p_delivery_outcome" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  sale_result jsonb;
  resolved_sale_id uuid;
  existing_sale_id uuid;
begin
  if coalesce(trim(p_idempotency_key), '') = '' then
    raise exception 'IDEMPOTENCY_KEY_REQUIRED';
  end if;

  -- Serialize retries before checking repair payment state. The v2 function uses
  -- the same transaction lock, so a retry remains idempotent.
  perform pg_advisory_xact_lock(
    hashtextextended(p_organization_id::text || ':pos:' || trim(p_idempotency_key), 0)
  );

  select sale.id
  into existing_sale_id
  from public.sales sale
  where sale.organization_id = p_organization_id
    and sale.idempotency_key = trim(p_idempotency_key);

  if existing_sale_id is null
     and jsonb_typeof(coalesce(p_repair_ids, '[]'::jsonb)) = 'array' then
    -- Lock selected repair rows so two cashiers cannot charge the same repair.
    perform repair.id
    from jsonb_array_elements_text(coalesce(p_repair_ids, '[]'::jsonb)) requested(value)
    join public.repairs repair
      on requested.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     and repair.id = requested.value::uuid
    where repair.organization_id = p_organization_id
      and repair.branch_id = p_branch_id
    order by repair.id
    for update of repair;

    -- Blocks repairs that are explicitly marked paid, and repairs whose
    -- paid_amount already covers the cost (balance due <= 0) even if
    -- payment_status wasn't updated to 'pagado' for some reason. A repair
    -- sitting at payment_status = 'parcial' is NOT blocked here: v2 now
    -- charges only its remaining balance, so linking it is the normal way
    -- to collect the rest.
    if exists (
      select 1
      from jsonb_array_elements_text(coalesce(p_repair_ids, '[]'::jsonb)) requested(value)
      join public.repairs repair
        on requested.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       and repair.id = requested.value::uuid
      where repair.organization_id = p_organization_id
        and repair.branch_id = p_branch_id
        and (
          lower(coalesce(repair.payment_status, '')) in ('pagado', 'paid')
          or coalesce(repair.final_cost, repair.estimated_cost, 0) - coalesce(repair.paid_amount, 0) <= 0
        )
    ) then
      raise exception 'REPAIR_ALREADY_PAID';
    end if;
  end if;

  sale_result := public.process_pos_sale_atomic_v2(
    p_organization_id => p_organization_id,
    p_branch_id => p_branch_id,
    p_actor_id => p_actor_id,
    p_session_id => p_session_id,
    p_idempotency_key => p_idempotency_key,
    p_code => p_code,
    p_customer_id => p_customer_id,
    p_items => p_items,
    p_payments => p_payments,
    p_price_mode => p_price_mode,
    p_order_discount_rate => p_order_discount_rate,
    p_notes => p_notes,
    p_tax_rate => p_tax_rate,
    p_prices_include_tax => p_prices_include_tax,
    p_credit => p_credit,
    p_repair_ids => p_repair_ids,
    p_mark_repairs_delivered => p_mark_repairs_delivered,
    p_delivery_outcome => p_delivery_outcome
  );

  resolved_sale_id := (sale_result->>'sale_id')::uuid;
  if resolved_sale_id is null then
    raise exception 'INVALID_ATOMIC_SALE_RESPONSE';
  end if;

  perform public.apply_pos_payment_metadata_atomic(
    p_organization_id,
    p_branch_id,
    resolved_sale_id,
    p_actor_id,
    p_payments
  );

  return sale_result;
end;
$_$;


ALTER FUNCTION "public"."process_pos_sale_atomic_v3"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_session_id" "uuid", "p_idempotency_key" "text", "p_code" "text", "p_customer_id" "uuid", "p_items" "jsonb", "p_payments" "jsonb", "p_price_mode" "text", "p_order_discount_rate" numeric, "p_notes" "text", "p_tax_rate" numeric, "p_prices_include_tax" boolean, "p_credit" "jsonb", "p_repair_ids" "jsonb", "p_mark_repairs_delivered" boolean, "p_delivery_outcome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_pos_sale_atomic_v4"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_session_id" "uuid", "p_idempotency_key" "text", "p_code" "text", "p_customer_id" "uuid", "p_items" "jsonb", "p_payments" "jsonb", "p_price_mode" "text" DEFAULT 'retail'::"text", "p_order_discount_rate" numeric DEFAULT 0, "p_notes" "text" DEFAULT NULL::"text", "p_tax_rate" numeric DEFAULT 0, "p_prices_include_tax" boolean DEFAULT true, "p_credit" "jsonb" DEFAULT NULL::"jsonb", "p_repair_ids" "jsonb" DEFAULT '[]'::"jsonb", "p_mark_repairs_delivered" boolean DEFAULT false, "p_delivery_outcome" "text" DEFAULT NULL::"text", "p_store_credit_amount" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  result jsonb;
  created_sale_id uuid;
  sale public.sales%rowtype;
  available_balance numeric := 0;
  requested_store_credit numeric := round(greatest(0, coalesce(p_store_credit_amount, 0)), 2);
  effective_payments jsonb := coalesce(p_payments, '[]'::jsonb);
  existing_debit numeric;
begin
  if requested_store_credit > 0 then
    if p_customer_id is null then
      raise exception 'STORE_CREDIT_CUSTOMER_REQUIRED';
    end if;

    -- Every redemption for this customer uses the same row lock. This makes
    -- the balance check and ledger insert safe across simultaneous registers.
    perform 1
    from public.customers customer
    where customer.id = p_customer_id
      and customer.organization_id = p_organization_id
    for update;

    if not found then
      raise exception 'CUSTOMER_NOT_IN_ORGANIZATION';
    end if;

    select coalesce(sum(credit.amount), 0)
    into available_balance
    from public.customer_store_credits credit
    where credit.organization_id = p_organization_id
      and credit.customer_id = p_customer_id;

    if requested_store_credit > available_balance then
      raise exception 'STORE_CREDIT_EXCEEDS_BALANCE|%', greatest(0, available_balance);
    end if;

    -- v3 validates that payment tenders equal the server-calculated sale total.
    -- The synthetic entry participates only in that validation and is removed
    -- together with its cash movement before this transaction commits.
    effective_payments := effective_payments || jsonb_build_array(jsonb_build_object(
      'payment_method', 'cash',
      'amount', requested_store_credit,
      'reference', null,
      'card_last4', null,
      'payment_index', 9999
    ));
  end if;

  result := public.process_pos_sale_atomic_v3(
    p_organization_id => p_organization_id,
    p_branch_id => p_branch_id,
    p_actor_id => p_actor_id,
    p_session_id => p_session_id,
    p_idempotency_key => p_idempotency_key,
    p_code => p_code,
    p_customer_id => p_customer_id,
    p_items => p_items,
    p_payments => effective_payments,
    p_price_mode => p_price_mode,
    p_order_discount_rate => p_order_discount_rate,
    p_notes => p_notes,
    p_tax_rate => p_tax_rate,
    p_prices_include_tax => p_prices_include_tax,
    p_credit => p_credit,
    p_repair_ids => p_repair_ids,
    p_mark_repairs_delivered => p_mark_repairs_delivered,
    p_delivery_outcome => p_delivery_outcome
  );

  created_sale_id := (result->>'sale_id')::uuid;
  if requested_store_credit <= 0 then
    return result;
  end if;

  select * into sale
  from public.sales
  where id = created_sale_id
    and organization_id = p_organization_id;

  if not found or sale.customer_id is distinct from p_customer_id then
    raise exception 'STORE_CREDIT_SALE_CUSTOMER_MISMATCH';
  end if;
  if requested_store_credit > sale.total_amount then
    raise exception 'STORE_CREDIT_EXCEEDS_SALE_TOTAL';
  end if;

  select abs(credit.amount) into existing_debit
  from public.customer_store_credits credit
  where credit.organization_id = p_organization_id
    and credit.source_type = 'sale'
    and credit.source_id = created_sale_id;

  if existing_debit is not null then
    if existing_debit <> requested_store_credit then
      raise exception 'STORE_CREDIT_IDEMPOTENCY_MISMATCH';
    end if;
    return result || jsonb_build_object('store_credit_applied', existing_debit);
  end if;

  -- The synthetic entry is always last, so v3 assigns this ordinal index.
  delete from public.cash_movements
  where organization_id = p_organization_id
    and sale_id = created_sale_id
    and payment_index = jsonb_array_length(effective_payments) - 1;

  delete from public.sale_payments
  where organization_id = p_organization_id
    and sale_id = created_sale_id
    and payment_index = jsonb_array_length(effective_payments) - 1;

  insert into public.customer_store_credits (
    organization_id, customer_id, amount, reason, source_type, source_id, created_by
  ) values (
    p_organization_id, p_customer_id, -requested_store_credit,
    'Aplicado en venta ' || coalesce(sale.code, created_sale_id::text),
    'sale', created_sale_id, p_actor_id
  );

  update public.sales
  set payment_method = case
    when jsonb_array_length(coalesce(p_payments, '[]'::jsonb)) = 0 then 'store_credit'
    when jsonb_array_length(coalesce(p_payments, '[]'::jsonb)) = 1 then 'mixed'
    else payment_method
  end
  where id = created_sale_id and organization_id = p_organization_id;

  return result || jsonb_build_object('store_credit_applied', requested_store_credit);
end;
$$;


ALTER FUNCTION "public"."process_pos_sale_atomic_v4"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_session_id" "uuid", "p_idempotency_key" "text", "p_code" "text", "p_customer_id" "uuid", "p_items" "jsonb", "p_payments" "jsonb", "p_price_mode" "text", "p_order_discount_rate" numeric, "p_notes" "text", "p_tax_rate" numeric, "p_prices_include_tax" boolean, "p_credit" "jsonb", "p_repair_ids" "jsonb", "p_mark_repairs_delivered" boolean, "p_delivery_outcome" "text", "p_store_credit_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_pos_sale_atomic_v5"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_session_id" "uuid", "p_idempotency_key" "text", "p_code" "text", "p_customer_id" "uuid", "p_items" "jsonb", "p_payments" "jsonb", "p_price_mode" "text" DEFAULT 'retail'::"text", "p_order_discount_rate" numeric DEFAULT 0, "p_notes" "text" DEFAULT NULL::"text", "p_tax_rate" numeric DEFAULT 0, "p_prices_include_tax" boolean DEFAULT true, "p_credit" "jsonb" DEFAULT NULL::"jsonb", "p_repair_ids" "jsonb" DEFAULT '[]'::"jsonb", "p_mark_repairs_delivered" boolean DEFAULT false, "p_delivery_outcome" "text" DEFAULT NULL::"text", "p_store_credit_amount" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare result jsonb; created_sale_id uuid; line record; variant_price numeric; parent_price numeric;
begin
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then raise exception 'INVALID_POS_ITEMS'; end if;

  for line in
    select (e.value->>'product_id')::uuid product_id, (e.value->>'variant_id')::uuid variant_id
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) e(value)
    where nullif(e.value->>'variant_id', '') is not null
  loop
    select case when p_price_mode = 'wholesale' and coalesce(v.wholesale_price,0)>0 then v.wholesale_price else v.sale_price end,
           case when p_price_mode = 'wholesale' and coalesce(p.wholesale_price,0)>0 then p.wholesale_price
                when p_price_mode = 'wholesale' then round(p.sale_price*.90,2) else p.sale_price end
    into variant_price, parent_price
    from public.product_variants v join public.products p on p.id=v.product_id
    join public.branch_variant_inventory i on i.variant_id=v.id and i.branch_id=p_branch_id
    where v.id=line.variant_id and v.product_id=line.product_id
      and v.organization_id=p_organization_id and i.organization_id=p_organization_id and v.is_active=true;
    if not found then raise exception 'VARIANT_NOT_IN_POS_SCOPE'; end if;
    if variant_price is distinct from parent_price then raise exception 'VARIANT_PRICE_REQUIRES_SYNC'; end if;
  end loop;

  if exists (
    select 1 from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) a(value)
    join jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) b(value)
      on a.value->>'product_id'=b.value->>'product_id'
    where nullif(a.value->>'variant_id','') is null and nullif(b.value->>'variant_id','') is not null
  ) then raise exception 'POS_VARIANT_MIXED_WITH_PARENT'; end if;

  result := public.process_pos_sale_atomic_v4(
    p_organization_id,p_branch_id,p_actor_id,p_session_id,p_idempotency_key,p_code,p_customer_id,
    p_items,p_payments,p_price_mode,p_order_discount_rate,p_notes,p_tax_rate,p_prices_include_tax,
    p_credit,p_repair_ids,p_mark_repairs_delivered,p_delivery_outcome,p_store_credit_amount);
  if coalesce((result->>'idempotent')::boolean,false) then return result; end if;
  created_sale_id := (result->>'sale_id')::uuid;

  for line in
    select (e.value->>'product_id')::uuid product_id, (e.value->>'variant_id')::uuid variant_id,
      sum((e.value->>'quantity')::integer)::integer quantity,
      sum(greatest(0,coalesce((e.value->>'discount_amount')::numeric,0))) discount_amount
    from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) e(value)
    where nullif(e.value->>'variant_id','') is not null
    group by 1,2 order by 1,2
  loop
    perform public.adjust_variant_stock_atomic(p_organization_id,p_branch_id,line.variant_id,-line.quantity,
      'sale','pos-sale:'||p_idempotency_key||':'||line.variant_id::text,p_actor_id,'sale',created_sale_id,'Venta POS',
      jsonb_build_object('sale_id',created_sale_id));
  end loop;

  delete from public.sale_items si where si.sale_id=created_sale_id and si.product_id in (
    select distinct (e.value->>'product_id')::uuid from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) e(value)
    where nullif(e.value->>'variant_id','') is not null);

  insert into public.sale_items(sale_id,product_id,variant_id,variant_name,variant_sku,variant_attributes,
    quantity,unit_price,discount_amount,subtotal,organization_id)
  select created_sale_id,g.product_id,g.variant_id,v.variant_name,v.sku,v.attributes,g.quantity,
    case when p_price_mode='wholesale' and coalesce(v.wholesale_price,0)>0 then v.wholesale_price else v.sale_price end,
    least(g.discount_amount,round((case when p_price_mode='wholesale' and coalesce(v.wholesale_price,0)>0 then v.wholesale_price else v.sale_price end)*g.quantity,2)),
    round((case when p_price_mode='wholesale' and coalesce(v.wholesale_price,0)>0 then v.wholesale_price else v.sale_price end)*g.quantity,2)
      - least(g.discount_amount,round((case when p_price_mode='wholesale' and coalesce(v.wholesale_price,0)>0 then v.wholesale_price else v.sale_price end)*g.quantity,2)),
    p_organization_id
  from (
    select (e.value->>'product_id')::uuid product_id,(e.value->>'variant_id')::uuid variant_id,
      sum((e.value->>'quantity')::integer)::integer quantity,
      sum(greatest(0,coalesce((e.value->>'discount_amount')::numeric,0))) discount_amount
    from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) e(value)
    where nullif(e.value->>'variant_id','') is not null group by 1,2
  ) g join public.product_variants v on v.id=g.variant_id;

  return result||jsonb_build_object('variants_processed',true);
end; $$;


ALTER FUNCTION "public"."process_pos_sale_atomic_v5"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_session_id" "uuid", "p_idempotency_key" "text", "p_code" "text", "p_customer_id" "uuid", "p_items" "jsonb", "p_payments" "jsonb", "p_price_mode" "text", "p_order_discount_rate" numeric, "p_notes" "text", "p_tax_rate" numeric, "p_prices_include_tax" boolean, "p_credit" "jsonb", "p_repair_ids" "jsonb", "p_mark_repairs_delivered" boolean, "p_delivery_outcome" "text", "p_store_credit_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."products_compute_device_sort_key"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  base text;
begin
  if coalesce(new.device_brand, '') = '' and coalesce(array_length(new.device_models, 1), 0) = 0 then
    new.device_sort_key := null;
    return new;
  end if;

  base := lower(btrim(coalesce(new.device_brand, '') || ' ' || coalesce(new.device_models[1], '')));

  select string_agg(
           case when t.parte[1] ~ '^[0-9]+$' then lpad(t.parte[1], 6, '0') else t.parte[1] end,
           '' order by t.orden
         )
    into new.device_sort_key
    from regexp_matches(base, '([0-9]+|[^0-9]+)', 'g') with ordinality as t(parte, orden);

  return new;
end;
$_$;


ALTER FUNCTION "public"."products_compute_device_sort_key"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_current_user_to_admin"() RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  uid uuid;
BEGIN
  uid := auth.uid();
  IF uid IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Actualizar profiles (el trigger sincronizará con auth.users)
  INSERT INTO public.profiles(id, role, updated_at)
  VALUES (uid, 'admin', NOW())
  ON CONFLICT (id) DO UPDATE
  SET role = 'admin', updated_at = EXCLUDED.updated_at;

  -- Actualizar user_roles
  INSERT INTO public.user_roles(user_id, role, is_active, updated_at)
  VALUES (uid, 'admin', TRUE, NOW())
  ON CONFLICT (user_id) DO UPDATE
  SET role = 'admin', is_active = TRUE, updated_at = EXCLUDED.updated_at;

  -- Actualizar auth.users directamente también
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) ||
    jsonb_build_object('role', 'admin')
  WHERE id = uid;

  -- Registrar en audit_log
  INSERT INTO public.audit_log(user_id, action, resource, resource_id, new_values)
  VALUES (uid, 'grant_admin_self_rpc', 'auth', uid::text, '{"role":"admin"}'::jsonb);

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."promote_current_user_to_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_approved_commission_rule"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_fk_nulling_only boolean := false;
  safe_effective_close boolean := false;
  safe_retire boolean := false;
  organization_today date;
begin
  if tg_op = 'DELETE' and old.status = 'approved' then
    raise exception 'PAYROLL_APPROVED_COMMISSION_RULE_IS_IMMUTABLE';
  end if;
  if tg_op <> 'UPDATE' or old.status <> 'approved' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  organization_today := public.payroll_organization_date(old.organization_id, now());

  actor_fk_nulling_only :=
    to_jsonb(new) - 'approved_by' - 'created_by' - 'updated_at'
      = to_jsonb(old) - 'approved_by' - 'created_by' - 'updated_at'
    and (
      (
        old.approved_by is not null and new.approved_by is null
        and not exists (select 1 from auth.users actor where actor.id = old.approved_by)
      )
      or (
        old.created_by is not null and new.created_by is null
        and not exists (select 1 from auth.users actor where actor.id = old.created_by)
      )
    )
    and (
      new.approved_by is not distinct from old.approved_by
      or (
        old.approved_by is not null and new.approved_by is null
        and not exists (select 1 from auth.users actor where actor.id = old.approved_by)
      )
    )
    and (
      new.created_by is not distinct from old.created_by
      or (
        old.created_by is not null and new.created_by is null
        and not exists (select 1 from auth.users actor where actor.id = old.created_by)
      )
    );

  if actor_fk_nulling_only then
    return new;
  end if;

  -- Caso 1: Cierre de vigencia manteniendo approved
  safe_effective_close :=
    to_jsonb(new) - 'effective_to' - 'updated_at'
      = to_jsonb(old) - 'effective_to' - 'updated_at'
    and new.effective_to is not null
    and new.effective_to >= old.effective_from
    and new.effective_to >= organization_today
    and (old.effective_to is null or new.effective_to <= old.effective_to)
    and not exists (
      select 1
      from public.earned_commissions commission
      where commission.organization_id = old.organization_id
        and commission.commission_rule_id = old.id
        and commission.occurred_on > new.effective_to
    );

  if safe_effective_close then
    return new;
  end if;

  -- Caso 2: Retiro formal de la regla (status = 'retired')
  safe_retire :=
    to_jsonb(new) - 'status' - 'effective_to' - 'updated_at'
      = to_jsonb(old) - 'status' - 'effective_to' - 'updated_at'
    and new.status = 'retired'
    and (
      new.effective_to is null
      or (
        new.effective_to >= old.effective_from
        and not exists (
          select 1
          from public.earned_commissions commission
          where commission.organization_id = old.organization_id
            and commission.commission_rule_id = old.id
            and commission.occurred_on > new.effective_to
        )
      )
    );

  if safe_retire then
    return new;
  end if;

  raise exception 'PAYROLL_APPROVED_COMMISSION_RULE_IS_IMMUTABLE';
end;
$$;


ALTER FUNCTION "public"."protect_approved_commission_rule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_approved_payroll_entry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  parent_status text;
  ledger_paid numeric(14, 2);
  adjusted_payable numeric(14, 2);
  expected_status text;
begin
  select run.status
  into parent_status
  from public.payroll_runs run
  where run.organization_id = old.organization_id
    and run.id = old.payroll_run_id;

  if parent_status <> 'approved' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'PAYROLL_APPROVED_ENTRY_IS_IMMUTABLE';
  end if;

  if to_jsonb(new) - 'paid_amount' - 'payment_status' - 'updated_at'
       <> to_jsonb(old) - 'paid_amount' - 'payment_status' - 'updated_at' then
    raise exception 'PAYROLL_APPROVED_ENTRY_IS_IMMUTABLE';
  end if;

  select coalesce(sum(
    case payment.direction when 'payment' then payment.amount else -payment.amount end
  ), 0)
  into ledger_paid
  from public.payroll_payments payment
  where payment.organization_id = old.organization_id
    and payment.payroll_entry_id = old.id;

  select old.net_amount + coalesce(sum(adjustment.amount) filter (
    where adjustment.included_in_net = false
  ), 0)
  into adjusted_payable
  from public.payroll_adjustments adjustment
  where adjustment.organization_id = old.organization_id
    and adjustment.payroll_entry_id = old.id;

  expected_status := case
    when ledger_paid = adjusted_payable and adjusted_payable > 0 then 'paid'
    when ledger_paid > 0 then 'partially_paid'
    else 'pending'
  end;

  if new.paid_amount is distinct from ledger_paid
     or new.payment_status is distinct from expected_status then
    raise exception 'PAYROLL_PAYMENT_STATE_MUST_MATCH_LEDGER';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."protect_approved_payroll_entry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_approved_payroll_run"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_fk_nulling_only boolean := false;
begin
  if tg_op = 'UPDATE'
     and old.status = 'draft'
     and new.status = 'voided'
     and exists (
       select 1
       from public.payroll_entries entry
       join public.payroll_entry_commissions claim
         on claim.organization_id = entry.organization_id
        and claim.payroll_entry_id = entry.id
       where entry.organization_id = old.organization_id
         and entry.payroll_run_id = old.id
     ) then
    raise exception 'PAYROLL_RUN_WITH_CLAIMS_CANNOT_BE_VOIDED';
  end if;

  if tg_op = 'DELETE' and old.status = 'approved' then
    raise exception 'PAYROLL_APPROVED_RUN_IS_IMMUTABLE';
  end if;
  if tg_op <> 'UPDATE' or old.status <> 'approved' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  actor_fk_nulling_only :=
    to_jsonb(new) - 'generated_by' - 'approved_by' - 'updated_at'
      = to_jsonb(old) - 'generated_by' - 'approved_by' - 'updated_at'
    and (
      (
        old.generated_by is not null and new.generated_by is null
        and not exists (select 1 from auth.users actor where actor.id = old.generated_by)
      )
      or (
        old.approved_by is not null and new.approved_by is null
        and not exists (select 1 from auth.users actor where actor.id = old.approved_by)
      )
    )
    and (
      new.generated_by is not distinct from old.generated_by
      or (
        old.generated_by is not null and new.generated_by is null
        and not exists (select 1 from auth.users actor where actor.id = old.generated_by)
      )
    )
    and (
      new.approved_by is not distinct from old.approved_by
      or (
        old.approved_by is not null and new.approved_by is null
        and not exists (select 1 from auth.users actor where actor.id = old.approved_by)
      )
    );

  if actor_fk_nulling_only then
    return new;
  end if;

  raise exception 'PAYROLL_APPROVED_RUN_IS_IMMUTABLE';
end;
$$;


ALTER FUNCTION "public"."protect_approved_payroll_run"() OWNER TO "postgres";


