CREATE OR REPLACE FUNCTION "public"."reconcile_sale_payment_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_payment_id" "uuid", "p_status" "text", "p_fee_amount" numeric DEFAULT 0, "p_provider" "text" DEFAULT NULL::"text", "p_institution" "text" DEFAULT NULL::"text", "p_channel" "text" DEFAULT NULL::"text", "p_terminal_id" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_settled_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
  target_payment public.sale_payments%rowtype;
begin
  if actor_id is null then
    raise exception 'Authentication required';
  end if;
  if not public.has_org_permission(p_organization_id, 'pos.cash.manage') then
    raise exception 'Insufficient cash permissions';
  end if;
  if not public.user_has_branch_access(p_branch_id) then
    raise exception 'Insufficient branch permissions';
  end if;
  if p_status not in ('pending', 'confirmed', 'rejected', 'refunded', 'disputed') then
    raise exception 'INVALID_RECONCILIATION_STATUS';
  end if;

  select * into target_payment
  from public.sale_payments payment
  where payment.id = p_payment_id
    and payment.organization_id = p_organization_id
    and payment.branch_id = p_branch_id
    and payment.payment_method in ('card', 'transfer')
  for update;

  if not found then
    raise exception 'ELECTRONIC_PAYMENT_NOT_FOUND';
  end if;
  if coalesce(p_fee_amount, 0) < 0 or coalesce(p_fee_amount, 0) > target_payment.amount then
    raise exception 'INVALID_PAYMENT_FEE';
  end if;
  if p_channel is not null and p_channel not in ('card_terminal', 'bank_transfer', 'qr', 'other') then
    raise exception 'INVALID_PAYMENT_CHANNEL';
  end if;
  if target_payment.payment_method = 'card'
     and p_channel is not null
     and p_channel not in ('card_terminal', 'other') then
    raise exception 'INVALID_PAYMENT_CHANNEL';
  end if;
  if target_payment.payment_method = 'transfer'
     and p_channel is not null
     and p_channel not in ('bank_transfer', 'qr', 'other') then
    raise exception 'INVALID_PAYMENT_CHANNEL';
  end if;

  update public.sale_payments
  set
    reconciliation_status = p_status,
    fee_amount = coalesce(p_fee_amount, 0),
    provider = nullif(left(trim(p_provider), 120), ''),
    institution = nullif(left(trim(p_institution), 120), ''),
    channel = coalesce(p_channel, channel),
    terminal_id = nullif(left(trim(p_terminal_id), 80), ''),
    reconciliation_notes = nullif(left(trim(p_notes), 1000), ''),
    settled_at = case when p_status = 'confirmed' then coalesce(p_settled_at, now()) else p_settled_at end,
    reconciled_at = now(),
    reconciled_by = actor_id,
    updated_at = now()
  where id = target_payment.id;

  insert into public.sale_payment_reconciliation_events (
    organization_id, branch_id, sale_payment_id, previous_status,
    new_status, fee_amount, notes, created_by
  ) values (
    p_organization_id, p_branch_id, target_payment.id, target_payment.reconciliation_status,
    p_status, coalesce(p_fee_amount, 0), nullif(left(trim(p_notes), 1000), ''), actor_id
  );

  return (
    select to_jsonb(updated_payment)
    from public.sale_payments updated_payment
    where updated_payment.id = target_payment.id
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_sale_payment_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_payment_id" "uuid", "p_status" "text", "p_fee_amount" numeric, "p_provider" "text", "p_institution" "text", "p_channel" "text", "p_terminal_id" "text", "p_notes" "text", "p_settled_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_cash_count_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_session_id" "uuid", "p_counted_total" numeric, "p_denominations" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
  expected_total numeric;
  created_count public.cash_counts%rowtype;
begin
  if actor_id is null then
    raise exception 'Authentication required';
  end if;
  if not public.has_org_permission(p_organization_id, 'pos.cash.manage') then
    raise exception 'Insufficient cash permissions';
  end if;
  if coalesce(p_counted_total, -1) < 0 then
    raise exception 'Counted total cannot be negative';
  end if;

  perform 1
  from public.cash_closures c
  where c.id = p_session_id
    and c.organization_id = p_organization_id
    and c.branch_id = p_branch_id
    and c.date is null
  for update;

  if not found then
    raise exception 'Open cash session not found in selected branch';
  end if;

  expected_total := public.calculate_cash_session_expected(
    p_session_id,
    p_organization_id,
    p_branch_id
  );

  insert into public.cash_counts (
    organization_id, branch_id, session_id, counted_total,
    expected_total, discrepancy, denominations, counted_by
  ) values (
    p_organization_id,
    p_branch_id,
    p_session_id,
    p_counted_total,
    expected_total,
    p_counted_total - expected_total,
    coalesce(p_denominations, '{}'::jsonb),
    actor_id
  ) returning * into created_count;

  return to_jsonb(created_count);
end;
$$;


ALTER FUNCTION "public"."record_cash_count_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_session_id" "uuid", "p_counted_total" numeric, "p_denominations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_cash_movement_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_session_id" "uuid", "p_type" "text", "p_amount" numeric, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
  created_movement public.cash_movements%rowtype;
begin
  if actor_id is null then
    raise exception 'Authentication required';
  end if;
  if not public.has_org_permission(p_organization_id, 'pos.cash.manage') then
    raise exception 'Insufficient cash permissions';
  end if;
  if p_type not in ('cash_in', 'cash_out') then
    raise exception 'INVALID_CASH_MOVEMENT_TYPE';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'INVALID_CASH_MOVEMENT_AMOUNT';
  end if;
  if nullif(trim(p_reason), '') is null then
    raise exception 'CASH_MOVEMENT_REASON_REQUIRED';
  end if;

  perform 1
  from public.cash_closures c
  join public.cash_registers r
    on r.id::text = c.register_id
   and r.organization_id = c.organization_id
   and r.branch_id = c.branch_id
  where c.id = p_session_id
    and c.organization_id = p_organization_id
    and c.branch_id = p_branch_id
    and c.date is null
    and r.is_active = true
  for update of c, r;

  if not found then
    raise exception 'OPEN_CASH_SESSION_NOT_FOUND';
  end if;

  insert into public.cash_movements (
    session_id, type, amount, reason, created_by, created_at,
    organization_id, branch_id
  ) values (
    p_session_id,
    p_type,
    p_amount,
    left(trim(p_reason), 500),
    actor_id,
    now(),
    p_organization_id,
    p_branch_id
  ) returning * into created_movement;

  update public.cash_closures
  set last_activity_at = now(), updated_at = now()
  where id = p_session_id
    and organization_id = p_organization_id
    and branch_id = p_branch_id;

  return to_jsonb(created_movement);
end;
$$;


ALTER FUNCTION "public"."record_cash_movement_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_session_id" "uuid", "p_type" "text", "p_amount" numeric, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_customer_order_collection_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_payment_reference" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_idempotency_key" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  order_row public.customer_orders%rowtype;
  normalized_method text := upper(coalesce(p_payment_method, ''));
  amount_due numeric(12,2);
  next_collected numeric(12,2);
  next_status text;
  existing_history public.customer_order_payment_history%rowtype;
begin
  if p_actor_id is null or not exists (
    select 1
    from public.organization_members membership
    where membership.organization_id = p_organization_id
      and membership.user_id = p_actor_id
      and membership.status = 'active'
      and membership.role in ('owner', 'admin', 'manager', 'seller', 'cashier')
  ) then
    raise exception 'ORDER_PERMISSION_DENIED';
  end if;

  if p_idempotency_key is null then
    raise exception 'PAYMENT_IDEMPOTENCY_KEY_REQUIRED';
  end if;

  select * into existing_history
  from public.customer_order_payment_history history
  where history.organization_id = p_organization_id
    and history.idempotency_key = p_idempotency_key;
  if found then
    return jsonb_build_object(
      'order_id', existing_history.order_id,
      'unchanged', true,
      'payment_status', existing_history.to_status,
      'collected_amount', existing_history.amount
    );
  end if;

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'PAYMENT_AMOUNT_INVALID';
  end if;
  if normalized_method not in ('CASH', 'CARD', 'TRANSFER', 'DIGITAL_WALLET') then
    raise exception 'ORDER_PAYMENT_METHOD_INVALID';
  end if;
  if normalized_method in ('TRANSFER', 'CARD', 'DIGITAL_WALLET')
     and nullif(trim(p_payment_reference), '') is null then
    raise exception 'PAYMENT_REFERENCE_REQUIRED';
  end if;

  select * into order_row
  from public.customer_orders
  where id = p_order_id and organization_id = p_organization_id
  for update;
  if not found then raise exception 'ORDER_NOT_FOUND'; end if;
  if order_row.status = 'CANCELLED' then raise exception 'ORDER_ALREADY_CANCELLED'; end if;
  if order_row.payment_status = 'REFUNDED' then raise exception 'ORDER_PAYMENT_ALREADY_REFUNDED'; end if;

  amount_due := greatest(
    0,
    order_row.total
      - coalesce(order_row.store_credit_reserved, 0)
      - coalesce(order_row.store_credit_applied, 0)
      - coalesce(order_row.collected_amount, 0)
  );
  if p_amount > amount_due then
    raise exception 'PAYMENT_EXCEEDS_AMOUNT_DUE';
  end if;

  next_collected := coalesce(order_row.collected_amount, 0) + p_amount;
  next_status := case
    when next_collected + coalesce(order_row.store_credit_reserved, 0)
         + coalesce(order_row.store_credit_applied, 0) >= order_row.total then 'PAID'
    else 'PARTIAL'
  end;

  update public.customer_orders
  set collected_amount = next_collected,
      payment_status = next_status,
      payment_method = normalized_method,
      updated_at = now()
  where id = order_row.id and organization_id = p_organization_id;

  insert into public.customer_order_payment_history (
    organization_id, order_id, from_status, to_status, payment_method,
    amount, payment_reference, note, changed_by, idempotency_key, created_at
  ) values (
    p_organization_id, order_row.id, order_row.payment_status, next_status,
    normalized_method, p_amount, nullif(trim(p_payment_reference), ''),
    nullif(trim(p_note), ''), p_actor_id, p_idempotency_key, now()
  );

  return jsonb_build_object(
    'order_id', order_row.id,
    'unchanged', false,
    'payment_status', next_status,
    'collected_amount', next_collected,
    'amount_due', greatest(0, amount_due - p_amount)
  );
end;
$$;


ALTER FUNCTION "public"."record_customer_order_collection_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_amount" numeric, "p_payment_method" "text", "p_payment_reference" "text", "p_note" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_customer_order_payment_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_to_status" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  order_row public.customer_orders%rowtype;
  normalized_status text := upper(coalesce(p_to_status, ''));
  paid_amount numeric(12,2);
begin
  if p_actor_id is null or not exists (
    select 1 from public.organization_members membership
    where membership.organization_id = p_organization_id
      and membership.user_id = p_actor_id
      and membership.status = 'active'
      and membership.role in ('owner', 'admin', 'manager', 'seller', 'cashier')
  ) then
    raise exception 'ORDER_PERMISSION_DENIED';
  end if;
  if normalized_status not in ('PAID', 'PARTIAL', 'REFUNDED', 'FAILED') then
    raise exception 'ORDER_PAYMENT_STATUS_INVALID';
  end if;

  select * into order_row from public.customer_orders
  where id = p_order_id and organization_id = p_organization_id
  for update;
  if not found then raise exception 'ORDER_NOT_FOUND'; end if;

  if order_row.payment_status = normalized_status then
    return jsonb_build_object('order_id', order_row.id, 'unchanged', true);
  end if;
  if order_row.status = 'CANCELLED' and normalized_status not in ('REFUNDED', 'FAILED') then
    raise exception 'ORDER_ALREADY_CANCELLED';
  end if;
  if order_row.payment_status = 'REFUNDED' then raise exception 'ORDER_PAYMENT_ALREADY_REFUNDED'; end if;
  if normalized_status = 'REFUNDED' and order_row.payment_status not in ('PAID', 'PARTIAL') then
    raise exception 'ORDER_PAYMENT_NOT_REFUNDABLE';
  end if;

  paid_amount := case when normalized_status = 'PAID'
    then greatest(0, order_row.total - order_row.store_credit_reserved - order_row.store_credit_applied)
    else null end;

  update public.customer_orders
  set payment_status = normalized_status, updated_at = now()
  where id = order_row.id and organization_id = p_organization_id;

  insert into public.customer_order_payment_history (
    organization_id, order_id, from_status, to_status, payment_method,
    amount, note, changed_by, created_at
  ) values (
    p_organization_id, order_row.id, order_row.payment_status, normalized_status,
    order_row.payment_method, paid_amount, nullif(trim(p_note), ''), p_actor_id, now()
  );

  return jsonb_build_object('order_id', order_row.id, 'unchanged', false, 'amount', paid_amount);
end;
$$;


ALTER FUNCTION "public"."record_customer_order_payment_atomic"("p_organization_id" "uuid", "p_order_id" "uuid", "p_actor_id" "uuid", "p_to_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_database_growth_snapshot"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_size bigint;
BEGIN
  v_size := pg_database_size(current_database());
  INSERT INTO public.database_growth_snapshots (snapshot_date, total_size_bytes, total_size_mb)
  VALUES (CURRENT_DATE, v_size, round(v_size / (1024.0 * 1024.0), 2))
  ON CONFLICT (snapshot_date) DO UPDATE
    SET total_size_bytes = EXCLUDED.total_size_bytes,
        total_size_mb = EXCLUDED.total_size_mb,
        recorded_at = now();
END;
$$;


ALTER FUNCTION "public"."record_database_growth_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_finance_audit_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  row_values jsonb;
  target_organization_id uuid;
  target_branch_id uuid;
  target_entity_id uuid;
  target_actor_id uuid;
  actor_fk_nulling_only boolean := false;
begin
  if tg_op = 'DELETE' and not exists (
    select 1
    from public.organizations organization
    where organization.id = old.organization_id
  ) then
    return old;
  end if;

  if tg_op = 'UPDATE' then
    actor_fk_nulling_only :=
      to_jsonb(new) - 'created_by' - 'updated_by' - 'voided_by' - 'updated_at'
        = to_jsonb(old) - 'created_by' - 'updated_by' - 'voided_by' - 'updated_at'
      and (
        (
          (to_jsonb(old) ->> 'created_by') is not null
          and (to_jsonb(new) ->> 'created_by') is null
          and not exists (
            select 1 from auth.users actor
            where actor.id = (to_jsonb(old) ->> 'created_by')::uuid
          )
        )
        or (
          (to_jsonb(old) ->> 'updated_by') is not null
          and (to_jsonb(new) ->> 'updated_by') is null
          and not exists (
            select 1 from auth.users actor
            where actor.id = (to_jsonb(old) ->> 'updated_by')::uuid
          )
        )
        or (
          (to_jsonb(old) ->> 'voided_by') is not null
          and (to_jsonb(new) ->> 'voided_by') is null
          and not exists (
            select 1 from auth.users actor
            where actor.id = (to_jsonb(old) ->> 'voided_by')::uuid
          )
        )
      )
      and not (
        (to_jsonb(new) ->> 'created_by') is distinct from (to_jsonb(old) ->> 'created_by')
        and not ((to_jsonb(old) ->> 'created_by') is not null and (to_jsonb(new) ->> 'created_by') is null)
      )
      and not (
        (to_jsonb(new) ->> 'updated_by') is distinct from (to_jsonb(old) ->> 'updated_by')
        and not ((to_jsonb(old) ->> 'updated_by') is not null and (to_jsonb(new) ->> 'updated_by') is null)
      )
      and not (
        (to_jsonb(new) ->> 'voided_by') is distinct from (to_jsonb(old) ->> 'voided_by')
        and not ((to_jsonb(old) ->> 'voided_by') is not null and (to_jsonb(new) ->> 'voided_by') is null)
      );

    if actor_fk_nulling_only then
      return new;
    end if;
  end if;

  row_values := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  target_organization_id := (row_values ->> 'organization_id')::uuid;
  target_branch_id := nullif(row_values ->> 'branch_id', '')::uuid;
  target_entity_id := (row_values ->> 'id')::uuid;
  target_actor_id := coalesce(
    auth.uid(),
    nullif(row_values ->> 'updated_by', '')::uuid,
    nullif(row_values ->> 'created_by', '')::uuid
  );

  insert into public.finance_audit_events (
    organization_id,
    branch_id,
    entity_type,
    entity_id,
    action,
    actor_id,
    old_values,
    new_values
  ) values (
    target_organization_id,
    target_branch_id,
    tg_table_name,
    target_entity_id,
    lower(tg_op),
    target_actor_id,
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end
  );

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."record_finance_audit_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_repair_quality_check"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_result" "text", "p_checklist" "jsonb", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_repair public.repairs%rowtype;
  created_check public.repair_quality_checks%rowtype;
  operation_time timestamptz := now();
  next_status public.repair_status;
begin
  if p_result not in ('passed', 'failed', 'unrepairable', 'withdrawn') then
    raise exception 'REPAIR_QUALITY_INVALID_RESULT';
  end if;
  if jsonb_typeof(coalesce(p_checklist, '{}'::jsonb)) <> 'object' then
    raise exception 'REPAIR_QUALITY_INVALID_CHECKLIST';
  end if;
  if p_result = 'passed' and not (
    coalesce((p_checklist->>'powersOn')::boolean, false)
    and coalesce((p_checklist->>'reportedIssueResolved')::boolean, false)
    and coalesce((p_checklist->>'basicFunctions')::boolean, false)
    and coalesce((p_checklist->>'physicalCondition')::boolean, false)
    and coalesce((p_checklist->>'accessoriesVerified')::boolean, false)
  ) then
    raise exception 'REPAIR_QUALITY_CHECKLIST_INCOMPLETE';
  end if;
  if p_result <> 'passed' and char_length(trim(coalesce(p_note, ''))) < 5 then
    raise exception 'REPAIR_QUALITY_NOTE_REQUIRED';
  end if;

  select * into target_repair
  from public.repairs
  where id = p_repair_id
    and organization_id = p_organization_id
    and branch_id = p_branch_id
  for update;

  if not found then raise exception 'REPAIR_NOT_FOUND'; end if;
  if target_repair.status in ('entregado', 'cancelado') then
    raise exception 'REPAIR_QUALITY_INVALID_STATE';
  end if;
  if target_repair.technician_id is null then
    raise exception 'REPAIR_TECHNICIAN_REQUIRED';
  end if;

  next_status := case when p_result = 'failed' then 'reparacion' else 'listo' end;

  insert into public.repair_quality_checks (
    organization_id, branch_id, repair_id, result, checklist, note, created_by, created_at
  ) values (
    p_organization_id, p_branch_id, p_repair_id, p_result, coalesce(p_checklist, '{}'::jsonb),
    nullif(trim(coalesce(p_note, '')), ''), p_actor_id, operation_time
  ) returning * into created_check;

  update public.repairs
  set current_quality_check_id = created_check.id,
      status = next_status,
      completed_at = case when next_status = 'listo' then coalesce(completed_at, operation_time) else null end,
      updated_at = operation_time
  where id = p_repair_id;

  if target_repair.status is distinct from next_status then
    insert into public.repair_status_history (
      repair_id, organization_id, old_status, new_status, changed_by, notes
    ) values (
      p_repair_id, p_organization_id, target_repair.status, next_status, p_actor_id,
      case when p_result = 'failed'
        then 'Fallo la prueba funcional: ' || trim(coalesce(p_note, ''))
        else 'Verificacion tecnica: ' || p_result
      end
    );
  end if;

  return jsonb_build_object(
    'repair_id', p_repair_id,
    'quality_check_id', created_check.id,
    'result', created_check.result,
    'status', next_status,
    'checked_at', created_check.created_at
  );
end;
$$;


ALTER FUNCTION "public"."record_repair_quality_check"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_result" "text", "p_checklist" "jsonb", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_storefront_visit"("p_organization_id" "uuid", "p_page" "text", "p_new_visitor" boolean) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  insert into public.storefront_daily_visits (organization_id, day, page, views, visitors)
  values (
    p_organization_id,
    (now() at time zone 'America/Asuncion')::date,
    p_page,
    1,
    case when p_new_visitor then 1 else 0 end
  )
  on conflict (organization_id, day, page) do update
    set views = public.storefront_daily_visits.views + 1,
        visitors = public.storefront_daily_visits.visitors + excluded.visitors,
        updated_at = now();
$$;


ALTER FUNCTION "public"."record_storefront_visit"("p_organization_id" "uuid", "p_page" "text", "p_new_visitor" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redeem_points_for_raffle_tickets"("p_raffle_id" "uuid", "p_customer_id" "uuid", "p_quantity" integer) RETURNS SETOF "public"."raffle_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  raffle public.raffles;
  account public.loyalty_accounts;
  cost integer;
  owned integer;
  issued integer;
  ledger_row public.loyalty_ledger;
  chosen integer;
  attempts integer;
  created_ids uuid[] := array[]::uuid[];
  new_ticket public.raffle_tickets;
  i integer;
begin
  if p_quantity is null or p_quantity <= 0 or p_quantity > 100 then
    raise exception 'La cantidad de números debe estar entre 1 y 100.' using errcode = 'invalid_parameter_value';
  end if;

  -- Se bloquea el sorteo: el cupo total se evalua sin carreras.
  select * into raffle from public.raffles where id = p_raffle_id for update;

  if not found then
    raise exception 'El sorteo no existe.' using errcode = 'no_data_found';
  end if;

  -- El canje lo hace quien atiende el mostrador.
  if not public.has_org_permission(raffle.organization_id, 'pos.sales.create') then
    raise exception 'No tenés permiso sobre este sorteo.' using errcode = 'insufficient_privilege';
  end if;

  if raffle.status <> 'published' then
    raise exception 'El sorteo no está abierto a participación.' using errcode = 'invalid_parameter_value';
  end if;

  if now() < raffle.starts_at then
    raise exception 'El sorteo todavía no comenzó.' using errcode = 'invalid_parameter_value';
  end if;

  if now() >= raffle.ends_at then
    raise exception 'El sorteo ya cerró.' using errcode = 'invalid_parameter_value';
  end if;

  if not exists (
    select 1 from public.customers c
    where c.id = p_customer_id and c.organization_id = raffle.organization_id
  ) then
    raise exception 'El cliente no pertenece a la organización del sorteo.' using errcode = 'invalid_parameter_value';
  end if;

  select * into account
  from public.loyalty_accounts
  where customer_id = p_customer_id
  for update;

  if not found then
    raise exception 'El cliente no tiene puntos acumulados.' using errcode = 'invalid_parameter_value';
  end if;

  -- Juego responsable: la autoexclusion manda por encima del saldo.
  if account.self_excluded_until is not null and account.self_excluded_until > now() then
    raise exception 'El cliente está autoexcluido de participar hasta %.', account.self_excluded_until
      using errcode = 'invalid_parameter_value';
  end if;

  cost := raffle.points_per_ticket * p_quantity;

  if account.balance < cost then
    raise exception 'Puntos insuficientes: hacen falta % y hay %.', cost, account.balance
      using errcode = 'invalid_parameter_value';
  end if;

  -- Tope por cliente.
  if raffle.max_tickets_per_customer is not null then
    select count(*) into owned
    from public.raffle_tickets
    where raffle_id = p_raffle_id and customer_id = p_customer_id;

    if owned + p_quantity > raffle.max_tickets_per_customer then
      raise exception 'Máximo % números por cliente en este sorteo (ya tiene %).',
        raffle.max_tickets_per_customer, owned
        using errcode = 'invalid_parameter_value';
    end if;
  end if;

  -- Cupo del pool.
  select count(*) into issued from public.raffle_tickets where raffle_id = p_raffle_id;

  if issued + p_quantity > raffle.max_tickets_total then
    raise exception 'No quedan suficientes números: hay % libres.', raffle.max_tickets_total - issued
      using errcode = 'invalid_parameter_value';
  end if;

  -- Un solo asiento negativo por la operacion completa.
  insert into public.loyalty_ledger (
    organization_id, customer_id, points, balance_after, source, description, raffle_id, created_by
  )
  values (
    raffle.organization_id,
    p_customer_id,
    -cost,
    account.balance - cost,
    'raffle_entry',
    format('%s número(s) del sorteo "%s"', p_quantity, raffle.name),
    p_raffle_id,
    auth.uid()
  )
  returning * into ledger_row;

  for i in 1..p_quantity loop
    attempts := 0;

    loop
      attempts := attempts + 1;

      if attempts > 25 then
        raise exception 'No se pudo asignar un número libre. Volvé a intentar.' using errcode = 'restrict_violation';
      end if;

      select n into chosen
      from generate_series(1, raffle.max_tickets_total) as n
      where not exists (
        select 1 from public.raffle_tickets t
        where t.raffle_id = p_raffle_id and t.ticket_number = n
      )
      order by random()
      limit 1;

      if chosen is null then
        raise exception 'No quedan números libres en el sorteo.' using errcode = 'restrict_violation';
      end if;

      begin
        insert into public.raffle_tickets (
          organization_id, raffle_id, customer_id, ticket_number, points_spent, ledger_id
        )
        values (
          raffle.organization_id, p_raffle_id, p_customer_id, chosen,
          raffle.points_per_ticket, ledger_row.id
        )
        returning * into new_ticket;

        created_ids := created_ids || new_ticket.id;
        exit;
      exception
        when unique_violation then
          -- Otro canje se quedo con el numero entre el select y el insert.
          null;
      end;
    end loop;
  end loop;

  return query
  select * from public.raffle_tickets where id = any(created_ids) order by ticket_number;
end;
$$;


ALTER FUNCTION "public"."redeem_points_for_raffle_tickets"("p_raffle_id" "uuid", "p_customer_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_all_branch_product_alerts"("p_product_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_branch_id UUID;
BEGIN
  IF p_product_id IS NULL THEN
    RETURN;
  END IF;

  PERFORM public.refresh_global_product_metadata_alerts(p_product_id);

  FOR v_branch_id IN
    SELECT DISTINCT branch_id
    FROM (
      SELECT bi.branch_id
      FROM public.branch_inventory bi
      WHERE bi.product_id = p_product_id
      UNION
      SELECT public.get_default_branch_id()
    ) branches_to_refresh
  LOOP
    PERFORM public.refresh_branch_product_alerts(p_product_id, v_branch_id);
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."refresh_all_branch_product_alerts"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_branch_product_alerts"("p_product_id" "uuid", "p_branch_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_branch_stock INTEGER;
  v_branch_min INTEGER;
  v_branch_name TEXT;
  v_default_branch_id UUID;
BEGIN
  IF p_product_id IS NULL OR p_branch_id IS NULL THEN
    RETURN;
  END IF;

  SELECT * INTO v_product FROM public.products WHERE id = p_product_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT name INTO v_branch_name FROM public.branches WHERE id = p_branch_id;
  IF v_branch_name IS NULL THEN
    RETURN;
  END IF;

  v_default_branch_id := public.get_default_branch_id();

  SELECT bi.stock_quantity, bi.min_stock
  INTO v_branch_stock, v_branch_min
  FROM public.branch_inventory bi
  WHERE bi.product_id = p_product_id
    AND bi.branch_id = p_branch_id;

  v_branch_stock := COALESCE(
    v_branch_stock,
    CASE
      WHEN p_branch_id = v_default_branch_id THEN COALESCE(v_product.stock_quantity, 0)
      ELSE 0
    END
  );

  -- El umbral de la sucursal manda; sin el, el del producto.
  v_branch_min := COALESCE(v_branch_min, v_product.min_stock, 0);

  DELETE FROM public.product_alerts
  WHERE product_id = p_product_id
    AND branch_id = p_branch_id
    AND is_resolved = FALSE
    AND alert_type IN ('low_stock', 'out_of_stock');

  IF v_branch_stock = 0 THEN
    INSERT INTO public.product_alerts (product_id, branch_id, alert_type, message, is_resolved)
    VALUES (
      p_product_id, p_branch_id, 'out_of_stock',
      format('Producto agotado en %s', v_branch_name), FALSE
    );
  ELSIF v_branch_stock <= v_branch_min THEN
    INSERT INTO public.product_alerts (product_id, branch_id, alert_type, message, is_resolved)
    VALUES (
      p_product_id, p_branch_id, 'low_stock',
      format('Stock bajo en %s: %s unidades restantes (mínimo %s)', v_branch_name, v_branch_stock, v_branch_min),
      FALSE
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."refresh_branch_product_alerts"("p_product_id" "uuid", "p_branch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_global_product_metadata_alerts"("p_product_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product public.products%ROWTYPE;
BEGIN
  IF p_product_id IS NULL THEN
    RETURN;
  END IF;

  SELECT *
  INTO v_product
  FROM public.products
  WHERE id = p_product_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  DELETE FROM public.product_alerts
  WHERE product_id = p_product_id
    AND branch_id IS NULL
    AND is_resolved = FALSE
    AND alert_type IN ('no_supplier', 'no_category', 'no_image');

  IF public.is_service_like_product(p_product_id) THEN
    RETURN;
  END IF;

  IF v_product.supplier_id IS NULL THEN
    INSERT INTO public.product_alerts (
      product_id,
      branch_id,
      alert_type,
      message,
      is_resolved
    )
    VALUES (
      p_product_id,
      NULL,
      'no_supplier',
      'Producto sin proveedor asignado',
      FALSE
    );
  END IF;

  IF v_product.category_id IS NULL THEN
    INSERT INTO public.product_alerts (
      product_id,
      branch_id,
      alert_type,
      message,
      is_resolved
    )
    VALUES (
      p_product_id,
      NULL,
      'no_category',
      'Producto sin categoría asignada',
      FALSE
    );
  END IF;

  IF v_product.images IS NULL OR COALESCE(array_length(v_product.images, 1), 0) = 0 THEN
    INSERT INTO public.product_alerts (
      product_id,
      branch_id,
      alert_type,
      message,
      is_resolved
    )
    VALUES (
      p_product_id,
      NULL,
      'no_image',
      'Producto sin imagen',
      FALSE
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."refresh_global_product_metadata_alerts"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_organization_review_stats"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  target_org_id uuid;
BEGIN
  target_org_id := COALESCE(NEW.organization_id, OLD.organization_id);

  UPDATE public.organizations
  SET
    review_rating_avg = COALESCE((
      SELECT avg(rating)::numeric(3,2)
      FROM public.organization_reviews
      WHERE organization_id = target_org_id AND moderation_status = 'published'
    ), 0),
    review_count = (
      SELECT count(*) FROM public.organization_reviews
      WHERE organization_id = target_org_id AND moderation_status = 'published'
    ),
    review_verified_avg = COALESCE((
      SELECT avg(rating)::numeric(3,2)
      FROM public.organization_reviews
      WHERE organization_id = target_org_id
        AND moderation_status = 'published'
        AND verification_type IN ('purchase', 'repair')
    ), 0),
    review_verified_count = (
      SELECT count(*) FROM public.organization_reviews
      WHERE organization_id = target_org_id
        AND moderation_status = 'published'
        AND verification_type IN ('purchase', 'repair')
    ),
    updated_at = now()
  WHERE id = target_org_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."refresh_organization_review_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_product_stock_from_branch_inventory"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_product_id UUID;
BEGIN
  v_product_id := COALESCE(NEW.product_id, OLD.product_id);

  UPDATE public.products
  SET stock_quantity = COALESCE((
    SELECT SUM(bi.stock_quantity)
    FROM public.branch_inventory bi
    WHERE bi.product_id = v_product_id
  ), 0),
      updated_at = NOW()
  WHERE id = v_product_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


