CREATE OR REPLACE FUNCTION "public"."refresh_variant_product_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  affected_product_id uuid := coalesce(new.product_id, old.product_id);
begin
  update public.product_variants variant
  set stock_quantity = coalesce((
    select sum(inventory.stock_quantity)
    from public.branch_variant_inventory inventory
    where inventory.variant_id = variant.id
  ), 0),
  updated_at = now()
  where variant.product_id = affected_product_id;

  update public.products product
  set stock_quantity = coalesce((
    select sum(inventory.stock_quantity)
    from public.branch_variant_inventory inventory
    where inventory.product_id = affected_product_id
  ), 0),
  updated_at = now()
  where product.id = affected_product_id
    and product.has_variants = true;

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."refresh_variant_product_stock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_applied_store_credit_on_order_cancel"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.status = 'CANCELLED'
     and old.status is distinct from 'CANCELLED'
     and coalesce(old.store_credit_applied, 0) > 0
     and old.customer_id is not null then
    insert into public.customer_store_credits (
      organization_id, customer_id, amount, reason, source_type, source_id, created_by
    ) values (
      old.organization_id, old.customer_id, old.store_credit_applied,
      'Reintegro por cancelación del pedido ' || old.order_number,
      'order_refund', old.id, auth.uid()
    )
    on conflict (organization_id, source_id)
      where source_type = 'order_refund' and source_id is not null
    do nothing;
    new.store_credit_applied := 0;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."refund_applied_store_credit_on_order_cancel"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_credit_payment_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_installment_id" "uuid", "p_amount" numeric, "p_method" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
  target_installment public.credit_installments%rowtype;
  paid_total numeric;
  applied_amount numeric;
  target_session_id uuid;
  customer_name text;
  payment_id uuid;
begin
  if actor_id is null then
    raise exception 'Authentication required';
  end if;
  if not public.has_org_permission(p_organization_id, 'crm.customers.manage') then
    raise exception 'Insufficient credit permissions';
  end if;
  if p_method not in ('cash', 'card', 'transfer') then
    raise exception 'Invalid payment method';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Payment amount must be greater than zero';
  end if;

  select i.*
  into target_installment
  from public.credit_installments i
  join public.customer_credits c on c.id = i.credit_id
  where i.id = p_installment_id
    and c.organization_id = p_organization_id
  for update of i;

  if not found then
    raise exception 'Installment does not belong to organization';
  end if;

  select coalesce(sum(p.amount), 0)
  into paid_total
  from public.credit_payments p
  where p.installment_id = target_installment.id;

  applied_amount := least(p_amount, greatest(target_installment.amount - paid_total, 0));
  if applied_amount <= 0 then
    raise exception 'Installment has no outstanding balance';
  end if;

  if p_method = 'cash' then
    if p_branch_id is null then
      raise exception 'A branch is required for cash payments';
    end if;

    select c.id
    into target_session_id
    from public.cash_closures c
    where c.organization_id = p_organization_id
      and c.branch_id = p_branch_id
      and c.date is null
    order by
      case when lower(c.register_id) = 'principal' then 0 else 1 end,
      c.created_at desc
    limit 1
    for update;

    if target_session_id is null then
      raise exception 'Open cash session required for cash payment';
    end if;
  end if;

  insert into public.credit_payments (
    credit_id,
    installment_id,
    amount,
    payment_method,
    notes
  )
  values (
    target_installment.credit_id,
    target_installment.id,
    applied_amount,
    p_method,
    nullif(trim(p_notes), '')
  )
  returning id into payment_id;

  if p_method = 'cash' then
    select c.name
    into customer_name
    from public.customer_credits cc
    join public.customers c on c.id = cc.customer_id
    where cc.id = target_installment.credit_id;

    insert into public.cash_movements (
      session_id,
      type,
      amount,
      reason,
      payment_method,
      created_by,
      created_at,
      organization_id,
      branch_id
    )
    values (
      target_session_id,
      'cash_in',
      applied_amount,
      'Cobro cuota credito' ||
        case when customer_name is null then '' else ' - ' || customer_name end ||
        case when nullif(trim(p_notes), '') is null then '' else ' (' || trim(p_notes) || ')' end,
      'cash',
      actor_id,
      now(),
      p_organization_id,
      p_branch_id
    );
  end if;

  return jsonb_build_object(
    'payment_id', payment_id,
    'installment_id', target_installment.id,
    'credit_id', target_installment.credit_id,
    'installment_number', target_installment.installment_number,
    'applied_amount', applied_amount,
    'requested_amount', p_amount
  );
end;
$$;


ALTER FUNCTION "public"."register_credit_payment_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_installment_id" "uuid", "p_amount" numeric, "p_method" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_unpriced_repair_deposit"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_payment_method" "text", "p_payment_amount" numeric, "p_payment_reference" "text", "p_payment_note" "text", "p_idempotency_key" "text", "p_cash_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_repair public.repairs%rowtype;
  existing_payment public.repair_payments%rowtype;
  created_payment_id uuid;
  resolved_paid numeric(12, 2);
  operation_time timestamptz := now();
begin
  if p_actor_id is null or not exists (
    select 1
    from public.organization_members membership
    where membership.organization_id = p_organization_id
      and membership.user_id = p_actor_id
      and membership.status = 'active'
      and membership.role in ('owner', 'admin', 'manager', 'cashier', 'technician', 'seller')
  ) then
    raise exception 'REPAIR_FINANCIAL_PERMISSION_DENIED';
  end if;

  if p_idempotency_key is null
     or char_length(trim(p_idempotency_key)) < 8
     or char_length(trim(p_idempotency_key)) > 120 then
    raise exception 'REPAIR_IDEMPOTENCY_KEY_REQUIRED';
  end if;

  if p_payment_method not in ('cash', 'card', 'transfer')
     or coalesce(p_payment_amount, 0) <= 0 then
    raise exception 'REPAIR_PAYMENT_AMOUNT_INVALID';
  end if;

  if p_payment_method in ('card', 'transfer')
     and nullif(trim(coalesce(p_payment_reference, '')), '') is null then
    raise exception 'REPAIR_PAYMENT_REFERENCE_REQUIRED';
  end if;

  select repair.*
  into target_repair
  from public.repairs repair
  where repair.id = p_repair_id
    and repair.organization_id = p_organization_id
    and repair.branch_id = p_branch_id
  for update;

  if not found then
    raise exception 'REPAIR_NOT_FOUND';
  end if;

  select payment.*
  into existing_payment
  from public.repair_payments payment
  where payment.organization_id = p_organization_id
    and payment.idempotency_key = trim(p_idempotency_key)
  limit 1;

  if existing_payment.id is not null then
    if existing_payment.repair_id <> p_repair_id
       or existing_payment.amount is distinct from p_payment_amount
       or existing_payment.payment_method is distinct from p_payment_method
       or existing_payment.reference is distinct from nullif(trim(coalesce(p_payment_reference, '')), '') then
      raise exception 'REPAIR_IDEMPOTENCY_CONFLICT';
    end if;

    return jsonb_build_object(
      'repair_id', target_repair.id,
      'payment_id', existing_payment.id,
      'paid_amount', greatest(0, coalesce(target_repair.paid_amount, 0)),
      'idempotent', true
    );
  end if;

  if target_repair.status = 'cancelado' then
    raise exception 'REPAIR_PAYMENT_INVALID_STATE';
  end if;

  if target_repair.final_cost is not null
     or coalesce(target_repair.estimated_cost, 0) > 0
     or coalesce(target_repair.labor_cost, 0) > 0
     or exists (
       select 1
       from public.repair_parts part
       where part.repair_id = target_repair.id
         and coalesce(part.unit_price, part.unit_cost, 0) * greatest(part.quantity, 0) > 0
     ) then
    raise exception 'REPAIR_PRICE_ALREADY_DEFINED';
  end if;

  if p_cash_session_id is null or not exists (
    select 1
    from public.cash_closures closure
    where closure.id = p_cash_session_id
      and closure.organization_id = p_organization_id
      and closure.branch_id = p_branch_id
      and closure.date is null
  ) then
    raise exception 'REPAIR_CASH_REGISTER_NOT_OPEN';
  end if;

  insert into public.repair_payments (
    repair_id, organization_id, branch_id, amount, payment_method,
    idempotency_key, source, reference, notes, cash_session_id,
    created_by, created_at
  ) values (
    target_repair.id, p_organization_id, p_branch_id, p_payment_amount,
    p_payment_method, trim(p_idempotency_key), 'repairs',
    nullif(trim(coalesce(p_payment_reference, '')), ''),
    nullif(trim(coalesce(p_payment_note, '')), ''),
    p_cash_session_id, p_actor_id, operation_time
  ) returning id into created_payment_id;

  insert into public.cash_movements (
    session_id, type, amount, reason, payment_method, created_by,
    created_at, organization_id, branch_id
  ) values (
    p_cash_session_id, 'cash_in', p_payment_amount,
    'Anticipo reparación ' || coalesce(target_repair.ticket_number, target_repair.id::text),
    p_payment_method, p_actor_id, operation_time, p_organization_id, p_branch_id
  );

  resolved_paid := greatest(0, coalesce(target_repair.paid_amount, 0)) + p_payment_amount;

  update public.repairs
  set paid_amount = resolved_paid,
      payment_status = 'parcial',
      updated_at = operation_time
  where id = target_repair.id;

  return jsonb_build_object(
    'repair_id', target_repair.id,
    'payment_id', created_payment_id,
    'paid_amount', resolved_paid,
    'idempotent', false
  );
end;
$$;


ALTER FUNCTION "public"."register_unpriced_repair_deposit"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_payment_method" "text", "p_payment_amount" numeric, "p_payment_reference" "text", "p_payment_note" "text", "p_idempotency_key" "text", "p_cash_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_repair_parts_with_inventory"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_parts" "jsonb", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("parts_cost" numeric, "parts_price" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  item jsonb;
  old_item record;
  resolved_product_id uuid;
  resolved_name text;
  resolved_quantity integer;
  resolved_unit_price numeric;
  resolved_unit_cost numeric;
  available_stock integer;
  previous_stock integer;
  direct_cost_total numeric := 0;
  charged_price_total numeric := 0;
begin
  if jsonb_typeof(coalesce(p_parts, '[]'::jsonb)) <> 'array' then
    raise exception 'INVALID_REPAIR_PARTS';
  end if;

  if jsonb_array_length(coalesce(p_parts, '[]'::jsonb)) > 100 then
    raise exception 'TOO_MANY_REPAIR_PARTS';
  end if;

  perform 1
  from public.repairs repair
  where repair.id = p_repair_id
    and repair.organization_id = p_organization_id
    and repair.branch_id = p_branch_id
  for update;

  if not found then
    raise exception 'REPAIR_NOT_FOUND';
  end if;

  -- Lock every inventory row that can be restored or consumed in a stable
  -- order. This prevents concurrent repairs from overselling the same item.
  perform 1
  from public.branch_inventory inventory
  where inventory.branch_id = p_branch_id
    and inventory.product_id in (
      select product_id
      from public.repair_parts
      where repair_id = p_repair_id
        and product_id is not null
      union
      select (value->>'product_id')::uuid
      from jsonb_array_elements(coalesce(p_parts, '[]'::jsonb))
      where nullif(value->>'product_id', '') is not null
    )
  order by inventory.product_id
  for update;

  -- Editing replaces the complete list. Return previously consumed stock
  -- before validating and consuming the replacement list.
  for old_item in
    select product_id, sum(quantity)::integer as quantity
    from public.repair_parts
    where repair_id = p_repair_id
      and product_id is not null
    group by product_id
    order by product_id
  loop
    select coalesce(stock_quantity, 0)
      into previous_stock
    from public.branch_inventory
    where branch_id = p_branch_id
      and product_id = old_item.product_id
    for update;

    if not found then
      raise exception 'REPAIR_INVENTORY_ROW_MISSING|%', old_item.product_id;
    end if;

    update public.branch_inventory
    set stock_quantity = previous_stock + old_item.quantity,
        updated_at = now()
    where branch_id = p_branch_id
      and product_id = old_item.product_id;

    insert into public.product_movements (
      product_id, movement_type, quantity, previous_stock, new_stock,
      reference_id, reference_type, notes, user_id, branch_id,
      organization_id, created_at
    ) values (
      old_item.product_id, 'return', old_item.quantity, previous_stock,
      previous_stock + old_item.quantity, p_repair_id, 'repair',
      'Reposicion automatica al editar repuestos de reparacion',
      p_actor_id, p_branch_id, p_organization_id, now()
    );
  end loop;

  delete from public.repair_parts where repair_id = p_repair_id;

  for item in
    select value from jsonb_array_elements(coalesce(p_parts, '[]'::jsonb))
  loop
    resolved_name := trim(coalesce(item->>'part_name', ''));
    resolved_quantity := (item->>'quantity')::integer;
    resolved_unit_price := (item->>'unit_price')::numeric;
    resolved_unit_cost := coalesce(nullif(item->>'unit_cost', '')::numeric, resolved_unit_price);
    resolved_product_id := nullif(item->>'product_id', '')::uuid;

    if resolved_name = '' or resolved_quantity <= 0 or resolved_unit_price < 0 or resolved_unit_cost < 0 then
      raise exception 'INVALID_REPAIR_PART';
    end if;

    if resolved_product_id is not null then
      select coalesce(product.purchase_price, 0)
        into resolved_unit_cost
      from public.products product
      where product.id = resolved_product_id
        and product.organization_id = p_organization_id
        and product.is_active = true;

      if not found then
        raise exception 'REPAIR_PRODUCT_NOT_FOUND|%', resolved_product_id;
      end if;

      select coalesce(stock_quantity, 0)
        into available_stock
      from public.branch_inventory
      where branch_id = p_branch_id
        and product_id = resolved_product_id
      for update;

      if not found or available_stock < resolved_quantity then
        raise exception 'REPAIR_STOCK_CHANGED|%|%', resolved_product_id, coalesce(available_stock, 0);
      end if;

      update public.branch_inventory
      set stock_quantity = available_stock - resolved_quantity,
          updated_at = now()
      where branch_id = p_branch_id
        and product_id = resolved_product_id;

      insert into public.product_movements (
        product_id, movement_type, quantity, previous_stock, new_stock,
        unit_cost, total_cost, reference_id, reference_type, notes,
        user_id, branch_id, organization_id, created_at
      ) values (
        resolved_product_id, 'repair_use', resolved_quantity, available_stock,
        available_stock - resolved_quantity, resolved_unit_cost,
        resolved_unit_cost * resolved_quantity, p_repair_id, 'repair',
        'Consumo en reparacion', p_actor_id, p_branch_id,
        p_organization_id, now()
      );
    end if;

    insert into public.repair_parts (
      repair_id, product_id, part_name, part_number, quantity,
      unit_cost, unit_price, supplier, status
    ) values (
      p_repair_id,
      resolved_product_id,
      resolved_name,
      nullif(trim(coalesce(item->>'part_number', '')), ''),
      resolved_quantity,
      resolved_unit_cost,
      resolved_unit_price,
      nullif(trim(coalesce(item->>'supplier', '')), ''),
      'installed'
    );

    direct_cost_total := direct_cost_total + (resolved_unit_cost * resolved_quantity);
    charged_price_total := charged_price_total + (resolved_unit_price * resolved_quantity);
  end loop;

  update public.repairs
  set parts_cost = direct_cost_total,
      updated_at = now()
  where id = p_repair_id
    and organization_id = p_organization_id
    and branch_id = p_branch_id;

  return query select direct_cost_total, charged_price_total;
end;
$$;


ALTER FUNCTION "public"."replace_repair_parts_with_inventory"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_parts" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_repair_parts_with_inventory"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_parts" "jsonb", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_labor_cost" numeric DEFAULT NULL::numeric, "p_final_cost" numeric DEFAULT NULL::numeric, "p_estimated_cost" numeric DEFAULT NULL::numeric, "p_pricing_mode" "text" DEFAULT NULL::"text", "p_discount_amount" numeric DEFAULT NULL::numeric, "p_price_override_reason" "text" DEFAULT NULL::"text", "p_pricing_updated_by" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("parts_cost" numeric, "parts_price" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  operation jsonb;
  operation_key text;
begin
  operation_key := 'parts-replace-' || gen_random_uuid()::text;
  operation := public.save_repair_cost_revision(
    p_repair_id, p_organization_id, p_branch_id, coalesce(p_actor_id, p_pricing_updated_by),
    coalesce(p_labor_cost, 0), coalesce(p_parts, '[]'::jsonb), 0, 0,
    coalesce(p_discount_amount, 0), p_price_override_reason, operation_key
  );
  return query select
    coalesce((operation->'summary'->>'partsInternalCost')::numeric, 0),
    coalesce((operation->'summary'->>'servicesSubtotal')::numeric, 0)
      + coalesce((operation->'summary'->>'chargedPartsSubtotal')::numeric, 0);
end;
$$;


ALTER FUNCTION "public"."replace_repair_parts_with_inventory"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_parts" "jsonb", "p_actor_id" "uuid", "p_labor_cost" numeric, "p_final_cost" numeric, "p_estimated_cost" numeric, "p_pricing_mode" "text", "p_discount_amount" numeric, "p_price_override_reason" "text", "p_pricing_updated_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_middleware_access"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  -- El usuario SIEMPRE sale del token, nunca de un parametro: recibirlo por
  -- argumento permitiria a cualquier autenticado pedir el acceso de otro.
  uid uuid := auth.uid();
  platform_role text;
  platform_role_active boolean;
  profile_role text;
  profile_status text;
  organization_role text;
begin
  if uid is null then
    return null;
  end if;

  select ur.role, ur.is_active
  into platform_role, platform_role_active
  from public.user_roles ur
  where ur.user_id = uid
  limit 1;

  select p.role, p.status
  into profile_role, profile_status
  from public.profiles p
  where p.id = uid
  limit 1;

  -- La membresia solo importa cuando la plataforma no dio un rol operativo,
  -- que es exactamente cuando el middleware hacia la tercera consulta.
  if coalesce(platform_role, profile_role, 'cliente') = 'cliente' then
    select om.role
    into organization_role
    from public.organization_members om
    where om.user_id = uid
      and om.status = 'active'
      and om.role in ('owner', 'admin', 'manager', 'cashier', 'technician', 'seller')
      and (p_organization_id is null or om.organization_id = p_organization_id)
    order by om.created_at asc
    limit 1;
  end if;

  return jsonb_build_object(
    'platformRole', platform_role,
    'platformRoleActive', coalesce(platform_role_active, true),
    'profileRole', profile_role,
    'profileStatus', profile_status,
    'organizationRole', organization_role
  );
end;
$$;


ALTER FUNCTION "public"."resolve_middleware_access"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_plan_downgrade_grace"("p_organization_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  restored integer := 0;
begin
  -- Solo se reactiva lo que apago el ciclo: lo que el usuario desactivo a mano
  -- sigue como el lo dejo.
  update public.products
  set is_active = true,
      deactivated_by_plan = false,
      archived_by_plan_at = null,
      updated_at = now()
  where organization_id = p_organization_id
    and deactivated_by_plan = true;

  get diagnostics restored = row_count;

  update public.plan_downgrade_grace
  set stage = 'resolved',
      resolved_at = now(),
      updated_at = now()
  where organization_id = p_organization_id;

  return restored;
end;
$$;


ALTER FUNCTION "public"."resolve_plan_downgrade_grace"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_variant_stock_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_variant_id" "uuid", "p_quantity" integer, "p_movement_type" "text", "p_idempotency_key" "text", "p_actor_id" "uuid", "p_reference_type" "text" DEFAULT NULL::"text", "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_quantity <= 0 or p_movement_type not in ('sale_cancel', 'return', 'correction') then
    raise exception 'VARIANT_STOCK_INVALID_RESTORE';
  end if;

  return public.adjust_variant_stock_atomic(
    p_organization_id,
    p_branch_id,
    p_variant_id,
    p_quantity,
    p_movement_type,
    p_idempotency_key,
    p_actor_id,
    p_reference_type,
    p_reference_id,
    p_reason,
    p_metadata
  );
end;
$$;


ALTER FUNCTION "public"."restore_variant_stock_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_variant_id" "uuid", "p_quantity" integer, "p_movement_type" "text", "p_idempotency_key" "text", "p_actor_id" "uuid", "p_reference_type" "text", "p_reference_id" "uuid", "p_reason" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rotate_audit_logs"("days_to_keep" integer DEFAULT 90) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    deleted_count INT;
BEGIN
    -- Delete old logs in batches to avoid locking the table for too long
    -- This is a simple implementation. For massive tables, pg_partman is recommended.
    WITH deleted AS (
        DELETE FROM public.audit_log
        WHERE created_at < NOW() - (days_to_keep || ' days')::interval
        RETURNING 1
    )
    SELECT count(*) INTO deleted_count FROM deleted;

    -- Optional: Log the cleanup action itself (to the same log, recursively? Maybe just raise notice)
    RAISE NOTICE 'Rotated audit logs. Deleted % rows older than % days.', deleted_count, days_to_keep;
END;
$$;


ALTER FUNCTION "public"."rotate_audit_logs"("days_to_keep" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_subscription_lifecycle"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  trials_expired integer;
  periods_expired integer;
  accounts_downgraded integer;
begin
  select public.expire_trials() into trials_expired;
  select public.expire_paid_periods() into periods_expired;
  select public.downgrade_overdue_accounts() into accounts_downgraded;

  return jsonb_build_object(
    'trials_expired', trials_expired,
    'periods_expired', periods_expired,
    'accounts_downgraded', accounts_downgraded,
    'ran_at', now()
  );
end;
$$;


ALTER FUNCTION "public"."run_subscription_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_product_with_variants"("p_product" "jsonb", "p_variants" "jsonb", "p_branch_id" "uuid", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_variable
declare
  product_id uuid := coalesce(nullif(p_product->>'id', '')::uuid, gen_random_uuid());
  organization_id uuid := nullif(p_product->>'organization_id', '')::uuid;
  has_variants boolean := coalesce((p_product->>'has_variants')::boolean, false);
  variant_entry jsonb;
  saved_variant_id uuid;
  saved_variant_ids uuid[] := '{}'::uuid[];
  initial_stock integer;
  branch_organization_id uuid;
begin
  if organization_id is null or p_actor_id is null then
    raise exception 'VARIANT_PRODUCT_INVALID_INPUT';
  end if;

  if not exists (
    select 1
    from public.organization_members member
    where member.organization_id = organization_id
      and member.user_id = p_actor_id
      and member.status = 'active'
  ) then
    raise exception 'VARIANT_ACTOR_FORBIDDEN';
  end if;

  if jsonb_typeof(coalesce(p_variants, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_product->'variant_attribute_config', '[]'::jsonb)) <> 'array' then
    raise exception 'VARIANT_PRODUCT_INVALID_INPUT';
  end if;

  if has_variants and (p_branch_id is null or jsonb_array_length(p_variants) = 0) then
    raise exception 'VARIANT_PRODUCT_REQUIRES_VARIANTS';
  end if;

  if p_branch_id is not null then
    select branch.organization_id into branch_organization_id
    from public.branches branch
    where branch.id = p_branch_id;

    if branch_organization_id is distinct from organization_id then
      raise exception 'VARIANT_BRANCH_FORBIDDEN';
    end if;
  end if;

  insert into public.products (
    id,
    organization_id,
    name,
    sku,
    description,
    category_id,
    supplier_id,
    brand,
    brand_id,
    tags,
    purchase_price,
    sale_price,
    wholesale_price,
    stock_quantity,
    min_stock,
    max_stock,
    unit_measure,
    barcode,
    images,
    image_url,
    offer_price,
    has_offer,
    installments_enabled,
    installments_public,
    installments_plans,
    visibility,
    warranty_months,
    warranty_info,
    return_window_days,
    exchange_window_days,
    return_policy,
    exchange_policy,
    is_active,
    has_variants,
    variant_attribute_config
  ) values (
    product_id,
    organization_id,
    trim(p_product->>'name'),
    trim(p_product->>'sku'),
    nullif(trim(p_product->>'description'), ''),
    nullif(p_product->>'category_id', '')::uuid,
    nullif(p_product->>'supplier_id', '')::uuid,
    nullif(trim(p_product->>'brand'), ''),
    nullif(p_product->>'brand_id', '')::uuid,
    case
      when jsonb_typeof(p_product->'tags') = 'array'
        then array(select jsonb_array_elements_text(p_product->'tags'))
      else null
    end,
    coalesce((p_product->>'purchase_price')::numeric, 0),
    coalesce((p_product->>'sale_price')::numeric, 0),
    nullif(p_product->>'wholesale_price', '')::numeric,
    case when has_variants then 0 else coalesce((p_product->>'stock_quantity')::integer, 0) end,
    coalesce((p_product->>'min_stock')::integer, 0),
    coalesce((p_product->>'max_stock')::integer, 1000),
    coalesce(nullif(trim(p_product->>'unit_measure'), ''), 'unidad'),
    nullif(trim(p_product->>'barcode'), ''),
    case
      when jsonb_typeof(p_product->'images') = 'array'
        then array(select jsonb_array_elements_text(p_product->'images'))
      else null
    end,
    nullif(trim(p_product->>'image_url'), ''),
    nullif(p_product->>'offer_price', '')::numeric,
    coalesce((p_product->>'has_offer')::boolean, false),
    coalesce((p_product->>'installments_enabled')::boolean, false),
    coalesce((p_product->>'installments_public')::boolean, true),
    coalesce(p_product->'installments_plans', '[]'::jsonb),
    coalesce(nullif(trim(p_product->>'visibility'), ''), 'public'),
    nullif(p_product->>'warranty_months', '')::integer,
    nullif(trim(p_product->>'warranty_info'), ''),
    nullif(p_product->>'return_window_days', '')::integer,
    nullif(p_product->>'exchange_window_days', '')::integer,
    nullif(trim(p_product->>'return_policy'), ''),
    nullif(trim(p_product->>'exchange_policy'), ''),
    coalesce((p_product->>'is_active')::boolean, true),
    has_variants,
    coalesce(p_product->'variant_attribute_config', '[]'::jsonb)
  )
  on conflict (id) do update
  set
    name = excluded.name,
    sku = excluded.sku,
    description = excluded.description,
    category_id = excluded.category_id,
    supplier_id = excluded.supplier_id,
    brand = excluded.brand,
    brand_id = excluded.brand_id,
    tags = excluded.tags,
    purchase_price = excluded.purchase_price,
    sale_price = excluded.sale_price,
    wholesale_price = excluded.wholesale_price,
    min_stock = excluded.min_stock,
    max_stock = excluded.max_stock,
    unit_measure = excluded.unit_measure,
    barcode = excluded.barcode,
    images = excluded.images,
    image_url = excluded.image_url,
    offer_price = excluded.offer_price,
    has_offer = excluded.has_offer,
    installments_enabled = excluded.installments_enabled,
    installments_public = excluded.installments_public,
    installments_plans = excluded.installments_plans,
    visibility = excluded.visibility,
    warranty_months = excluded.warranty_months,
    warranty_info = excluded.warranty_info,
    return_window_days = excluded.return_window_days,
    exchange_window_days = excluded.exchange_window_days,
    return_policy = excluded.return_policy,
    exchange_policy = excluded.exchange_policy,
    is_active = excluded.is_active,
    has_variants = excluded.has_variants,
    variant_attribute_config = excluded.variant_attribute_config,
    updated_at = now()
  where products.organization_id = excluded.organization_id;

  if not found then
    raise exception 'VARIANT_PRODUCT_NOT_IN_ORGANIZATION';
  end if;

  delete from public.product_variant_attributes
  where product_variant_attributes.organization_id = organization_id
    and product_variant_attributes.product_id = product_id;

  insert into public.product_variant_attributes (
    organization_id,
    product_id,
    attribute_key,
    label,
    control,
    options,
    sort_order
  )
  select
    organization_id,
    product_id,
    trim(attribute.value->>'key'),
    trim(attribute.value->>'label'),
    attribute.value->>'control',
    coalesce(attribute.value->'options', '[]'::jsonb),
    attribute.ordinality - 1
  from jsonb_array_elements(coalesce(p_product->'variant_attribute_config', '[]'::jsonb))
    with ordinality as attribute(value, ordinality);

  if not has_variants then
    update public.product_variants
    set is_active = false,
        updated_at = now()
    where product_variants.organization_id = organization_id
      and product_variants.product_id = product_id;

    return jsonb_build_object('product_id', product_id, 'variant_ids', '[]'::jsonb);
  end if;

  for variant_entry in
    select value from jsonb_array_elements(p_variants)
  loop
    initial_stock := greatest(0, coalesce((variant_entry->>'stock_quantity')::integer, 0));
    saved_variant_id := coalesce(nullif(variant_entry->>'id', '')::uuid, gen_random_uuid());

    insert into public.product_variants (
      id,
      organization_id,
      product_id,
      variant_name,
      attributes,
      sku,
      barcode,
      purchase_price,
      sale_price,
      wholesale_price,
      min_stock,
      stock_quantity,
      price_adjustment,
      is_active
    ) values (
      saved_variant_id,
      organization_id,
      product_id,
      trim(variant_entry->>'name'),
      coalesce(variant_entry->'attributes', '{}'::jsonb),
      nullif(trim(variant_entry->>'sku'), ''),
      nullif(trim(variant_entry->>'barcode'), ''),
      coalesce((variant_entry->>'purchase_price')::numeric, 0),
      coalesce((variant_entry->>'sale_price')::numeric, 0),
      nullif(variant_entry->>'wholesale_price', '')::numeric,
      greatest(0, coalesce((variant_entry->>'min_stock')::integer, 0)),
      initial_stock,
      coalesce((variant_entry->>'sale_price')::numeric, 0)
        - coalesce((p_product->>'sale_price')::numeric, 0),
      coalesce((variant_entry->>'is_active')::boolean, true)
    )
    on conflict (id) do update
    set
      variant_name = excluded.variant_name,
      attributes = excluded.attributes,
      sku = excluded.sku,
      barcode = excluded.barcode,
      purchase_price = excluded.purchase_price,
      sale_price = excluded.sale_price,
      wholesale_price = excluded.wholesale_price,
      min_stock = excluded.min_stock,
      price_adjustment = excluded.price_adjustment,
      is_active = excluded.is_active,
      updated_at = now()
    where product_variants.organization_id = excluded.organization_id
      and product_variants.product_id = excluded.product_id;

    if not found then
      raise exception 'VARIANT_PRODUCT_MISMATCH';
    end if;

    saved_variant_ids := array_append(saved_variant_ids, saved_variant_id);

    insert into public.branch_variant_inventory (
      organization_id,
      branch_id,
      product_id,
      variant_id,
      stock_quantity,
      min_stock
    ) values (
      organization_id,
      p_branch_id,
      product_id,
      saved_variant_id,
      initial_stock,
      greatest(0, coalesce((variant_entry->>'min_stock')::integer, 0))
    )
    on conflict (branch_id, variant_id) do nothing;

    if found and initial_stock > 0 then
      insert into public.variant_inventory_movements (
        organization_id,
        branch_id,
        product_id,
        variant_id,
        movement_type,
        quantity_delta,
        stock_before,
        stock_after,
        idempotency_key,
        reason,
        actor_id,
        metadata
      ) values (
        organization_id,
        p_branch_id,
        product_id,
        saved_variant_id,
        'initial',
        initial_stock,
        0,
        initial_stock,
        'variant-initial:' || p_branch_id::text || ':' || saved_variant_id::text,
        'Stock inicial de la variante',
        p_actor_id,
        '{}'::jsonb
      ) on conflict (organization_id, idempotency_key) do nothing;
    end if;

    update public.branch_variant_inventory
    set min_stock = greatest(0, coalesce((variant_entry->>'min_stock')::integer, 0)),
        updated_at = now()
    where branch_variant_inventory.organization_id = organization_id
      and branch_variant_inventory.branch_id = p_branch_id
      and branch_variant_inventory.variant_id = saved_variant_id;
  end loop;

  update public.product_variants
  set is_active = false,
      updated_at = now()
  where product_variants.organization_id = organization_id
    and product_variants.product_id = product_id
    and not (product_variants.id = any(saved_variant_ids));

  return jsonb_build_object(
    'product_id', product_id,
    'variant_ids', to_jsonb(saved_variant_ids)
  );
exception
  when unique_violation then
    if sqlerrm ilike '%barcode%' then
      raise exception 'VARIANT_BARCODE_DUPLICATE';
    end if;
    raise exception 'VARIANT_SKU_DUPLICATE';
end;
$$;


ALTER FUNCTION "public"."save_product_with_variants"("p_product" "jsonb", "p_variants" "jsonb", "p_branch_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_repair_cost_revision"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_labor_amount" numeric, "p_parts" "jsonb", "p_additional_charges" numeric, "p_deductions" numeric, "p_discount_amount" numeric, "p_override_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  target_repair public.repairs%rowtype;
  existing_revision public.repair_cost_revisions%rowtype;
  membership_role text;
  is_admin boolean := false;
  customer_is_wholesale boolean := false;
  max_discount_percent numeric := 20;
  labor_tax_rate numeric := 10;
  normalized_labor numeric := round(coalesce(p_labor_amount, 0), 2);
  normalized_charges numeric := round(coalesce(p_additional_charges, 0), 2);
  normalized_deductions numeric := round(coalesce(p_deductions, 0), 2);
  normalized_discount numeric := round(coalesce(p_discount_amount, 0), 2);
  normalized_reason text := nullif(trim(coalesce(p_override_reason, '')), '');
  normalized_parts jsonb := coalesce(p_parts, '[]'::jsonb);
  request_hash text;
  item jsonb;
  old_item record;
  resolved_parts jsonb := '[]'::jsonb;
  resolved_line_type text;
  resolved_product_id uuid;
  resolved_name text;
  resolved_part_number text;
  resolved_supplier text;
  resolved_quantity integer;
  resolved_unit_price numeric;
  resolved_unit_cost numeric;
  resolved_part_discount numeric;
  resolved_tax_rate numeric;
  resolved_subtotal numeric;
  product_unit_measure text;
  product_sale_price numeric;
  product_wholesale_price numeric;
  previous_stock integer;
  available_stock integer;
  services_subtotal numeric := 0;
  charged_parts_subtotal numeric := 0;
  included_materials_internal_cost numeric := 0;
  parts_internal_cost numeric := 0;
  subtotal_before_discount numeric := 0;
  final_total numeric := 0;
  paid_snapshot numeric := 0;
  balance_snapshot numeric := 0;
  discount_percent numeric := 0;
  tax_gross_0 numeric := 0;
  tax_gross_5 numeric := 0;
  tax_gross_10 numeric := 0;
  allocation_factor numeric := 0;
  tax_breakdown jsonb := '[]'::jsonb;
  policy_snapshot jsonb;
  previous_snapshot jsonb;
  new_revision_id uuid;
  new_revision_number integer;
  result_payload jsonb;
begin
  if jsonb_typeof(normalized_parts) <> 'array' or jsonb_array_length(normalized_parts) > 100 then
    raise exception 'INVALID_REPAIR_PARTS';
  end if;
  if normalized_labor < 0 or normalized_charges < 0 or normalized_deductions < 0
     or normalized_discount < 0 or trim(coalesce(p_idempotency_key, '')) = '' then
    raise exception 'INVALID_REPAIR_COST_INPUT';
  end if;

  request_hash := md5(jsonb_build_object(
    'repair_id', p_repair_id, 'labor', normalized_labor, 'parts', normalized_parts,
    'charges', normalized_charges, 'deductions', normalized_deductions,
    'discount', normalized_discount, 'reason', normalized_reason
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':' || p_idempotency_key, 0));

  select * into existing_revision
  from public.repair_cost_revisions revision
  where revision.organization_id = p_organization_id
    and revision.idempotency_key = p_idempotency_key;
  if found then
    if existing_revision.intent_hash is distinct from request_hash then
      raise exception 'REPAIR_COST_IDEMPOTENCY_CONFLICT';
    end if;
    return existing_revision.result_snapshot;
  end if;

  select * into target_repair
  from public.repairs repair
  where repair.id = p_repair_id
    and repair.organization_id = p_organization_id
    and repair.branch_id = p_branch_id
  for update;
  if not found then raise exception 'REPAIR_NOT_FOUND'; end if;
  if target_repair.status in ('entregado', 'cancelado') then raise exception 'REPAIR_COST_NOT_EDITABLE'; end if;

  select membership.role::text into membership_role
  from public.organization_members membership
  where membership.organization_id = p_organization_id
    and membership.user_id = p_actor_id
    and membership.status = 'active';
  if membership_role is null then raise exception 'REPAIR_COST_FORBIDDEN'; end if;
  is_admin := membership_role in ('owner', 'admin', 'super_admin');

  select lower(coalesce(customer.customer_type, '')) in ('wholesale', 'mayorista')
  into customer_is_wholesale
  from public.customers customer
  where customer.id = target_repair.customer_id
    and customer.organization_id = p_organization_id;
  customer_is_wholesale := coalesce(customer_is_wholesale, false);

  select coalesce(settings.repair_max_discount_percent, 20),
         coalesce(settings.repair_labor_tax_rate, 10)
  into max_discount_percent, labor_tax_rate
  from public.organization_settings settings
  where settings.organization_id = p_organization_id;
  max_discount_percent := coalesce(max_discount_percent, 20);
  labor_tax_rate := coalesce(labor_tax_rate, 10);

  perform 1
  from public.branch_inventory inventory
  where inventory.branch_id = p_branch_id
    and inventory.product_id in (
      select part.product_id from public.repair_parts part
      where part.repair_id = p_repair_id and part.product_id is not null and part.line_type <> 'service'
      union
      select (value->>'product_id')::uuid
      from jsonb_array_elements(normalized_parts)
      where nullif(value->>'product_id', '') is not null
        and coalesce(value->>'line_type', 'charged_part') <> 'service'
    )
  order by inventory.product_id
  for update;

  for old_item in
    select product_id, sum(quantity)::integer quantity
    from public.repair_parts
    where repair_id = p_repair_id and product_id is not null and line_type <> 'service'
    group by product_id order by product_id
  loop
    select inventory.stock_quantity into previous_stock
    from public.branch_inventory inventory
    where inventory.branch_id = p_branch_id and inventory.product_id = old_item.product_id
    for update;
    if not found then raise exception 'REPAIR_INVENTORY_ROW_MISSING|%', old_item.product_id; end if;
    update public.branch_inventory
    set stock_quantity = previous_stock + old_item.quantity, updated_at = now()
    where branch_id = p_branch_id and product_id = old_item.product_id;
    insert into public.product_movements (
      product_id, movement_type, quantity, previous_stock, new_stock,
      reference_id, reference_type, notes, user_id, branch_id, organization_id, created_at
    ) values (
      old_item.product_id, 'return', old_item.quantity, previous_stock,
      previous_stock + old_item.quantity, p_repair_id, 'repair',
      'Reposicion automatica al editar costos de reparacion', p_actor_id,
      p_branch_id, p_organization_id, now()
    );
  end loop;

  for item in select value from jsonb_array_elements(normalized_parts)
  loop
    resolved_line_type := coalesce(nullif(item->>'line_type', ''), 'charged_part');
    if resolved_line_type not in ('service', 'included_material', 'charged_part') then
      raise exception 'INVALID_REPAIR_LINE_TYPE';
    end if;
    resolved_product_id := nullif(item->>'product_id', '')::uuid;
    resolved_name := trim(coalesce(item->>'part_name', ''));
    resolved_part_number := nullif(trim(coalesce(item->>'part_number', '')), '');
    resolved_supplier := nullif(trim(coalesce(item->>'supplier', '')), '');
    resolved_quantity := coalesce((item->>'quantity')::integer, 0);
    resolved_unit_price := round(coalesce((item->>'unit_price')::numeric, 0), 2);
    resolved_unit_cost := round(coalesce(nullif(item->>'unit_cost', '')::numeric, 0), 2);
    resolved_part_discount := round(coalesce((item->>'discount_amount')::numeric, 0), 2);
    resolved_tax_rate := coalesce(nullif(item->>'tax_rate', '')::numeric, labor_tax_rate);
    if resolved_name = '' or resolved_quantity <= 0 or resolved_unit_price < 0 or resolved_unit_cost < 0
       or resolved_part_discount < 0 or resolved_part_discount > resolved_unit_price * resolved_quantity
       or resolved_tax_rate not in (0, 5, 10) then raise exception 'INVALID_REPAIR_PART'; end if;

    if resolved_product_id is not null then
      select round(coalesce(product.purchase_price, 0), 2),
             round(coalesce(product.sale_price, 0), 2),
             round(coalesce(product.wholesale_price, 0), 2),
             coalesce(product.tax_rate, labor_tax_rate),
             lower(trim(coalesce(product.unit_measure, ''))), product.name, product.sku
      into resolved_unit_cost, product_sale_price, product_wholesale_price,
           resolved_tax_rate, product_unit_measure, resolved_name, resolved_part_number
      from public.products product
      where product.id = resolved_product_id
        and product.organization_id = p_organization_id and product.is_active = true
      for update;
      if not found then raise exception 'REPAIR_PRODUCT_NOT_FOUND|%', resolved_product_id; end if;

      if product_unit_measure = 'servicio' then
        resolved_line_type := 'service';
        resolved_unit_cost := 0;
        resolved_unit_price := case when customer_is_wholesale and product_wholesale_price > 0
          then product_wholesale_price else product_sale_price end;
      elsif resolved_line_type = 'service' then
        raise exception 'REPAIR_LINE_TYPE_MISMATCH';
      elsif resolved_line_type = 'included_material' then
        resolved_unit_price := 0;
        resolved_part_discount := 0;
      else
        resolved_line_type := 'charged_part';
        resolved_unit_price := case when customer_is_wholesale and product_wholesale_price > 0
          then product_wholesale_price else product_sale_price end;
      end if;
    elsif resolved_line_type = 'included_material' then
      resolved_unit_price := 0;
      resolved_part_discount := 0;
    end if;

    resolved_subtotal := round(resolved_unit_price * resolved_quantity - resolved_part_discount, 2);
    if resolved_line_type = 'charged_part' and resolved_subtotal / resolved_quantity < resolved_unit_cost then
      if not is_admin then raise exception 'REPAIR_PART_BELOW_COST'; end if;
      if normalized_reason is null or length(normalized_reason) < 5 then raise exception 'REPAIR_OVERRIDE_REASON_REQUIRED'; end if;
    end if;

    if resolved_line_type = 'service' then
      services_subtotal := services_subtotal + resolved_subtotal;
    elsif resolved_line_type = 'included_material' then
      included_materials_internal_cost := included_materials_internal_cost + resolved_unit_cost * resolved_quantity;
      parts_internal_cost := parts_internal_cost + resolved_unit_cost * resolved_quantity;
    else
      charged_parts_subtotal := charged_parts_subtotal + resolved_subtotal;
      parts_internal_cost := parts_internal_cost + resolved_unit_cost * resolved_quantity;
    end if;

    resolved_parts := resolved_parts || jsonb_build_array(jsonb_build_object(
      'line_type', resolved_line_type, 'product_id', resolved_product_id,
      'part_name', resolved_name, 'part_number', resolved_part_number,
      'supplier', resolved_supplier, 'quantity', resolved_quantity,
      'unit_price', resolved_unit_price, 'unit_cost', resolved_unit_cost,
      'discount_amount', resolved_part_discount, 'tax_rate', resolved_tax_rate,
      'subtotal', resolved_subtotal
    ));
  end loop;

  subtotal_before_discount := round(normalized_labor + services_subtotal + charged_parts_subtotal + normalized_charges, 2);
  if normalized_discount + normalized_deductions > subtotal_before_discount then raise exception 'REPAIR_DISCOUNT_EXCEEDS_SUBTOTAL'; end if;
  discount_percent := case when subtotal_before_discount = 0 then 0 else normalized_discount * 100 / subtotal_before_discount end;
  if discount_percent > max_discount_percent then
    if not is_admin then raise exception 'REPAIR_DISCOUNT_LIMIT_EXCEEDED'; end if;
    if normalized_reason is null or length(normalized_reason) < 5 then raise exception 'REPAIR_OVERRIDE_REASON_REQUIRED'; end if;
  end if;
  final_total := round(greatest(0, subtotal_before_discount - normalized_discount - normalized_deductions), 2);
  paid_snapshot := round(greatest(coalesce(target_repair.paid_amount, 0), 0), 2);
  if final_total < paid_snapshot then raise exception 'REPAIR_FINAL_BELOW_PAID_AMOUNT'; end if;
  balance_snapshot := round(greatest(final_total - paid_snapshot, 0), 2);
  allocation_factor := case when subtotal_before_discount = 0 then 0 else final_total / subtotal_before_discount end;

  if labor_tax_rate = 0 then tax_gross_0 := normalized_labor + normalized_charges;
  elsif labor_tax_rate = 5 then tax_gross_5 := normalized_labor + normalized_charges;
  else tax_gross_10 := normalized_labor + normalized_charges; end if;
  for item in select value from jsonb_array_elements(resolved_parts)
  loop
    if (item->>'subtotal')::numeric <= 0 then continue; end if;
    if (item->>'tax_rate')::numeric = 0 then tax_gross_0 := tax_gross_0 + (item->>'subtotal')::numeric;
    elsif (item->>'tax_rate')::numeric = 5 then tax_gross_5 := tax_gross_5 + (item->>'subtotal')::numeric;
    else tax_gross_10 := tax_gross_10 + (item->>'subtotal')::numeric; end if;
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object(
    'rate', rate, 'grossAmount', gross_amount,
    'taxableBase', round(gross_amount / (1 + rate / 100), 2),
    'taxAmount', round(gross_amount - gross_amount / (1 + rate / 100), 2)
  ) order by rate), '[]'::jsonb)
  into tax_breakdown
  from (values
    (0::numeric, round(tax_gross_0 * allocation_factor, 2)),
    (5::numeric, round(tax_gross_5 * allocation_factor, 2)),
    (10::numeric, round(tax_gross_10 * allocation_factor, 2))
  ) buckets(rate, gross_amount)
  where gross_amount > 0;

  select coalesce(max(revision.revision_number), 0) + 1 into new_revision_number
  from public.repair_cost_revisions revision where revision.repair_id = p_repair_id;
  select jsonb_build_object(
    'laborAmount', revision.labor_amount, 'servicesSubtotal', revision.services_subtotal,
    'chargedPartsSubtotal', revision.charged_parts_subtotal,
    'includedMaterialsInternalCost', revision.included_materials_internal_cost,
    'partsSubtotal', revision.parts_subtotal, 'finalTotal', revision.final_total
  ) into previous_snapshot
  from public.repair_cost_revisions revision where revision.id = target_repair.current_cost_revision_id;
  policy_snapshot := jsonb_build_object(
    'maxDiscountPercent', max_discount_percent, 'laborTaxRate', labor_tax_rate,
    'customerIsWholesale', customer_is_wholesale,
    'administratorOverride', is_admin and normalized_reason is not null
  );

  new_revision_id := gen_random_uuid();
  result_payload := jsonb_build_object(
    'revisionId', new_revision_id, 'revisionNumber', new_revision_number,
    'summary', jsonb_build_object(
      'laborAmount', normalized_labor, 'servicesSubtotal', round(services_subtotal, 2),
      'chargedPartsSubtotal', round(charged_parts_subtotal, 2),
      'includedMaterialsInternalCost', round(included_materials_internal_cost, 2),
      'partsSubtotal', round(services_subtotal + charged_parts_subtotal, 2),
      'partsInternalCost', round(parts_internal_cost, 2),
      'additionalCharges', normalized_charges, 'deductions', normalized_deductions,
      'discountAmount', normalized_discount, 'subtotalBeforeDiscount', subtotal_before_discount,
      'finalTotal', final_total, 'paidAmount', paid_snapshot, 'balance', balance_snapshot,
      'taxBreakdown', tax_breakdown
    ), 'parts', resolved_parts
  );

  insert into public.repair_cost_revisions (
    id, organization_id, branch_id, repair_id, revision_number, actor_id, actor_role,
    reason, labor_amount, labor_tax_rate, services_subtotal, charged_parts_subtotal,
    included_materials_internal_cost, parts_subtotal, parts_internal_cost,
    additional_charges, deductions, discount_amount, subtotal_before_discount,
    final_total, paid_amount_snapshot, balance_snapshot, tax_breakdown,
    policy_snapshot, previous_snapshot, intent_hash, idempotency_key, result_snapshot
  ) values (
    new_revision_id, p_organization_id, p_branch_id, p_repair_id, new_revision_number,
    p_actor_id, membership_role, normalized_reason, normalized_labor, labor_tax_rate,
    round(services_subtotal, 2), round(charged_parts_subtotal, 2),
    round(included_materials_internal_cost, 2), round(services_subtotal + charged_parts_subtotal, 2),
    round(parts_internal_cost, 2), normalized_charges, normalized_deductions,
    normalized_discount, subtotal_before_discount, final_total, paid_snapshot,
    balance_snapshot, tax_breakdown, policy_snapshot, previous_snapshot,
    request_hash, p_idempotency_key, result_payload
  );

  delete from public.repair_parts where repair_id = p_repair_id;
  for item in select value from jsonb_array_elements(resolved_parts)
  loop
    resolved_line_type := item->>'line_type';
    resolved_product_id := nullif(item->>'product_id', '')::uuid;
    resolved_quantity := (item->>'quantity')::integer;
    resolved_unit_cost := (item->>'unit_cost')::numeric;
    if resolved_product_id is not null and resolved_line_type <> 'service' then
      select inventory.stock_quantity into available_stock
      from public.branch_inventory inventory
      where inventory.branch_id = p_branch_id and inventory.product_id = resolved_product_id
      for update;
      if not found or available_stock < resolved_quantity then
        raise exception 'REPAIR_STOCK_CHANGED|%|%', resolved_product_id, coalesce(available_stock, 0);
      end if;
      update public.branch_inventory set stock_quantity = available_stock - resolved_quantity, updated_at = now()
      where branch_id = p_branch_id and product_id = resolved_product_id;
      insert into public.product_movements (
        product_id, movement_type, quantity, previous_stock, new_stock, unit_cost,
        total_cost, reference_id, reference_type, notes, user_id, branch_id,
        organization_id, created_at
      ) values (
        resolved_product_id, 'repair_use', resolved_quantity, available_stock,
        available_stock - resolved_quantity, resolved_unit_cost,
        resolved_unit_cost * resolved_quantity, p_repair_id, 'repair',
        'Consumo al confirmar revision de costos', p_actor_id, p_branch_id,
        p_organization_id, now()
      );
    end if;
    insert into public.repair_parts (
      repair_id, product_id, part_name, part_number, quantity, unit_cost,
      unit_price, discount_amount, tax_rate, supplier, status, line_type
    ) values (
      p_repair_id, resolved_product_id, item->>'part_name', nullif(item->>'part_number', ''),
      resolved_quantity, resolved_unit_cost, (item->>'unit_price')::numeric,
      (item->>'discount_amount')::numeric, (item->>'tax_rate')::numeric,
      nullif(item->>'supplier', ''), 'installed', resolved_line_type
    );
    insert into public.repair_cost_revision_parts (
      revision_id, organization_id, branch_id, repair_id, product_id, part_name,
      part_number, supplier, quantity, unit_cost_snapshot, unit_price_snapshot,
      discount_amount, tax_rate, subtotal, line_type_snapshot
    ) values (
      new_revision_id, p_organization_id, p_branch_id, p_repair_id,
      resolved_product_id, item->>'part_name', nullif(item->>'part_number', ''),
      nullif(item->>'supplier', ''), resolved_quantity, resolved_unit_cost,
      (item->>'unit_price')::numeric, (item->>'discount_amount')::numeric,
      (item->>'tax_rate')::numeric, (item->>'subtotal')::numeric, resolved_line_type
    );
  end loop;

  update public.repairs set
    labor_cost = normalized_labor, parts_cost = round(parts_internal_cost, 2),
    additional_charges = normalized_charges, deductions = normalized_deductions,
    discount_amount = normalized_discount, final_cost = final_total,
    estimated_cost = final_total, pricing_mode = 'automatic',
    price_override_reason = normalized_reason, pricing_updated_by = p_actor_id,
    pricing_updated_at = now(), current_cost_revision_id = new_revision_id, updated_at = now()
  where id = p_repair_id and organization_id = p_organization_id and branch_id = p_branch_id;

  return result_payload;
end;
$$;


ALTER FUNCTION "public"."save_repair_cost_revision"("p_repair_id" "uuid", "p_organization_id" "uuid", "p_branch_id" "uuid", "p_actor_id" "uuid", "p_labor_amount" numeric, "p_parts" "jsonb", "p_additional_charges" numeric, "p_deductions" numeric, "p_discount_amount" numeric, "p_override_reason" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_customers"("search_term" "text") RETURNS TABLE("id" "uuid", "customer_code" "text", "name" "text", "email" "text", "phone" "text", "similarity" real)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        c.id,
        c.customer_code,
        c.name,
        c.email,
        c.phone,
        GREATEST(
            similarity(c.name, search_term),
            similarity(c.email, search_term),
            similarity(COALESCE(c.phone, ''), search_term),
            similarity(COALESCE(c.customer_code, ''), search_term)
        ) as similarity
    FROM public.customers c
    WHERE
        c.name ILIKE '%' || search_term || '%' OR
        c.email ILIKE '%' || search_term || '%' OR
        c.phone ILIKE '%' || search_term || '%' OR
        c.customer_code ILIKE '%' || search_term || '%'
    ORDER BY similarity DESC
    LIMIT 10;
END;
$$;


ALTER FUNCTION "public"."search_customers"("search_term" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_products"("search_term" "text" DEFAULT ''::"text", "category_filter" "uuid" DEFAULT NULL::"uuid", "supplier_filter" "uuid" DEFAULT NULL::"uuid", "status_filter" character varying DEFAULT NULL::character varying, "stock_filter" character varying DEFAULT NULL::character varying, "limit_count" integer DEFAULT 50, "offset_count" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "sku" character varying, "name" character varying, "description" "text", "category_name" character varying, "category_color" character varying, "brand" character varying, "supplier_name" character varying, "purchase_price" numeric, "sale_price" numeric, "wholesale_price" numeric, "stock" integer, "min_stock" integer, "status" character varying, "stock_status" character varying, "profit_margin" numeric, "total_value" numeric, "active_alerts" integer, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        p.id,
        p.sku,
        p.name,
        p.description,
        c.name as category_name,
        NULL::text as category_color,
        p.brand,
        s.name as supplier_name,
        p.purchase_price,
        p.sale_price,
        p.wholesale_price,
        p.stock_quantity,
        p.min_stock,
        CASE WHEN p.is_active THEN 'active' ELSE 'inactive' END as status,
        CASE
            WHEN p.stock_quantity = 0 THEN 'out_of_stock'
            WHEN p.stock_quantity <= p.min_stock THEN 'low_stock'
            ELSE 'normal'
        END as stock_status,
        CASE
            WHEN p.purchase_price > 0 THEN
                ROUND(((p.sale_price - p.purchase_price) / p.purchase_price * 100)::numeric, 2)
            ELSE 0
        END as profit_margin,
        (p.stock_quantity * p.purchase_price) as total_value,
        (SELECT COUNT(*)::INTEGER FROM product_alerts pa WHERE pa.product_id = p.id AND pa.is_resolved = false) as active_alerts,
        p.created_at
    FROM products p
    LEFT JOIN categories c ON p.category_id = c.id
    LEFT JOIN suppliers s ON p.supplier_id = s.id
    WHERE
        (search_term = '' OR
         p.name ILIKE '%' || search_term || '%' OR
         p.sku ILIKE '%' || search_term || '%' OR
         p.brand ILIKE '%' || search_term || '%' OR
         p.description ILIKE '%' || search_term || '%')
        AND (category_filter IS NULL OR p.category_id = category_filter)
        AND (supplier_filter IS NULL OR p.supplier_id = supplier_filter)
        AND (status_filter IS NULL OR (status_filter = 'active' AND p.is_active = true) OR (status_filter = 'inactive' AND p.is_active = false))
        AND (stock_filter IS NULL OR
             (stock_filter = 'low' AND p.stock_quantity <= p.min_stock) OR
             (stock_filter = 'out' AND p.stock_quantity = 0) OR
             (stock_filter = 'normal' AND p.stock_quantity > p.min_stock))
    ORDER BY
        CASE WHEN p.stock_quantity = 0 THEN 0 ELSE 1 END,
        CASE WHEN p.stock_quantity <= p.min_stock THEN 0 ELSE 1 END,
        p.name
    LIMIT limit_count
    OFFSET offset_count;
END;
$$;


ALTER FUNCTION "public"."search_products"("search_term" "text", "category_filter" "uuid", "supplier_filter" "uuid", "status_filter" character varying, "stock_filter" character varying, "limit_count" integer, "offset_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_users"("p_search_term" "text" DEFAULT NULL::"text", "p_role" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_department" "text" DEFAULT NULL::"text", "p_date_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_date_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 10, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "full_name" "text", "email" "text", "role" "text", "status" "text", "department" "text", "phone" "text", "avatar_url" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH filtered_users AS (
    SELECT
      p.id,
      p.full_name,
      p.email,
      p.role,
      p.status,
      p.department,
      p.phone,
      p.avatar_url,
      p.created_at,
      p.updated_at
    FROM profiles p
    WHERE
      (p_search_term IS NULL OR (
        p.full_name ILIKE '%' || p_search_term || '%' OR
        p.email ILIKE '%' || p_search_term || '%' OR
        p.phone ILIKE '%' || p_search_term || '%' OR
        p.department ILIKE '%' || p_search_term || '%'
      ))
      AND (p_role IS NULL OR p.role = p_role)
      AND (p_status IS NULL OR p.status = p_status)
      AND (p_department IS NULL OR p.department = p_department)
      AND (p_date_from IS NULL OR p.created_at >= p_date_from)
      AND (p_date_to IS NULL OR p.created_at <= p_date_to)
    ORDER BY p.created_at DESC
    LIMIT p_limit
    OFFSET p_offset
  ),
  total AS (
    SELECT COUNT(*) as cnt
    FROM profiles p
    WHERE
      (p_search_term IS NULL OR (
        p.full_name ILIKE '%' || p_search_term || '%' OR
        p.email ILIKE '%' || p_search_term || '%' OR
        p.phone ILIKE '%' || p_search_term || '%' OR
        p.department ILIKE '%' || p_search_term || '%'
      ))
      AND (p_role IS NULL OR p.role = p_role)
      AND (p_status IS NULL OR p.status = p_status)
      AND (p_department IS NULL OR p.department = p_department)
      AND (p_date_from IS NULL OR p.created_at >= p_date_from)
      AND (p_date_to IS NULL OR p.created_at <= p_date_to)
  )
  SELECT
    fu.*,
    t.cnt as total_count
  FROM filtered_users fu
  CROSS JOIN total t;
END;
$$;


ALTER FUNCTION "public"."search_users"("p_search_term" "text", "p_role" "text", "p_status" "text", "p_department" "text", "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_users"("p_search_term" "text", "p_role" "text", "p_status" "text", "p_department" "text", "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_limit" integer, "p_offset" integer) IS 'Búsqueda avanzada de usuarios con filtros múltiples y paginación optimizada';



CREATE OR REPLACE FUNCTION "public"."search_users"("p_search_term" "text" DEFAULT NULL::"text", "p_role" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_department" "text" DEFAULT NULL::"text", "p_date_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_date_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 10, "p_offset" integer DEFAULT 0, "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "full_name" "text", "email" "text", "role" "text", "status" "text", "department" "text", "phone" "text", "avatar_url" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
BEGIN
  IF public.get_jwt_role() <> 'super_admin' THEN
    v_org_id := COALESCE(p_organization_id, public.get_current_user_org_id());
  ELSE
    v_org_id := p_organization_id;
  END IF;

  RETURN QUERY
  WITH org_user_ids AS (
    SELECT user_id FROM organization_members
    WHERE v_org_id IS NULL OR organization_id = v_org_id
  ),
  base AS (
    SELECT p.id, p.full_name, p.email, p.role, p.status,
           p.department, p.phone, p.avatar_url, p.created_at, p.updated_at
    FROM profiles p
    WHERE p.id IN (SELECT user_id FROM org_user_ids)
      AND (p_search_term IS NULL OR (
            p.full_name ILIKE '%' || p_search_term || '%'
         OR p.email     ILIKE '%' || p_search_term || '%'
         OR p.phone     ILIKE '%' || p_search_term || '%'
      ))
      AND (p_role       IS NULL OR p.role       = p_role)
      AND (p_status     IS NULL OR p.status     = p_status)
      AND (p_department IS NULL OR p.department = p_department)
      AND (p_date_from  IS NULL OR p.created_at >= p_date_from)
      AND (p_date_to    IS NULL OR p.created_at <= p_date_to)
  ),
  paged AS (SELECT * FROM base ORDER BY created_at DESC LIMIT p_limit OFFSET p_offset),
  total AS (SELECT COUNT(*) AS cnt FROM base)
  SELECT paged.*, total.cnt FROM paged CROSS JOIN total;
END;
$$;


ALTER FUNCTION "public"."search_users"("p_search_term" "text", "p_role" "text", "p_status" "text", "p_department" "text", "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_limit" integer, "p_offset" integer, "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_default_branch_inventory_for_new_product"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_default_branch_id UUID;
BEGIN
  SELECT b.id
  INTO v_default_branch_id
  FROM public.branches b
  WHERE b.organization_id = NEW.organization_id
    AND b.is_active = TRUE
  ORDER BY b.is_default DESC, b.created_at ASC
  LIMIT 1;

  IF v_default_branch_id IS NOT NULL THEN
    INSERT INTO public.branch_inventory (branch_id, product_id, stock_quantity)
    VALUES (v_default_branch_id, NEW.id, COALESCE(NEW.stock_quantity, 0))
    ON CONFLICT (branch_id, product_id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


