CREATE OR REPLACE FUNCTION "public"."set_super_admin_role"("p_target_user_id" "uuid", "p_email" "text", "p_grant" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_active_super_admins integer;
begin
  perform pg_advisory_xact_lock(hashtext('super_admin_role_changes'));

  if not exists (select 1 from auth.users where id = p_target_user_id) then
    raise exception 'USER_NOT_FOUND';
  end if;

  if p_grant then
    insert into public.user_roles (user_id, role, is_active, updated_at)
    values (p_target_user_id, 'super_admin', true, now())
    on conflict (user_id) do update
      set role = excluded.role,
          is_active = true,
          updated_at = now();

    insert into public.profiles (id, email, role, status)
    values (p_target_user_id, nullif(lower(trim(p_email)), ''), 'super_admin', 'active')
    on conflict (id) do update
      set email = coalesce(excluded.email, public.profiles.email),
          role = 'super_admin',
          status = 'active';

    update auth.users
       set raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb)
         || jsonb_build_object('role', 'super_admin')
     where id = p_target_user_id;
    return;
  end if;

  select count(*)
    into v_active_super_admins
    from public.user_roles
   where role = 'super_admin'
     and is_active = true;

  if v_active_super_admins <= 1 then
    raise exception 'LAST_SUPER_ADMIN';
  end if;

  update public.user_roles
     set role = 'admin',
         is_active = true,
         updated_at = now()
   where user_id = p_target_user_id
     and role = 'super_admin';

  if not found then
    raise exception 'SUPER_ADMIN_NOT_FOUND';
  end if;

  update public.profiles
     set role = 'admin'
   where id = p_target_user_id;

  update auth.users
     set raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb)
       || jsonb_build_object('role', 'admin')
   where id = p_target_user_id;
end;
$$;


ALTER FUNCTION "public"."set_super_admin_role"("p_target_user_id" "uuid", "p_email" "text", "p_grant" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_verified_organization_review"("p_organization_id" "uuid", "p_token_hash" "text", "p_reviewer_name" "text", "p_reviewer_email" "text", "p_rating" integer, "p_comment" "text") RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  invite public.organization_review_invites%ROWTYPE;
BEGIN
  SELECT * INTO invite
  FROM public.organization_review_invites
  WHERE organization_id = p_organization_id
    AND token_hash = p_token_hash
    AND used_at IS NULL
    AND expires_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invalid_review_invite';
  END IF;

  RETURN QUERY
  INSERT INTO public.organization_reviews (
    organization_id,
    reviewer_name,
    reviewer_email,
    rating,
    comment,
    moderation_status,
    verification_type,
    sale_id,
    repair_id,
    customer_id
  ) VALUES (
    p_organization_id,
    p_reviewer_name,
    p_reviewer_email,
    p_rating,
    p_comment,
    'pending',
    invite.verification_type,
    invite.sale_id,
    invite.repair_id,
    invite.customer_id
  )
  RETURNING organization_reviews.id, organization_reviews.created_at;

  UPDATE public.organization_review_invites
  SET used_at = now()
  WHERE organization_review_invites.id = invite.id;
END;
$$;


ALTER FUNCTION "public"."submit_verified_organization_review"("p_organization_id" "uuid", "p_token_hash" "text", "p_reviewer_name" "text", "p_reviewer_email" "text", "p_rating" integer, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suggest_global_category"("p_name" "text", "p_limit" integer DEFAULT 5, "p_threshold" double precision DEFAULT 0.2) RETURNS TABLE("id" "uuid", "name" "text", "slug" "text", "level" integer, "parent_name" "text", "similarity" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    gc.id,
    gc.name,
    gc.slug,
    gc.level,
    parent.name AS parent_name,
    GREATEST(
      similarity(lower(p_name), lower(gc.name)),
      -- También compara con aliases
      COALESCE(
        (SELECT MAX(similarity(lower(p_name), lower(a)))
         FROM unnest(gc.aliases) a),
        0
      )
    ) AS sim
  FROM public.global_categories gc
  LEFT JOIN public.global_categories parent ON parent.id = gc.parent_id
  WHERE gc.is_active = true
    AND GREATEST(
          similarity(lower(p_name), lower(gc.name)),
          COALESCE(
            (SELECT MAX(similarity(lower(p_name), lower(a)))
             FROM unnest(gc.aliases) a),
            0
          )
        ) >= p_threshold
  ORDER BY sim DESC
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."suggest_global_category"("p_name" "text", "p_limit" integer, "p_threshold" double precision) OWNER TO "postgres";


