CREATE OR REPLACE FUNCTION "public"."sync_customer_name"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Si se inserta name pero no first/last, actualizarlos
    IF (NEW.first_name IS NULL OR NEW.first_name = '') AND (NEW.name IS NOT NULL AND NEW.name != '') THEN
        NEW.first_name := split_part(NEW.name, ' ', 1);
        NEW.last_name := NULLIF(TRIM(substring(NEW.name from length(split_part(NEW.name, ' ', 1)) + 1)), '');
    -- Si se insertan first/last pero no name, actualizar name
    ELSIF (NEW.name IS NULL OR NEW.name = '') THEN
        NEW.name := TRIM(COALESCE(NEW.first_name, '') || ' ' || COALESCE(NEW.last_name, ''));
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_customer_name"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_customer_store_credit_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    update public.customers c
    set store_credit = coalesce(c.store_credit, 0) + coalesce(new.amount, 0)
    where c.organization_id = new.organization_id
      and c.id = new.customer_id;
    return new;
  elsif tg_op = 'UPDATE' then
    if old.organization_id = new.organization_id and old.customer_id = new.customer_id then
      update public.customers c
      set store_credit = coalesce(c.store_credit, 0) - coalesce(old.amount, 0) + coalesce(new.amount, 0)
      where c.organization_id = new.organization_id
        and c.id = new.customer_id;
    else
      update public.customers c
      set store_credit = coalesce(c.store_credit, 0) - coalesce(old.amount, 0)
      where c.organization_id = old.organization_id
        and c.id = old.customer_id;

      update public.customers c
      set store_credit = coalesce(c.store_credit, 0) + coalesce(new.amount, 0)
      where c.organization_id = new.organization_id
        and c.id = new.customer_id;
    end if;
    return new;
  elsif tg_op = 'DELETE' then
    update public.customers c
    set store_credit = coalesce(c.store_credit, 0) - coalesce(old.amount, 0)
    where c.organization_id = old.organization_id
      and c.id = old.customer_id;
    return old;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."sync_customer_store_credit_balance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_default_branch_inventory_from_product_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_active_branch_count INTEGER;
  v_default_branch_id UUID;
BEGIN
  SELECT COUNT(*)
  INTO v_active_branch_count
  FROM public.branches b
  WHERE b.organization_id = NEW.organization_id
    AND b.is_active = TRUE;

  IF v_active_branch_count <= 1 AND NEW.stock_quantity IS DISTINCT FROM OLD.stock_quantity THEN
    SELECT b.id
    INTO v_default_branch_id
    FROM public.branches b
    WHERE b.organization_id = NEW.organization_id
      AND b.is_active = TRUE
    ORDER BY b.is_default DESC, b.created_at ASC
    LIMIT 1;

    IF v_default_branch_id IS NOT NULL THEN
      INSERT INTO public.branch_inventory (branch_id, product_id, stock_quantity)
      VALUES (v_default_branch_id, NEW.id, COALESCE(NEW.stock_quantity, 0))
      ON CONFLICT (branch_id, product_id)
      DO UPDATE
      SET stock_quantity = EXCLUDED.stock_quantity,
          updated_at = NOW();
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_default_branch_inventory_from_product_stock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_finance_obligation_from_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  net_paid_amount numeric(14, 2);
begin
  select coalesce(sum(
    case payment.direction
      when 'payment' then payment.amount
      else -payment.amount
    end
  ), 0)
  into net_paid_amount
  from public.finance_payments payment
  where payment.organization_id = new.organization_id
    and payment.obligation_id = new.obligation_id;

  update public.finance_obligations obligation
  set paid_amount = net_paid_amount,
      status = case
        when net_paid_amount = obligation.amount then 'paid'
        when net_paid_amount > 0 then 'partially_paid'
        when obligation.due_date is not null and obligation.due_date < current_date then 'overdue'
        else 'pending'
      end,
      updated_by = new.created_by,
      updated_at = now()
  where obligation.id = new.obligation_id
    and obligation.organization_id = new.organization_id
    and obligation.branch_id = new.branch_id;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_finance_obligation_from_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_loyalty_account_from_ledger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  insert into public.loyalty_accounts (customer_id, organization_id, balance, lifetime_earned, lifetime_redeemed, updated_at)
  values (
    new.customer_id,
    new.organization_id,
    new.balance_after,
    greatest(new.points, 0),
    greatest(-new.points, 0),
    now()
  )
  on conflict (customer_id) do update
  set balance = new.balance_after,
      lifetime_earned = public.loyalty_accounts.lifetime_earned + greatest(new.points, 0),
      lifetime_redeemed = public.loyalty_accounts.lifetime_redeemed + greatest(-new.points, 0),
      updated_at = now();

  return new;
end;
$$;


