CREATE OR REPLACE FUNCTION "public"."update_superadmin_subscription"("p_subscription_id" "uuid", "p_plan" "text", "p_status" "text", "p_trial_ends_at" timestamp with time zone, "p_period_starts_at" timestamp with time zone, "p_period_ends_at" timestamp with time zone, "p_cancel_at_period_end" boolean) RETURNS SETOF "public"."subscriptions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_subscription public.subscriptions%rowtype;
begin
  if not exists (
    select 1
      from public.subscription_plans
     where tier = lower(p_plan)
       and is_active = true
  ) then
    raise exception 'INVALID_PLAN';
  end if;

  select *
    into v_subscription
    from public.subscriptions
   where id = p_subscription_id
   for update;

  if not found then
    raise exception 'SUBSCRIPTION_NOT_FOUND';
  end if;

  update public.subscriptions
     set plan = p_plan,
         status = p_status::public.subscription_status,
         trial_ends_at = p_trial_ends_at,
         current_period_starts_at = p_period_starts_at,
         current_period_ends_at = p_period_ends_at,
         cancel_at_period_end = p_cancel_at_period_end,
         updated_at = now()
   where id = p_subscription_id
   returning * into v_subscription;

  update public.organizations
     set plan = p_plan,
         updated_at = now()
   where id = v_subscription.organization_id;

  if not found then
    raise exception 'ORGANIZATION_NOT_FOUND';
  end if;

  return next v_subscription;
end;
$$;


