CREATE OR REPLACE FUNCTION "public"."user_has_branch_access"("target_branch_id" "uuid", "user_uuid" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_organization_id UUID;
  v_org_role public.organization_role;
BEGIN
  IF target_branch_id IS NULL OR user_uuid IS NULL THEN
    RETURN FALSE;
  END IF;

  v_role := public.get_user_role(user_uuid);
  IF v_role = 'super_admin' THEN
    RETURN TRUE;
  END IF;

  SELECT organization_id
  INTO v_organization_id
  FROM public.branches
  WHERE id = target_branch_id
    AND is_active = TRUE;

  IF v_organization_id IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT om.role
  INTO v_org_role
  FROM public.organization_members om
  WHERE om.organization_id = v_organization_id
    AND om.user_id = user_uuid
    AND om.status = 'active'
  LIMIT 1;

  IF v_org_role IN ('owner', 'admin') THEN
    RETURN TRUE;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.user_branch_assignments uba
    WHERE uba.user_id = user_uuid
      AND uba.branch_id = target_branch_id
      AND uba.is_active = TRUE
  );
END;
$$;


ALTER FUNCTION "public"."user_has_branch_access"("target_branch_id" "uuid", "user_uuid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_commission_rule_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.status <> 'approved' then
    return new;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    new.organization_id::text || ':commission-rule:'
      || new.scope_type || ':' || coalesce(new.employee_id::text, new.role::text)
      || ':' || coalesce(new.branch_id::text, 'organization')
      || ':' || new.source_type || ':' || new.calculation_type
      || ':' || coalesce(new.source_reference_id::text, 'all'),
    0
  ));

  if exists (
    select 1
    from public.commission_rules existing
    where existing.organization_id = new.organization_id
      and existing.id <> new.id
      and existing.status = 'approved'
      and existing.scope_type = new.scope_type
      and existing.role is not distinct from new.role
      and existing.employee_id is not distinct from new.employee_id
      and existing.branch_id is not distinct from new.branch_id
      and existing.source_type = new.source_type
      and existing.source_reference_id is not distinct from new.source_reference_id
      and existing.calculation_type = new.calculation_type
      and daterange(
        existing.effective_from,
        coalesce(existing.effective_to + 1, 'infinity'::date),
        '[)'
      ) && daterange(
        new.effective_from,
        coalesce(new.effective_to + 1, 'infinity'::date),
        '[)'
      )
  ) then
    raise exception 'PAYROLL_COMMISSION_RULE_PERIOD_OVERLAP';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_commission_rule_period"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_earned_commission_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  original_commission public.earned_commissions%rowtype;
  existing_reversals numeric(14, 2);
begin
  if new.entry_kind = 'accrual' then
    return new;
  end if;
  if new.entry_kind <> 'reversal'
     or new.origin_type not in ('after_sales', 'terminal_status') then
    raise exception 'PAYROLL_INVALID_COMMISSION_REVERSAL';
  end if;

  select commission.*
  into original_commission
  from public.earned_commissions commission
  where commission.organization_id = new.organization_id
    and commission.branch_id = new.branch_id
    and commission.id = new.reverses_commission_id
    and commission.entry_kind = 'accrual'
  for update;

  if not found then
    raise exception 'PAYROLL_COMMISSION_TO_REVERSE_NOT_FOUND';
  end if;
  if new.employee_id <> original_commission.employee_id
     or new.commission_rule_id <> original_commission.commission_rule_id
     or new.source_type <> original_commission.source_type
     or new.basis_amount <> original_commission.basis_amount
     or new.employee_role <> original_commission.employee_role
     or new.occurred_on < original_commission.occurred_on then
    raise exception 'PAYROLL_COMMISSION_REVERSAL_SCOPE_MISMATCH';
  end if;

  select coalesce(sum(reversal.amount), 0)
  into existing_reversals
  from public.earned_commissions reversal
  where reversal.organization_id = new.organization_id
    and reversal.reverses_commission_id = original_commission.id
    and reversal.entry_kind = 'reversal';

  if original_commission.amount + existing_reversals + new.amount < 0 then
    raise exception 'PAYROLL_COMMISSION_REVERSAL_EXCEEDS_ACCRUAL';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_earned_commission_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_employee_compensation_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtextextended(
    new.organization_id::text || ':compensation:' || new.employee_id::text,
    0
  ));

  if exists (
    select 1
    from public.employee_compensation existing
    where existing.organization_id = new.organization_id
      and existing.employee_id = new.employee_id
      and existing.id <> new.id
      and daterange(
        existing.effective_from,
        coalesce(existing.effective_to + 1, 'infinity'::date),
        '[)'
      ) && daterange(
        new.effective_from,
        coalesce(new.effective_to + 1, 'infinity'::date),
        '[)'
      )
  ) then
    raise exception 'PAYROLL_COMPENSATION_PERIOD_OVERLAP';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_employee_compensation_period"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_finance_cash_movement_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.finance_payment_id is null then
    return new;
  end if;

  if not exists (
    select 1
    from public.finance_payments payment
    where payment.id = new.finance_payment_id
      and payment.organization_id = new.organization_id
      and payment.branch_id = new.branch_id
      and payment.payment_method = 'cash'
      and payment.cash_session_id = new.session_id
      and payment.amount = new.amount
      and new.payment_method = 'cash'
      and new.type = case
        when payment.direction = 'payment' then 'cash_out'
        else 'cash_in'
      end
      and new.created_by is not distinct from payment.created_by
  ) then
    raise exception 'FINANCE_CASH_MOVEMENT_DOES_NOT_MATCH_PAYMENT';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_finance_cash_movement_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_finance_obligation_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  stored_paid_amount numeric(14, 2);
  financial_identity_changed boolean := false;
  created_by_fk_nulling boolean := false;
  voided_by_fk_nulling boolean := false;
begin
  if tg_op = 'UPDATE' then
    created_by_fk_nulling := old.created_by is not null
      and new.created_by is null
      and not exists (
        select 1 from auth.users actor where actor.id = old.created_by
      );
    voided_by_fk_nulling := old.voided_by is not null
      and new.voided_by is null
      and not exists (
        select 1 from auth.users actor where actor.id = old.voided_by
      );
    financial_identity_changed :=
      new.id is distinct from old.id
      or new.organization_id is distinct from old.organization_id
      or new.branch_id is distinct from old.branch_id
      or new.category_id is distinct from old.category_id
      or new.template_id is distinct from old.template_id
      or new.recurrence_period is distinct from old.recurrence_period
      or new.concept is distinct from old.concept
      or new.amount is distinct from old.amount
      or new.currency is distinct from old.currency
      or new.vendor is distinct from old.vendor
      or new.accounting_date is distinct from old.accounting_date
      or new.due_date is distinct from old.due_date
      or new.notes is distinct from old.notes
      or new.created_at is distinct from old.created_at;

    if old.status = 'voided'
       and (
         new.status is distinct from old.status
         or financial_identity_changed
         or new.void_reason is distinct from old.void_reason
         or new.voided_at is distinct from old.voided_at
       ) then
      raise exception 'FINANCE_VOIDED_OBLIGATION_IS_TERMINAL';
    end if;

    if old.status = 'voided'
       and new.voided_by is distinct from old.voided_by
       and not voided_by_fk_nulling then
      raise exception 'FINANCE_VOIDED_OBLIGATION_ACTOR_IMMUTABLE';
    end if;
  end if;

  if new.currency is null then
    select settings.currency
    into new.currency
    from public.organization_settings settings
    where settings.organization_id = new.organization_id;

    new.currency := coalesce(new.currency, 'PYG');
  end if;

  if tg_op = 'INSERT' then
    if new.paid_amount <> 0 then
      raise exception 'FINANCE_INITIAL_PAID_AMOUNT_MUST_BE_ZERO';
    end if;
  elsif financial_identity_changed and exists (
    select 1
    from public.finance_payments payment
    where payment.organization_id = old.organization_id
      and payment.obligation_id = old.id
  ) then
    raise exception 'FINANCE_EVER_PAID_OBLIGATION_IMMUTABLE';
  end if;

  if tg_op = 'UPDATE' and exists (
    select 1
    from public.finance_payments payment
    where payment.organization_id = old.organization_id
      and payment.obligation_id = old.id
  ) then
    if new.created_by is distinct from old.created_by
       and not created_by_fk_nulling then
      raise exception 'FINANCE_EVER_PAID_OBLIGATION_ACTOR_IMMUTABLE';
    end if;
    if new.voided_by is distinct from old.voided_by
       and not voided_by_fk_nulling
       and not (
         old.status <> 'voided'
         and new.status = 'voided'
         and old.voided_by is null
         and new.voided_by is not null
       ) then
      raise exception 'FINANCE_EVER_PAID_OBLIGATION_ACTOR_IMMUTABLE';
    end if;
  end if;

  if tg_op = 'UPDATE' and new.paid_amount is distinct from old.paid_amount then
    select coalesce(sum(
      case payment.direction
        when 'payment' then payment.amount
        else -payment.amount
      end
    ), 0)
    into stored_paid_amount
    from public.finance_payments payment
    where payment.organization_id = new.organization_id
      and payment.obligation_id = new.id;

    if new.paid_amount is distinct from stored_paid_amount then
      raise exception 'FINANCE_PAID_AMOUNT_MUST_MATCH_LEDGER';
    end if;
  end if;

  if new.status = 'paid' and new.paid_amount <> new.amount then
    raise exception 'FINANCE_PAID_STATUS_REQUIRES_FULL_PAYMENT';
  end if;
  if new.status = 'partially_paid'
     and not (new.paid_amount > 0 and new.paid_amount < new.amount) then
    raise exception 'FINANCE_PARTIAL_STATUS_REQUIRES_PARTIAL_PAYMENT';
  end if;
  if new.status in ('draft', 'pending', 'overdue') and new.paid_amount <> 0 then
    raise exception 'FINANCE_UNPAID_STATUS_REQUIRES_ZERO_PAYMENT';
  end if;
  if new.status = 'voided' and exists (
    select 1
    from public.finance_payments original_payment
    where original_payment.organization_id = new.organization_id
      and original_payment.obligation_id = new.id
      and original_payment.direction = 'payment'
      and not exists (
        select 1
        from public.finance_payments reversal
        where reversal.organization_id = original_payment.organization_id
          and reversal.branch_id = original_payment.branch_id
          and reversal.reverses_payment_id = original_payment.id
          and reversal.direction = 'reversal'
      )
  ) then
    raise exception 'FINANCE_VOID_REQUIRES_PAYMENT_COMPENSATION';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_finance_obligation_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_finance_payment_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_obligation public.finance_obligations%rowtype;
  original_payment public.finance_payments%rowtype;
  current_paid_amount numeric(14, 2);
begin
  select obligation.*
  into target_obligation
  from public.finance_obligations obligation
  where obligation.id = new.obligation_id
    and obligation.organization_id = new.organization_id
    and obligation.branch_id = new.branch_id
  for update;

  if not found then
    raise exception 'FINANCE_OBLIGATION_NOT_FOUND';
  end if;

  select coalesce(sum(
    case payment.direction
      when 'payment' then payment.amount
      else -payment.amount
    end
  ), 0)
  into current_paid_amount
  from public.finance_payments payment
  where payment.organization_id = new.organization_id
    and payment.obligation_id = new.obligation_id;

  if new.direction = 'payment' then
    if target_obligation.status in ('draft', 'paid', 'voided') then
      raise exception 'FINANCE_OBLIGATION_NOT_PAYABLE';
    end if;
    if current_paid_amount + new.amount > target_obligation.amount then
      raise exception 'FINANCE_OVERPAYMENT';
    end if;
  else
    select payment.*
    into original_payment
    from public.finance_payments payment
    where payment.id = new.reverses_payment_id
      and payment.organization_id = new.organization_id
      and payment.branch_id = new.branch_id
      and payment.obligation_id = new.obligation_id
      and payment.direction = 'payment'
    for update;

    if not found then
      raise exception 'FINANCE_PAYMENT_TO_REVERSE_NOT_FOUND';
    end if;
    if new.amount <> original_payment.amount
       or new.payment_method <> original_payment.payment_method then
      raise exception 'FINANCE_REVERSAL_MUST_FULLY_COMPENSATE_PAYMENT';
    end if;
    if current_paid_amount - new.amount < 0 then
      raise exception 'FINANCE_REVERSAL_EXCEEDS_PAID_AMOUNT';
    end if;
  end if;

  if new.payment_method = 'cash' then
    perform 1
    from public.cash_closures session
    join public.cash_registers register
      on register.id::text = session.register_id
     and register.organization_id = session.organization_id
     and register.branch_id = session.branch_id
    where session.id = new.cash_session_id
      and session.organization_id = new.organization_id
      and session.branch_id = new.branch_id
      and session.date is null
      and register.is_active = true
    for update of session, register;

    if not found then
      raise exception 'OPEN_CASH_SESSION_NOT_FOUND';
    end if;
  elsif new.cash_session_id is not null then
    raise exception 'NON_CASH_PAYMENT_CANNOT_USE_CASH_SESSION';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_finance_payment_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_payroll_adjustment_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_run_id uuid;
  target_entry public.payroll_entries%rowtype;
  target_run public.payroll_runs%rowtype;
  original_adjustment public.payroll_adjustments%rowtype;
  adjusted_payable numeric(14, 2);
begin
  select entry.payroll_run_id
  into target_run_id
  from public.payroll_entries entry
  where entry.organization_id = new.organization_id
    and entry.id = new.payroll_entry_id;

  if not found then
    raise exception 'PAYROLL_ENTRY_NOT_FOUND';
  end if;

  select run.*
  into target_run
  from public.payroll_runs run
  where run.organization_id = new.organization_id
    and run.id = target_run_id
  for update;

  select entry.*
  into target_entry
  from public.payroll_entries entry
  where entry.organization_id = new.organization_id
    and entry.id = new.payroll_entry_id
    and entry.payroll_run_id = target_run.id
  for update;

  if not found then
    raise exception 'PAYROLL_ENTRY_NOT_FOUND';
  end if;

  if target_run.status not in ('draft', 'approved') then
    raise exception 'PAYROLL_ADJUSTMENT_REQUIRES_OPEN_OR_APPROVED_RUN';
  end if;

  -- Draft adjustments are frozen into the approved entry net. Later
  -- corrections remain external append-only deltas against that snapshot.
  new.included_in_net := case when target_run.status = 'draft' then true else false end;

  if new.adjustment_type = 'reversal' then
    select adjustment.*
    into original_adjustment
    from public.payroll_adjustments adjustment
    where adjustment.organization_id = new.organization_id
      and adjustment.id = new.reverses_adjustment_id
      and adjustment.payroll_entry_id = new.payroll_entry_id
      and adjustment.adjustment_type <> 'reversal'
    for update;

    if not found or new.amount <> -original_adjustment.amount then
      raise exception 'PAYROLL_ADJUSTMENT_REVERSAL_MUST_COMPENSATE_ORIGINAL';
    end if;
  end if;

  select case
    when target_run.status = 'draft' then
      target_entry.gross_amount + coalesce(sum(adjustment.amount), 0) + new.amount
    else
      target_entry.net_amount + coalesce(sum(adjustment.amount) filter (
        where adjustment.included_in_net = false
      ), 0) + new.amount
    end
  into adjusted_payable
  from public.payroll_adjustments adjustment
  where adjustment.organization_id = new.organization_id
    and adjustment.payroll_entry_id = new.payroll_entry_id;

  if adjusted_payable < target_entry.paid_amount or adjusted_payable < 0 then
    raise exception 'PAYROLL_ADJUSTMENT_BELOW_PAID_AMOUNT';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_payroll_adjustment_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_payroll_cash_movement_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.payroll_payment_id is null then
    return new;
  end if;

  if new.finance_payment_id is not null or not exists (
    select 1
    from public.payroll_payments payment
    where payment.organization_id = new.organization_id
      and payment.branch_id = new.branch_id
      and payment.id = new.payroll_payment_id
      and payment.payment_method = 'cash'
      and payment.cash_session_id = new.session_id
      and payment.amount = new.amount
      and new.payment_method = 'cash'
      and new.type = case
        when payment.direction = 'payment' then 'cash_out'
        else 'cash_in'
      end
      and new.created_by is not distinct from payment.created_by
  ) then
    raise exception 'PAYROLL_CASH_MOVEMENT_DOES_NOT_MATCH_PAYMENT';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_payroll_cash_movement_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_payroll_entry_commission_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_run_id uuid;
  target_entry public.payroll_entries%rowtype;
  target_run public.payroll_runs%rowtype;
  target_commission public.earned_commissions%rowtype;
begin
  select entry.payroll_run_id
  into target_run_id
  from public.payroll_entries entry
  where entry.organization_id = new.organization_id
    and entry.id = new.payroll_entry_id;

  if not found then
    raise exception 'PAYROLL_ENTRY_NOT_FOUND';
  end if;

  select run.*
  into target_run
  from public.payroll_runs run
  where run.organization_id = new.organization_id
    and run.id = target_run_id
  for key share;

  select entry.*
  into target_entry
  from public.payroll_entries entry
  where entry.organization_id = new.organization_id
    and entry.id = new.payroll_entry_id
    and entry.payroll_run_id = target_run.id
  for key share;

  if not found then
    raise exception 'PAYROLL_ENTRY_NOT_FOUND';
  end if;

  select commission.*
  into target_commission
  from public.earned_commissions commission
  where commission.organization_id = new.organization_id
    and commission.id = new.earned_commission_id
  for key share;

  if not found then
    raise exception 'PAYROLL_EARNED_COMMISSION_NOT_FOUND';
  end if;
  if target_run.status <> 'draft'
     or target_commission.employee_id <> target_entry.employee_id
     or target_commission.occurred_on > target_run.period_to
     or (
       target_entry.branch_id is not null
       and target_commission.branch_id <> target_entry.branch_id
     ) then
    raise exception 'PAYROLL_ENTRY_COMMISSION_SCOPE_MISMATCH';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_payroll_entry_commission_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_payroll_entry_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_run public.payroll_runs%rowtype;
  target_membership public.organization_members%rowtype;
  target_employment_role public.organization_role;
  has_active_employment boolean := false;
  organization_timezone text := 'America/Asuncion';
begin
  select run.*
  into target_run
  from public.payroll_runs run
  where run.organization_id = new.organization_id
    and run.id = new.payroll_run_id
  for key share;

  if not found then
    raise exception 'PAYROLL_RUN_NOT_FOUND';
  end if;
  if target_run.branch_id is distinct from new.branch_id
     or target_run.allocation_scope <> new.allocation_scope then
    raise exception 'PAYROLL_ENTRY_SCOPE_MISMATCH';
  end if;

  select timezone_record.name
  into organization_timezone
  from public.organization_settings settings
  join pg_timezone_names timezone_record
    on timezone_record.name = settings.timezone
  where settings.organization_id = new.organization_id
  limit 1;
  organization_timezone := coalesce(organization_timezone, 'America/Asuncion');

  if tg_op = 'INSERT' then
    if target_run.status <> 'draft' then
      raise exception 'PAYROLL_ENTRY_REQUIRES_DRAFT_RUN';
    end if;

    select membership.*
    into target_membership
    from public.organization_members membership
    where membership.organization_id = new.organization_id
      and membership.user_id = new.employee_id;

    if not found then
      raise exception 'PAYROLL_ENTRY_REQUIRES_ORGANIZATION_MEMBER';
    end if;

    select employment.employee_role
    into target_employment_role
    from (
      select
        event.id,
        event.employee_role,
        event.employment_status,
        event.occurred_at,
        lead(event.occurred_at) over (
          partition by event.organization_id, event.employee_id
          order by event.occurred_at, event.id
        ) as ended_at
      from public.employee_employment_events event
      where event.organization_id = new.organization_id
        and event.employee_id = new.employee_id
    ) employment
    where employment.employment_status = 'active'
      and employment.employee_role <> 'customer'
      and employment.occurred_at
        < ((target_run.period_to + 1)::timestamp at time zone organization_timezone)
      and coalesce(employment.ended_at, 'infinity'::timestamptz)
        > (target_run.period_from::timestamp at time zone organization_timezone)
    order by employment.occurred_at desc, employment.id desc
    limit 1;
    has_active_employment := found;

    if has_active_employment then
      if target_employment_role <> new.employee_role then
        raise exception 'PAYROLL_ENTRY_ROLE_MISMATCH';
      end if;
    elsif new.base_amount <> 0 or not exists (
      select 1
      from public.earned_commissions commission
      where commission.organization_id = new.organization_id
        and commission.employee_id = new.employee_id
        and commission.employee_role = new.employee_role
        and commission.occurred_on <= target_run.period_to
        and (
          target_run.branch_id is null
          or commission.branch_id = target_run.branch_id
        )
        and not exists (
          select 1
          from public.payroll_entry_commissions claimed
          where claimed.organization_id = commission.organization_id
            and claimed.earned_commission_id = commission.id
        )
    ) then
      -- Former/suspended staff remain payable only for already materialized,
      -- unclaimed commission. A zero net is valid when an accrual and its
      -- reversal are claimed together; approval later proves the linked sum.
      raise exception 'PAYROLL_ENTRY_REQUIRES_STAFF_OR_OWED_COMMISSION';
    end if;
  elsif new.organization_id is distinct from old.organization_id
     or new.payroll_run_id is distinct from old.payroll_run_id
     or new.employee_id is distinct from old.employee_id
     or new.employee_role is distinct from old.employee_role
     or new.allocation_scope is distinct from old.allocation_scope
     or new.branch_id is distinct from old.branch_id then
    raise exception 'PAYROLL_ENTRY_SCOPE_IS_IMMUTABLE';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_payroll_entry_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_payroll_payment_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_run_id uuid;
  target_entry public.payroll_entries%rowtype;
  target_run public.payroll_runs%rowtype;
  original_payment public.payroll_payments%rowtype;
  adjusted_payable numeric(14, 2);
  current_paid numeric(14, 2);
begin
  select entry.payroll_run_id
  into target_run_id
  from public.payroll_entries entry
  where entry.organization_id = new.organization_id
    and entry.id = new.payroll_entry_id;

  if not found then
    raise exception 'PAYROLL_ENTRY_NOT_FOUND';
  end if;

  select run.*
  into target_run
  from public.payroll_runs run
  where run.organization_id = new.organization_id
    and run.id = target_run_id
  for update;

  select entry.*
  into target_entry
  from public.payroll_entries entry
  where entry.organization_id = new.organization_id
    and entry.id = new.payroll_entry_id
    and entry.payroll_run_id = target_run.id
  for update;

  if not found then
    raise exception 'PAYROLL_ENTRY_NOT_FOUND';
  end if;

  if target_run.status <> 'approved' then
    raise exception 'PAYROLL_ENTRY_NOT_PAYABLE';
  end if;
  if target_entry.branch_id is not null
     and target_entry.branch_id <> new.branch_id then
    raise exception 'PAYROLL_PAYMENT_BRANCH_MISMATCH';
  end if;

  select target_entry.net_amount + coalesce(sum(adjustment.amount) filter (
    where adjustment.included_in_net = false
  ), 0)
  into adjusted_payable
  from public.payroll_adjustments adjustment
  where adjustment.organization_id = new.organization_id
    and adjustment.payroll_entry_id = new.payroll_entry_id;

  select coalesce(sum(
    case payment.direction when 'payment' then payment.amount else -payment.amount end
  ), 0)
  into current_paid
  from public.payroll_payments payment
  where payment.organization_id = new.organization_id
    and payment.payroll_entry_id = new.payroll_entry_id;

  if new.direction = 'payment' then
    if adjusted_payable <= 0 then
      raise exception 'PAYROLL_ENTRY_NOT_PAYABLE';
    end if;
    if current_paid + new.amount > adjusted_payable then
      raise exception 'PAYROLL_OVERPAYMENT';
    end if;
  else
    select payment.*
    into original_payment
    from public.payroll_payments payment
    where payment.organization_id = new.organization_id
      and payment.branch_id is not distinct from new.branch_id
      and payment.payroll_entry_id = new.payroll_entry_id
      and payment.id = new.reverses_payment_id
      and payment.direction = 'payment'
    for update;

    if not found
       or original_payment.amount <> new.amount
       or original_payment.payment_method <> new.payment_method then
      raise exception 'PAYROLL_REVERSAL_MUST_COMPENSATE_PAYMENT';
    end if;
    if current_paid - new.amount < 0 then
      raise exception 'PAYROLL_REVERSAL_EXCEEDS_PAID_AMOUNT';
    end if;
  end if;

  if new.payment_method = 'cash' then
    perform 1
    from public.cash_closures session
    join public.cash_registers register
      on register.id::text = session.register_id
     and register.organization_id = session.organization_id
     and register.branch_id = session.branch_id
    where session.id = new.cash_session_id
      and session.organization_id = new.organization_id
      and session.branch_id = new.branch_id
      and session.date is null
      and register.is_active = true
    for update of session, register;

    if not found then
      raise exception 'OPEN_CASH_SESSION_NOT_FOUND';
    end if;
  elsif new.cash_session_id is not null then
    raise exception 'NON_CASH_PAYMENT_CANNOT_USE_CASH_SESSION';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_payroll_payment_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_variant_tenant_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  product_organization_id uuid;
  branch_organization_id uuid;
  variant_product_id uuid;
  variant_organization_id uuid;
begin
  select organization_id
  into product_organization_id
  from public.products
  where id = new.product_id;

  if product_organization_id is null or product_organization_id <> new.organization_id then
    raise exception 'VARIANT_PRODUCT_NOT_IN_ORGANIZATION';
  end if;

  if tg_table_name = 'branch_variant_inventory' then
    select organization_id into branch_organization_id
    from public.branches
    where id = new.branch_id;

    select product_id, organization_id
    into variant_product_id, variant_organization_id
    from public.product_variants
    where id = new.variant_id;

    if branch_organization_id is distinct from new.organization_id then
      raise exception 'VARIANT_BRANCH_FORBIDDEN';
    end if;

    if variant_product_id is distinct from new.product_id
       or variant_organization_id is distinct from new.organization_id then
      raise exception 'VARIANT_PRODUCT_MISMATCH';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_variant_tenant_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_user_password"("password" "text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    user_id UUID;
BEGIN
    user_id := auth.uid();

    IF user_id IS NULL THEN
        RETURN FALSE;
    END IF;

    -- Nota: Esta es una implementación simplificada
    -- En producción, deberías usar auth.users() o una función más segura
    -- Por ahora, retornamos true si el usuario está autenticado
    RETURN TRUE;
END;
$$;


