CREATE OR REPLACE FUNCTION "public"."void_finance_obligation_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_obligation_id" "uuid", "p_reason" "text", "p_cash_session_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  actor_id uuid := auth.uid();
  target_obligation public.finance_obligations%rowtype;
  original_payment public.finance_payments%rowtype;
  has_cash_compensation boolean;
begin
  if actor_id is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;
  if not (
    public.has_org_permission(p_organization_id, 'finances.void')
    or public.get_user_role(actor_id) = 'super_admin'
  ) then
    raise exception 'FINANCE_VOID_PERMISSION_DENIED';
  end if;
  if not public.user_has_branch_access(p_branch_id) then
    raise exception 'FINANCE_BRANCH_PERMISSION_DENIED';
  end if;
  if nullif(trim(p_reason), '') is null then
    raise exception 'FINANCE_VOID_REASON_REQUIRED';
  end if;

  select obligation.*
  into target_obligation
  from public.finance_obligations obligation
  where obligation.id = p_obligation_id
    and obligation.organization_id = p_organization_id
    and obligation.branch_id = p_branch_id
  for update;

  if not found then
    raise exception 'FINANCE_OBLIGATION_NOT_FOUND';
  end if;
  if target_obligation.status = 'voided' then
    return to_jsonb(target_obligation);
  end if;

  select exists (
    select 1
    from public.finance_payments payment
    where payment.organization_id = p_organization_id
      and payment.obligation_id = p_obligation_id
      and payment.direction = 'payment'
      and payment.payment_method = 'cash'
      and not exists (
        select 1
        from public.finance_payments reversal
        where reversal.organization_id = payment.organization_id
          and reversal.branch_id = payment.branch_id
          and reversal.reverses_payment_id = payment.id
      )
  ) into has_cash_compensation;

  if has_cash_compensation then
    perform 1
    from public.cash_closures session
    join public.cash_registers register
      on register.id::text = session.register_id
     and register.organization_id = session.organization_id
     and register.branch_id = session.branch_id
    where session.id = p_cash_session_id
      and session.organization_id = p_organization_id
      and session.branch_id = p_branch_id
      and session.date is null
      and register.is_active = true
    for update of session, register;

    if not found then
      raise exception 'OPEN_CASH_SESSION_NOT_FOUND';
    end if;
  elsif p_cash_session_id is not null then
    raise exception 'CASH_SESSION_ONLY_ALLOWED_FOR_CASH_COMPENSATION';
  end if;

  for original_payment in
    select payment.*
    from public.finance_payments payment
    where payment.organization_id = p_organization_id
      and payment.branch_id = p_branch_id
      and payment.obligation_id = p_obligation_id
      and payment.direction = 'payment'
      and not exists (
        select 1
        from public.finance_payments existing_reversal
        where existing_reversal.organization_id = payment.organization_id
          and existing_reversal.branch_id = payment.branch_id
          and existing_reversal.reverses_payment_id = payment.id
      )
    order by payment.created_at, payment.id
  loop
    insert into public.finance_payments (
      organization_id,
      branch_id,
      obligation_id,
      idempotency_key,
      direction,
      reverses_payment_id,
      amount,
      payment_method,
      payment_date,
      cash_session_id,
      reference,
      notes,
      created_by
    ) values (
      p_organization_id,
      p_branch_id,
      p_obligation_id,
      'finance-system:reversal:' || original_payment.id::text,
      'reversal',
      original_payment.id,
      original_payment.amount,
      original_payment.payment_method,
      current_date,
      case when original_payment.payment_method = 'cash' then p_cash_session_id else null end,
      left('Reversion de pago ' || original_payment.id::text, 200),
      left(trim(p_reason), 2000),
      actor_id
    );
  end loop;

  update public.finance_obligations
  set status = 'voided',
      paid_amount = 0,
      void_reason = left(trim(p_reason), 1000),
      voided_at = now(),
      voided_by = actor_id,
      updated_by = actor_id,
      updated_at = now()
  where id = p_obligation_id
    and organization_id = p_organization_id
    and branch_id = p_branch_id
  returning * into target_obligation;

  return to_jsonb(target_obligation);
end;
$$;


ALTER FUNCTION "public"."void_finance_obligation_atomic"("p_organization_id" "uuid", "p_branch_id" "uuid", "p_obligation_id" "uuid", "p_reason" "text", "p_cash_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_pos_sale"("p_sale_id" "uuid", "p_organization_id" "uuid", "p_actor_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  sale public.sales%rowtype;
  item record;
  credit record;
  paid_installments integer := 0;
  cancelled_installments integer := 0;
  restored_units integer := 0;
  cash_total numeric := 0;
  open_session uuid;
  motivo text := nullif(trim(coalesce(p_reason, '')), '');
begin
  select * into sale
  from public.sales
  where id = p_sale_id and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'SALE_NOT_IN_ORGANIZATION';
  end if;

  -- Anular dos veces no puede devolver el stock dos veces.
  if sale.status = 'cancelled' then
    return jsonb_build_object('sale_id', sale.id, 'already_voided', true);
  end if;

  -- ── El crédito primero: si ya cobraron algo, no se sigue ──
  for credit in
    select c.id
    from public.customer_credits c
    where c.sale_id = p_sale_id and c.organization_id = p_organization_id
  loop
    select count(*) into paid_installments
    from public.credit_installments i
    where i.credit_id = credit.id and coalesce(i.amount_paid, 0) > 0;

    if paid_installments > 0 then
      raise exception 'SALE_CREDIT_ALREADY_PAID';
    end if;
  end loop;

  -- ── Stock: se devuelve lo que la venta descontó ──
  for item in
    select si.product_id, si.variant_id, sum(si.quantity)::integer as quantity
    from public.sale_items si
    where si.sale_id = p_sale_id and si.organization_id = p_organization_id
    group by si.product_id, si.variant_id
  loop
    if item.variant_id is not null then
      perform public.adjust_variant_stock_atomic(
        p_organization_id, sale.branch_id, item.variant_id, item.quantity,
        'return', 'void-sale:' || p_sale_id::text || ':' || item.variant_id::text,
        p_actor_id, 'sale', p_sale_id, 'Anulación de venta',
        jsonb_build_object('sale_id', p_sale_id, 'voided', true)
      );
    else
      update public.products
      set stock_quantity = stock_quantity + item.quantity, updated_at = now()
      where id = item.product_id and organization_id = p_organization_id;

      update public.branch_inventory
      set stock_quantity = stock_quantity + item.quantity, updated_at = now()
      where branch_id = sale.branch_id and product_id = item.product_id;
    end if;

    restored_units := restored_units + item.quantity;
  end loop;

  -- ── Crédito: las cuotas impagas se cancelan y el crédito se cierra ──
  for credit in
    select c.id
    from public.customer_credits c
    where c.sale_id = p_sale_id and c.organization_id = p_organization_id
  loop
    update public.credit_installments
    set status = 'cancelled', updated_at = now()
    where credit_id = credit.id and status <> 'paid';
    get diagnostics cancelled_installments = row_count;

    update public.customer_credits
    set status = 'cancelled',
        updated_at = now(),
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'voided_with_sale', p_sale_id, 'voided_at', now(), 'voided_by', p_actor_id)
    where id = credit.id;
  end loop;

  -- ── Caja: el efectivo cobrado sale con un movimiento inverso ──
  select coalesce(sum(sp.amount), 0) into cash_total
  from public.sale_payments sp
  where sp.sale_id = p_sale_id
    and sp.organization_id = p_organization_id
    and lower(sp.payment_method) = 'cash';

  if cash_total > 0 then
    select cc.id into open_session
    from public.cash_closures cc
    where cc.organization_id = p_organization_id
      and cc.branch_id = sale.branch_id
      and cc.date is null
    order by cc.created_at desc
    limit 1;

    -- Sin caja abierta el movimiento no se puede registrar: mejor frenar que
    -- devolver el stock y dejar la plata contada como si se hubiera vendido.
    if open_session is null then
      raise exception 'VOID_REQUIRES_OPEN_REGISTER';
    end if;

    insert into public.cash_movements (
      session_id, type, amount, reason, payment_method, created_by, created_at,
      organization_id, branch_id
    ) values (
      open_session, 'cash_out', cash_total,
      'Anulación de venta ' || coalesce(sale.code, p_sale_id::text)
        || case when motivo is null then '' else ' — ' || motivo end,
      'cash', p_actor_id, now(), p_organization_id, sale.branch_id
    );
  end if;

  -- ── La venta queda, marcada ──
  update public.sales
  set status = 'cancelled',
      payment_status = 'cancelled',
      notes = trim(both E'\n' from coalesce(notes, '') || E'\n[ANULADA ' || to_char(now(), 'YYYY-MM-DD HH24:MI') || ']'
        || case when motivo is null then '' else ' ' || motivo end),
      updated_at = now()
  where id = p_sale_id;

  return jsonb_build_object(
    'sale_id', sale.id,
    'already_voided', false,
    'restored_units', restored_units,
    'cancelled_installments', cancelled_installments,
    'cash_returned', cash_total
  );
end $$;


ALTER FUNCTION "public"."void_pos_sale"("p_sale_id" "uuid", "p_organization_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "ops"."pg_stat_statements_20260927" (
    "snapshot_at" timestamp with time zone,
    "userid" "oid",
    "dbid" "oid",
    "toplevel" boolean,
    "queryid" bigint,
    "query" "text",
