CREATE TABLE IF NOT EXISTS "public"."after_sales_cases" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "case_number" "text" DEFAULT ((('ASC-'::"text" || "to_char"("now"(), 'YYYYMMDD'::"text")) || '-'::"text") || "upper"("substr"("replace"(("extensions"."uuid_generate_v4"())::"text", '-'::"text", ''::"text"), 1, 8))),
    "source_type" "text" NOT NULL,
    "request_type" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "customer_id" "uuid",
    "repair_id" "uuid",
    "sale_id" "uuid",
    "sale_item_id" "uuid",
    "product_id" "uuid",
    "quantity" integer DEFAULT 1 NOT NULL,
    "reason" "text" NOT NULL,
    "notes" "text",
    "refund_amount" numeric(12,2),
    "approved_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "created_by" "uuid",
    "resolved_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "organization_id" "uuid",
    "refund_method" "text",
    "generated_repair_id" "uuid",
    "restock_action" "text",
    "replacement_product_id" "uuid",
    "replacement_quantity" integer,
    "price_difference" numeric(14,2),
    CONSTRAINT "after_sales_cases_quantity_check" CHECK (("quantity" > 0)),
    CONSTRAINT "after_sales_cases_refund_method_check" CHECK ((("refund_method" IS NULL) OR ("refund_method" = ANY (ARRAY['cash'::"text", 'store_credit'::"text"])))),
    CONSTRAINT "after_sales_cases_replacement_qty_check" CHECK ((("replacement_quantity" IS NULL) OR ("replacement_quantity" > 0))),
    CONSTRAINT "after_sales_cases_request_type_check" CHECK (("request_type" = ANY (ARRAY['repair_warranty'::"text", 'product_warranty'::"text", 'exchange'::"text", 'return'::"text", 'garantia_reparacion'::"text", 'garantia_producto'::"text", 'cambio'::"text", 'devolucion'::"text"]))),
    CONSTRAINT "after_sales_cases_restock_action_check" CHECK ((("restock_action" IS NULL) OR ("restock_action" = ANY (ARRAY['sellable'::"text", 'quarantine'::"text", 'none'::"text"])))),
    CONSTRAINT "after_sales_cases_source_type_check" CHECK (("source_type" = ANY (ARRAY['repair'::"text", 'sale'::"text", 'reparacion'::"text", 'venta'::"text"]))),
    CONSTRAINT "after_sales_cases_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'approved'::"text", 'rejected'::"text", 'completed'::"text", 'cancelled'::"text", 'abierto'::"text", 'aprobado'::"text", 'rechazado'::"text", 'completado'::"text", 'cancelado'::"text"]))),
    CONSTRAINT "after_sales_source_reference_chk" CHECK (((("source_type" = ANY (ARRAY['repair'::"text", 'reparacion'::"text"])) AND ("repair_id" IS NOT NULL)) OR (("source_type" = ANY (ARRAY['sale'::"text", 'venta'::"text"])) AND ("sale_id" IS NOT NULL))))
);


ALTER TABLE "public"."after_sales_cases" OWNER TO "postgres";


COMMENT ON TABLE "public"."after_sales_cases" IS 'After-sales cases: repair warranty claims, product warranty claims, exchanges and returns.';



COMMENT ON COLUMN "public"."after_sales_cases"."source_type" IS 'Source module for the case: repair or sale.';



COMMENT ON COLUMN "public"."after_sales_cases"."request_type" IS 'Type of case: repair_warranty, product_warranty, exchange, return.';



COMMENT ON COLUMN "public"."after_sales_cases"."refund_method" IS 'Como se devolvio el dinero: cash (sale de caja) o store_credit (saldo a favor).';



COMMENT ON COLUMN "public"."after_sales_cases"."restock_action" IS 'Destino de la mercaderia devuelta: sellable reingresa al stock, quarantine vuelve con falla, none no vuelve nada.';



COMMENT ON COLUMN "public"."after_sales_cases"."replacement_product_id" IS 'Producto que se lleva el cliente en un cambio. Sale del stock al completar el caso.';



COMMENT ON COLUMN "public"."after_sales_cases"."price_difference" IS 'Diferencia a favor de la organizacion (positiva) o del cliente (negativa) en un cambio.';



