    CONSTRAINT "customers_purchase_frequency_check" CHECK (("purchase_frequency" = ANY (ARRAY['very_high'::"text", 'high'::"text", 'medium'::"text", 'low'::"text"]))),
    CONSTRAINT "customers_satisfaction_score_check" CHECK ((("satisfaction_score" >= (0)::numeric) AND ("satisfaction_score" <= (10)::numeric))),
    CONSTRAINT "customers_segment_check" CHECK (("segment" = ANY (ARRAY['vip'::"text", 'premium'::"text", 'regular'::"text", 'new'::"text", 'high_value'::"text", 'low_value'::"text", 'business'::"text", 'wholesale'::"text"]))),
    CONSTRAINT "customers_status_check" CHECK (("status" = ANY (ARRAY['activo'::"text", 'inactivo'::"text", 'suspendido'::"text", 'pendiente'::"text"])))
);


