CREATE OR REPLACE VIEW "public"."credit_details" WITH ("security_invoker"='true') AS
 SELECT "cc"."id",
    "cc"."customer_id",
    "cc"."sale_id",
    "cc"."principal",
    "cc"."interest_rate",
    "cc"."term_months",
    "cc"."start_date",
    "cc"."status",
    "cc"."created_at",
    "cc"."updated_at",
    "c"."name" AS "customer_name",
    "cc"."organization_id",
    "c"."customer_code",
    "cc"."credit_code",
    "cc"."credit_type",
    "cc"."origin_type",
    "cc"."label",
    "s"."code" AS "sale_code"
   FROM (("public"."customer_credits" "cc"
     JOIN "public"."customers" "c" ON (("c"."id" = "cc"."customer_id")))
     LEFT JOIN "public"."sales" "s" ON (("s"."id" = "cc"."sale_id")));


