    "cc"."parent_credit_id",
    "cc"."principal",
    "cc"."interest_rate",
    "cc"."term_months",
    "cc"."start_date",
    "cc"."status",
    "cc"."created_at",
    "cc"."updated_at",
    "c"."name" AS "customer_name",
    "c"."customer_code",
    "s"."code" AS "sale_code",
    COALESCE("cc"."label", ('Venta '::"text" || "s"."code"), 'Credito'::"text") AS "display_name"
   FROM (("public"."customer_credits" "cc"
     JOIN "public"."customers" "c" ON (("c"."id" = "cc"."customer_id")))
     LEFT JOIN "public"."sales" "s" ON (("s"."id" = "cc"."sale_id")));


