    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "credit_id" "uuid" NOT NULL,
    "installment_number" integer NOT NULL,
    "due_date" timestamp with time zone NOT NULL,
    "amount" numeric NOT NULL,
    "principal_component" numeric DEFAULT 0 NOT NULL,
    "interest_component" numeric DEFAULT 0 NOT NULL,
    "status" "text" NOT NULL,
    "paid_at" timestamp with time zone,
    "payment_method" "text",
    "amount_paid" numeric,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "sale_id" "uuid",
    CONSTRAINT "credit_installments_payment_method_check" CHECK (("payment_method" = ANY (ARRAY['cash'::"text", 'card'::"text", 'transfer'::"text"]))),
    CONSTRAINT "credit_installments_payment_method_valid" CHECK ((("payment_method" IS NULL) OR ("payment_method" = ANY (ARRAY['cash'::"text", 'card'::"text", 'transfer'::"text"])))),
    CONSTRAINT "credit_installments_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'paid'::"text", 'late'::"text"])))
);


ALTER TABLE "public"."credit_installments" OWNER TO "postgres";


COMMENT ON COLUMN "public"."credit_installments"."status" IS 'pending | paid | cancelled. El estado «late» no lo escribe nadie: la mora se calcula por fecha al leer (ver isCreditInstallmentOverdue). Una consulta que filtre por «late» va a devolver siempre cero.';



CREATE OR REPLACE VIEW "public"."credit_installments_progress" WITH ("security_invoker"='true') AS
 SELECT "i"."id",
    "i"."credit_id",
    "cc"."organization_id",
    "i"."installment_number",
    "i"."due_date",
    "i"."amount",
    COALESCE("i"."amount_paid", (0)::numeric) AS "amount_paid",
        CASE
            WHEN (COALESCE("i"."amount_paid", (0)::numeric) >= "i"."amount") THEN 'paid'::"text"
            WHEN ("i"."due_date" < "now"()) THEN 'late'::"text"
            ELSE 'pending'::"text"
        END AS "status_effective",
        CASE
            WHEN ("i"."amount" > (0)::numeric) THEN LEAST(100, ("round"(((COALESCE("i"."amount_paid", (0)::numeric) / "i"."amount") * (100)::numeric)))::integer)
            ELSE 0
        END AS "progreso"
   FROM ("public"."credit_installments" "i"
     JOIN "public"."customer_credits" "cc" ON (("cc"."id" = "i"."credit_id")));


ALTER VIEW "public"."credit_installments_progress" OWNER TO "postgres";


