);


ALTER TABLE "public"."credit_payments" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."credit_summary" WITH ("security_invoker"='on') AS
 WITH "inst" AS (
         SELECT "credit_installments"."credit_id",
            ("count"(*))::numeric AS "total_installments",
            COALESCE("sum"("credit_installments"."amount"), (0)::numeric) AS "total_principal",
            COALESCE("sum"(
                CASE
                    WHEN ("credit_installments"."status" = 'paid'::"text") THEN "credit_installments"."amount"
                    ELSE COALESCE("credit_installments"."amount_paid", (0)::numeric)
                END), (0)::numeric) AS "total_pagado",
            COALESCE("sum"(
                CASE
                    WHEN ("credit_installments"."status" <> 'paid'::"text") THEN ("credit_installments"."amount" - COALESCE("credit_installments"."amount_paid", (0)::numeric))
                    ELSE (0)::numeric
                END), (0)::numeric) AS "saldo_pendiente"
           FROM "public"."credit_installments"
          GROUP BY "credit_installments"."credit_id"
        )
 SELECT "c"."id" AS "credit_id",
    COALESCE("inst"."total_principal", "c"."principal") AS "total_principal",
    COALESCE("inst"."total_installments", (0)::numeric) AS "total_installments",
    COALESCE("inst"."total_pagado", (0)::numeric) AS "total_pagado",
    COALESCE("inst"."saldo_pendiente", "c"."principal") AS "saldo_pendiente",
        CASE
            WHEN (COALESCE("inst"."total_principal", "c"."principal") > (0)::numeric) THEN "round"(((COALESCE("inst"."total_pagado", (0)::numeric) / COALESCE("inst"."total_principal", "c"."principal")) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS "progreso"
   FROM ("public"."customer_credits" "c"
     LEFT JOIN "inst" ON (("inst"."credit_id" = "c"."id")));


