CREATE OR REPLACE VIEW "public"."customer_stats" WITH ("security_invoker"='on') AS
 SELECT "count"(*) AS "total_customers",
    "count"(*) FILTER (WHERE ("status" = 'active'::"text")) AS "active_customers",
    "count"(*) FILTER (WHERE ("status" = 'inactive'::"text")) AS "inactive_customers",
    "count"(*) FILTER (WHERE ("customer_type" = 'vip'::"text")) AS "vip_customers",
    "count"(*) FILTER (WHERE ("customer_type" = 'premium'::"text")) AS "premium_customers",
    COALESCE("avg"("lifetime_value"), (0)::numeric) AS "avg_lifetime_value",
    COALESCE("sum"("lifetime_value"), (0)::numeric) AS "total_revenue",
    COALESCE("avg"("satisfaction_score"), (0)::numeric) AS "avg_satisfaction_score"
   FROM "public"."customers";


