    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "branch_id" "uuid" NOT NULL,
    "category_id" "uuid" NOT NULL,
    "template_id" "uuid",
    "recurrence_period" "date",
    "concept" "text" NOT NULL,
    "amount" numeric(14,2) NOT NULL,
    "paid_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "currency" "text" NOT NULL,
    "vendor" "text",
    "accounting_date" "date" NOT NULL,
    "due_date" "date",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "notes" "text",
    "void_reason" "text",
    "voided_at" timestamp with time zone,
    "voided_by" "uuid",
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "finance_obligations_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "finance_obligations_check" CHECK ((("paid_amount" >= (0)::numeric) AND ("paid_amount" <= "amount"))),
    CONSTRAINT "finance_obligations_check1" CHECK (((("template_id" IS NULL) AND ("recurrence_period" IS NULL)) OR (("template_id" IS NOT NULL) AND ("recurrence_period" IS NOT NULL)))),
    CONSTRAINT "finance_obligations_check2" CHECK ((("due_date" IS NULL) OR ("due_date" >= "accounting_date"))),
    CONSTRAINT "finance_obligations_check3" CHECK ((("status" <> 'voided'::"text") OR (("paid_amount" = (0)::numeric) AND ("voided_at" IS NOT NULL) AND (("char_length"(TRIM(BOTH FROM "void_reason")) >= 1) AND ("char_length"(TRIM(BOTH FROM "void_reason")) <= 1000))))),
    CONSTRAINT "finance_obligations_concept_check" CHECK ((("char_length"(TRIM(BOTH FROM "concept")) >= 1) AND ("char_length"(TRIM(BOTH FROM "concept")) <= 200))),
    CONSTRAINT "finance_obligations_currency_check" CHECK ((("char_length"("currency") = 3) AND ("currency" = "upper"("currency")))),
    CONSTRAINT "finance_obligations_notes_check" CHECK ((("notes" IS NULL) OR ("char_length"("notes") <= 2000))),
    CONSTRAINT "finance_obligations_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'pending'::"text", 'partially_paid'::"text", 'paid'::"text", 'overdue'::"text", 'voided'::"text"]))),
    CONSTRAINT "finance_obligations_vendor_check" CHECK ((("vendor" IS NULL) OR (("char_length"(TRIM(BOTH FROM "vendor")) >= 1) AND ("char_length"(TRIM(BOTH FROM "vendor")) <= 200))))
);


