CREATE TABLE IF NOT EXISTS "public"."finance_payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "branch_id" "uuid" NOT NULL,
    "obligation_id" "uuid" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "direction" "text" DEFAULT 'payment'::"text" NOT NULL,
    "reverses_payment_id" "uuid",
    "amount" numeric(14,2) NOT NULL,
    "payment_method" "text" NOT NULL,
    "payment_date" "date" NOT NULL,
    "cash_session_id" "uuid",
    "reference" "text",
    "receipt_storage_path" "text",
    "receipt_original_name" "text",
    "receipt_mime_type" "text",
    "receipt_size_bytes" bigint,
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "finance_payments_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "finance_payments_check" CHECK (((("direction" = 'payment'::"text") AND ("reverses_payment_id" IS NULL)) OR (("direction" = 'reversal'::"text") AND ("reverses_payment_id" IS NOT NULL)))),
    CONSTRAINT "finance_payments_check1" CHECK (((("payment_method" = 'cash'::"text") AND ("cash_session_id" IS NOT NULL)) OR (("payment_method" <> 'cash'::"text") AND ("cash_session_id" IS NULL)))),
    CONSTRAINT "finance_payments_check2" CHECK ((("receipt_storage_path" IS NULL) OR (("receipt_storage_path" !~~ '%://%'::"text") AND ("receipt_storage_path" !~~ '/%'::"text") AND ("receipt_storage_path" ~~ (("organization_id")::"text" || '/%'::"text"))))),
    CONSTRAINT "finance_payments_check3" CHECK (((("receipt_storage_path" IS NULL) AND ("receipt_original_name" IS NULL) AND ("receipt_mime_type" IS NULL) AND ("receipt_size_bytes" IS NULL)) OR (("receipt_storage_path" IS NOT NULL) AND ("receipt_original_name" IS NOT NULL) AND ("receipt_mime_type" IS NOT NULL) AND ("receipt_size_bytes" IS NOT NULL)))),
    CONSTRAINT "finance_payments_direction_check" CHECK (("direction" = ANY (ARRAY['payment'::"text", 'reversal'::"text"]))),
    CONSTRAINT "finance_payments_idempotency_key_check" CHECK ((("char_length"(TRIM(BOTH FROM "idempotency_key")) >= 1) AND ("char_length"(TRIM(BOTH FROM "idempotency_key")) <= 128))),
    CONSTRAINT "finance_payments_notes_check" CHECK ((("notes" IS NULL) OR ("char_length"("notes") <= 2000))),
    CONSTRAINT "finance_payments_payment_method_check" CHECK (("payment_method" = ANY (ARRAY['cash'::"text", 'bank_transfer'::"text", 'other'::"text"]))),
    CONSTRAINT "finance_payments_receipt_mime_type_check" CHECK ((("receipt_mime_type" IS NULL) OR ("receipt_mime_type" = ANY (ARRAY['application/pdf'::"text", 'image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"])))),
    CONSTRAINT "finance_payments_receipt_original_name_check" CHECK ((("receipt_original_name" IS NULL) OR (("char_length"(TRIM(BOTH FROM "receipt_original_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "receipt_original_name")) <= 255)))),
    CONSTRAINT "finance_payments_receipt_size_bytes_check" CHECK ((("receipt_size_bytes" IS NULL) OR (("receipt_size_bytes" >= 1) AND ("receipt_size_bytes" <= 10485760)))),
    CONSTRAINT "finance_payments_reference_check" CHECK ((("reference" IS NULL) OR (("char_length"(TRIM(BOTH FROM "reference")) >= 1) AND ("char_length"(TRIM(BOTH FROM "reference")) <= 200))))
);


