CREATE TABLE IF NOT EXISTS "public"."products" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "sku" character varying(100) NOT NULL,
    "name" character varying(200) NOT NULL,
    "description" "text",
    "category_id" "uuid",
    "brand" character varying(100),
    "supplier_id" "uuid",
    "purchase_price" numeric(10,2) DEFAULT 0,
    "sale_price" numeric(10,2) NOT NULL,
    "wholesale_price" numeric(10,2),
    "offer_price" numeric(10,2),
    "has_offer" boolean DEFAULT false,
    "stock_quantity" integer DEFAULT 0,
    "min_stock" integer DEFAULT 0,
    "max_stock" integer,
    "unit_measure" character varying(50) DEFAULT 'unidad'::character varying,
    "barcode" character varying(50),
    "images" "text"[],
    "image_url" "text",
    "weight" numeric(10,2),
    "dimensions" character varying(100),
    "location" character varying(100),
    "tags" "text"[],
    "is_active" boolean DEFAULT true,
    "featured" boolean DEFAULT false,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "brand_id" "uuid",
    "visibility" character varying(50) DEFAULT 'public'::character varying,
    "warranty_months" integer DEFAULT 0 NOT NULL,
    "warranty_info" "text",
    "return_window_days" integer DEFAULT 0 NOT NULL,
    "exchange_window_days" integer DEFAULT 0 NOT NULL,
    "return_policy" "text",
    "exchange_policy" "text",
    "stock_status_computed" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("stock_quantity" = 0) THEN 'out_of_stock'::"text"
    WHEN ("stock_quantity" <= "min_stock") THEN 'low_stock'::"text"
    ELSE 'in_stock'::"text"
END) STORED,
    "organization_id" "uuid",
    "installments_enabled" boolean DEFAULT false NOT NULL,
    "installments_plans" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "installments_public" boolean DEFAULT true NOT NULL,
    "deactivated_by_plan" boolean DEFAULT false NOT NULL,
    "archived_by_plan_at" timestamp with time zone,
    "tax_rate" numeric(5,2),
    "has_variants" boolean DEFAULT false NOT NULL,
    "variant_attribute_config" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "device_brand" "text",
    "device_models" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "device_sort_key" "text",
    "hide_price" boolean DEFAULT false NOT NULL,
    CONSTRAINT "productos_dias_ventana_cambio_validacion" CHECK ((("exchange_window_days" >= 0) AND ("exchange_window_days" <= 90))),
    CONSTRAINT "productos_dias_ventana_devolucion_validacion" CHECK ((("return_window_days" >= 0) AND ("return_window_days" <= 90))),
    CONSTRAINT "productos_meses_garantia_validacion" CHECK ((("warranty_months" >= 0) AND ("warranty_months" <= 60))),
    CONSTRAINT "productos_visibilidad_validacion" CHECK ((("visibility")::"text" = ANY (ARRAY[('public'::character varying)::"text", ('wholesale'::character varying)::"text", ('hidden'::character varying)::"text"]))),
    CONSTRAINT "products_device_brand_length" CHECK ((("device_brand" IS NULL) OR ("char_length"("device_brand") <= 60))),
    CONSTRAINT "products_device_models_limit" CHECK ((COALESCE("array_length"("device_models", 1), 0) <= 20)),
    CONSTRAINT "products_tax_rate_check" CHECK ((("tax_rate" IS NULL) OR ("tax_rate" = ANY (ARRAY[(0)::numeric, (5)::numeric, (10)::numeric]))))
);


ALTER TABLE "public"."products" OWNER TO "postgres";


COMMENT ON TABLE "public"."products" IS 'Productos del inventario con precios y stock';



COMMENT ON COLUMN "public"."products"."stock_quantity" IS 'Suma del stock de todas las sucursales, mantenida por trg_branch_inventory_sync_total. No se escribe a mano cuando hay inventario por sucursal.';



COMMENT ON COLUMN "public"."products"."warranty_months" IS 'Warranty duration in months. 0 means no warranty.';



COMMENT ON COLUMN "public"."products"."warranty_info" IS 'Warranty terms and conditions shown to the customer.';



COMMENT ON COLUMN "public"."products"."return_window_days" IS 'Return period in days after sale. 0 means no returns.';



COMMENT ON COLUMN "public"."products"."exchange_window_days" IS 'Exchange period in days after sale. 0 means no exchanges.';



COMMENT ON COLUMN "public"."products"."return_policy" IS 'Detailed return policy shown to the customer.';



COMMENT ON COLUMN "public"."products"."exchange_policy" IS 'Detailed exchange policy shown to the customer.';



COMMENT ON COLUMN "public"."products"."installments_enabled" IS 'Si el producto se ofrece en cuotas (mostrado en la web pública)';



COMMENT ON COLUMN "public"."products"."installments_plans" IS 'Planes de cuotas ofrecidos: [{"count":int 1-60,"rate":numeric % recargo}]. Informativo para la web pública.';



COMMENT ON COLUMN "public"."products"."installments_public" IS 'Si las cuotas configuradas se muestran en la tienda pública. No afecta a que los planes queden guardados.';



COMMENT ON COLUMN "public"."products"."device_brand" IS 'Marca del celular al que pertenece el repuesto (Apple, Samsung). No es la marca del repuesto: esa es brand.';



COMMENT ON COLUMN "public"."products"."device_models" IS 'Modelos de celular compatibles (iPhone 13, A15). Lista: una pieza puede servir para varios.';



COMMENT ON COLUMN "public"."products"."device_sort_key" IS 'Clave para ordenar por celular. La completa el trigger products_device_sort_key; no se escribe a mano.';



COMMENT ON COLUMN "public"."products"."hide_price" IS 'El producto se publica sin precio: la tienda muestra «Preguntar» y abre WhatsApp. No afecta la visibilidad ni el precio de venta real.';



CREATE OR REPLACE VIEW "public"."org_catalog_counts" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    COALESCE("p"."products", (0)::bigint) AS "products",
    COALESCE("c"."categories", (0)::bigint) AS "categories"
   FROM (("public"."organizations" "o"
     LEFT JOIN ( SELECT "products"."organization_id",
            "count"(*) AS "products"
           FROM "public"."products"
          GROUP BY "products"."organization_id") "p" ON (("p"."organization_id" = "o"."id")))
     LEFT JOIN ( SELECT "categories"."organization_id",
            "count"(*) AS "categories"
           FROM "public"."categories"
          GROUP BY "categories"."organization_id") "c" ON (("c"."organization_id" = "o"."id")));


ALTER VIEW "public"."org_catalog_counts" OWNER TO "postgres";


COMMENT ON VIEW "public"."org_catalog_counts" IS 'Per-organization product/category counts for superadmin dashboards (service-role only).';



