CREATE OR REPLACE VIEW "public"."organization_members_es" WITH ("security_invoker"='on') AS
 SELECT "id",
    "organization_id",
    "user_id",
    "role",
    "status",
    "created_at",
    "updated_at",
        CASE ("role")::"text"
            WHEN 'owner'::"text" THEN 'propietario'::"text"
            WHEN 'admin'::"text" THEN 'administrador'::"text"
            WHEN 'manager'::"text" THEN 'gerente'::"text"
            WHEN 'cashier'::"text" THEN 'cajero'::"text"
            WHEN 'technician'::"text" THEN 'tecnico'::"text"
            WHEN 'seller'::"text" THEN 'vendedor'::"text"
            WHEN 'customer'::"text" THEN 'cliente'::"text"
            ELSE ("role")::"text"
        END AS "role_es"
   FROM "public"."organization_members" "om";


