CREATE OR REPLACE VIEW "public"."product_stats" WITH ("security_invoker"='on') AS
 SELECT "count"(*) AS "total_products",
    "count"(*) FILTER (WHERE ("is_active" = true)) AS "active_products",
    "sum"((("stock_quantity")::numeric * "sale_price")) AS "total_stock_value",
    "sum"((("stock_quantity")::numeric * "purchase_price")) AS "total_cost_value",
    "sum"((("stock_quantity")::numeric * ("sale_price" - "purchase_price"))) AS "total_margin",
    "count"(*) FILTER (WHERE (("stock_quantity" <= "min_stock") AND ("stock_quantity" > 0))) AS "low_stock_count",
    "count"(*) FILTER (WHERE ("stock_quantity" = 0)) AS "out_of_stock_count"
   FROM "public"."products";


