CREATE OR REPLACE VIEW "public"."products_detailed" WITH ("security_invoker"='on') AS
 SELECT "p"."id",
    "p"."sku",
    "p"."name",
    "p"."description",
    "p"."category_id",
    "p"."brand",
    "p"."supplier_id",
    "p"."purchase_price",
    "p"."sale_price",
    "p"."wholesale_price",
    "p"."offer_price",
    "p"."has_offer",
    "p"."stock_quantity",
    "p"."min_stock",
    "p"."max_stock",
    "p"."unit_measure",
    "p"."barcode",
    "p"."images",
    "p"."image_url",
    "p"."weight",
    "p"."dimensions",
    "p"."location",
    "p"."tags",
    "p"."is_active",
    "p"."featured",
    "p"."created_at",
    "p"."updated_at",
    "c"."name" AS "category_name",
    NULL::"text" AS "category_color",
    NULL::"text" AS "category_icon",
    "s"."name" AS "supplier_name",
    "s"."contact_name" AS "supplier_contact",
    "s"."email" AS "supplier_email",
    "s"."phone" AS "supplier_phone",
        CASE
            WHEN ("p"."purchase_price" > (0)::numeric) THEN "round"(((("p"."sale_price" - "p"."purchase_price") / "p"."purchase_price") * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "profit_margin_percentage",
    (("p"."stock_quantity")::numeric * "p"."purchase_price") AS "total_stock_value",
        CASE
            WHEN ("p"."stock_quantity" = 0) THEN 'out_of_stock'::"text"
            WHEN ("p"."stock_quantity" <= "p"."min_stock") THEN 'low_stock'::"text"
            ELSE 'normal'::"text"
        END AS "stock_status",
    ( SELECT "count"(*) AS "count"
           FROM "public"."product_alerts" "pa"
          WHERE (("pa"."product_id" = "p"."id") AND ("pa"."is_resolved" = false))) AS "active_alerts_count"
   FROM (("public"."products" "p"
     LEFT JOIN "public"."categories" "c" ON (("p"."category_id" = "c"."id")))
     LEFT JOIN "public"."suppliers" "s" ON (("p"."supplier_id" = "s"."id")));


ALTER VIEW "public"."products_detailed" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."products_full" WITH ("security_invoker"='on') AS
 SELECT "p"."id",
    "p"."sku",
    "p"."name",
    "p"."description",
    "p"."category_id",
    "p"."brand",
    "p"."supplier_id",
    "p"."purchase_price",
    "p"."sale_price",
    "p"."wholesale_price",
    "p"."offer_price",
    "p"."has_offer",
    "p"."stock_quantity",
    "p"."min_stock",
    "p"."max_stock",
    "p"."unit_measure",
    "p"."barcode",
    "p"."images",
    "p"."image_url",
    "p"."weight",
    "p"."dimensions",
    "p"."location",
    "p"."tags",
    "p"."is_active",
    "p"."featured",
    "p"."created_at",
    "p"."updated_at",
    "c"."name" AS "category_name",
    "s"."name" AS "supplier_name",
        CASE
            WHEN ("p"."stock_quantity" = 0) THEN 'out_of_stock'::"text"
            WHEN ("p"."stock_quantity" <= "p"."min_stock") THEN 'low_stock'::"text"
            ELSE 'in_stock'::"text"
        END AS "stock_status",
    ("p"."sale_price" - "p"."purchase_price") AS "margin",
        CASE
            WHEN ("p"."purchase_price" > (0)::numeric) THEN "round"(((("p"."sale_price" - "p"."purchase_price") / "p"."sale_price") * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "margin_percentage",
    (("p"."stock_quantity")::numeric * "p"."sale_price") AS "total_value"
   FROM (("public"."products" "p"
     LEFT JOIN "public"."categories" "c" ON (("p"."category_id" = "c"."id")))
     LEFT JOIN "public"."suppliers" "s" ON (("p"."supplier_id" = "s"."id")));


ALTER VIEW "public"."products_full" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."products_safe" WITH ("security_invoker"='true') AS
 SELECT "id",
