    "supplier_id",
        CASE
            WHEN "public"."app_can_view_cost"() THEN "purchase_price"
            ELSE NULL::numeric
        END AS "purchase_price",
    "sale_price",
    "wholesale_price",
    "offer_price",
    "has_offer",
    "stock_quantity",
    "min_stock",
    "max_stock",
    "unit_measure",
    "barcode",
    "images",
    "image_url",
    "weight",
    "dimensions",
    "location",
    "tags",
    "is_active",
    "featured",
    "created_at",
    "updated_at",
    "brand_id",
    "visibility",
    "warranty_months",
    "warranty_info",
    "return_window_days",
    "exchange_window_days",
    "return_policy",
    "exchange_policy",
    "stock_status_computed",
    "organization_id"
   FROM "public"."products" "p";


