    "device_brand" character varying(100) NOT NULL,
    "device_model" character varying(100) NOT NULL,
    "serial_number" character varying(100),
    "imei" character varying(50),
    "problem_description" "text" NOT NULL,
    "diagnosis" "text",
    "solution" "text",
    "status" "public"."repair_status" DEFAULT 'recibido'::"public"."repair_status",
    "priority" "public"."repair_priority" DEFAULT 'medium'::"public"."repair_priority",
    "urgency" "public"."repair_urgency" DEFAULT 'normal'::"public"."repair_urgency",
    "technician_id" "uuid",
    "estimated_cost" numeric(10,2) DEFAULT 0,
    "final_cost" numeric(10,2),
    "labor_cost" numeric(10,2) DEFAULT 0,
    "parts_cost" numeric(10,2) DEFAULT 0,
    "location" character varying(100) DEFAULT 'Taller Principal'::character varying,
    "warranty_months" integer DEFAULT 0,
    "warranty_expires_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "estimated_completion" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "delivered_at" timestamp with time zone,
    "progress" integer DEFAULT 0,
    "customer_rating" integer,
    "customer_feedback" "text",
    "notify_customer" boolean DEFAULT true,
    "notify_technician" boolean DEFAULT true,
    "notify_manager" boolean DEFAULT false,
    "tags" "text"[],
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "is_deleted" boolean DEFAULT false,
    "deleted_at" timestamp with time zone,
    "access_type" "text" DEFAULT 'none'::"text",
    "access_password" "text",
    "received_at" timestamp with time zone DEFAULT "now"(),
    "ticket_number" "text",
    "warranty_type" character varying(20) DEFAULT 'full'::character varying,
    "warranty_notes" "text",
    "picked_up_at" timestamp with time zone,
    "payment_status" character varying(50) DEFAULT 'pendiente'::character varying,
    "paid_amount" numeric(10,2) DEFAULT 0,
    "delivery_outcome" "text",
    "branch_id" "uuid" DEFAULT "public"."get_default_branch_id"() NOT NULL,
    "organization_id" "uuid",
    "parent_repair_id" "uuid",
    "pricing_mode" "text" DEFAULT 'automatic'::"text" NOT NULL,
    "discount_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "price_override_reason" "text",
    "pricing_updated_by" "uuid",
    "pricing_updated_at" timestamp with time zone,
    "delivery_idempotency_key" "text",
    "additional_charges" numeric(14,2) DEFAULT 0 NOT NULL,
    "deductions" numeric(14,2) DEFAULT 0 NOT NULL,
    "current_cost_revision_id" "uuid",
    "creation_idempotency_key" "text",
    "creation_payload_hash" "text",
    "creation_completed_at" timestamp with time zone,
    "reception_id" "uuid",
    "current_quality_check_id" "uuid",
    CONSTRAINT "repairs_adjustments_nonnegative_check" CHECK ((("additional_charges" >= (0)::numeric) AND ("deductions" >= (0)::numeric))),
    CONSTRAINT "repairs_creation_idempotency_consistency" CHECK (((("creation_idempotency_key" IS NULL) AND ("creation_payload_hash" IS NULL)) OR (("creation_idempotency_key" IS NOT NULL) AND ("creation_payload_hash" IS NOT NULL) AND (("char_length"(TRIM(BOTH FROM "creation_idempotency_key")) >= 8) AND ("char_length"(TRIM(BOTH FROM "creation_idempotency_key")) <= 120)) AND ("creation_payload_hash" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "repairs_customer_rating_check" CHECK ((("customer_rating" >= 1) AND ("customer_rating" <= 5))),
    CONSTRAINT "repairs_delivery_outcome_check" CHECK (("delivery_outcome" = ANY (ARRAY['repaired'::"text", 'unrepairable'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "repairs_discount_amount_check" CHECK (("discount_amount" >= (0)::numeric)),
    CONSTRAINT "repairs_pricing_mode_check" CHECK (("pricing_mode" = ANY (ARRAY['automatic'::"text", 'budget'::"text", 'manual'::"text"]))),
    CONSTRAINT "repairs_progress_check" CHECK ((("progress" >= 0) AND ("progress" <= 100)))
);


ALTER TABLE "public"."repairs" OWNER TO "postgres";


COMMENT ON COLUMN "public"."repairs"."received_at" IS 'Fecha y hora en que se recibió el dispositivo';



COMMENT ON COLUMN "public"."repairs"."warranty_type" IS 'Tipo de garantía: labor (mano de obra), parts (repuestos), full (completa)';



COMMENT ON COLUMN "public"."repairs"."warranty_notes" IS 'Notas adicionales sobre la garantía';



COMMENT ON COLUMN "public"."repairs"."picked_up_at" IS 'Fecha y hora en que el cliente retiró el equipo reparado';



COMMENT ON COLUMN "public"."repairs"."parent_repair_id" IS 'Reparacion original cuando esta es un retrabajo por garantia. NULL en reparaciones normales.';



COMMENT ON COLUMN "public"."repairs"."pricing_mode" IS 'automatic: labor + parts - discount; budget: total agreed derives labor; manual: administrative override';



COMMENT ON COLUMN "public"."repairs"."price_override_reason" IS 'Audit explanation required for discounts and authorized pricing exceptions.';



COMMENT ON COLUMN "public"."repairs"."creation_idempotency_key" IS 'Client-generated key that makes repair creation safe to retry.';



COMMENT ON COLUMN "public"."repairs"."creation_payload_hash" IS 'SHA-256 fingerprint used to reject reuse of a creation key with changed data.';



COMMENT ON COLUMN "public"."repairs"."creation_completed_at" IS 'Set only after all related repair rows and inventory synchronization finish; idempotent retries replay completed rows only.';



COMMENT ON COLUMN "public"."repairs"."reception_id" IS 'Agrupa las ordenes creadas en una misma recepcion. Null = el equipo vino solo.';



CREATE OR REPLACE VIEW "public"."repair_stats" WITH ("security_invoker"='on') AS
 SELECT "count"(*) AS "total_repairs",
    "count"(*) FILTER (WHERE ("status" = 'recibido'::"public"."repair_status")) AS "pending_repairs",
    "count"(*) FILTER (WHERE ("status" = 'diagnostico'::"public"."repair_status")) AS "in_diagnosis",
    "count"(*) FILTER (WHERE ("status" = 'reparacion'::"public"."repair_status")) AS "in_repair",
    "count"(*) FILTER (WHERE ("status" = 'listo'::"public"."repair_status")) AS "ready_for_pickup",
    "count"(*) FILTER (WHERE ("status" = 'entregado'::"public"."repair_status")) AS "delivered",
    "count"(*) FILTER (WHERE ("priority" = 'high'::"public"."repair_priority")) AS "high_priority",
    "count"(*) FILTER (WHERE ("urgency" = 'urgent'::"public"."repair_urgency")) AS "urgent_repairs",
    "avg"("final_cost") AS "avg_repair_cost",
    "sum"("final_cost") AS "total_revenue",
    "avg"("customer_rating") AS "avg_customer_rating",
    "avg"((EXTRACT(epoch FROM ("completed_at" - "created_at")) / (3600)::numeric)) AS "avg_completion_hours"
   FROM "public"."repairs"
  WHERE ("is_deleted" = false);


ALTER VIEW "public"."repair_stats" OWNER TO "postgres";


