CREATE OR REPLACE VIEW "public"."repairs_full" WITH ("security_invoker"='on') AS
 SELECT "r"."id",
    "r"."customer_id",
    "r"."device_type",
    "r"."device_brand",
    "r"."device_model",
    "r"."serial_number",
    "r"."imei",
    "r"."problem_description",
    "r"."diagnosis",
    "r"."solution",
    "r"."status",
    "r"."priority",
    "r"."urgency",
    "r"."technician_id",
    "r"."estimated_cost",
    "r"."final_cost",
    "r"."labor_cost",
    "r"."parts_cost",
    "r"."location",
    "r"."warranty_months",
    "r"."warranty_expires_at",
    "r"."created_at",
    "r"."updated_at",
    "r"."estimated_completion",
    "r"."completed_at",
    "r"."delivered_at",
    "r"."progress",
    "r"."customer_rating",
    "r"."customer_feedback",
    "r"."notify_customer",
    "r"."notify_technician",
    "r"."notify_manager",
    "r"."tags",
    "r"."metadata",
    "r"."is_deleted",
    "r"."deleted_at",
    "c"."name" AS "customer_name",
    "c"."phone" AS "customer_phone",
    "c"."email" AS "customer_email",
    "p"."full_name" AS "technician_name",
    "p"."email" AS "technician_email",
    ("r"."final_cost" - "r"."estimated_cost") AS "cost_variance",
        CASE
            WHEN ("r"."completed_at" IS NOT NULL) THEN (EXTRACT(epoch FROM ("r"."completed_at" - "r"."created_at")) / (3600)::numeric)
            ELSE (EXTRACT(epoch FROM ("now"() - "r"."created_at")) / (3600)::numeric)
        END AS "hours_in_repair",
    ( SELECT "count"(*) AS "count"
           FROM "public"."repair_notes"
          WHERE ("repair_notes"."repair_id" = "r"."id")) AS "notes_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."repair_parts"
          WHERE ("repair_parts"."repair_id" = "r"."id")) AS "parts_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."repair_images"
          WHERE ("repair_images"."repair_id" = "r"."id")) AS "images_count"
   FROM (("public"."repairs" "r"
     LEFT JOIN "public"."customers" "c" ON (("r"."customer_id" = "c"."id")))
     LEFT JOIN "public"."profiles" "p" ON (("r"."technician_id" = "p"."id")))
  WHERE ("r"."is_deleted" = false);


ALTER VIEW "public"."repairs_full" OWNER TO "postgres";


