CREATE OR REPLACE VIEW "public"."settings_change_history" WITH ("security_invoker"='on') AS
 SELECT "a"."id",
    "a"."created_at",
    "a"."field_name",
    "a"."old_value",
    "a"."new_value",
    "a"."severity",
    "p"."full_name" AS "changed_by",
    "p"."email" AS "changed_by_email"
   FROM ("public"."system_settings_audit" "a"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "a"."user_id")))
  WHERE ("a"."action" = 'update'::"text")
  ORDER BY "a"."created_at" DESC;


