    CONSTRAINT "subscription_promo_codes_benefit_type_check" CHECK (("benefit_type" = ANY (ARRAY['discount_percent'::"text", 'discount_fixed'::"text", 'activate_plan'::"text", 'extend_trial'::"text", 'extend_period'::"text"]))),
    CONSTRAINT "subscription_promo_codes_dates_check" CHECK ((("expires_at" IS NULL) OR ("starts_at" IS NULL) OR ("expires_at" > "starts_at"))),
    CONSTRAINT "subscription_promo_codes_discount_amount_check" CHECK (("discount_amount" > (0)::numeric)),
