CREATE OR REPLACE VIEW "public"."technician_workload" WITH ("security_invoker"='on') AS
 SELECT "p"."id" AS "technician_id",
    "p"."full_name" AS "technician_name",
    "count"(*) AS "total_repairs",
    "count"(*) FILTER (WHERE ("r"."status" = ANY (ARRAY['diagnostico'::"public"."repair_status", 'reparacion'::"public"."repair_status"]))) AS "active_repairs",
    "count"(*) FILTER (WHERE ("r"."status" = 'listo'::"public"."repair_status")) AS "completed_repairs",
    "avg"("r"."customer_rating") AS "avg_rating",
    "sum"("r"."final_cost") AS "total_revenue",
    "avg"((EXTRACT(epoch FROM ("r"."completed_at" - "r"."created_at")) / (3600)::numeric)) AS "avg_completion_hours"
   FROM ("public"."profiles" "p"
     LEFT JOIN "public"."repairs" "r" ON ((("p"."id" = "r"."technician_id") AND ("r"."is_deleted" = false))))
  WHERE ("p"."role" = 'technician'::"text")
  GROUP BY "p"."id", "p"."full_name";


ALTER VIEW "public"."technician_workload" OWNER TO "postgres";


