    "count"(*) FILTER (WHERE ("role" = 'admin'::"text")) AS "admins_count",
    "count"(*) FILTER (WHERE ("created_at" >= "date_trunc"('month'::"text", (CURRENT_DATE)::timestamp with time zone))) AS "new_users_this_month",
