    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "branch_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "variant_id" "uuid" NOT NULL,
    "movement_type" "text" NOT NULL,
    "quantity_delta" integer NOT NULL,
    "stock_before" integer NOT NULL,
    "stock_after" integer NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "reference_type" "text",
    "reference_id" "uuid",
    "reason" "text",
    "actor_id" "uuid" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "variant_inventory_movements_movement_type_check" CHECK (("movement_type" = ANY (ARRAY['initial'::"text", 'adjustment'::"text", 'sale'::"text", 'sale_cancel'::"text", 'return'::"text", 'correction'::"text"]))),
    CONSTRAINT "variant_inventory_movements_quantity_delta_check" CHECK (("quantity_delta" <> 0)),
    CONSTRAINT "variant_inventory_movements_stock_after_check" CHECK (("stock_after" >= 0)),
    CONSTRAINT "variant_inventory_movements_stock_before_check" CHECK (("stock_before" >= 0))
);


ALTER TABLE "public"."variant_inventory_movements" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."website_settings" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "key" "text" NOT NULL,
    "value" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "organization_id" "uuid" NOT NULL
);


ALTER TABLE "public"."website_settings" OWNER TO "postgres";


